    let mut gpu = pollster::block_on(Gpu::new_headless(640, 480))?;
    gpu.view.show_grid = false;
    let input = FrameInput {
        view_proj: session_rust::Xform::new(),
        clear: wgpu::Color::WHITE,
        now_ms: 0.0,
