    let pixels = gpu.render_offscreen(&input);
    let mut file = std::fs::File::create("lesson.ppm")?;
    file.write_all(b"P6\n640 480\n255\n")?;

    for pixel in pixels.chunks_exact(4) {
        file.write_all(&pixel[..3])?;
    }

    Ok(())
}

