        self.release(ctx, layouts);
    }

    fn bytes(&self) -> (u64, u64) {
        (self.allocated_bytes(), 0)
    }
}

use super::Gpu;
use super::buffers::GpuCtx;
use super::frame::{Binds, FrameInput, MAX_PLANES};
use super::lane::Lane;
use crate::engine::pipelines::Target;
use std::any::Any;

/// What every pass of one frame shares.
pub struct Frame<'a> {
    pub view: &'a wgpu::TextureView, // the canvas
    pub clear: wgpu::Color,          // background color
    pub tier: u8,                    // drag tier; 0 is full quality
}

// A pass is one optional stage of the frame, such as clipping or ambient occlusion, that owns its GPU state.
// `Lane + Any`: every pass is also a lane, and `Any` lets `pass::<T>()` find it by its type.
/// One optional pass of the frame owning its GPU state; each hook runs on every pass in `PASSES` order.
pub trait Pass: Lane + Any {
    /// Before anything of the frame is encoded.
    fn prepare(&mut self, _g: &mut Gpu, _encoder: &mut wgpu::CommandEncoder) {}

    /// Write this frame's uniforms.
    fn write_frame(&mut self, _g: &mut Gpu, _input: &FrameInput) {}

    /// Face passes of its own before the main one; the first opened clears, draws the backdrop, sets `drew`.
    fn before_faces(
        &mut self,
        _g: &mut Gpu,
        _encoder: &mut wgpu::CommandEncoder,
        _f: &Frame,
        _drew: &mut bool,
    ) -> u32 {
        0
    }

    /// Draws into the face pass, after the backdrop and before the faces.
    fn in_faces(&self, _g: &Gpu, _pass: &mut wgpu::RenderPass<'_>, _b: &Binds) -> u32 {
        0
    }

    /// True while this pass cuts the faces, which then keep their clip tests.
    fn clips(&self) -> bool {
        false
    }

    /// After the faces and before the ink; returns the draw count.
    fn after_faces(
        &mut self,
        _g: &mut Gpu,
        _encoder: &mut wgpu::CommandEncoder,
        _f: &Frame,
    ) -> u32 {
        0
    }

    /// Bind what its outline mask draws read.
    fn bind_masks(&mut self, _g: &Gpu) {}

    /// Draws into the open outline mask pass, `both` masks at once or the selection's alone.
    fn in_masks(&self, _g: &Gpu, _pass: &mut wgpu::RenderPass<'_>, _b: &Binds, _both: bool) -> u32 {
        0
    }

    /// Draws into the ink pass, over the selected mesh edges and under the selected curves.
    fn over_ink(&self, _g: &Gpu, _pass: &mut wgpu::RenderPass<'_>, _b: &Binds) -> u32 {
        0
    }

    /// Before the id pass draws over a `size` window.
    fn before_ids(
        &mut self,
        _g: &Gpu,
        _encoder: &mut wgpu::CommandEncoder,
        _b: &Binds,
        _size: (u32, u32),
    ) {
    }

    /// Draws into the id pass, before the faces.
    fn in_ids(&self, _g: &Gpu, _pass: &mut wgpu::RenderPass<'_>, _b: &Binds) -> u32 {
        0
    }

    /// Object `row` was selected or deselected.
    fn on_select(&mut self, _row: u32, _on: bool) {}

    /// True while the view asks for this pass and its pipelines are still compiling.
    fn pending(&self, _g: &Gpu) -> bool {
        false
    }

    /// After the frame was presented: compile ahead, outside the frame.
    fn after_present(&mut self, _g: &mut Gpu) {}

    /// The world planes (normal, offset) this pass cuts with.
    fn clip_world(&self) -> Option<[[f64; 4]; MAX_PLANES]> {
        None
    }
}

// Empty in the first lessons: each pass a later lesson writes adds one line here.
/// The passes in frame order. Adding one means its `Pass` impl in one file and one line here.
pub const PASSES: &[fn(&GpuCtx, Target) -> Box<dyn Pass>] = &[
];

// `pub(super)` = visible to the parent module, `gpu`, and no further.
/// Stands in the list for a pass while its own hook runs.
pub(super) struct Nothing;

impl Lane for Nothing {}

impl Pass for Nothing {}

impl Gpu {
    /// Run `f` on every pass in order with the rest of the GPU; the pass is out of the list meanwhile.
    pub(super) fn each_pass(&mut self, mut f: impl FnMut(&mut dyn Pass, &mut Gpu)) {
        for i in 0..self.passes.len() {
            // `mem::replace` takes the pass out and leaves `Nothing` in its slot, so the pass and the rest of `self` can both be borrowed mutably
            let mut pass = std::mem::replace(&mut self.passes[i], Box::new(Nothing));
            f(pass.as_mut(), self);
            self.passes[i] = pass;
        }
    }

    /// The clipping planes in world space; zero planes cut nothing.
    pub(crate) fn clip_planes(&self) -> [[f64; 4]; MAX_PLANES] {
        self.passes
            .iter()
            .find_map(|pass| pass.clip_world())
            .unwrap_or([[0.0; 4]; MAX_PLANES])
    }

    /// The registered pass of type `T`.
    pub fn pass<T: Pass>(&self) -> &T {
        self.passes
            .iter()
            .find_map(|pass| (pass.as_ref() as &dyn Any).downcast_ref::<T>())
            .expect("a registered pass")
    }

    /// The registered pass of type `T`, mutable.
    pub fn pass_mut<T: Pass>(&mut self) -> &mut T {
        find_mut(&mut self.passes)
    }
}

/// The pass of type `T` in `passes`, for a borrow beside other `Gpu` fields.
pub(super) fn find_mut<T: Pass>(passes: &mut [Box<dyn Pass>]) -> &mut T {
    passes
        .iter_mut()
        .find_map(|pass| (pass.as_mut() as &mut dyn Any).downcast_mut::<T>())
        .expect("a registered pass")
}

use super::Gpu;
use super::frame::{FrameCx, FrameInput};
#[cfg(not(target_arch = "wasm32"))]
use super::targets::{TextureSpec, texture};

impl Gpu {
    /// Write this frame's uniforms and prepare the widget and text.
    fn write_frame_uniforms(&mut self, input: &FrameInput) {
        let size = (self.config.width, self.config.height);
        let cx = FrameCx {
            view: &self.view,
            anchor: self.objects.anchor_f32(),
            size,
            // framebuffer pixels per CSS pixel
            pixel_scale: size.0 as f32 / self.logical_size[0].max(1.0) as f32,
        };
        self.frame.write(&self.ctx, input, &cx);
        self.each_pass(|pass, g| pass.write_frame(g, input));
        self.objects
            .update_inside(&self.ctx, self.frame.eye, &self.bounds);
    }

    /// Keep a requested Arctic view awake until its idle-compiled pipelines are ready.
    pub fn ambient_pending(&self) -> bool {
        self.passes.iter().any(|pass| pass.pending(self))
    }

    /// Draw one frame to the canvas; returns encode time in ms.
    pub fn present(&mut self, input: &FrameInput) -> Option<f64> {
        self.write_frame_uniforms(input);
        let surface = self.surface.as_ref()?;
        // the canvas lends one texture per frame; `present()` below hands it back to be shown
        let output = match surface.get_current_texture() {
            wgpu::CurrentSurfaceTexture::Success(t)
            | wgpu::CurrentSurfaceTexture::Suboptimal(t) => t,
            _ => {
                surface.configure(&self.ctx.device, &self.config);
                return None;
            }
        };
        let view = output
            .texture
            .create_view(&wgpu::TextureViewDescriptor::default());
        let mut encoder = self
            .ctx
            .device
            .create_command_encoder(&wgpu::CommandEncoderDescriptor {
                label: Some("frame"),
            });

        let t0 = crate::engine::performance::now_ms();
        let (draws, objects) = self.encode_frame(&mut encoder, &view, input.clear);
        let encode_ms = crate::engine::performance::now_ms() - t0;
        // submit: the GPU starts on the recorded commands while the CPU moves on
        self.ctx.queue.submit([encoder.finish()]);
        // start reading back any pick copied this frame
        output.present();

        // startup marks; the GPU-side one also times the pipelines the first frames compiled
        let mut geometry = false;

        if let Some(done) = self.performance.mark_startup(geometry) {
            self.ctx
                .queue
                .on_submitted_work_done(move || crate::engine::performance::mark(done));
        }

        // compile ahead outside the frame, after the first geometry has been presented
        self.each_pass(|pass, g| pass.after_present(g));
        self.performance
            .frame(draws, objects, input.now_ms, self.view.perf);
        if self.view.ssao {
            self.performance.keep_arctic_quality();
        }

        Some(encode_ms)
    }

    /// Draw one frame into a texture and return its RGBA8 pixels; native only.
    #[cfg(not(target_arch = "wasm32"))]
    pub fn render_offscreen(&mut self, input: &FrameInput) -> Vec<u8> {
        let (w, h) = (self.config.width, self.config.height);
        let usage = wgpu::TextureUsages::RENDER_ATTACHMENT | wgpu::TextureUsages::COPY_SRC;
        let tex = texture(
            &self.ctx,
            "headless.color",
            &TextureSpec {
                size: (w, h),
                format: self.config.format,
                samples: 1,
                usage,
            },
        );
        let view = tex.create_view(&wgpu::TextureViewDescriptor::default());
        // bytes per row, 256-aligned as wgpu requires
        let padded = (w * 4).div_ceil(256) * 256;
        let readback = self.ctx.device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("headless.readback"),
            size: (padded * h) as u64,
            usage: wgpu::BufferUsages::COPY_DST | wgpu::BufferUsages::MAP_READ,
            mapped_at_creation: false,
        });

        self.write_frame_uniforms(input);
        let mut encoder = self.ctx.device.create_command_encoder(&Default::default());
        let (draws, objects) = self.encode_frame(&mut encoder, &view, input.clear);
        encoder.copy_texture_to_buffer(
            wgpu::TexelCopyTextureInfo {
                texture: &tex,
                mip_level: 0,
                origin: wgpu::Origin3d::ZERO,
                aspect: wgpu::TextureAspect::All,
            },
            wgpu::TexelCopyBufferInfo {
                buffer: &readback,
                layout: wgpu::TexelCopyBufferLayout {
                    offset: 0,
                    bytes_per_row: Some(padded),
                    rows_per_image: Some(h),
                },
            },
            wgpu::Extent3d {
                width: w,
                height: h,
                depth_or_array_layers: 1,
            },
        );

        self.ctx.queue.submit([encoder.finish()]);
        log::info!("headless frame: {draws} draws, {objects} objects, {w}x{h}");

        let slice = readback.slice(..);
        // wait for the copy to land on the CPU
        slice.map_async(wgpu::MapMode::Read, |_| {});
        let _ = self.ctx.device.poll(wgpu::PollType::Wait {
            submission_index: None,
            timeout: None,
        });
        let data = slice.get_mapped_range();
        let mut out = Vec::with_capacity((w * 4 * h) as usize);

        // drop the row padding
        for row in 0..h {
            let a = (row * padded) as usize;
            out.extend_from_slice(&data[a..a + (w * 4) as usize]);
        }

        drop(data);
        readback.unmap();

        out
    }
}

use super::Gpu;
use super::frame::Binds;
use super::pass::Frame;

// `impl Gpu` blocks may sit in any file of the crate: this one adds the frame encoding.
impl Gpu {
    /// Encode one frame into `view`; returns (draws, objects).
    pub fn encode_frame(
        &mut self,
        encoder: &mut wgpu::CommandEncoder,
        view: &wgpu::TextureView,
        clear: wgpu::Color,
    ) -> (u32, u32) {
        self.each_pass(|pass, g| pass.prepare(g, encoder));

        let tier = if self.view.ssao {
            0
        } else {
            self.performance.drag_tier()
        };

        let frame = Frame {
            view,
            clear,
            tier,
        };
        // pass 1: background, section caps, faces and clouds write depth
        let mut draws = self.face_passes(encoder, &frame);
        // pass 2: ambient occlusion and the outline masks, each pass in turn
        self.each_pass(|pass, g| draws += pass.after_faces(g, encoder, &frame));
        (draws, self.objects.len())
    }

    /// The first pass: each pass's own face passes, then the one the faces draw in.
    fn face_passes(&mut self, encoder: &mut wgpu::CommandEncoder, f: &Frame) -> u32 {
        let mut draws = 0;
        let mut drew = false;
        self.each_pass(|pass, g| draws += pass.before_faces(g, encoder, f, &mut drew));

        let b = self.frame.binds(&self.objects.group);
        let mut pass = self
            .targets
            .begin_faces(encoder, f.view, (!drew).then_some(f.clear));

        if !drew {
            draws += self.backdrop_list(&mut pass, &b);
        }

        for other in &self.passes {
            draws += other.in_faces(self, &mut pass, &b);
        }

        draws + self.face_list(&mut pass, &b)
    }

    /// Draws of the backdrop: background and grid.
    pub(super) fn backdrop_list(&self, pass: &mut wgpu::RenderPass<'_>, b: &Binds) -> u32 {
        let mut draws = self.backdrop.draw_background(pass, b);

        draws
    }

    /// Draws of the first pass after the backdrop and caps: faces, clouds.
    fn face_list(&self, pass: &mut wgpu::RenderPass<'_>, b: &Binds) -> u32 {
        let clipped = self.passes.iter().any(|pass| pass.clips());
        let opaque = self.view.opacity >= 1.0; // at full opacity the blend returns the face color itself
        let mut draws = 0;
        draws
    }
}

use super::buffers::GpuCtx;

// MSAA = multisample anti-aliasing: 4 samples per pixel smooth the edges and cost 4 times the memory.
/// Pixels a discrete GPU may draw at 4x MSAA.
const MSAA_PIXELS_DISCRETE: u32 = 9_000_000;

/// Device scale from which MSAA is off unless forced.
const MSAA_MAX_PIXEL_SCALE: f32 = 2.0;

/// Pixels an integrated GPU may draw at 4x MSAA.
const MSAA_PIXELS_SHARED: u32 = 2_500_000;

/// Pixels at 4x when the GPU type is unknown; every browser lands here.
const MSAA_PIXELS_UNKNOWN: u32 = 4_200_000;

// A render target is a texture a pass draws into; the depth texture keeps, per pixel, how near the closest surface is.
/// The frame's depth and color textures at one sample count.
pub struct Targets {
    pub depth: Attachment,                  // scene depth
    pub msaa: Option<Attachment>,           // multisampled color, only at 4x
    pub depth_single: wgpu::TextureView,    // depth at 1x, or a 1x1 placeholder
    pub depth_msaa: wgpu::TextureView,      // depth at 4x, or a 1x1 placeholder
    pub samples: u32,                       // MSAA samples, 1 or 4
    pub gradient: Attachment, // triangle index + 1 per sample in two 16-bit halves, 0 for none
    pub gradient_single: wgpu::TextureView, // triangle ids at 1x, or a placeholder
    pub gradient_msaa: wgpu::TextureView, // triangle ids at 4x, or a placeholder
    _placeholders: [Attachment; 2], // the 1x1 textures, freed with the rest
}

impl Targets {
    /// Create the textures for `size` at `samples`.
    pub fn new(ctx: &GpuCtx, size: (u32, u32), format: wgpu::TextureFormat, samples: u32) -> Self {
        let usage = wgpu::TextureUsages::RENDER_ATTACHMENT | wgpu::TextureUsages::TEXTURE_BINDING;
        let attachment = |label, size, format, samples| {
            Attachment::new(
                ctx,
                label,
                &TextureSpec {
                    size,
                    format,
                    samples,
                    usage,
                },
            )
        };
        let depth = attachment("depth", size, wgpu::TextureFormat::Depth32Float, samples);
        let msaa = (samples > 1).then(|| attachment("msaa_color", size, format, samples));

        // shaders bind both sample counts; the unused one is 1x1
        let other_samples = if samples == 1 { 4 } else { 1 };
        let empty_depth = attachment(
            "unused.depth",
            (1, 1),
            wgpu::TextureFormat::Depth32Float,
            other_samples,
        );
        let (depth_single, depth_msaa) = if samples == 1 {
            (depth.view.clone(), empty_depth.view.clone())
        } else {
            (empty_depth.view.clone(), depth.view.clone())
        };
        let gradient = attachment(
            "physical.primitive",
            size,
            wgpu::TextureFormat::Rg16Uint,
            samples,
        );
        let empty_gradient = attachment(
            "unused.primitive",
            (1, 1),
            wgpu::TextureFormat::Rg16Uint,
            other_samples,
        );
        let (gradient_single, gradient_msaa) = if samples == 1 {
            (gradient.view.clone(), empty_gradient.view.clone())
        } else {
            (empty_gradient.view.clone(), gradient.view.clone())
        };
        Self {
            gradient,
            gradient_single,
            gradient_msaa,
            depth,
            msaa,
            depth_single,
            depth_msaa,
            samples,
            _placeholders: [empty_depth, empty_gradient],
        }
    }

    /// Free every texture now.
    pub fn destroy(&self) {
        self.depth.destroy();
        self.gradient.destroy();

        if let Some(msaa) = &self.msaa {
            msaa.destroy();
        }

        for placeholder in &self._placeholders {
            placeholder.destroy();
        }
    }

    /// Pixels this GPU type may draw at 4x; None = never.
    pub fn msaa_budget(gpu: wgpu::DeviceType) -> Option<u32> {
        match gpu {
            wgpu::DeviceType::DiscreteGpu => Some(MSAA_PIXELS_DISCRETE),
            wgpu::DeviceType::IntegratedGpu | wgpu::DeviceType::VirtualGpu => {
                Some(MSAA_PIXELS_SHARED)
            }
            wgpu::DeviceType::Cpu => None,
            wgpu::DeviceType::Other => Some(MSAA_PIXELS_UNKNOWN),
        }
    }

    /// Sample count: 4x only with solids, within budget, below device scale 2.
    pub fn samples_for(
        solid: bool,
        pixels: u32,
        forced: Option<u32>,
        budget: Option<u32>,
        pixel_scale: f32,
    ) -> u32 {
        // a page that lost its device stays at 1x
        if super::view::reduced() {
            return 1;
        }

        if let Some(s) = forced {
            return if s == 4 { 4 } else { 1 };
        }

        if pixel_scale >= MSAA_MAX_PIXEL_SCALE {
            return 1;
        }

        match budget {
            Some(max) if solid && pixels <= max => 4,
            _ => 1,
        }
    }

    // A render pass is one run of draws into a set of targets: `load` says what they start from, `store` whether the result is kept.
    // `'a` ties the pass to the encoder and views it borrows: it may not outlive them.
    /// Open the face pass: color and depth cleared, or kept when `clear` is None.
    pub fn begin_faces<'a>(
        &'a self,
        encoder: &'a mut wgpu::CommandEncoder,
        view: &'a wgpu::TextureView,
        clear: Option<wgpu::Color>,
    ) -> wgpu::RenderPass<'a> {
        let target = self.msaa.as_deref().unwrap_or(view);
        // a pass after the first keeps what the one before drew
        let load = |color| match clear {
            Some(_) => wgpu::LoadOp::Clear(color),
            None => wgpu::LoadOp::Load,
        };
        encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("physical face pass"),
            color_attachments: &[
                Some(wgpu::RenderPassColorAttachment {
                    view: target,
                    resolve_target: None,
                    depth_slice: None,
                    ops: wgpu::Operations {
                        load: load(clear.unwrap_or(wgpu::Color::TRANSPARENT)),
                        store: wgpu::StoreOp::Store,
                    },
                }),
                Some(wgpu::RenderPassColorAttachment {
                    view: &self.gradient,
                    resolve_target: None,
                    depth_slice: None,
                    ops: wgpu::Operations {
                        load: load(wgpu::Color::TRANSPARENT),
                        store: wgpu::StoreOp::Store,
                    },
                }),
            ],
            depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
                view: &self.depth,
                depth_ops: Some(wgpu::Operations {
                    // reverse-Z: near is 1 and far is 0, which keeps float depth precise far away
                    load: match clear {
                        Some(_) => wgpu::LoadOp::Clear(0.0),
                        None => wgpu::LoadOp::Load,
                    },
                    store: wgpu::StoreOp::Store,
                }),
                stencil_ops: None,
            }),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        })
    }

    /// Open the ink pass over the faces; depth is read, not written.
    pub fn begin_ink<'a>(
        &'a self,
        encoder: &'a mut wgpu::CommandEncoder,
        view: &'a wgpu::TextureView,
    ) -> wgpu::RenderPass<'a> {
        // at 4x the pass resolves into the canvas: each pixel's 4 samples are averaged into one
        let (target, resolve) = match self.msaa.as_deref() {
            Some(msaa) => (msaa, Some(view)),
            None => (view, None),
        };
        encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
            label: Some("visible ink pass"),
            color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                view: target,
                resolve_target: resolve,
                depth_slice: None,
                ops: wgpu::Operations {
                    load: wgpu::LoadOp::Load,
                    store: wgpu::StoreOp::Store,
                },
            })],
            depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
                view: &self.depth,
                depth_ops: None,
                stencil_ops: None,
            }),
            timestamp_writes: None,
            occlusion_query_set: None,
            multiview_mask: None,
        })
    }
}

/// Settings for one 2D texture.
pub struct TextureSpec {
    pub size: (u32, u32),            // width and height, px
    pub format: wgpu::TextureFormat, // pixel format
    pub samples: u32,                // MSAA samples
    pub usage: wgpu::TextureUsages,  // how the GPU may use it
}

/// Create a 2D texture from `spec`.
pub fn texture(ctx: &GpuCtx, label: &str, spec: &TextureSpec) -> wgpu::Texture {
    ctx.device.create_texture(&wgpu::TextureDescriptor {
        label: Some(label),
        size: wgpu::Extent3d {
            width: spec.size.0.max(1),
            height: spec.size.1.max(1),
            depth_or_array_layers: 1,
        },
        mip_level_count: 1,
        sample_count: spec.samples,
        dimension: wgpu::TextureDimension::D2,
        format: spec.format,
        usage: spec.usage,
        view_formats: &[],
    })
}

/// A texture and its view; dropping it frees the memory at once.
pub struct Attachment {
    texture: wgpu::Texture,
    pub view: wgpu::TextureView, // its default view
}

impl Attachment {
    /// Create a texture from `spec` and its default view.
    pub fn new(ctx: &GpuCtx, label: &str, spec: &TextureSpec) -> Self {
        let texture = texture(ctx, label, spec);
        let view = texture.create_view(&wgpu::TextureViewDescriptor::default());
        Self { texture, view }
    }

    /// The texture itself, for copies.
    pub fn texture(&self) -> &wgpu::Texture {
        &self.texture
    }

    /// Free the memory now; destroying twice is fine.
    pub fn destroy(&self) {
        self.texture.destroy();
    }
}

// Deref lets `&attachment` stand in for `&TextureView`, the way a smart pointer stands in for its value.
/// An Attachment can be used wherever a view is expected.
impl std::ops::Deref for Attachment {
    type Target = wgpu::TextureView;

    fn deref(&self) -> &wgpu::TextureView {
        &self.view
    }
}

/// Free the texture on drop.
impl Drop for Attachment {
    /// Rust runs this when the value goes out of scope.
    fn drop(&mut self) {
        self.texture.destroy();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The budget follows the GPU type, not the pixel count alone.
    #[test]
    fn msaa_follows_the_adapter() {
        let discrete = Targets::msaa_budget(wgpu::DeviceType::DiscreteGpu);
        let shared = Targets::msaa_budget(wgpu::DeviceType::IntegratedGpu);
        let software = Targets::msaa_budget(wgpu::DeviceType::Cpu);
        assert_eq!(
            Targets::samples_for(true, 3840 * 2160, None, discrete, 1.0),
            4
        );
        assert_eq!(
            Targets::samples_for(true, 3840 * 2160, None, shared, 1.0),
            1
        );
        assert_eq!(
            Targets::samples_for(true, 1920 * 1080, None, shared, 1.0),
            4
        );
        assert_eq!(Targets::samples_for(true, 1, None, software, 1.0), 1);
        assert_eq!(Targets::samples_for(false, 1, None, discrete, 1.0), 1);
        assert_eq!(
            Targets::samples_for(true, 3840 * 2160, Some(1), discrete, 1.0),
            1
        );
        assert_eq!(
            Targets::samples_for(false, u32::MAX, Some(4), software, 1.0),
            4
        );
        // device scale 2: 1x unless forced
        assert_eq!(
            Targets::samples_for(true, 1920 * 1080, None, discrete, 2.0),
            1
        );
        assert_eq!(
            Targets::samples_for(true, 1920 * 1080, None, discrete, 1.5),
            4
        );
        assert_eq!(
            Targets::samples_for(true, 1920 * 1080, Some(4), discrete, 2.0),
            4
        );
    }

    /// The unknown-GPU budget keeps 4x at 2560x1440 but not at 4K.
    #[test]
    fn the_browser_arm_is_not_the_integrated_one() {
        let browser = Targets::msaa_budget(wgpu::DeviceType::Other);
        let shared = Targets::msaa_budget(wgpu::DeviceType::IntegratedGpu);
        assert_eq!(
            Targets::samples_for(true, 2560 * 1440, None, browser, 1.0),
            4
        );
        assert_eq!(
            Targets::samples_for(true, 2560 * 1440, None, shared, 1.0),
            1
        );
        assert_eq!(
            Targets::samples_for(true, 3840 * 2160, None, browser, 1.0),
            1
        );
    }
}

use super::lane::LaneRows;
use super::objects::ObjectRows;
use session_rust::AABB;

/// Everything one file adds to the GPU, collected on the CPU first, so the GPU sees one write per buffer.
pub struct Upload {
    pub obj: ObjectRows,
    pub lanes: LaneRows,                 // rows of registered lanes, by type
    pub bounds: AABB,                    // world box: the camera fits to it
}

// By hand, since an empty box is AABB::empty(); a derived Default would be a point at the origin.
impl Default for Upload {
    fn default() -> Self {
        Self {
            obj: ObjectRows::default(),
            lanes: LaneRows::default(),
            bounds: AABB::empty(),
        }
    }
}

impl Upload {
    /// Free the rows once the GPU holds them.
    pub fn drop_uploaded(&mut self) {
        drop_rows(&mut self.obj.rows);
        self.lanes.clear();
        self.bounds = AABB::empty();
    }

    /// Move `other`'s rows after these; its vertex 0 lands on vertex `vert_base`.
    /// `mut other: Upload` takes it by value: the caller gives it away, so its lists can be moved out.
    pub fn merge(&mut self, mut other: Upload, vert_base: u32) {

        for lane in super::lane::REGISTRY {
            (lane.merge)(self, &mut other);
        }

        self.obj.rows.append(&mut other.obj.rows); // append moves every element and leaves `other` empty
        self.bounds.union_with(&other.bounds);
    }
}

/// A new empty Vec frees the old memory; `clear()` would empty the list but keep its capacity.
pub fn drop_rows<T>(v: &mut Vec<T>) {
    *v = Vec::new();
}

/// Display settings; most start from a `?query` or an env variable.
pub struct View {
    pub ssao: bool,               // ambient occlusion on
    pub show_grid: bool,          // floor grid
    pub show_points: bool,        // point markers, `Q`
    pub show_lines: bool,         // lines and curves, `W`
    pub show_mesh_edges: bool,    // mesh edges and their vertex markers, `E`
    pub show_outlines: bool,      // black outlines around surfaces, `O`
    pub markers: bool,            // vertex markers on mesh edges
    pub cloud_size: f32,          // point size scale, `[` and `]`
    pub edl_strength: f32,        // eye-dome lighting strength; 0 = off
    pub lod_px: f32,              // cloud LOD cutoff, px; 0 = draw every point
    pub thickness_px: f32,        // pen width, CSS px
    pub feather_px: f32,          // edge softness of dots, px
    pub lit: bool,                // headlight on mesh faces, `D`
    pub backface: bool,           // back faces painted red, `B`
    pub opacity: f32,             // face alpha; 0 = x-ray, `P` toggles
    pub msaa_forced: Option<u32>, // 4 forces 4x, other values 1x
    pub perf: bool,               // draw every frame and show timing
    pub spin: bool,               // orbit a little every frame
}

impl View {
    /// Arctic: ambient occlusion on, and the outlines with it.
    pub fn set_arctic(&mut self, on: bool) {
        self.ssao = on;
        if on {
            self.show_outlines = true;
        }
    }

    /// Read every setting once at start.
    pub fn from_env() -> Self {
        Self {
            ssao: false,
            show_grid: knob("VIEWER_NO_GRID", "nogrid").is_none(),
            show_points: true,
            show_lines: true,
            show_mesh_edges: true,
            show_outlines: knob("VIEWER_OUTLINES", "outlines").is_some(),
            markers: knob("BENCH_NO_MARKERS", "nomarkers").is_none(),
            cloud_size: knob_f32("VIEWER_CLOUD_SCALE", "cloud", 1.0),
            edl_strength: knob_f32("VIEWER_EDL", "edl", 0.25),
            lod_px: knob_f32("VIEWER_LOD", "lod", 0.0),
            thickness_px: knob_f32("VIEWER_THICKNESS", "thickness", 1.0).max(0.1),
            feather_px: knob_f32("VIEWER_AA", "aa", 1.0).clamp(0.5, 4.0),
            lit: knob("VIEWER_LIT", "lit").is_some(),
            backface: knob("VIEWER_BACKFACE", "backface").is_some(),
            opacity: knob_f32("VIEWER_OPACITY", "opacity", 1.0).clamp(0.0, 1.0),
            msaa_forced: knob_u32("VIEWER_MSAA", "msaa"),
            perf: knob("VIEWER_PERF", "perf").is_some(),
            spin: knob("VIEWER_SPIN", "spin").is_some(),
        }
    }
}

// Device pixel ratio = real pixels per CSS pixel: 2 on most phones and Retina screens.
/// Framebuffer pixels per CSS pixel, capped by `?dpr=`.
pub fn device_pixel_ratio() -> f64 {
    #[cfg(target_arch = "wasm32")]
    {
        let ratio = web_sys::window()
            .map(|window| window.device_pixel_ratio())
            .filter(|ratio| *ratio > 0.0)
            .unwrap_or(1.0);
        let cap = f64::from(knob_f32("VIEWER_DPR", "dpr", 0.0));
        let ratio = if cap >= 0.5 { ratio.min(cap) } else { ratio };

        if reduced() { ratio.min(1.0) } else { ratio }
    }
    #[cfg(not(target_arch = "wasm32"))]
    {
        1.0
    }
}

// A `static` lives for the whole program; an atomic can change without `mut` and without a lock.
/// True once the page dropped to device scale 1 without MSAA.
static REDUCED: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// Drop to device scale 1 without MSAA until reload.
pub fn reduce() {
    REDUCED.store(true, std::sync::atomic::Ordering::Relaxed);
}

/// True once `reduce` was called.
pub fn reduced() -> bool {
    REDUCED.load(std::sync::atomic::Ordering::Relaxed)
}

/// Canvas pixels per browser pixel; below 1 when `?dpr=` caps it.
pub fn surface_per_physical() -> f64 {
    #[cfg(target_arch = "wasm32")]
    {
        let browser = web_sys::window()
            .map(|window| window.device_pixel_ratio())
            .filter(|ratio| *ratio > 0.0)
            .unwrap_or(1.0);
        device_pixel_ratio() / browser
    }
    #[cfg(not(target_arch = "wasm32"))]
    {
        1.0
    }
}

// A knob is one setting read at start: `?msaa=4` in the page URL, `VIEWER_MSAA=4` in a native test.
/// One setting's text: `?query=` in the browser, `ENV` natively.
pub fn knob(env: &str, query: &str) -> Option<String> {
    #[cfg(target_arch = "wasm32")]
    {
        let _ = env;
        self::query(query)
    }
    #[cfg(not(target_arch = "wasm32"))]
    {
        let _ = query;
        std::env::var(env).ok()
    }
}

/// A float setting, or `default`.
fn knob_f32(env: &str, query: &str, default: f32) -> f32 {
    let Some(raw) = knob(env, query) else {
        return default;
    };

    match raw.parse::<f32>() {
        Ok(value) if value.is_finite() => value,
        _ => default,
    }
}

/// An integer setting, or None.
fn knob_u32(env: &str, query: &str) -> Option<u32> {
    knob(env, query)?.parse().ok() // `?` works on an Option too: None returns None
}

/// The `?name=` value of the page URL.
#[cfg(target_arch = "wasm32")]
pub fn query(name: &str) -> Option<String> {
    let search = web_sys::window()?.location().search().ok()?;
    let raw = search.strip_prefix('?')?;
    let prefix = format!("{name}=");

    for pair in raw.split('&') {
        if let Some(v) = pair.strip_prefix(prefix.as_str()) {
            return js_sys::decode_uri_component(v).ok()?.as_string();
        }

        if pair == name {
            return Some(String::new());
        }
    }

    None
}

// The engine draws; it knows nothing about files, clicks or commands.
pub mod gpu;
pub mod performance;
pub mod pipelines;

/// Frame timing, the drag quality tiers and the slow-interaction detector.
pub struct Performance {
    prev_frame: f64,       // time of the last frame, ms
    last_log: f64,         // time of the last log line, ms
    frame_ms: f64,         // smoothed frame time
    pub frames: u64,       // frames so far
    pub draws: u32,        // draw calls in the last frame
    pub interacting: bool, // a drag or pinch is in progress
    dragged: bool,         // the last frame was a drag frame too
    recent: Vec<f64>,      // the last drag frame times, ms, oldest first
    tier: u8,              // quality given up while dragging; kept for the next drag
    rough: bool,           // the last frame was drawn at a tier
    slow_run: u32,         // slow top-tier drag frames in a row
    slow: bool,            // the run reached SLOW_FRAMES; read once
    shown: bool,           // a frame with geometry was presented
}

/// Drag frames the tier decision takes the median of.
const TIER_WINDOW: usize = 5;

/// Drag frames a tier decision waits for, unless two already took TIER_WAIT_MS.
const TIER_MIN_FRAMES: usize = 3;

/// Drag time after which two frames are enough to decide.
const TIER_WAIT_MS: f64 = 150.0;

/// A median drag frame slower than this gives up the next tier.
const TIER_UP_MS: f64 = 33.0;

/// A median drag frame faster than this takes the last tier back.
const TIER_DOWN_MS: f64 = 20.0;

/// Tiers: 1 tests ink against planes alone, 2 also drops edge outlines.
pub const TOP_TIER: u8 = 2;

/// A top-tier drag frame slower than this is slow.
const SLOW_FRAME_MS: f64 = 100.0;

/// This many slow frames in a row mean the GPU cannot keep up.
const SLOW_FRAMES: u32 = 30;

impl Performance {
    /// Start the clock now.
    pub fn new() -> Self {
        let t = now_ms();
        Self {
            prev_frame: t,
            last_log: t,
            frame_ms: 0.0,
            frames: 0,
            draws: 0,
            interacting: false,
            dragged: false,
            recent: Vec::with_capacity(TIER_WINDOW + 1),
            tier: 0,
            rough: false,
            slow_run: 0,
            slow: false,
            shown: false,
        }
    }

    /// Mark the first frame and the first with geometry; names the mark due once the GPU is done.
    pub fn mark_startup(&mut self, geometry: bool) -> Option<&'static str> {
        let first = self.frames == 0;

        if first {
            mark("first frame");
        }

        if geometry && !self.shown {
            self.shown = true;
            mark("first geometry frame");
            return Some("geometry on screen");
        }

        first.then_some("first frame on screen")
    }

    /// True once when a run of slow frames was seen.
    pub fn take_slow_interaction(&mut self) -> bool {
        std::mem::take(&mut self.slow)
    }

    // Arctic = the ambient occlusion look (lesson 32); it trades frame rate for quality on purpose.
    /// Keep Arctic's chosen canvas scale and MSAA during sustained slow navigation.
    pub fn keep_arctic_quality(&mut self) {
        self.slow = false;
        self.slow_run = 0;
    }

    /// Quality tier for the frame being drawn: 0 at rest, the learned one while dragging.
    pub fn drag_tier(&self) -> u8 {
        if self.interacting { self.tier } else { 0 }
    }

    /// True when the last frame gave up quality, so the one after the drag must redraw.
    pub fn rough(&self) -> bool {
        self.rough
    }

    /// The frame just recorded gave up quality outside the tiers too.
    pub fn mark_rough(&mut self) {
        self.rough = true;
    }

    /// Record one frame; logs once a second when `perf` is on.
    pub fn frame(&mut self, draws: u32, objects: u32, now: f64, perf: bool) {
        let dt = now - self.prev_frame;
        self.prev_frame = now;
        self.frames += 1;
        self.draws = draws;
        self.rough = self.drag_tier() > 0;
        self.drag(dt);

        // smooth the frame time
        self.frame_ms = if self.frame_ms == 0.0 {
            dt
        } else {
            self.frame_ms * 0.9 + dt * 0.1
        };

        if perf && now - self.last_log >= 1000.0 {
            let fps = if self.frame_ms > 0.0 {
                1000.0 / self.frame_ms
            } else {
                0.0
            };
            log::info!(
                "perf: {:.1} fps | {:.2} ms | {} draws | {} objects | tier {} | wasm capacity {:.0} MiB",
                fps,
                self.frame_ms,
                draws,
                objects,
                self.tier,
                heap_mb()
            );
            self.last_log = now;
        }
    }

    /// Move the tier by the median of the last drag frames; `dt` ms since the frame before.
    fn drag(&mut self, dt: f64) {
        // the first frame of a drag timed the pause before it
        let timed = self.interacting && self.dragged;
        self.dragged = self.interacting;

        if !timed {
            self.recent.clear();
            self.slow_run = 0;
            return;
        }

        self.recent.push(dt);

        if self.recent.len() > TIER_WINDOW {
            self.recent.remove(0);
        }

        // only the top tier counts toward giving up MSAA and device scale
        self.slow_run = if self.tier == TOP_TIER && dt > SLOW_FRAME_MS {
            self.slow_run + 1
        } else {
            0
        };

        if self.slow_run == SLOW_FRAMES {
            self.slow = true;
        }

        // one long frame may be a pause in the drag, not a slow GPU
        let waited = self.recent.len() >= 2 && self.recent.iter().sum::<f64>() > TIER_WAIT_MS;

        if self.recent.len() < TIER_MIN_FRAMES && !waited {
            return;
        }

        let mut sorted = self.recent.clone();
        sorted.sort_by(f64::total_cmp);
        // half the frames must agree, so one pause among them decides nothing
        let slow = sorted[(sorted.len() - 1) / 2];
        let fast = sorted[sorted.len() / 2];

        if slow > TIER_UP_MS && self.tier < TOP_TIER {
            self.tier += 1;
            self.recent.clear();
        } else if fast < TIER_DOWN_MS && self.tier > 0 {
            self.tier -= 1;
            self.recent.clear();
        }
    }
}

/// Milliseconds now: `performance.now()` in the browser.
#[cfg(target_arch = "wasm32")]
pub fn now_ms() -> f64 {
    web_sys::window().unwrap().performance().unwrap().now()
}

/// A startup milestone on the browser timeline, with the pipelines and shaders made so far.
#[cfg(target_arch = "wasm32")]
pub fn mark(name: &str) {
    if let Some(performance) = web_sys::window().and_then(|window| window.performance()) {
        let _ = performance.mark(name);
    }

    let (pipelines, shaders) = crate::engine::pipelines::created();
    log::info!("{name}: {pipelines} pipelines, {shaders} shaders");
}

/// A startup milestone: time since the first one, with the pipelines and shaders made so far.
#[cfg(not(target_arch = "wasm32"))]
pub fn mark(name: &str) {
    // a `static` OnceLock is set once, on first use, and shared for the program's life
    static START: std::sync::OnceLock<std::time::Instant> = std::sync::OnceLock::new();
    let ms = START
        .get_or_init(std::time::Instant::now)
        .elapsed()
        .as_secs_f64()
        * 1000.0;
    let (pipelines, shaders) = crate::engine::pipelines::created();
    log::info!("{name}: {ms:.1} ms, {pipelines} pipelines, {shaders} shaders");
}

/// Milliseconds now: the system clock natively.
#[cfg(not(target_arch = "wasm32"))]
pub fn now_ms() -> f64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_secs_f64()
        * 1000.0
}

/// WASM memory size in MiB.
#[cfg(target_arch = "wasm32")]
pub fn heap_mb() -> f64 {
    use wasm_bindgen::JsCast;
    let Ok(memory) = wasm_bindgen::memory().dyn_into::<js_sys::WebAssembly::Memory>() else {
        return 0.0;
    };
    memory
        .buffer()
        .unchecked_into::<js_sys::ArrayBuffer>()
        .byte_length() as f64
        / 1.048576e6
}

/// Process resident memory in MiB, Linux.
#[cfg(all(not(target_arch = "wasm32"), target_os = "linux"))]
pub fn heap_mb() -> f64 {
    let Ok(stats) = std::fs::read_to_string("/proc/self/statm") else {
        return 0.0;
    };
    let Some(resident) = stats.split_whitespace().nth(1) else {
        return 0.0;
    };

    match resident.parse::<f64>() {
        Ok(pages) => pages * 4096.0 / 1.048576e6,
        Err(_) => 0.0,
    }
}

/// Native, non-Linux: no cheap measure.
#[cfg(all(not(target_arch = "wasm32"), not(target_os = "linux")))]
pub fn heap_mb() -> f64 {
    0.0
}

/// Show one line of text in the page's top-left corner.
#[cfg(target_arch = "wasm32")]
pub fn perf_line(text: &str) {
    let Some(window) = web_sys::window() else {
        return;
    };
    let Some(doc) = window.document() else { return };
    let el = match doc.get_element_by_id("perf") {
        Some(e) => e,
        None => {
            let Ok(e) = doc.create_element("pre") else {
                return;
            };
            e.set_id("perf");
            let _ = e.set_attribute("style", "position:fixed;left:0;top:0;margin:0;padding:2px 6px;font:12px monospace;color:#000;background:rgba(255,255,255,.7);z-index:9;pointer-events:none");

            if let Some(b) = doc.body() {
                let _ = b.append_child(&e);
            }

            e
        }
    };
    el.set_text_content(Some(text));
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Feed `count` frames `step_ms` apart; true if a slow run fired.
    fn frames(perf: &mut Performance, count: u32, step_ms: f64, interacting: bool) -> bool {
        perf.interacting = interacting;
        let mut now = perf.prev_frame;
        let mut slow = false;

        for _ in 0..count {
            now += step_ms;
            perf.frame(1, 1, now, false);
            slow |= perf.take_slow_interaction();
        }

        slow
    }

    #[test]
    /// Slow drag frames give up a tier within three frames; fast ones take it back.
    fn slow_drags_step_through_the_tiers() {
        let mut perf = Performance::new();
        frames(&mut perf, 100, 60.0, false);
        assert_eq!(perf.drag_tier(), 0, "idle gaps are not slow frames");
        // the first drag frame timed the pause before it
        frames(&mut perf, 3, 45.0, true);
        assert_eq!(perf.drag_tier(), 0, "two timed frames are too few");
        frames(&mut perf, 1, 45.0, true);
        assert_eq!(
            perf.drag_tier(),
            1,
            "three slow frames: 135 ms to the first tier"
        );
        frames(&mut perf, 3, 45.0, true);
        assert_eq!(perf.drag_tier(), TOP_TIER);
        frames(&mut perf, 20, 45.0, true);
        assert_eq!(perf.drag_tier(), TOP_TIER, "no tier above the top one");
        assert!(perf.rough(), "the last drag frame gave up quality");
        frames(&mut perf, 1, 16.7, false);
        assert_eq!(perf.drag_tier(), 0, "at rest every frame is full quality");
        assert!(!perf.rough(), "the frame after the drag is full quality");
        frames(&mut perf, 1, 16.7, true);
        assert_eq!(
            perf.drag_tier(),
            TOP_TIER,
            "the next drag starts at the learned tier"
        );
        frames(&mut perf, 30, 25.0, true);
        assert_eq!(
            perf.drag_tier(),
            TOP_TIER,
            "between the thresholds the tier holds"
        );
        frames(&mut perf, 3, 16.7, true);
        assert_eq!(perf.drag_tier(), 1, "fast frames take a tier back");
        frames(&mut perf, 3, 16.7, true);
        assert_eq!(perf.drag_tier(), 0);
        // very slow frames decide sooner
        frames(&mut perf, 1, 16.7, false);
        frames(&mut perf, 2, 100.0, true);
        assert_eq!(perf.drag_tier(), 0, "one 100 ms frame is too little");
        frames(&mut perf, 1, 100.0, true);
        assert_eq!(
            perf.drag_tier(),
            1,
            "two 100 ms frames: 200 ms to the first tier"
        );
        frames(&mut perf, 1, 400.0, true);
        assert_eq!(perf.drag_tier(), 1, "one long frame may be a pause");
        frames(&mut perf, 1, 400.0, true);
        assert_eq!(perf.drag_tier(), 2, "two 400 ms frames are enough");
    }

    #[test]
    /// A pause in a fast drag is one long frame, not a slow GPU.
    fn a_pause_in_a_fast_drag_keeps_full_quality() {
        let mut perf = Performance::new();
        frames(&mut perf, 2, 16.7, true);
        frames(&mut perf, 1, 400.0, true);
        assert_eq!(perf.drag_tier(), 0, "a pause after the first frames");
        frames(&mut perf, 20, 16.7, true);
        frames(&mut perf, 1, 400.0, true);
        frames(&mut perf, 20, 16.7, true);
        assert_eq!(perf.drag_tier(), 0, "a pause mid-drag");
        frames(&mut perf, 1, 16.7, false);
        frames(&mut perf, 1, 16.7, true);
        frames(&mut perf, 1, 400.0, true);
        frames(&mut perf, 3, 16.7, true);
        assert_eq!(
            perf.drag_tier(),
            0,
            "a pause after the first frame of a drag"
        );
    }

    #[test]
    /// Only a run of slow frames at the top tier fires, and only once.
    fn slow_interaction_needs_a_run_of_slow_top_tier_frames() {
        let mut perf = Performance::new();
        assert!(
            !frames(&mut perf, 100, 150.0, false),
            "idle gaps are not slow frames"
        );
        assert!(!frames(&mut perf, 100, 16.7, true), "a smooth drag is fine");
        // reach the top tier first
        assert!(!frames(&mut perf, 6, 150.0, true));
        assert_eq!(perf.drag_tier(), TOP_TIER);
        assert!(
            !frames(&mut perf, 1, 40.0, true),
            "a faster frame resets the run"
        );
        assert!(
            !frames(&mut perf, SLOW_FRAMES - 1, 150.0, true),
            "one frame short of the run"
        );
        assert!(
            !frames(&mut perf, 1, 40.0, true),
            "a faster frame resets the run"
        );
        assert!(frames(&mut perf, SLOW_FRAMES, 150.0, true), "the run fires");
        assert!(!frames(&mut perf, 10, 150.0, true), "and fires once");
    }

    #[test]
    fn arctic_keeps_canvas_quality_through_a_slow_drag() {
        let mut perf = Performance::new();
        perf.interacting = true;
        let mut now = perf.prev_frame;
        for _ in 0..SLOW_FRAMES * 2 {
            now += 150.0;
            perf.frame(1, 1, now, false);
            perf.keep_arctic_quality();
            assert!(!perf.take_slow_interaction());
        }
        assert_eq!(perf.drag_tier(), TOP_TIER);
        assert!(
            frames(&mut perf, SLOW_FRAMES, 150.0, true),
            "normal fallback resumes after Arctic is off"
        );
    }
}

/// One buffer binding without a dynamic offset or a minimum binding size.
pub(crate) fn buffer_entry(
    binding: u32,
    visibility: wgpu::ShaderStages,
    ty: wgpu::BufferBindingType,
) -> wgpu::BindGroupLayoutEntry {
    wgpu::BindGroupLayoutEntry {
        binding,
        visibility,
        ty: wgpu::BindingType::Buffer {
            ty,
            has_dynamic_offset: false,
            min_binding_size: None,
        },
        count: None,
    }
}

/// One two-dimensional texture binding.
pub(crate) fn texture_entry(
    binding: u32,
    visibility: wgpu::ShaderStages,
    sample_type: wgpu::TextureSampleType,
    multisampled: bool,
) -> wgpu::BindGroupLayoutEntry {
    wgpu::BindGroupLayoutEntry {
        binding,
        visibility,
        ty: wgpu::BindingType::Texture {
            sample_type,
            view_dimension: wgpu::TextureViewDimension::D2,
            multisampled,
        },
        count: None,
    }
}

// A bind group layout is the type of a bind group: which binding holds a uniform, a storage buffer or a texture, and which shader stages see it.
/// One buffer binding, visible to `stages`.
use crate::engine::pipelines::bindings::{buffer_entry, texture_entry};
use wgpu::{BufferBindingType, ShaderStages, TextureSampleType};

/// A read-only storage buffer at `binding`, for the vertex stage.
fn storage_entry(binding: u32) -> wgpu::BindGroupLayoutEntry {
    buffer_entry(
        binding,
        ShaderStages::VERTEX,
        BufferBindingType::Storage { read_only: true },
    )
}

/// A layout with one uniform buffer at binding 0.
fn uniform_layout(
    device: &wgpu::Device,
    label: &str,
    stages: wgpu::ShaderStages,
) -> wgpu::BindGroupLayout {
    device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some(label),
        entries: &[buffer_entry(0, stages, BufferBindingType::Uniform)],
    })
}

/// Group 1: pen and view settings at binding 0, clipping planes at 1.
fn line_layout(device: &wgpu::Device) -> wgpu::BindGroupLayout {
    let stages = ShaderStages::VERTEX_FRAGMENT | ShaderStages::COMPUTE;
    device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("line.layout"),
        entries: &[
            buffer_entry(0, stages, BufferBindingType::Uniform),
            buffer_entry(1, stages, BufferBindingType::Uniform),
        ],
    })
}

/// Group 2: object rows at binding 0, translations at 1.
fn instance_layout(device: &wgpu::Device) -> wgpu::BindGroupLayout {
    device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("instance.layout"),
        entries: &[
            buffer_entry(
                0,
                ShaderStages::VERTEX | ShaderStages::COMPUTE,
                BufferBindingType::Storage { read_only: true },
            ),
            buffer_entry(
                1,
                ShaderStages::VERTEX | ShaderStages::COMPUTE,
                BufferBindingType::Storage { read_only: true },
            ),
        ],
    })
}

/// A depth texture binding for the fragment stage.
fn scene_depth(binding: u32, multisampled: bool) -> wgpu::BindGroupLayoutEntry {
    texture_entry(
        binding,
        ShaderStages::FRAGMENT,
        TextureSampleType::Depth,
        multisampled,
    )
}

/// A triangle id texture binding for the fragment stage.
fn scene_gradient(binding: u32, multisampled: bool) -> wgpu::BindGroupLayoutEntry {
    texture_entry(
        binding,
        ShaderStages::FRAGMENT,
        TextureSampleType::Uint,
        multisampled,
    )
}

/// Bind group 2 for ink: rows, depths, triangle ids, triangles, tiles.
fn ink_instance_layout(device: &wgpu::Device) -> wgpu::BindGroupLayout {
    device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("ink.instance.layout"),
        entries: &[
            buffer_entry(
                0,
                ShaderStages::VERTEX_FRAGMENT,
                BufferBindingType::Storage { read_only: true },
            ),
            buffer_entry(
                1,
                ShaderStages::VERTEX_FRAGMENT,
                BufferBindingType::Storage { read_only: true },
            ),
            scene_depth(2, false),
            scene_depth(3, true),
            scene_gradient(4, false),
            scene_gradient(5, true),
            buffer_entry(
                6,
                ShaderStages::FRAGMENT,
                BufferBindingType::Storage { read_only: true },
            ),
            buffer_entry(
                7,
                ShaderStages::FRAGMENT,
                BufferBindingType::Storage { read_only: true },
            ),
        ],
    })
}

/// Group 3 for markers and dots: one row table.
fn ink_rows_layout(device: &wgpu::Device) -> wgpu::BindGroupLayout {
    device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("ink.rows.layout"),
        entries: &[buffer_entry(
            0,
            ShaderStages::VERTEX_FRAGMENT,
            BufferBindingType::Storage { read_only: true },
        )],
    })
}

/// Group 3 for lines: rows, source edge ids, selected edge.
fn segment_rows_layout(device: &wgpu::Device) -> wgpu::BindGroupLayout {
    device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("segment.rows.layout"),
        entries: &[
            storage_entry(0),
            storage_entry(1),
            buffer_entry(2, ShaderStages::VERTEX, BufferBindingType::Uniform),
        ],
    })
}

/// Group 1 for points: records, positions, colors, normals.
fn points_layout(device: &wgpu::Device) -> wgpu::BindGroupLayout {
    device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("points.layout"),
        entries: &[
            storage_entry(0),
            storage_entry(1),
            storage_entry(2),
            storage_entry(3),
        ],
    })
}

/// Group 1 for the point resolve: depth and color textures.
fn resolve_layout(device: &wgpu::Device) -> wgpu::BindGroupLayout {
    device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
        label: Some("splat.resolve.layout"),
        entries: &[
            texture_entry(0, ShaderStages::FRAGMENT, TextureSampleType::Depth, false),
            texture_entry(
                1,
                ShaderStages::FRAGMENT,
                TextureSampleType::Float { filterable: false },
                false,
            ),
        ],
    })
}

/// The bind group layouts every lane shares.
pub struct Layouts {
    pub mvp: wgpu::BindGroupLayout,          // group 0: camera matrix
    pub line: wgpu::BindGroupLayout,         // group 1: pen and view settings, clipping planes
    pub instance: wgpu::BindGroupLayout,     // group 2: object rows
    pub ink_instance: wgpu::BindGroupLayout, // group 2 for ink, with depth textures
    pub ink_rows: wgpu::BindGroupLayout,     // group 3 for markers and dots
    pub segment_rows: wgpu::BindGroupLayout, // group 3 for lines
    pub points: wgpu::BindGroupLayout,       // group 1 for points
    pub resolve: wgpu::BindGroupLayout,      // group 1 for the point resolve
}

impl Layouts {
    /// Build every layout once.
    pub fn new(device: &wgpu::Device) -> Self {
        Self {
            mvp: uniform_layout(
                device,
                "mvp.layout",
                ShaderStages::VERTEX_FRAGMENT | ShaderStages::COMPUTE,
            ),
            line: line_layout(device),
            instance: instance_layout(device),
            ink_instance: ink_instance_layout(device),
            ink_rows: ink_rows_layout(device),
            segment_rows: segment_rows_layout(device),
            points: points_layout(device),
            resolve: resolve_layout(device),
        }
    }
}

pub(crate) mod bindings;
pub mod layouts;

pub use layouts::Layouts; // `pub use` re-exports: other files write `pipelines::Layouts`

use crate::engine::gpu::buffers::GpuCtx;
use std::cell::{Cell, LazyCell, RefCell};
use std::collections::HashMap;
use std::hash::{Hash, Hasher};
use std::rc::Rc;

// `thread_local!` = a global, one per thread; `Cell` lets it change through a shared reference. The browser runs one thread.
thread_local! {
    /// Render and compute pipelines compiled on this thread so far.
    static PIPELINES: Cell<u32> = const { Cell::new(0) };

    /// Shader modules compiled on this thread so far.
    static SHADERS: Cell<u32> = const { Cell::new(0) };
}

/// Count one compiled pipeline.
pub fn count_pipeline() {
    PIPELINES.set(PIPELINES.get() + 1);
}

/// Count one compiled shader module.
pub fn count_shader() {
    SHADERS.set(SHADERS.get() + 1);
}

/// (pipelines, shader modules) compiled on this thread so far.
pub fn created() -> (u32, u32) {
    (PIPELINES.get(), SHADERS.get())
}

// `Rc` = shared ownership, freed when the last clone is dropped; `LazyCell` runs its closure on first use and keeps the result.
// `Box<dyn FnOnce() -> T>` = any closure that runs once, whatever its concrete type, kept on the heap.
/// A GPU object made on its first use; clones share it, and equal means the same one.
pub struct Lazy<T>(Rc<LazyCell<T, Box<dyn FnOnce() -> T>>>);

impl<T> Lazy<T> {
    /// Made by `make` when first used.
    // `impl FnOnce() -> T` accepts any closure of that shape; `'static` = it borrows nothing that could be dropped first.
    pub fn new(make: impl FnOnce() -> T + 'static) -> Self {
        Self(Rc::new(LazyCell::new(Box::new(make))))
    }
}

impl<T> Clone for Lazy<T> {
    fn clone(&self) -> Self {
        Self(Rc::clone(&self.0))
    }
}

impl<T> std::ops::Deref for Lazy<T> {
    type Target = T;

    /// The object, made now if this is its first use.
    fn deref(&self) -> &T {
        LazyCell::force(&self.0)
    }
}

impl<T> PartialEq for Lazy<T> {
    fn eq(&self, other: &Self) -> bool {
        Rc::ptr_eq(&self.0, &other.0)
    }
}

impl<T> Eq for Lazy<T> {}

impl<T> Hash for Lazy<T> {
    fn hash<H: Hasher>(&self, state: &mut H) {
        Rc::as_ptr(&self.0).hash(state);
    }
}

/// A render pipeline, compiled when a pass first sets it.
pub type Pipeline = Lazy<wgpu::RenderPipeline>;

/// A shader module, compiled when a pipeline first needs it.
pub type Shader = Lazy<wgpu::ShaderModule>;

// `RefCell` moves the borrow check to run time, so methods on `&self` can still insert.
// `#[derive(Default)]` writes the Default impl for us: every field starts empty.
/// Shaders, layouts and pipelines by description: asking again, or a second lane of the same
/// kind asking, returns the first one, so an MSAA flip back and forth compiles nothing twice.
#[derive(Default)]
pub struct Cache {
    shaders: RefCell<HashMap<ShaderKey, Shader>>, // by label and source digest
    layouts: RefCell<HashMap<LayoutKey, wgpu::BindGroupLayout>>, // by label and entries
    pipelines: RefCell<HashMap<PipelineKey, Pipeline>>, // by everything they compile from
    pub clipping: Cell<bool>, // a plane cuts: ink pipelines built now keep their clip tests
}

impl Cache {
    /// Compile every pipeline asked for so far; returns how many there are.
    pub fn compile_all(&self) -> usize {
        let pipelines = self.pipelines.borrow();

        for pipeline in pipelines.values() {
            let _: &wgpu::RenderPipeline = pipeline;
        }

        pipelines.len()
    }
}

/// A shader's label, source length and source hash: the text itself is not kept.
type ShaderKey = (String, usize, u64);

/// A bind group layout's label and entries.
type LayoutKey = (String, Vec<wgpu::BindGroupLayoutEntry>);

/// Everything a render pipeline compiles from, owned, so the compile can wait for its first use.
#[derive(Clone, PartialEq, Eq, Hash)]
struct PipelineKey {
    label: String,                      // name shown in GPU errors
    shader: Shader,                     // vertex and fragment code
    vs: String,                         // vertex entry point
    fs: String,                         // fragment entry point
    groups: Vec<wgpu::BindGroupLayout>, // bind group layouts, in slot order
    buffers: Vec<(u64, wgpu::VertexStepMode, Vec<wgpu::VertexAttribute>)>, // vertex buffer layouts
    topology: wgpu::PrimitiveTopology,  // triangles or lines
    color: ColorWrite,                  // how color is written
    depth: DepthMode,                   // how depth is used
    scene_samples: Option<u32>,         // sets SCENE_MSAA in the shader
    clipping: Option<bool>,             // sets CLIPPING in an ink shader
    physical: bool,                     // also writes the triangle id target
    masks: bool,                        // writes both outline masks
    target: Target,                     // color format and samples
}

/// Where a pipeline draws: color format and MSAA sample count.
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub struct Target {
    pub format: wgpu::TextureFormat, // color format
    pub samples: u32,                // MSAA samples
}

impl Target {
    /// The id pass target: two u32 per pixel, no MSAA.
    pub const ID: Target = Target {
        format: wgpu::TextureFormat::Rg32Uint,
        samples: 1,
    };
}

/// How a pipeline uses depth; reverse-Z, so nearer is greater.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum DepthMode {
    Opaque,        // write, nearer wins
    OpaqueEqual,   // write, nearer or equal wins
    ReadOnly,      // test only, nearer wins
    ReadOnlyEqual, // test only, nearer or equal wins
    Always,        // no test, no write
    Detached,      // no depth attachment at all
}

impl DepthMode {
    /// The (write, compare) pair wgpu wants.
    fn state(self) -> (bool, wgpu::CompareFunction) {
        match self {
            DepthMode::Opaque => (true, wgpu::CompareFunction::Greater),
            DepthMode::OpaqueEqual => (true, wgpu::CompareFunction::GreaterEqual),
            DepthMode::ReadOnly => (false, wgpu::CompareFunction::Greater),
            DepthMode::ReadOnlyEqual => (false, wgpu::CompareFunction::GreaterEqual),
            DepthMode::Always | DepthMode::Detached => (false, wgpu::CompareFunction::Always),
        }
    }
}

/// How a pipeline writes color.
#[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
pub enum ColorWrite {
    Opaque,  // overwrite
    Blended, // alpha blend
    Max,     // keep the larger value; for masks
    Add,     // add to the value; for counts
    Nothing, // write nothing; the fragment shader has side effects
}

impl ColorWrite {
    /// The (blend, write mask) pair wgpu wants.
    fn state(self) -> (Option<wgpu::BlendState>, wgpu::ColorWrites) {
        match self {
            ColorWrite::Opaque => (None, wgpu::ColorWrites::ALL),
            ColorWrite::Blended => (
                Some(wgpu::BlendState::ALPHA_BLENDING),
                wgpu::ColorWrites::ALL,
            ),
            ColorWrite::Nothing => (None, wgpu::ColorWrites::empty()),
            ColorWrite::Add => {
                let add = wgpu::BlendComponent {
                    src_factor: wgpu::BlendFactor::One,
                    dst_factor: wgpu::BlendFactor::One,
                    operation: wgpu::BlendOperation::Add,
                };
                (
                    Some(wgpu::BlendState {
                        color: add,
                        alpha: add,
                    }),
                    wgpu::ColorWrites::ALL,
                )
            }
            ColorWrite::Max => {
                let max = wgpu::BlendComponent {
                    src_factor: wgpu::BlendFactor::One,
                    dst_factor: wgpu::BlendFactor::One,
                    operation: wgpu::BlendOperation::Max,
                };
                (
                    Some(wgpu::BlendState {
                        color: max,
                        alpha: max,
                    }),
                    wgpu::ColorWrites::ALL,
                )
            }
        }
    }
}

/// Everything `build` needs for one render pipeline.
#[derive(Clone)]
pub struct PipelineDesc<'a> {
    pub label: &'a str,                                     // name shown in GPU errors
    pub shader: &'a Shader,                                 // vertex and fragment code
    pub vs: &'a str,                                        // vertex entry point
    pub fs: &'a str,                                        // fragment entry point
    pub groups: &'a [&'a wgpu::BindGroupLayout],            // bind group layouts, in slot order
    pub vertex_buffers: &'a [wgpu::VertexBufferLayout<'a>], // vertex buffer layouts
    pub topology: wgpu::PrimitiveTopology,                  // triangles or lines
    pub color: ColorWrite,                                  // how color is written
    pub depth: DepthMode,                                   // how depth is used
    pub scene_samples: Option<u32>,                         // sets SCENE_MSAA in the shader
    pub physical: bool,                                     // also writes the triangle id target
    pub masks: bool, // writes both outline masks with MAX blending
}

impl<'a> PipelineDesc<'a> {
    /// A base: `vs_main`, `fs_main`, opaque color, opaque depth.
    pub fn new(
        shader: &'a Shader,
        groups: &'a [&'a wgpu::BindGroupLayout],
        vertex_buffers: &'a [wgpu::VertexBufferLayout<'a>],
        topology: wgpu::PrimitiveTopology,
    ) -> Self {
        Self {
            label: "",
            shader,
            vs: "vs_main",
            fs: "fs_main",
            groups,
            vertex_buffers,
            topology,
            color: ColorWrite::Opaque,
            depth: DepthMode::Opaque,
            scene_samples: None,
            physical: false,
            masks: false,
        }
    }

    /// A copy with another label and fragment entry point.
    pub fn with(&self, label: &'a str, fs: &'a str) -> Self {
        let mut d = self.clone();
        d.label = label;
        d.fs = fs;
        d
    }

    // Each method takes `self` by value and returns it, so the calls chain: `base.with(..).depth(..)`.
    /// A copy with another vertex entry point.
    pub fn vertex(mut self, vs: &'a str) -> Self {
        self.vs = vs;
        self
    }

    /// A copy with another color mode.
    pub fn color(mut self, color: ColorWrite) -> Self {
        self.color = color;
        self
    }

    /// A copy that reads the scene depth at `samples`.
    pub fn scene_samples(mut self, samples: u32) -> Self {
        self.scene_samples = Some(samples);
        self
    }

    /// A copy that also writes the triangle id target.
    pub fn physical(mut self) -> Self {
        self.physical = true;
        self
    }

    /// A copy that writes both outline masks.
    pub fn masks(mut self) -> Self {
        self.masks = true;
        self
    }

    /// A copy with another depth mode.
    pub fn depth(mut self, depth: DepthMode) -> Self {
        self.depth = depth;
        self
    }
}

// WGSL has no `import`: shared code is pasted after each shader's own text.
// `shader!` (lib.rs) pastes the minified file in at compile time.
/// Shared WGSL: groups 0-2, Instance, LineUniform, flags, `place`.
pub const SCENE: &str = shader!("scene.wgsl");
pub const CLIP: &str = shader!("clip.wgsl"); // clipping planes, the includer binds `clipping`; register:meshes

/// WGSL every scene shader ends with. A shared snippet is one file and one line here.
pub const PRELUDE: &[&str] = &[
    SCENE, // register:scene
    CLIP,  // register:clip
];

/// A scene shader's full text: its own code, then the prelude.
pub fn scene_source(source: &str) -> String {
    PRELUDE
        .iter()
        .fold(source.to_owned(), |text, part| format!("{text}\n{part}"))
}

/// A shader with the shared scene and clipping code appended.
pub fn scene_module(ctx: &GpuCtx, label: &str, source: &str) -> Shader {
    module(ctx, label, &scene_source(source))
}

// A vertex buffer layout tells the pipeline how to cut a buffer into vertices: the stride, and which bytes feed which @location.
/// One u32 at location 3: the object row.
const INSTANCE_ID_ATTRIBS: [wgpu::VertexAttribute; 1] = [wgpu::VertexAttribute {
    offset: 0,
    shader_location: 3,
    format: wgpu::VertexFormat::Uint32,
}];

/// One vec3 at location 0: a template position.
const TEMPLATE_ATTRIBS: [wgpu::VertexAttribute; 1] = [wgpu::VertexAttribute {
    offset: 0,
    shader_location: 0,
    format: wgpu::VertexFormat::Float32x3,
}];

/// Vertex slot 1: one object row per vertex.
pub fn instance_id_layout() -> wgpu::VertexBufferLayout<'static> {
    wgpu::VertexBufferLayout {
        array_stride: 4,
        step_mode: wgpu::VertexStepMode::Vertex,
        attributes: &INSTANCE_ID_ATTRIBS,
    }
}

/// Vertex slot 0 for the marker quad: positions only.
pub fn template_layout() -> wgpu::VertexBufferLayout<'static> {
    wgpu::VertexBufferLayout {
        array_stride: 12,
        step_mode: wgpu::VertexStepMode::Vertex,
        attributes: &TEMPLATE_ATTRIBS,
    }
}

/// Append the WGSL every shader ends with: normals and physical output.
pub fn shared(source: &str) -> String {
    format!(
        "{source}\n{}\n{}",
        shader!("normals.wgsl"),
        shader!("physical.wgsl")
    )
}

/// A shader that declares its own bindings.
pub fn module(ctx: &GpuCtx, label: &str, source: &str) -> Shader {
    wgsl(ctx, label, shared(source))
}

// A shader module is WGSL compiled for this GPU; compiling is slow, so each text compiles once, on first use.
/// The shader for exactly `source`: one per label and source, compiled on first use.
pub fn wgsl(ctx: &GpuCtx, label: &str, source: String) -> Shader {
    let mut hasher = std::hash::DefaultHasher::new();
    source.hash(&mut hasher);
    let key = (label.to_string(), source.len(), hasher.finish());
    let mut shaders = ctx.cache.shaders.borrow_mut();

    if let Some(shader) = shaders.get(&key) {
        return shader.clone();
    }

    let device = ctx.device.clone();
    let (name, text) = (label.to_string(), source);
    let shader = Shader::new(move || {
        count_shader();
        device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some(&name),
            source: wgpu::ShaderSource::Wgsl(text.into()),
        })
    });
    shaders.insert(key, shader.clone());
    shader
}

/// A bind group layout: one per label and entries.
pub fn layout(
    ctx: &GpuCtx,
    label: &str,
    entries: &[wgpu::BindGroupLayoutEntry],
) -> wgpu::BindGroupLayout {
    ctx.cache
        .layouts
        .borrow_mut()
        .entry((label.to_string(), entries.to_vec()))
        .or_insert_with(|| {
            ctx.device
                .create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
                    label: Some(label),
                    entries,
                })
        })
        .clone()
}

/// A pipeline layout over `groups`, in slot order.
pub fn pipeline_layout(
    device: &wgpu::Device,
    label: &str,
    groups: &[&wgpu::BindGroupLayout],
) -> wgpu::PipelineLayout {
    let mut slots: Vec<Option<&wgpu::BindGroupLayout>> = Vec::with_capacity(groups.len());

    for g in groups {
        slots.push(Some(*g));
    }

    device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
        label: Some(label),
        bind_group_layouts: &slots,
        immediate_size: 0,
    })
}

// A render pipeline is the fixed recipe for one kind of draw: shaders, vertex layout, blending, depth test and sample count.
/// One render pipeline; Depth32Float, no culling, fill mode. It compiles on first use, and a
/// second request for the same description gets the same pipeline.
pub fn build(ctx: &GpuCtx, target: Target, desc: &PipelineDesc) -> Pipeline {
    let key = PipelineKey {
        label: desc.label.to_string(),
        shader: desc.shader.clone(),
        vs: desc.vs.to_string(),
        fs: desc.fs.to_string(),
        groups: desc.groups.iter().map(|group| (*group).clone()).collect(),
        buffers: desc
            .vertex_buffers
            .iter()
            .map(|b| (b.array_stride, b.step_mode, b.attributes.to_vec()))
            .collect(),
        topology: desc.topology,
        color: desc.color,
        depth: desc.depth,
        scene_samples: desc.scene_samples,
        // ink pipelines are rebuilt on every retarget, so they alone may drop their clip tests
        clipping: desc.scene_samples.map(|_| ctx.cache.clipping.get()),
        physical: desc.physical,
        masks: desc.masks,
        target,
    };
    let mut pipelines = ctx.cache.pipelines.borrow_mut();

    if let Some(pipeline) = pipelines.get(&key) {
        return pipeline.clone();
    }

    let device = ctx.device.clone();
    let desc = key.clone();
    let pipeline = Pipeline::new(move || compile(&device, &desc));
    pipelines.insert(key, pipeline.clone());
    pipeline
}

/// Compile the pipeline `desc` describes.
fn compile(device: &wgpu::Device, desc: &PipelineKey) -> wgpu::RenderPipeline {
    let groups: Vec<&wgpu::BindGroupLayout> = desc.groups.iter().collect();
    let layout = pipeline_layout(device, &desc.label, &groups);
    let buffers: Vec<wgpu::VertexBufferLayout> = desc
        .buffers
        .iter()
        .map(|(stride, step, attributes)| wgpu::VertexBufferLayout {
            array_stride: *stride,
            step_mode: *step,
            attributes,
        })
        .collect();
    let target = desc.target;
    let (depth_write, depth_compare) = desc.depth.state();
    let (blend, write_mask) = desc.color.state();
    let mut targets = vec![Some(wgpu::ColorTargetState {
        format: target.format,
        blend,
        write_mask,
    })];

    // two mask targets with MAX blending
    if desc.masks {
        let max = wgpu::BlendComponent {
            src_factor: wgpu::BlendFactor::One,
            dst_factor: wgpu::BlendFactor::One,
            operation: wgpu::BlendOperation::Max,
        };
        let coverage = Some(wgpu::ColorTargetState {
            format: target.format,
            blend: Some(wgpu::BlendState {
                color: max,
                alpha: max,
            }),
            write_mask: wgpu::ColorWrites::ALL,
        });
        targets = vec![coverage.clone(), coverage];
    }

    // the triangle id target
    if desc.physical {
        targets.push(Some(wgpu::ColorTargetState {
            format: wgpu::TextureFormat::Rg16Uint,
            blend: None,
            // a ReadOnlyEqual pass already wrote it: declare, do not write
            write_mask: if desc.depth == DepthMode::ReadOnlyEqual {
                wgpu::ColorWrites::empty()
            } else {
                wgpu::ColorWrites::ALL
            },
        }));
    }

    // override constants: values the WGSL declares with `override` and the pipeline fixes when it compiles
    let mut constants = Vec::new();

    // shader constant: which depth texture is live
    if let Some(samples) = desc.scene_samples {
        constants.push(("SCENE_MSAA", f64::from(samples > 1)));
    }

    // shader constant: no plane cuts, so the clip tests compile away
    if let Some(clipping) = desc.clipping {
        constants.push(("CLIPPING", f64::from(clipping)));
    }

    count_pipeline();
    device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
        label: Some(&desc.label),
        layout: Some(&layout),
        vertex: wgpu::VertexState {
            module: &desc.shader,
            entry_point: Some(&desc.vs),
            buffers: &buffers,
            compilation_options: wgpu::PipelineCompilationOptions {
                constants: &constants,
                ..Default::default()
            },
        },
        fragment: Some(wgpu::FragmentState {
            module: &desc.shader,
            entry_point: Some(&desc.fs),
            targets: &targets,
            compilation_options: wgpu::PipelineCompilationOptions {
                constants: &constants,
                ..Default::default()
            },
        }),
        primitive: wgpu::PrimitiveState {
            topology: desc.topology,
            strip_index_format: None,
            front_face: wgpu::FrontFace::Ccw,
            cull_mode: None,
            polygon_mode: wgpu::PolygonMode::Fill,
            unclipped_depth: false,
            conservative: false,
        },
        depth_stencil: (desc.depth != DepthMode::Detached).then_some(wgpu::DepthStencilState {
            format: wgpu::TextureFormat::Depth32Float,
            depth_write_enabled: Some(depth_write),
            depth_compare: Some(depth_compare),
            stencil: wgpu::StencilState::default(),
            bias: wgpu::DepthBiasState::default(),
        }),
        multisample: wgpu::MultisampleState {
            count: target.samples,
            mask: !0,
            alpha_to_coverage_enabled: false,
        },
        multiview_mask: None,
        cache: None,
    })
}

#[cfg(all(test, not(target_arch = "wasm32")))]
mod tests {
    use super::*;

    #[test]
    /// Clones share one object, made once, on its first use.
    fn lazy_objects_are_made_once_on_first_use() {
        let made = Rc::new(Cell::new(0));
        let counter = made.clone();
        let lazy = Lazy::new(move || {
            counter.set(counter.get() + 1);
            7
        });
        let copy = lazy.clone();
        assert_eq!(made.get(), 0, "nothing is made before its first use");
        assert_eq!(*copy, 7);
        assert_eq!(*lazy, 7);
        assert_eq!(made.get(), 1, "clones share the one made");
        assert!(lazy == copy);
        assert!(lazy != Lazy::new(|| 7), "equal means the same object");
    }
}

// One vertex of the fullscreen triangle.
struct VsOut {
    @builtin(position) pos: vec4<f32>, // clip position
}

// One triangle that covers the whole screen: clip space runs from -1 to 1, so corners at 3 cover it in one draw.
const CORNERS = array<vec2<f32>, 3>(
    vec2<f32>(-1.0, -1.0),
    vec2<f32>(3.0, -1.0),
    vec2<f32>(-1.0, 3.0),
);

// `@vertex` marks the function run once per vertex, `@fragment` the one run once per covered pixel.
// `vertex_index` counts 0, 1, 2 for `draw(0..3)`, so this shader needs no vertex buffer.
@vertex
// Place the three corners.
fn vs_main(@builtin(vertex_index) vid: u32) -> VsOut {
    var o: VsOut;
    o.pos = vec4<f32>(CORNERS[vid], 1.0, 1.0);
    return o;
}

// Location 0 is the colour; location 1 the triangle id, 0 here because the background is no triangle.
@fragment
// White background; slightly grey while the soft shadows of lesson 32 (SSAO) are on.
fn fs_main(in: VsOut) -> PhysicalColor {
    let value = select(1.0,0.94,line.lit > 1.5);
    return PhysicalColor(vec4<f32>(vec3<f32>(value),1.0), vec2<u32>(0u));
}

// This file is part of the prelude: WGSL text pasted after every scene shader, so each can call it.
// Lesson 18b fills the planes; until then count is 0 and every test below says "keep".
struct ClipUniform {
    planes: array<vec4<f32>, 6>, // xyz = unit normal toward the kept side, w = offset; up to 6 planes
    screen: array<vec4<f32>, 6>, // the same planes over canvas clip space (x, y, depth, 1)
    hatch: array<vec4<f32>, 6>, // hatch coordinate numerator over canvas (x, y, 1)
    hatch_w: array<vec4<f32>, 6>,
    sides: array<vec4<f32>, 2>, // 8 floats, one per plane: eye on the kept side 1, cut side -1, on it 0
    count: u32, // planes in use; 0 = nothing is cut
    samples: u32, // MSAA samples per pixel
    fill: u32, // 0 black hatch, 1 solid light grey
    spacing: f32, // in framebuffer px
    width: f32,
    outline: f32,
    pad1: f32, // two pads round the struct up to 448 bytes, the size of ClipUniform in Rust
    pad2: f32,
};

// An override is a constant the pipeline sets when it is built; false compiles every clip test away.
override CLIPPING: bool = true;

// Flag bits of an object row, the same numbers as Instance::FLAG_* in Rust.
const FLAG_CLIPPING_PLANE: u32 = 4096u; // the plane object itself: it cuts, it is never cut
const FLAG_CLOSED: u32 = 8192u; // a verified closed solid
const FLAG_INWARD: u32 = 16384u; // a closed solid whose faces point inward
// Triangle id of a section cap: this, plus twice the plane, plus 1 when selected.
const CAP_PRIMITIVE: u32 = 0xfffffff0u;
// A selected solid's crossing counts 64, so one sum tells "inside" and "selected" apart.
const SELECTED_CROSSING: f32 = 64.0;

// Where WebGPU puts the 4 samples of a 4x MSAA pixel, in pixels from its centre.
const CLIP_OFFSETS = array<vec2<f32>, 4>(
    vec2<f32>(-0.125, -0.375),
    vec2<f32>(0.375, -0.125),
    vec2<f32>(-0.375, 0.125),
    vec2<f32>(0.125, 0.375),
);

// Every shader asks this first, so a frame without planes pays one comparison.
fn clip_active() -> bool {
    return CLIPPING && clipping.count != 0u;
}

// 2^-17 of a point's coordinates: a face lying on the plane counts as cut in every pass alike.
const CLIP_SLACK: f32 = 7.62939453125e-6;

// Signed distance of scene point `p` to plane `i`, negative on the cut side.
fn clip_distance(i: u32, p: vec3<f32>) -> f32 {
    let plane = clipping.planes[i];
    let slack = CLIP_SLACK * (abs(p.x) + abs(p.y) + abs(p.z) + abs(plane.w));
    return dot(plane.xyz, p) + plane.w - slack;
}

// True when any plane cuts `p` away; a plane object is never cut by itself or another plane.
fn clip_cut(flags: u32, p: vec3<f32>) -> bool {
    if ((flags & FLAG_CLIPPING_PLANE) != 0u) {
        return false;
    }

    for (var i = 0u; i < clipping.count; i++) {
        if (clip_distance(i, p) < 0.0) {
            return true;
        }
    }

    return false;
}

// True when one plane cuts both ends of a segment away.
fn clip_cut_both(flags: u32, a: vec3<f32>, b: vec3<f32>) -> bool {
    if ((flags & FLAG_CLIPPING_PLANE) != 0u) {
        return false;
    }

    for (var i = 0u; i < clipping.count; i++) {
        if (clip_distance(i, a) < 0.0 && clip_distance(i, b) < 0.0) {
            return true;
        }
    }

    return false;
}

// Canvas pixel to clip space: x and y run -1..1, y up, e.g. pixel (0, 0) of any canvas is (-1, 1).
fn clip_ndc(px: vec2<f32>, frame: vec2<f32>, z: f32) -> vec3<f32> {
    return vec3<f32>(px.x / frame.x * 2.0 - 1.0, 1.0 - px.y / frame.y * 2.0, z);
}

// The same test for shaders that only know a screen point, not a scene point.
fn clip_cut_ndc(flags: u32, ndc: vec3<f32>) -> bool {
    if ((flags & FLAG_CLIPPING_PLANE) != 0u) {
        return false;
    }

    for (var i = 0u; i < clipping.count; i++) {
        if (dot(clipping.screen[i], vec4<f32>(ndc, 1.0)) < 0.0) {
            return true;
        }
    }

    return false;
}

// A sample mask has one bit per MSAA sample: bit k set = sample k of this pixel is covered.
// Here: the samples where `value`, changing by `slope` per pixel, is not below zero.
fn clip_samples(value: f32, slope: vec2<f32>) -> u32 {
    if (clipping.samples <= 1u) {
        return select(0u, 1u, value >= 0.0);
    }

    var mask = 0u;

    for (var k = 0u; k < 4u; k++) {
        if (value + dot(slope, CLIP_OFFSETS[k]) >= 0.0) {
            mask |= 1u << k;
        }
    }

    return mask;
}

// dpdx and dpdy read the value at the neighbouring pixels of a 2x2 group, so all four must get here:
// call this before any branch or discard.
fn clip_mask(flags: u32, p: vec3<f32>) -> u32 {
    var mask = 0xffffffffu;

    for (var i = 0u; i < clipping.count; i++) {
        let s = clip_distance(i, p);
        mask &= clip_samples(s, vec2<f32>(dpdx(s), dpdy(s)));
    }

    return select(mask, 0xffffffffu, (flags & FLAG_CLIPPING_PLANE) != 0u);
}

// Side of plane `i` the eye is on: 1 kept, -1 cut, 0 on the plane.
fn clip_eye_side(i: u32) -> f32 {
    return clipping.sides[i / 4u][i % 4u];
}

// Depth of plane `i` at canvas point `ndc`; NaN or outside 0..1 when it is not in view.
fn clip_plane_depth(i: u32, ndc: vec2<f32>) -> f32 {
    let s = clipping.screen[i];
    return -(s.x * ndc.x + s.y * ndc.y + s.w) / s.z;
}

// Depth change per pixel of plane `i`, over a canvas `frame` px wide and high.
fn clip_plane_slope(i: u32, frame: vec2<f32>) -> vec2<f32> {
    let s = clipping.screen[i];
    return vec2<f32>(-s.x / s.z * 2.0 / frame.x, s.y / s.z * 2.0 / frame.y);
}

fn clip_is_cap(primitive: u32) -> bool {
    return primitive >= CAP_PRIMITIVE;
}

fn clip_cap_plane(primitive: u32) -> u32 {
    return (primitive - CAP_PRIMITIVE) / 2u;
}

// Each plane keeps 4 words per pick pixel: count, id sum, nearest exit, owner; this is the first.
fn clip_pick_word(plane: u32, px: vec2<f32>, size: vec2<u32>) -> u32 {
    let at = min(vec2<u32>(px), size - 1u);
    return ((plane * size.y + at.y) * size.x + at.x) * 4u;
}

// A normal must stay perpendicular to its surface; a stretched object bends it, so it needs its own rule.
fn transform_normal(model: mat3x3<f32>, normal: vec3<f32>) -> vec3<f32> {
    let x = model[0];
    let y = model[1];
    let z = model[2];
    // the determinant is the volume the matrix scales a unit cube to; negative = mirrored
    let det = dot(x, cross(y, z));
    let scale = length(x) * length(y) * length(z);

    // a flattened object (volume ~0) has no normal to give
    if (scale == 0.0 || abs(det) <= scale * 1e-12 || dot(normal, normal) == 0.0) {
        return vec3<f32>(0.0);
    }

    // the inverse transpose times det, built from cross products; sign(det) undoes a mirror's flip
    let transformed = mat3x3<f32>(cross(y, z), cross(z, x), cross(x, y)) * normal * sign(det);

    if (dot(transformed, transformed) == 0.0) {
        return vec3<f32>(0.0);
    }

    return normalize(transformed);
}

// Translation never moves a normal, so only the upper-left 3x3 of the object matrix counts.
fn face_normal(model: mat4x4<f32>, normal: vec3<f32>) -> vec3<f32> {
    return transform_normal(mat3x3<f32>(model[0].xyz, model[1].xyz, model[2].xyz), normal);
}

// Octahedral packing: fold the unit sphere onto a square, keep the square's x and y.
// This one reads two signed bytes, x in bits 0-7 and y in bits 8-15.
fn oct16_decode(p: u32) -> vec3<f32> {
    // shift left then arithmetic-shift right: the byte comes back with its sign
    let e = vec2<f32>(f32(i32(p << 24u) >> 24u) / 127.0, f32(i32(p << 16u) >> 24u) / 127.0);
    var n = vec3<f32>(e, 1.0 - abs(e.x) - abs(e.y));

    // the lower half of the sphere was folded over the square's diagonals; unfold it
    if (n.z < 0.0) {
        let s = vec2<f32>(select(1.0, -1.0, n.x < 0.0), select(1.0, -1.0, n.y < 0.0));
        n = vec3<f32>((1.0 - abs(n.y)) * s.x, (1.0 - abs(n.x)) * s.y, n.z);
    }

    return normalize(n);
}

// The same with two 16-bit halves, 4 bytes in all instead of 12; 0x80008000 means "no normal".
fn oct32_decode(p: u32) -> vec3<f32> {
    if (p == 0x80008000u) {
        return vec3<f32>(0.0);
    }

    let e = unpack2x16snorm(p);
    var n = vec3<f32>(e, 1.0 - abs(e.x) - abs(e.y));

    if (n.z < 0.0) {
        let s = vec2<f32>(select(1.0, -1.0, n.x < 0.0), select(1.0, -1.0, n.y < 0.0));
        n = vec3<f32>((1.0 - abs(n.y)) * s.x, (1.0 - abs(n.x)) * s.y, n.z);
    }

    return normalize(n);
}

// `@location(n)` on an output = the n-th colour target in the pipeline's list.
// Output of a face fragment: color and triangle id.
struct PhysicalColor {
    @location(0) color: vec4<f32>, // rgba
    @location(1) primitive: vec2<u32>, // triangle index + 1, 0 for none, in two 16-bit halves
}

// Output of a face id fragment: ids and triangle id.
struct PhysicalId {
    @location(0) id: vec2<u32>, // object row + 1, sub id + 1
    @location(1) primitive: vec2<u32>, // triangle index + 1, 0 for none, in two 16-bit halves
}

// A triangle id as the two 16-bit halves the id target stores; 32-bit ids have no 4x format.
fn physical_primitive(primitive: u32) -> vec2<u32> {
    return vec2<u32>(primitive & 0xffffu, primitive >> 16u);
}

// WGSL is the WebGPU shading language. `@group(g) @binding(b)` names one slot of bind group g; the Rust side fills the same slot.
@group(0) @binding(0) var<uniform> mvp: mat4x4<f32>; // camera matrix
@group(1) @binding(0) var<uniform> line: LineUniform; // pen and view settings
@group(1) @binding(1) var<uniform> clipping: ClipUniform; // clipping planes

// One object row, 96 bytes; matches Instance in Rust.
struct Instance {
    model: mat4x4<f32>, // rotation and scale; translation is separate
    color: vec4<f32>, // rgba tint
    flags: u32, // FLAG_* bits
    ao_radius: f32, // SSAO contact radius, world units
    spacing: f32, // vertex spacing, world units
    edge_color: u32, // packed edge color
};

// `var<storage, read>` = a read-only array as long as the buffer bound to it.
@group(2) @binding(0) var<storage, read> instances: array<Instance>; // one row per object
@group(2) @binding(1) var<storage, read> translations: array<vec4<f32>>; // position per object, minus the scene origin

// Pen and view settings, 80 bytes; matches LineUniform in Rust.
struct LineUniform {
    thickness: f32, // pen width, px
    proj_y: f32, // perspective scale factor
    ortho_h: f32, // ortho half-height; 0 = perspective
    vp_h: f32, // target height, px
    vp_w: f32, // target width, px
    eye_x: f32, // camera position x
    eye_y: f32, // camera position y
    eye_z: f32, // camera position z
    anchor: vec3<f32>, // scene origin
    feather: f32, // edge softness of lines, px
    lit: f32, // 0 flat, 1 lit, 2 lit with SSAO
    backface: f32, // 1 = paint back faces red
    origin: vec2<f32>, // top-left of this target in the canvas, px
    frame: vec2<f32>, // canvas size, px
    opacity: f32, // alpha of mesh faces
};

// Object flag bits; match Instance::FLAG_* in Rust.
const FLAG_SELECTED: u32 = 1u; // selected: drawn tinted
const FLAG_HIDDEN: u32 = 2u; // hidden: skipped
const FLAG_INSIDE: u32 = 4u; // camera is inside the object
const FLAG_PRINT: u32 = 8u; // sheet fill: flat color
const FLAG_OPEN: u32 = 16u; // open mesh: no back-face culling
const FLAG_SHEET: u32 = 32u; // part of a drawing sheet
const FLAG_SMOOTH: u32 = 64u; // sampled surface: vertices are samples
const FLAG_SINGLE: u32 = 128u; // single face: stays shaded in x-ray
const FLAG_COLOR: u32 = 256u; // use the layer color

// layer colour if FLAG_COLOR, else the authored one
fn object_color(authored: vec4<f32>, inst: Instance) -> vec4<f32> {
    return select(authored * inst.color, vec4<f32>(inst.color.rgb, authored.a), (inst.flags & FLAG_COLOR) != 0u);
}

// Edge color: the layer edge color when set, else the face rule.
fn edge_color(authored: vec4<f32>, inst: Instance) -> vec4<f32> {
    // no faces: edges follow the face rule
    if ((inst.flags & 1024u) == 0u) {
        return object_color(authored, inst);
    }

    // layer edge color set
    if ((inst.flags & 512u) != 0u) {
        return vec4<f32>(unpack4x8unorm(inst.edge_color).rgb, authored.a);
    }

    return authored;
}

// No face normals known: always drawn.
const FACING_UNKNOWN: u32 = 0xffffffffu;

// Bit that marks a pick id as a marker.
const DISC_ID_TAG: u32 = 0x40000000u;
// Selection yellow.
const SELECT_COLOR: vec3<f32> = vec3<f32>(1.0, 1.0, 0.0);
// World millimetres to metres.
const MM_TO_M: f32 = 0.001;
// Thinnest lines never fade below this alpha.
const HAIRLINE_MIN_ALPHA: f32 = 0.5;

// A point of object `i` in scene space.
fn place(i: u32, p: vec3<f32>) -> vec3<f32> {
    return (instances[i].model * vec4<f32>(p, 1.0)).xyz + translations[i].xyz;
}

