struct ProjectLine {
    thickness: f32, // pen width, px
    proj_y: f32, // perspective scale factor
    ortho_h: f32, // ortho half-height; 0 = perspective
    vp_h: f32, // target height, px
    vp_w: f32, // target width, px
};

@group(1) @binding(0) var<uniform> line: ProjectLine; // view settings
@group(1) @binding(1) var<uniform> clipping: ClipUniform; // clipping planes

// Instance under another name; field order must match the Rust row.
struct ProjectInstance {
    model: mat4x4<f32>, // rotation and scale
    color: vec4<f32>, // rgba tint
    flags: u32, // FLAG_* bits
    ao_radius: f32, // SSAO contact radius
    spacing: f32, // vertex spacing
};

@group(2) @binding(0) var<storage, read> instances: array<ProjectInstance>; // one row per object
@group(2) @binding(1) var<storage, read> translations: array<vec4<f32>>; // position per object
@group(3) @binding(0) var<storage, read> physical_vertices: array<f32>; // mesh vertices, five words each
@group(3) @binding(1) var<storage, read> physical_objects: array<u32>; // object row per vertex
@group(3) @binding(2) var<storage, read> physical_indices: array<u32>; // triangle indices
@group(3) @binding(3) var<storage, read_write> projected: array<ProjectedTriangle>; // output: one record per triangle
@group(3) @binding(4) var<uniform> live_count: vec4<u32>; // x = triangle ids, the instances' included
@group(3) @binding(5) var slot_table: texture_2d<u32>; // where the instances' triangle ids lie

// Project one triangle id per invocation into `projected`: an arena triangle, or one instance's
// copy of its definition's.
// A workgroup = 64 invocations the GPU runs side by side; the Rust side dispatches one per 64 triangles.
@compute @workgroup_size(64)
fn cs_main(@builtin(global_invocation_id) id: vec3<u32>) {
    // rows of 32768 workgroups (PROJECT_ROW_GROUPS): a dispatch dimension holds at most 65535
    let index = id.x + id.y * 2097152u;

    if (index>=live_count.x) {
        return;
    }

    let placed = placed_triangle(index+1u, arrayLength(&physical_indices)/3u);
    let polygon = project_physical_triangle(placed.x+1u, placed.y);
    var out: ProjectedTriangle;

    // otherwise the record stays all zero
    if (polygon.count>=3u) {
        // screen box
        var lo = polygon.points[0].xy;
        var hi = lo;

        for (var i = 1u;i<polygon.count;i++) {
            lo = min(lo, polygon.points[i].xy);
            hi = max(hi, polygon.points[i].xy);
        }

        let area = physical_polygon_area(polygon);

        // degenerate: empty record
        if (abs(area)<1e-12) {
            projected[index] = out;
            return;
        }

        // one inward line equation per edge
        var equations: array<vec4<f32>, 4>;

        for (var i = 0u;i<polygon.count;i++) {
            let a = polygon.points[i].xy;
            let edge = polygon.points[(i+1u)%polygon.count].xy-a;
            let normal = sign(area)*vec2<f32>(-edge.y, edge.x)/length(edge);
            equations[i] = vec4<f32>(normal, -dot(normal, a), 0.0);
        }

        let ab = polygon.points[1]-polygon.points[0];
        let ac = polygon.points[2]-polygon.points[0];
        // depth change per screen pixel
        let gradient = vec2<f32>(ab.z*ac.y-ac.z*ab.y, ab.x*ac.z-ac.x*ab.z)/area;
        out.edge0 = vec4<f32>(equations[0].xyz, polygon.points[0].x);
        out.edge1 = vec4<f32>(equations[1].xyz, polygon.points[0].y);
        out.edge2 = vec4<f32>(equations[2].xyz, polygon.points[0].z);
        out.edge3 = vec4<f32>(equations[3].xyz, f32(polygon.count));
        // nearest corner depth
        var nearest = polygon.points[0].z;

        for (var i = 1u;i<polygon.count;i++) {
            nearest = max(nearest, polygon.points[i].z);
        }

        let row = physical_row(placed.x*3u, placed.y);
        out.gradient = vec4<f32>(gradient, nearest, instances[row].ao_radius);
        out.bounds = vec4<f32>(lo, hi);
    }

    projected[index] = out;
}

// A triangle clipped to the near plane: up to four screen-space corners.
struct ProjectedPolygon {
    points: array<vec3<f32>,
    4>,
    count: u32, // corners; 0 = not drawn
};

// Row drawing index `index`: `row`, or the vertex's own for SLOT_OWN_ROW.
fn physical_row(index: u32, row: u32) -> u32 {
    return select(row, physical_objects[physical_indices[index]], row == SLOT_OWN_ROW);
}

// Vertex `index` of the mesh in scene space, placed by `row`.
fn physical_world_corner(index: u32, row: u32) -> vec3<f32> {
    let vertex = physical_indices[index];
    // five words per vertex: position, normal, color
    let base = vertex * 5u;
    let point = vec3<f32>(physical_vertices[base], physical_vertices[base+1u], physical_vertices[base+2u]);
    return (instances[row].model * vec4<f32>(point, 1.0)).xyz + translations[row].xyz;
}

// Vertex `index` of the mesh in clip space, placed by `row`.
fn physical_clip_corner(index: u32, row: u32) -> vec4<f32> {
    return mvp * vec4<f32>(physical_world_corner(index, row), 1.0);
}

// True when one clipping plane cuts all three corners of the triangle at `base`, placed by `row`, away.
fn physical_cut(base: u32, row: u32) -> bool {
    if (!clip_active() || (instances[row].flags & FLAG_CLIPPING_PLANE) != 0u) {
        return false;
    }

    let a = physical_world_corner(base, row);
    let b = physical_world_corner(base+1u, row);
    let c = physical_world_corner(base+2u, row);

    for (var i = 0u; i < clipping.count; i++) {
        if (clip_distance(i, a) < 0.0 && clip_distance(i, b) < 0.0 && clip_distance(i, c) < 0.0) {
            return true;
        }
    }

    return false;
}

// Triangle `primitive` (one-based) placed by `row` (SLOT_OWN_ROW: its own), projected and
// clipped to the near plane.
fn project_physical_triangle(primitive: u32, row: u32) -> ProjectedPolygon {
    var polygon: ProjectedPolygon;

    if (primitive == 0u || primitive > arrayLength(&physical_indices)/3u) {
        return polygon;
    }

    let base = (primitive-1u)*3u;
    let owner = physical_row(base, row);

    // 2 = FLAG_HIDDEN; hidden objects do not occlude, nor do triangles a clipping plane removed
    if ((instances[owner].flags & 2u) != 0u || physical_cut(base, owner)) {
        return polygon;
    }

    let input = array<vec4<f32>, 3>(physical_clip_corner(base, owner), physical_clip_corner(base+1u, owner), physical_clip_corner(base+2u, owner));
    var clipped: array<vec4<f32>, 4>;
    var previous = input[2];
    var previous_distance = previous.w - previous.z;

    // clip each edge against the near plane
    for (var i = 0u; i<3u; i++) {
        let current = input[i];
        let distance = current.w - current.z;

        if ((distance > 0.0 && previous_distance < 0.0) || (distance < 0.0 && previous_distance > 0.0)) {
            let t = previous_distance / (previous_distance-distance);
            clipped[polygon.count] = mix(previous, current, t);
            polygon.count++;
        }

        if (distance >= 0.0) {
            clipped[polygon.count] = current;
            polygon.count++;
        }

        previous = current;
        previous_distance = distance;
    }

    // clip space to screen pixels
    for (var i = 0u; i<polygon.count; i++) {
        let clip = clipped[i];

        if (clip.w <= 0.0) {
            polygon.count = 0u;
            return polygon;
        }

        let ndc = clip.xyz/clip.w;
        polygon.points[i] = vec3<f32>((ndc.x*0.5+0.5)*line.vp_w, (0.5-ndc.y*0.5)*line.vp_h, ndc.z);
    }

    return polygon;
}

// 2D cross product.
fn physical_cross(a: vec2<f32>, b: vec2<f32>) -> f32 {
    return a.x*b.y-a.y*b.x;
}

// Twice the signed area of the first three corners.
fn physical_polygon_area(polygon: ProjectedPolygon) -> f32 {
    // zero only for a degenerate polygon
    return physical_cross(polygon.points[1].xy-polygon.points[0].xy, polygon.points[2].xy-polygon.points[0].xy);
}

#include "slot_table.wgsl"
#include "clip.wgsl"
#include "projected_triangle.wgsl"

// One triangle in screen space, 96 bytes; an edge line equation a*x + b*y + c is positive inside.
struct ProjectedTriangle {
    edge0: vec4<f32>, // xyz: edge line equation; w: reference x
    edge1: vec4<f32>, // xyz: edge line equation; w: reference y
    edge2: vec4<f32>, // xyz: edge line equation; w: reference depth
    edge3: vec4<f32>, // xyz: fourth edge after clipping; w: corner count
    gradient: vec4<f32>, // xy: depth slope; z: nearest depth; w: contact radius
    bounds: vec4<f32>, // screen box: left, top, right, bottom
};

// (depth, 1) where the triangle covers `at`, else (0, 0).
fn projected_triangle_at(triangle: ProjectedTriangle, at: vec2<f32>) -> vec2<f32> {
    // empty triangle
    if (triangle.edge3.w<3.0) {
        return vec2<f32>(0.0);
    }

    // 1/256 px slack: the rasterizer's vertex snap
    if (any(at<triangle.bounds.xy-0.00390625) || any(at>triangle.bounds.zw+0.00390625)) {
        return vec2<f32>(0.0);
    }

    // signed distance to each edge; negative = outside
    let distances = vec4<f32>(dot(triangle.edge0.xy, at)+triangle.edge0.z,
    dot(triangle.edge1.xy, at)+triangle.edge1.z,
    dot(triangle.edge2.xy, at)+triangle.edge2.z,
    dot(triangle.edge3.xy, at)+triangle.edge3.z);

    if (any(distances<vec4<f32>(-0.00390625))) {
        return vec2<f32>(0.0);
    }

    // depth at `at` from the reference point and slope
    let depth = triangle.edge2.w+dot(triangle.gradient.xy, at-vec2<f32>(triangle.edge0.w, triangle.edge1.w));
    return vec2<f32>(depth, 1.0);
}
// Pixels per tile side for a canvas; must match TileLayout in Rust.

fn visibility_tile_span_of(width: u32, height: u32) -> u32 {
    var span = 4u;

    while (((width+span-1u)/span)*((height+span-1u)/span)>262144u) {
        span*=2u;
    }

    return span;
}

// Pixels per tile side for this canvas.
fn visibility_tile_span() -> u32 {
    return visibility_tile_span_of(u32(line.vp_w), u32(line.vp_h));
}

// The first five fields of LineUniform; this shader needs no more.
struct ScanLine {
    thickness: f32, // pen width, px
    proj_y: f32, // perspective scale factor
    ortho_h: f32, // ortho half-height; 0 = perspective
    vp_h: f32, // target height, px
    vp_w: f32, // target width, px
};

@group(0) @binding(0) var<uniform> line: ScanLine; // view settings

// One 16-byte tile record: count, list start, cursor, overflow.
struct ScanRecord {
    values: array<u32, 4>
};

@group(1) @binding(0) var<storage, read_write> records: array<ScanRecord>; // tile records, then the reference pool
var<workgroup> scan: array<u32, 256>; // var<workgroup> = memory the 256 invocations of one workgroup share

// Tiles in the grid.
fn tile_count() -> u32 {
    return u32(ceil(line.vp_w/f32(visibility_tile_span())))*u32(ceil(line.vp_h/f32(visibility_tile_span())));
}

// Workgroups of 256 needed for `count` items.
fn blocks(count: u32) -> u32 {
    return (count+255u)/256u;
}

// Exclusive prefix sum across the workgroup; saturates at the buffer size.
fn prefix(lane: u32, value: u32) -> u32 {
    // an overflowing sum sticks at capacity instead of wrapping
    let capacity = arrayLength(&records)*4u;
    let bounded = min(value, capacity);
    scan[lane] = bounded;
    // a barrier waits until all 256 reach it, so nobody reads scan[] half written
    workgroupBarrier();

    for (var stride = 1u;stride<256u;stride*=2u) {
        var previous = 0u;

        if (lane>=stride) {
            previous = scan[lane-stride];
        }

        workgroupBarrier();
        scan[lane] = min(scan[lane]+previous, capacity);
        workgroupBarrier();
    }

    return select(scan[lane]-bounded, capacity, scan[lane]==capacity);
}

@compute @workgroup_size(256)
// Pass 1: prefix sum of tile counts inside each block of 256 tiles.
fn scan_tiles(@builtin(global_invocation_id) id: vec3<u32>, @builtin(local_invocation_index) lane: u32, @builtin(workgroup_id) group: vec3<u32>) {
    let count = tile_count();
    var value = 0u;

    if (id.x<count) {
        // two words per reference
        value = records[1u+id.x].values[0]*2u;
    }

    let offset = prefix(lane, value);

    if (id.x<count) {
        records[1u+id.x].values[1] = offset;
    }

    // block total, for pass 2
    if (lane==255u) {
        records[1u+count+group.x].values[0] = scan[255];
    }
}

@compute @workgroup_size(256)
// Pass 2: prefix sum of the block totals.
fn scan_blocks(@builtin(global_invocation_id) id: vec3<u32>, @builtin(local_invocation_index) lane: u32, @builtin(workgroup_id) group: vec3<u32>) {
    let count = tile_count();
    let block_count = blocks(count);
    var value = 0u;

    if (id.x<block_count) {
        value = records[1u+count+id.x].values[0];
    }

    let offset = prefix(lane, value);

    if (id.x<block_count) {
        records[1u+count+id.x].values[1] = offset;
    }

    if (lane==255u) {
        records[1u+count+block_count+group.x].values[0] = scan[255];
    }
}

@compute @workgroup_size(256)
// Pass 3: each tile's list start = pool start + block offset + tile offset.
fn finish_offsets(@builtin(global_invocation_id) id: vec3<u32>) {
    let count = tile_count();

    if (id.x==0u) {
        // record 0: valid flag
        records[0].values[0] = 1u;
    }

    if (id.x>=count) {
        return;
    }

    let block_count = blocks(count);
    let pool = 4u*(1u+count+block_count+blocks(block_count));
    let tile = 1u+id.x;
    let block = id.x/256u;
    var offset = records[tile].values[1]+records[1u+count+block].values[1];

    for (var i = 0u;i<block/256u;i++) {
        offset+=records[1u+count+block_count+i].values[0];
    }

    let start = pool+offset;
    records[tile].values[1] = start;
    // overflow flag when the list runs past the buffer
    records[tile].values[3] = select(0u, 1u, start+records[tile].values[0]*2u>arrayLength(&records)*4u);

    // record 0 word 1: words needed; the CPU reads it back
    if (id.x==count-1u) {
        records[0].values[1] = start+records[tile].values[0]*2u;
    }
}

#include "projected_triangle.wgsl"

// Slot table = a texture that maps an instance's triangle id to (definition triangle, instance row); texel 0 is the header.
// With no instances drawn the header is zero, so every id is an arena triangle at its own row.
// Row an arena triangle draws with: its own vertex's.
const SLOT_OWN_ROW: u32 = 0xffffffffu;

// No triangle behind an id.
const NO_TRIANGLE: u32 = 0xffffffffu;

// Texel `i` of the slot table, 1024 texels a row; texel 0 = (slots, arena triangles).
fn slot_texel(i: u32) -> vec4<u32> {
    return textureLoad(slot_table, vec2<u32>(i & 1023u, i >> 10u), 0);
}

// Triangle id `id` (one-based) as (arena triangle, row): an arena triangle keeps SLOT_OWN_ROW, an
// instance's names its definition's triangle and the instance row; x is NO_TRIANGLE for none.
// `arena` bounds the ids when no instance is drawn.
fn placed_triangle(id: u32, arena: u32) -> vec2<u32> {
    let head = slot_texel(0u);

    if (head.x == 0u || id <= head.y) {
        let own = id != 0u && id <= select(arena, head.y, head.x != 0u);
        return vec2<u32>(select(NO_TRIANGLE, id - 1u, own), SLOT_OWN_ROW);
    }

    // the last slot whose ids start at or before this one
    let index = id - 1u;
    var lo = 1u;
    var hi = head.x;

    while (lo < hi) {
        let mid = (lo + hi + 1u) / 2u;

        if (slot_texel(mid).y <= index) {
            lo = mid;
        } else {
            hi = mid - 1u;
        }
    }

    let slot = slot_texel(lo);

    if (index - slot.y >= slot.w) {
        return vec2<u32>(NO_TRIANGLE, SLOT_OWN_ROW);
    }

    return vec2<u32>(slot.z + index - slot.y, slot.x);
}

// No @location(1): print needs no normal, and an attribute the shader does not declare is ignored.
struct Vertex {
    @location(0) position: vec3<f32>, // object space
    @location(2) color: vec4<f32>,
    @location(3) object: u32, // object row
}

struct Fragment {
    @builtin(position) position: vec4<f32>,
    @location(0) color: vec4<f32>,
    @location(1) @interpolate(flat) object: u32,
}

// Sheet fills and lettering are print: flat colour, no light, yellow when selected.
@vertex
fn vs_main(vertex: Vertex) -> Fragment {
    let instance = instances[vertex.object];
    var out: Fragment;
    out.object = vertex.object;

    if (instance.flags & FLAG_HIDDEN) != 0u {
        out.position = vec4<f32>(3.0, 3.0, 0.5, 1.0);
        out.color = vec4<f32>(0.0);
        return out;
    }

    let world = place(vertex.object, vertex.position);
    out.position = mvp * vec4<f32>(world, 1.0);
    let selected = (instance.flags & FLAG_SELECTED) != 0u;
    out.color = vec4<f32>(select(vertex.color.rgb * instance.color.rgb,
        SELECT_COLOR, selected), vertex.color.a * instance.color.a);
    return out;
}

// In a fragment shader @builtin(position) is the pixel, so the test runs in canvas clip space.
fn cut(fragment: Fragment) -> bool {
    return clip_active() && clip_cut_ndc(0u, clip_ndc(fragment.position.xy + line.origin, line.frame, fragment.position.z));
}

@fragment
fn fs_main(fragment: Fragment) -> @location(0) vec4<f32> {
    if (cut(fragment)) {
        discard;
    }

    return fragment.color;
}

// Second output 0: print has no triangle id.
@fragment
fn fs_physical_id(fragment: Fragment) -> PhysicalId {
    if (cut(fragment)) {
        discard;
    }

 return PhysicalId(vec2<u32>(fragment.object+1u, 0u), vec2<u32>(0u));
}

@fragment
fn fs_id(fragment: Fragment) -> @location(0) vec2<u32> {
    if (cut(fragment)) {
        discard;
    }

    return vec2<u32>(fragment.object + 1u, 0u);
}

const BACKFACE_COLOR: vec3<f32> = vec3<f32>(0.80, 0.05, 0.05);

// Each @location(n) is filled by the vertex attribute with shader_location n: 0-2 come from GpuVertex,
// 3 from the object row buffer.
struct VsIn {
    @location(0) position: vec3<f32>, // object space
    @location(1) normal: u32, // octahedral, see oct32_decode
    @location(2) color: vec4<f32>, // Unorm8x4: the GPU turns 4 bytes into 4 floats 0..1
    @location(3) inst_id: u32, // object row
}

// @interpolate(flat) = every fragment gets the value of the triangle's first vertex, not a blend;
// integers must be flat, since 2.5 is no object row.
struct VsOut {
    @builtin(position) pos: vec4<f32>,
    @location(0) color: vec3<f32>,
    @location(1) world_pos: vec3<f32>, // scene space: world minus the scene origin
    @location(2) normal: vec3<f32>, // scene space
    @location(3) print: f32, // 1 for a sheet fill
    @location(4) @interpolate(flat) inst_id: u32,
    @location(5) @interpolate(flat) mirrored: u32, // 1 when the object matrix flips handedness
    @location(6) @interpolate(flat) selected: u32,
    @location(7) @interpolate(flat) source_face: u32, // face of the source object, or 0xffffffff
    @location(8) @interpolate(flat) primitive: u32, // triangle index + 1; 0 = no triangle id
    @location(9) @interpolate(flat) closed: u32, // closed solids take the opacity; open sheets stay opaque
    @location(10) @interpolate(flat) xray: u32, // x-ray drops the faces of multi-face solids only
}

// Clip space runs -1..1, so x = 3 lies outside it and the GPU drops every triangle this vertex is in.
fn dead_vertex() -> VsOut {
    var dead: VsOut; // a WGSL var starts zeroed
    dead.pos = vec4<f32>(3.0, 3.0, 0.5, 1.0);
    dead.source_face = 0xffffffffu;
    return dead;
}

// Place and colour one vertex; every vertex entry point below ends here.
fn transform_vertex(in: VsIn) -> VsOut {
    let inst = instances[in.inst_id];

    if ((inst.flags & FLAG_HIDDEN) != 0u) {
        return dead_vertex();
    }

    let world = place(in.inst_id, in.position);
    let clip = mvp * vec4<f32>(world, 1.0);
    var o: VsOut;
    o.pos = clip;
    var color = object_color(vec4<f32>(in.color.rgb, 1.0), inst).rgb;

    if ((inst.flags & FLAG_SELECTED) != 0u) {
        color = SELECT_COLOR;
    }

    o.color = color;
    o.world_pos = world;
    o.normal = face_normal(inst.model, oct32_decode(in.normal));
    // a negative determinant means a mirror, which turns counter-clockwise triangles clockwise
    o.mirrored = select(0u, 1u, dot(inst.model[0].xyz, cross(inst.model[1].xyz, inst.model[2].xyz)) < 0.0);
    o.print = select(0.0, 1.0, (inst.flags & FLAG_PRINT) != 0u);
    o.inst_id = in.inst_id;
    o.selected = inst.flags & FLAG_SELECTED;
    o.source_face = 0xffffffffu;
    o.closed = select(1u, 0u, (inst.flags & FLAG_OPEN) != 0u);
    o.xray = select(0u, 1u, line.opacity <= 0.0 && (inst.flags & (FLAG_PRINT | FLAG_SHEET | FLAG_SINGLE)) == 0u);
    return o;
}

// Slot 0 holds OWN_ROW, so a plain draw keeps each vertex's own row; lesson 18a adds real slots,
// one per placed copy of a shared mesh.
fn slot_row(own: u32, slot: u32) -> u32 {
    return select(slot, own, slot == OWN_ROW);
}

// The entry point of drawing with vertex buffers; `slot` comes from the slot buffer, one per instance.
@vertex
fn vs_main(in: VsIn, @location(4) slot: u32) -> VsOut {
    var placed = in;
    placed.inst_id = slot_row(in.inst_id, slot);
    return transform_vertex(placed);
}

// Group 3 = the arena buffers again, bound as storage so a shader can read any vertex by number.
@group(3) @binding(0) var<storage, read> face_vertices: array<u32>; // 5 words per vertex

// Pick ids with this bit set name a face, not an object part; the same value as FACE_TAG in Rust.
const FACE_TAG: u32 = 0x20000000u;
@group(3) @binding(1) var<storage, read> face_objects: array<u32>; // object row per vertex
@group(3) @binding(2) var<storage, read> face_indices: array<u32>;
@group(3) @binding(3) var<storage, read> source_faces: array<u32>; // source face per triangle
@group(3) @binding(4) var<uniform> selected_face: vec4<u32>; // x = the selected source face

// Slot value that keeps the vertex's own row; the same value as OWN_ROW in Rust.
const OWN_ROW: u32 = 0xffffffffu;

// Vertex pulling: draw with no vertex buffers and read vertex `index` from storage yourself.
// The shader then knows its triangle, index / 3, which a vertex buffer never tells it.
fn pull_triangle(index: u32, slot: u32, base: u32) -> VsOut {
    let vertex = face_indices[index];
    let start = vertex * 5u; // words 0-2 position, 3 octahedral normal, 4 rgba bytes
    // bitcast reads the same 32 bits as another type: here u32 words back into the f32 they were
    let position = bitcast<vec3<f32>>(vec3<u32>(face_vertices[start], face_vertices[start+1u], face_vertices[start+2u]));
    let color = unpack4x8unorm(face_vertices[start+4u]);
    let own = face_objects[vertex];
    var out = transform_vertex(VsIn(position, face_vertices[start+3u], color, slot_row(own, slot)));
    out.primitive = base + index/3u + 1u; // `base` turns the arena triangle into this instance's own id
    return out;
}

@vertex
fn vs_triangle(@builtin(vertex_index) index: u32, @location(0) slot: u32, @location(1) base: u32) -> VsOut {
    return pull_triangle(index, slot, base);
}

// The same, plus the face of the source object, so a click can pick one face of a solid.
@vertex
fn vs_face(@builtin(vertex_index) index: u32, @location(0) slot: u32, @location(1) base: u32) -> VsOut {
    var out=pull_triangle(index, slot, base);
    out.source_face = source_faces[index/3u];
    out.selected = select(0u, 1u, out.source_face != 0xffffffffu && out.source_face == selected_face.x);

    if (out.selected != 0u) {
        out.color = SELECT_COLOR;
    }

    return out;
}

// In ortho every ray is parallel, so the direction is the camera's axis, read from the matrix.
fn view_dir(world_pos: vec3<f32>) -> vec3<f32> {
    if (line.ortho_h > 0.0) {
        return normalize(vec3<f32>(mvp[0].z, mvp[1].z, mvp[2].z));
    }

    return normalize(vec3<f32>(line.eye_x, line.eye_y, line.eye_z) - world_pos);
}

// Face colour with lighting, opacity and red back faces.
fn shade(in: VsOut, raster_front: bool) -> vec4<f32> {
    let front = raster_front != (in.mirrored != 0u);

    // A translucent solid shows only its near side; `discard` drops the fragment, nothing is written.
    if (!front && in.closed != 0u && line.opacity > 0.0 && line.opacity < 1.0) {
        discard;
    }
    // no normal in the mesh: the cross product of two screen-space slopes is the flat face normal
    let flat_n = cross(dpdy(in.world_pos), dpdx(in.world_pos));
    var n = vec3<f32>(0.0, 0.0, 1.0);

    if (dot(in.normal, in.normal) > 1e-12) {
        n = normalize(in.normal);
    } else if (dot(flat_n, flat_n) > 1e-24) {
        n = normalize(flat_n);
    }

    // a headlight: the lamp rides with the camera, a little above it
    let v = view_dir(in.world_pos);

    if (dot(n, v) < 0.0) {
        n = -n;
    }

    let l = normalize(v + vec3<f32>(0.0, 0.0, 0.35));
    let h = normalize(l + v);
    // wrapped diffuse: light fades to 0.40, never to black, so there is no hard shadow line
    let wrap = clamp((dot(n, l) + 0.5) / 1.5, 0.0, 1.0);
    let spec = pow(max(dot(n, h), 0.0), 32.0) * 0.15;
    let lit = min(0.40 + 0.55 * wrap + spec, 1.0);

    let backface = !front && in.print <= 0.5 && line.backface > 0.5;
    let base = select(in.color, BACKFACE_COLOR, backface);
    // with SSAO on, a soft sky light from above; the occlusion pass adds the shadows
    let ambient = mix(0.72, 1.0, 0.5 + 0.5 * n.z);
    let lighting = select(lit, ambient, line.lit > 1.5);
    let shaded = select(1.0, lighting, line.lit > 0.5 && in.print <= 0.5);
    let alpha = select(1.0, line.opacity, in.closed != 0u);
    return vec4<f32>(base * shaded, alpha);
}

// Flags 0: a face is never part of a clipping plane object.
fn cut(in: VsOut) -> bool {
    return clip_active() && clip_cut(0u, in.world_pos);
}

// The pick id: object row + 1 (0 = background), then the tagged face + 1 (0 = no face).
@fragment
fn fs_id(in: VsOut) -> PhysicalId {
    if (in.xray != 0u || cut(in)) {
        discard;
    }

    let sub = select((FACE_TAG | in.source_face) + 1u, 0u, in.source_face == 0xffffffffu);
    return PhysicalId(vec2<u32>(in.inst_id + 1u, sub), physical_primitive(in.primitive));
}

// A one-channel mask the outline pass traces around the selection.
@fragment
fn fs_selection_mask(in: VsOut) -> @location(0) vec4<f32> {
    if (in.selected == 0u || in.xray != 0u || cut(in)) {
        discard;
    }

    return vec4<f32>(1.0);
}

// `front_facing` is true when the triangle's corners run counter-clockwise on screen.
@fragment
fn fs_main(in: VsOut, @builtin(front_facing) front: bool) -> PhysicalColor {
    if (in.xray != 0u) {
        discard;
    }

    return PhysicalColor(shade(in, front), physical_primitive(in.primitive));
}

struct PhysicalClipped {
    @location(0) color: vec4<f32>,
    @location(1) primitive: vec2<u32>, // triangle index + 1 in 16-bit halves
    @builtin(sample_mask) mask: u32, // written by the shader: only these samples keep the fragment
}

// Cut sample by sample, so the edge a plane leaves is as smooth as any other MSAA edge.
@fragment
fn fs_clipped(in: VsOut, @builtin(front_facing) front: bool) -> PhysicalClipped {
    let mask = clip_mask(0u, in.world_pos);

    if (in.xray != 0u || mask == 0u) {
        discard;
    }

    return PhysicalClipped(shade(in, front), physical_primitive(in.primitive), mask);
}

@fragment
fn fs_face_highlight(in: VsOut, @builtin(front_facing) front: bool) -> @location(0) vec4<f32> {
    if (in.selected == 0u || in.xray != 0u || cut(in)) {
        discard;
    }

    return shade(in, front);
}

// Two render targets written by one fragment: location 0 and location 1.
struct MaskPair {
    @location(0) solid: vec4<f32>, // every solid
    @location(1) selected: vec4<f32>, // the selection only
};

@fragment
fn fs_masks(in: VsOut) -> MaskPair {
    if (in.xray != 0u || cut(in)) {
        discard;
    }

    return MaskPair(vec4<f32>(1.0), vec4<f32>(f32(in.selected != 0u)));
}

// Section caps count crossings: along the view ray behind a plane, +1 where it leaves a solid and
// -1 where it enters; a sum above 0 means the pixel lies inside a cut solid, and 18b paints a cap.
struct CountOut {
    @builtin(position) pos: vec4<f32>,
    @location(0) world_pos: vec3<f32>,
    @location(1) @interpolate(flat) inst_id: u32,
    @location(2) @interpolate(flat) plane: u32,
    @location(3) @interpolate(flat) flip: u32, // 1 when the solid is mirrored or wound inward
    @location(4) @interpolate(flat) selected: u32,
}

// One draw instance per plane: instance_index says which plane this copy counts for.
@vertex
fn vs_count(in: VsIn, @builtin(instance_index) plane: u32) -> CountOut {
    return count_corner(in, plane);
}

// Instanced solids take the plane from the per-instance buffer instead.
@vertex
fn vs_count_placed(in: VsIn, @location(4) plane: u32) -> CountOut {
    return count_corner(in, plane);
}

// Only visible, closed solids that are not plane objects count; the rest land off screen.
fn count_corner(in: VsIn, plane: u32) -> CountOut {
    let inst = instances[in.inst_id];
    var out: CountOut;
    out.pos = vec4<f32>(3.0, 3.0, 0.5, 1.0);

    if ((inst.flags & (FLAG_HIDDEN | FLAG_CLOSED | FLAG_CLIPPING_PLANE)) != FLAG_CLOSED) {
        return out;
    }

    let world = place(in.inst_id, in.position);
    let mirrored = dot(inst.model[0].xyz, cross(inst.model[1].xyz, inst.model[2].xyz)) < 0.0;
    out.pos = mvp * vec4<f32>(world, 1.0);
    out.world_pos = world;
    out.inst_id = in.inst_id;
    out.plane = plane;
    out.flip = select(0u, 1u, mirrored != ((inst.flags & FLAG_INWARD) != 0u));
    out.selected = inst.flags & FLAG_SELECTED;
    return out;
}

struct CountColor {
    @location(0) count: vec4<f32>, // x: +-1, or +-SELECTED_CROSSING for a selected solid
    @builtin(sample_mask) mask: u32,
}

// Positive behind the plane, as the eye sees it.
fn behind(plane: u32, p: vec3<f32>) -> f32 {
    return -clip_eye_side(plane) * clip_distance(plane, p);
}

// The ray leaves through a back face, unless the solid is mirrored or wound inward.
fn leaving(in: CountOut, front: bool) -> bool {
    return front == (in.flip != 0u);
}

// The target blends by adding, so every crossing of the pixel sums into one number.
@fragment
fn fs_count(in: CountOut, @builtin(front_facing) front: bool) -> CountColor {
    let s = behind(in.plane, in.world_pos);
    let mask = clip_samples(s, vec2<f32>(dpdx(s), dpdy(s)));

    if (clip_eye_side(in.plane) == 0.0 || mask == 0u) {
        discard;
    }

    let sign = select(-1.0, 1.0, leaving(in, front));
    let weight = select(1.0, SELECTED_CROSSING, in.selected != 0u);
    return CountColor(vec4<f32>(sign * weight, 0.0, 0.0, 0.0), mask);
}

// An atomic is a word many fragments may change at once without losing a write.
@group(3) @binding(5) var<storage, read_write> pick_caps: array<atomic<u32>>;

fn pick_cap_word(plane: u32, px: vec2<f32>) -> u32 {
    return clip_pick_word(plane, px, vec2<u32>(u32(line.vp_w), u32(line.vp_h)));
}

// Clicking a cap: the count and the signed id sum name the solid the pixel is inside.
@fragment
fn fs_pick_count(in: CountOut, @builtin(front_facing) front: bool) -> @location(0) vec4<f32> {
    if (clip_eye_side(in.plane) == 0.0 || behind(in.plane, in.world_pos) < 0.0) {
        discard;
    }

    let leaves = leaving(in, front);
    let sign = select(-1, 1, leaves);
    let word = pick_cap_word(in.plane, in.pos.xy);
    atomicAdd(&pick_caps[word], bitcast<u32>(sign));
    atomicAdd(&pick_caps[word + 1u], bitcast<u32>(sign * i32(in.inst_id + 1u)));

    // a positive float's bits sort like the float, and here the largest depth is the nearest exit
    if (leaves) {
        atomicMax(&pick_caps[word + 2u], bitcast<u32>(in.pos.z));
    }

    return vec4<f32>(0.0);
}

// Where solids nest, the nearest exit names the innermost one: the owner of the cap.
@fragment
fn fs_pick_owner(in: CountOut, @builtin(front_facing) front: bool) -> @location(0) vec4<f32> {
    if (clip_eye_side(in.plane) == 0.0 || behind(in.plane, in.world_pos) < 0.0 || !leaving(in, front)) {
        discard;
    }

    let word = pick_cap_word(in.plane, in.pos.xy);

    if (bitcast<u32>(in.pos.z) == atomicLoad(&pick_caps[word + 2u])) {
        atomicStore(&pick_caps[word + 3u], in.inst_id + 1u);
    }

    return vec4<f32>(0.0);
}

@group(0) @binding(0) var<uniform> mvp: mat4x4<f32>; // camera matrix

// The first five fields of LineUniform; this shader needs no more.
struct TileLine {
    thickness: f32, // pen width, px
    proj_y: f32, // perspective scale factor
    ortho_h: f32, // ortho half-height; 0 = perspective
    vp_h: f32, // target height, px
    vp_w: f32, // target width, px
};

@group(1) @binding(0) var<uniform> line: TileLine; // view settings
@group(3) @binding(0) var<storage, read> projected: array<ProjectedTriangle>; // every triangle in screen space

// One tile record: 0 count, 1 list start, 2 write cursor, 3 overflow.
struct TileRecord {
    values: array<atomic<u32>, 4>
};

@group(3) @binding(1) var<storage, read_write> tile_records: array<TileRecord>; // tile records, then the reference pool

// what the vertex shader passes to the fragment shader
struct TileVertex {
    @builtin(position) clip: vec4<f32>, // position in the tile grid
    @location(0) @interpolate(flat) edge0: vec3<f32>, // edge line equation
    @location(1) @interpolate(flat) edge1: vec3<f32>, // edge line equation
    @location(2) @interpolate(flat) edge2: vec3<f32>, // edge line equation
    @location(3) @interpolate(flat) edge3: vec3<f32>, // fourth edge, if clipped
    @location(4) @interpolate(flat) bounds: vec4<f32>, // screen box
    @location(5) @interpolate(flat) primitive: u32, // triangle index + 1
    @location(6) @interpolate(flat) gradient: vec3<f32>, // depth slope and nearest depth
    @location(7) @interpolate(flat) reference: vec3<f32>, // reference point and its depth
};

@vertex
// A quad over the tiles the triangle's box touches; one instance per triangle.
fn vs_main(@builtin(vertex_index) vertex: u32, @builtin(instance_index) instance: u32) -> TileVertex {
    let triangle = projected[instance];
    var out: TileVertex;
    out.clip = vec4<f32>(2.0, 2.0, 0.0, 1.0);

    // empty triangle: off screen
    if (triangle.edge3.w<3.0) {
        return out;
    }

    // tile grid size
    let size = ceil(vec2<f32>(line.vp_w, line.vp_h)/f32(visibility_tile_span()));
    let lo = clamp(floor((triangle.bounds.xy-0.00390625)/f32(visibility_tile_span())), vec2<f32>(0.0), size);
    let hi = clamp(floor((triangle.bounds.zw+0.00390625)/f32(visibility_tile_span()))+1.0, vec2<f32>(0.0), size);
    // triangle strip: two triangles from four corners
    let corners = array<vec2<f32>, 4>(vec2<f32>(0.0, 0.0), vec2<f32>(1.0, 0.0), vec2<f32>(0.0, 1.0), vec2<f32>(1.0, 1.0));
    let position = mix(lo, hi, corners[vertex])/size;
    out.clip = vec4<f32>(position.x*2.0-1.0, 1.0-position.y*2.0, 0.0, 1.0);
    out.edge0 = triangle.edge0.xyz;
    out.edge1 = triangle.edge1.xyz;
    out.edge2 = triangle.edge2.xyz;
    out.edge3 = triangle.edge3.xyz;
    out.bounds = triangle.bounds;
    out.primitive = instance+1u;
    out.gradient = triangle.gradient.xyz;
    out.reference = vec3<f32>(triangle.edge0.w, triangle.edge1.w, triangle.edge2.w);
    return out;
}

// True when a whole tile lies outside one edge.
fn tile_outside(edge: vec3<f32>, centre: vec2<f32>) -> bool {
    return dot(edge.xy, centre)+edge.z+0.5*f32(visibility_tile_span())*(abs(edge.x)+abs(edge.y)) < -0.00390625;
}

// Record index of this fragment's tile; discards tiles the triangle misses.
fn covered_tile(v: TileVertex) -> u32 {
    let centre = (floor(v.clip.xy)+0.5)*f32(visibility_tile_span());

    if (tile_outside(v.edge0, centre) || tile_outside(v.edge1, centre) || tile_outside(v.edge2, centre) || tile_outside(v.edge3, centre)) {
        discard;
    }

    let size = vec2<u32>(ceil(vec2<f32>(line.vp_w, line.vp_h)/f32(visibility_tile_span())));
    let tile = 1u+u32(v.clip.y)*size.x+u32(v.clip.x);
    return tile;
}

@fragment
// Count one triangle for the tile.
fn fs_count(v: TileVertex) -> @location(0) f32 {
    let tile = covered_tile(v);
    atomicAdd(&tile_records[tile].values[0], 1u);
    return 0.0;
}

@fragment
// Append (triangle, nearest depth) to the tile's list.
fn fs_fill(v: TileVertex) -> @location(0) f32 {
    let tile = covered_tile(v);

    // list overflowed: stop
    if (atomicLoad(&tile_records[tile].values[3])!=0u) {
        return 0.0;
    }

    let cursor = atomicAdd(&tile_records[tile].values[2], 1u);

    // more writes than counted: mark overflow
    if (cursor>=atomicLoad(&tile_records[tile].values[0])) {
        atomicStore(&tile_records[tile].values[3], 1u);
        return 0.0;
    }

    let offset = atomicLoad(&tile_records[tile].values[1])+cursor*2u;
    atomicStore(&tile_records[offset/4u].values[offset%4u], v.primitive);
    let centre = (floor(v.clip.xy)+0.5)*f32(visibility_tile_span());
    let slope = abs(v.gradient.x)+abs(v.gradient.y);
    // nearest depth the triangle reaches in this tile
    let nearest = min(v.gradient.z, v.reference.z+dot(v.gradient.xy, centre-v.reference.xy)+0.5*f32(visibility_tile_span())*slope);
    // plus float and vertex-snap tolerance
    let bound = nearest+abs(nearest)*1.9073486e-6+slope*0.00390625;
    atomicStore(&tile_records[(offset+1u)/4u].values[(offset+1u)%4u], bitcast<u32>(bound));
    return 0.0;
}

