// Ink = everything drawn over the faces: edges, curves, markers, dots and arrows.
// Every ink fragment asks this file one question: does a face lie in front of me here?
@group(2) @binding(2) var scene_depth_single: texture_depth_2d; // scene depth at 1x
@group(2) @binding(3) var scene_depth_msaa: texture_depth_multisampled_2d; // scene depth at 4x

override SCENE_MSAA: bool = false; // which depth texture is live
@group(2) @binding(4) var scene_primitive_single: texture_2d<u32>; // triangle index + 1 at 1x, in 16-bit halves
@group(2) @binding(5) var scene_primitive_msaa: texture_multisampled_2d<u32>; // the same at 4x

// 2^-19 of the depth: two depths this close count as the same surface.
const DEPTH_REL_TOL: f32 = 1.9073486e-6;

// Vertex snapping error, px: 1/256.
const SLOPE_PX: f32 = 0.00390625;

// Two neighbouring slopes within 1/32 of each other still count as one flat surface.
const KINK: f32 = 0.03125;

// Depth change per pixel from which a slope carries no plane: 65504 / 65536.
const SLOPE_INVALID: f32 = 0.99951171875;

// Output of an ink fragment.
struct InkColor {
    @location(0) color: vec4<f32>, // rgba
};

// The stroke's center line as one fragment sees it.
struct InkAxis {
    at: vec2<f32>, // nearest point on the center line, screen px
    depth: f32, // its depth
    along: vec2<f32>, // stroke direction on screen, unit
    slope: f32, // depth change per pixel along it
};

// Scene depth at a pixel; 0 outside the screen or where nothing was drawn.
fn ink_depth(pixel: vec2<f32>, sample: u32) -> f32 {
    if (any(pixel < vec2<f32>(0.0)) || any(pixel >= vec2<f32>(line.vp_w, line.vp_h))) {
        return 0.0;
    }

    let at = vec2<i32>(pixel);

    if (SCENE_MSAA) {
        return textureLoad(scene_depth_msaa, at, i32(sample));
    }

    return textureLoad(scene_depth_single, at, 0);
}

// Allowed error of a depth carried `lever` pixels along a slope.
fn ink_tolerance(depth: f32, slope: f32, lever: f32) -> f32 {
    return abs(depth) * DEPTH_REL_TOL + abs(slope) * SLOPE_PX * (1.0 + lever);
}

// Plane fit = read the depth one and two pixels along `dir`; three depths on one straight line are one flat surface.
fn ink_pair_planar(pixel: vec2<f32>, dir: vec2<f32>, z: f32, sample: u32) -> bool {
    let z_side = ink_depth(pixel + dir, sample);

    // no neighbour: no pair
    if (z_side == 0.0) {
        return false;
    }

    let z_far = ink_depth(pixel + dir * 2.0, sample);

    // surface ends: the pair is all there is
    if (z_far == 0.0) {
        return true;
    }

    // the two slopes must nearly agree
    let g = z_side - z;
    let g_far = z_far - z_side;
    return abs(g_far - g) <= abs(z) * DEPTH_REL_TOL + KINK * (abs(g) + abs(g_far));
}

// Carry = extend the face's depth from this pixel along its slope to another point; `predicted` is that depth.
fn ink_carry_visible(predicted: f32, z: f32, depth: f32, tolerance: f32) -> bool {
    // pixel nearer than the ink: only its own surface may show it
    if (z > depth + abs(depth) * DEPTH_REL_TOL) {
        return abs(predicted - depth) <= tolerance;
    }

    return predicted <= depth + tolerance;
}

// One-pixel step away from the stroke, along x or y.
fn ink_step(pixel: vec2<f32>, axis: InkAxis) -> vec2<f32> {
    let perp = vec2<f32>(-axis.along.y, axis.along.x);
    var step = vec2<f32>(sign(perp.x), 0.0);

    if (abs(perp.y) > abs(perp.x)) {
        step = vec2<f32>(0.0, sign(perp.y));
    }

    return select(step, -step, dot(pixel - axis.at, step) < 0.0);
}

// A 6 px edge on a curved face covers pixels where the face is nearer than the edge's center line,
// so comparing depth there would hide half the stroke: carry the face's depth to the center line first.
fn ink_axis_visible(pixel: vec2<f32>, axis: InkAxis, sample: u32) -> bool {
    let z = ink_depth(pixel, sample);

    // nothing drawn here: visible
    if (z == 0.0) {
        return true;
    }

    let step = ink_step(pixel, axis);
    // fit away from the stroke, else toward it, else compare raw depth
    var side = step;

    if (!ink_pair_planar(pixel, side, z, sample)) {
        side = -step;

        if (!ink_pair_planar(pixel, side, z, sample)) {
            return z <= axis.depth + abs(axis.depth) * DEPTH_REL_TOL;
        }
    }

    let z_side = ink_depth(pixel + side, sample);
    // write the offset to the center line as a * along + b * side and solve the 2x2 system (Cramer's rule)
    let e = axis.at - pixel;
    let det = axis.along.x * side.y - axis.along.y * side.x;
    let a = (e.x * side.y - e.y * side.x) / det;
    let b = (axis.along.x * e.y - axis.along.y * e.x) / det;
    let g = z_side - z;
    // surface depth carried to the center line
    let predicted = z + a * axis.slope + b * g;
    return ink_carry_visible(predicted, z, axis.depth, ink_tolerance(axis.depth, abs(g) + abs(axis.slope), abs(b)));
}

// A disc (marker or dot) has no direction, so the fit runs along x and y and carries to its centre.
fn ink_disc_fragment_visible(pixel: vec2<f32>, centre: vec2<f32>, depth: f32, sample: u32) -> bool {
    let z = ink_depth(pixel, sample);

    if (z == 0.0) {
        return true;
    }

    let d = pixel - centre;
    // fit along x and y, away from the center first
    var along_x = vec2<f32>(select(1.0, -1.0, d.x < 0.0), 0.0);
    var along_y = vec2<f32>(0.0, select(1.0, -1.0, d.y < 0.0));

    if (!ink_pair_planar(pixel, along_x, z, sample)) {
        along_x = -along_x;

        if (!ink_pair_planar(pixel, along_x, z, sample)) {
            return z <= depth + abs(depth) * DEPTH_REL_TOL;
        }
    }

    if (!ink_pair_planar(pixel, along_y, z, sample)) {
        along_y = -along_y;

        if (!ink_pair_planar(pixel, along_y, z, sample)) {
            return z <= depth + abs(depth) * DEPTH_REL_TOL;
        }
    }

    // slopes per pixel
    let gx = (ink_depth(pixel + along_x, sample) - z) * along_x.x;
    let gy = (ink_depth(pixel + along_y, sample) - z) * along_y.y;
    let predicted = z - d.x * gx - d.y * gy;
    return ink_carry_visible(predicted, z, depth, ink_tolerance(depth, abs(gx) + abs(gy), abs(d.x) + abs(d.y)));
}

// Direction from a point to the camera; constant in ortho.
fn toward_eye(point: vec3<f32>) -> vec3<f32> {
    if (line.ortho_h > 0.0) {
        return vec3<f32>(mvp[0].z, mvp[1].z, mvp[2].z);
    }

    return vec3<f32>(line.eye_x, line.eye_y, line.eye_z) - point;
}

// Is a disc visible: its fragment, and its center pixel too.
fn ink_disc_visible(pixel: vec2<f32>, centre: vec2<f32>, depth: f32, sample: u32) -> bool {
    if (!ink_disc_fragment_visible(pixel, centre, depth, sample)) {
        return false;
    }

    let source_pixel = floor(centre) + fract(pixel);
    return !ink_disc_source_hidden(source_pixel, centre, depth, sample);
}

// Is a plane fitted at the center pixel in front of the disc?
fn ink_disc_source_hidden(pixel: vec2<f32>, centre: vec2<f32>, depth: f32, sample: u32) -> bool {
    let z = ink_depth(pixel, sample);

    if (z == 0.0) {
        return false;
    }

    let d = pixel - centre;

    // try every quadrant
    for (var x = 0u; x < 2u; x++) {
        let dx = vec2<f32>(select(1.0, -1.0, x == 1u), 0.0);

        if (!ink_pair_planar(pixel, dx, z, sample)) {
            continue;
        }

        let gx = (ink_depth(pixel + dx, sample) - z) * dx.x;

        for (var y = 0u; y < 2u; y++) {
            let dy = vec2<f32>(0.0, select(1.0, -1.0, y == 1u));

            if (!ink_pair_planar(pixel, dy, z, sample)) {
                continue;
            }

            let gy = (ink_depth(pixel + dy, sample) - z) * dy.y;
            // the diagonal pixel must agree with the plane too
            let diagonal = ink_depth(pixel + dx + dy, sample);
            let expected = z + gx * dx.x + gy * dy.y;

            if (diagonal == 0.0 || abs(diagonal - expected) > ink_tolerance(z, abs(gx) + abs(gy), 2.0)) {
                continue;
            }

            let predicted = z - d.x * gx - d.y * gy;

            if (predicted > depth + ink_tolerance(depth, abs(gx) + abs(gy), abs(d.x) + abs(d.y))) {
                return true;
            }
        }
    }

    return false;
}

// The face pass stores which triangle it drew at each pixel; that triangle's exact slope beats a fit from neighbours.
fn ink_visible_plane(pixel: vec2<f32>, axis: InkAxis, sample: u32) -> bool {
    let z = ink_depth(pixel, sample);

    if (z == 0.0) {
        return true;
    }

    // the grid and points are flat
    let primitive = ink_primitive(pixel, sample);
    var gradient = vec2<f32>(0.0);

    if (primitive != 0u) {
        let triangle = min(primitive, arrayLength(&projected)) - 1u;

        // no projected triangle: fit a plane
        if (projected[triangle].edge3.w < 3.0) {
            return ink_axis_visible(pixel, axis, sample);
        }

        gradient = projected[triangle].gradient.xy;
    }

    // too steep for a plane: fit one
    if (any(abs(gradient) >= vec2<f32>(SLOPE_INVALID))) {
        return ink_axis_visible(pixel, axis, sample);
    }

    let delta = axis.at - pixel;
    let predicted = z + dot(gradient, delta);
    return ink_carry_visible(predicted, z, axis.depth, ink_tolerance(axis.depth, abs(gradient.x)+abs(gradient.y), abs(delta.x)+abs(delta.y)));
}

@group(2) @binding(6) var<storage, read> projected: array<ProjectedTriangle>; // every triangle in screen space

// Triangle index + 1 at a pixel, or 0.
fn ink_primitive(pixel: vec2<f32>, sample: u32) -> u32 {
    if (any(pixel < vec2<f32>(0.0)) || any(pixel >= vec2<f32>(line.vp_w, line.vp_h))) {
        return 0u;
    }

    var halves: vec2<u32>;

    if (SCENE_MSAA) {
        halves = textureLoad(scene_primitive_msaa, vec2<i32>(pixel), i32(sample)).xy;
    } else {
        halves = textureLoad(scene_primitive_single, vec2<i32>(pixel), 0).xy;
    }

    return halves.x | (halves.y << 16u);
}

@group(2) @binding(7) var<storage, read> triangle_tiles: array<vec4<u32>>; // which triangles cover each screen tile

// Section cap = the flat face a clipping plane draws where it cuts a closed solid (lesson 18b).
// True when a clipping plane removed the triangle point hit at canvas point `at`, depth `depth`.
fn ink_hit_cut(at: vec2<f32>, depth: f32) -> bool {
    return clip_active() && clip_cut_ndc(0u, clip_ndc(at, line.frame, depth));
}

// Is the ink visible where the section cap of clipping plane `plane` lies under its center line?
fn ink_cap_visible(plane: u32, axis: InkAxis) -> bool {
    let slope = clip_plane_slope(plane, line.frame);
    let depth = clip_plane_depth(plane, clip_ndc(axis.at + line.origin, line.frame, 0.0).xy);
    return depth <= axis.depth + ink_tolerance(axis.depth, abs(slope.x) + abs(slope.y), 1.0);
}

// Exact test = ask a triangle itself, by its edge lines and depth plane, whether it covers the center point in front of the ink.
// `boundary` = the stroke is a surface's own border, where a plane fit is least sure, so the exact tests always run.
fn ink_visible(pixel: vec2<f32>, axis: InkAxis, sample: u32, boundary: bool) -> bool {
    // a section cap is flat on its plane: exact where it lies under the center line
    var fit_at = pixel;

    if (clip_active()) {
        let under = floor(axis.at) + fract(pixel);
        let cap = ink_primitive(under, sample);

        if (clip_is_cap(cap)) {
            return ink_cap_visible(clip_cap_plane(cap), axis);
        }

        // a cap beside the center line only: the surface under the line decides
        if (clip_is_cap(ink_primitive(pixel, sample))) {
            fit_at = under;
        }
    }

    let plane_visible = ink_visible_plane(fit_at, axis, sample);
    if (plane_visible && !boundary) {
        return true;
    }

    // Tile = a square of screen pixels listing every triangle that touches it; lesson 18 builds the lists.
    // no tile lists: the plane fit decides
    if (triangle_tiles[0].x==0u) {
        return plane_visible;
    }

    // canvas pixel of the center line
    let at = axis.at + line.origin;
    // the triangle under this pixel, tested exactly
    let fringe = ink_primitive(fit_at, sample);

    if (fringe!=0u && !(clip_active() && clip_is_cap(fringe))) {
        let fringe_hit = projected_triangle_at(projected[fringe-1u], at);
        if (fringe_hit.y>0.5 && fringe_hit.x>axis.depth+abs(axis.depth)*DEPTH_REL_TOL && !ink_hit_cut(at, fringe_hit.x)) {
            return false;
        }
    }

    // the four triangles around the center line, tested exactly
    let source_base = floor(axis.at-fract(fit_at))+fract(fit_at);

    for (var i = 0u;i<4u;i++) {
        let primitive = ink_primitive(source_base+vec2<f32>(f32(i&1u), f32(i>>1u)), sample);

        if (primitive==0u || primitive==fringe || (clip_active() && clip_is_cap(primitive))) {
            continue;
        }

        let hit = projected_triangle_at(projected[primitive-1u], at);

        if (hit.y>0.5 && hit.x>axis.depth+abs(axis.depth)*DEPTH_REL_TOL && !ink_hit_cut(at, hit.x)) {
            return false;
        }
    }

    // a boundary stroke also checks every triangle in its tile
    if (plane_visible) { return true; }

    if (any(at<vec2<f32>(0.0)) || any(at>=line.frame)) {
        return false;
    }

    let span = f32(visibility_tile_span_of(u32(line.frame.x), u32(line.frame.y)));
    let size = vec2<u32>(ceil(line.frame/span));
    let cell = vec2<u32>(at/span);
    let head = triangle_tiles[1u+cell.y*size.x+cell.x];

    // tile record: x count, y list start, z written, w overflow
    if (head.w!=0u || head.z!=head.x) {
        return false;
    }

    for (var i = 0u;i<head.x;i++) {
        let offset = head.y+i*2u;
        let nearest = bitcast<f32>(triangle_tiles[(offset+1u)/4u][(offset+1u)%4u]);

        // triangle no nearer than the ink: skip
        if (nearest<=axis.depth+abs(axis.depth)*DEPTH_REL_TOL) {
            continue;
        }

        let primitive = triangle_tiles[offset/4u][offset%4u];
        let bounds = projected[primitive-1u].bounds;

        if (any(at<bounds.xy-SLOPE_PX) || any(at>bounds.zw+SLOPE_PX)) {
            continue;
        }

        let hit = projected_triangle_at(projected[primitive-1u], at);

        if (hit.y>0.5 && hit.x>axis.depth+abs(axis.depth)*DEPTH_REL_TOL && !ink_hit_cut(at, hit.x)) {
            return false;
        }
    }

    return true;
}

// Alpha of hidden ink: 0, or 1 - opacity through translucent faces.
fn through_glass(hidden: bool) -> f32 {
    let glass = line.opacity > 0.0 && line.opacity < 1.0;
    return select(1.0, select(0.0, 1.0 - line.opacity, glass), hidden);
}

// Not WGSL: build.rs pastes the named file in place of this line before the shader compiles.
#include "projected_triangle.wgsl"

// One line segment with its neighbours, 48 bytes; matches StrokeSegment in Rust.
struct StrokeSegment {
    p0x: f32, // start point x
    p0y: f32, // start point y
    p0z: f32, // start point z
    radius: f32, // 0 = pen; > 0 world mm; < 0 pen multiplier
    p1x: f32, // end point x
    p1y: f32, // end point y
    p1z: f32, // end point z
    instance_id: u32, // object row
    color: u32, // packed rgba
    facing: u32, // packed normals of the two faces beside it
    previous: u32, // row of the segment before it, none, or HEAD_MARK
    next: u32, // row of the segment after it, none, or HEAD_MARK
}

// Neighbour code of an end under an arrowhead, drawn by the vector lane; matches HEAD_MARK in Rust.
const HEAD_MARK: u32 = 0xfffffffeu;
// A curve with arrowheads; matches Instance::FLAG_HEADS.
const FLAG_HEADS: u32 = 32768u;

// A storage buffer is a GPU array any vertex can index; here row vid / 6 is the segment to draw.
@group(3) @binding(0) var<storage, read> segments: array<StrokeSegment>; // one row per segment
@group(3) @binding(1) var<storage, read> source_edges: array<u32>; // source edge per segment
@group(3) @binding(2) var<uniform> edge_selection: vec4<u32>; // selected (object, edge)

// True when either face beside the edge faces the camera.
fn edge_faces_camera(facing: u32, n0: vec3<f32>, n1: vec3<f32>, to_eye: vec3<f32>) -> bool {
    if (facing == FACING_UNKNOWN) {
        return true;
    }

    return dot(n0, to_eye) > 0.0 || dot(n1, to_eye) > 0.0;
}

// Half width in px at depth `w`, from the radius field.
// A world width shrinks with distance: in perspective the pixel size divides by w, the depth after projection.
fn half_width_px(radius: f32, w: f32) -> f32 {
    if (radius < 0.0) { return -radius * line.thickness; }
    if (radius > 0.0) {
        if (line.ortho_h > 0.0) {
            return radius * line.vp_h * 0.5 / line.ortho_h;
        }

        return radius * line.proj_y * line.vp_h * 0.5 / w;
    }

    return line.thickness * 0.5;
}

// Half a pixel's diagonal: how far a pixel reaches from its center.
const FILTER_REACH: f32 = 0.70711;
// Default arrowhead length, in pen widths; as in vector.wgsl.
const HEAD_PENS: f32 = 10.0;
// Half the arrowhead's base width over its length; as in vector.wgsl.
const HEAD_ASPECT: f32 = 0.4;

// The ribbon and the vector lane must agree on the head's size to the pixel; a test compares these lines in both files.
// Arrowhead length in px: `pens` pen widths, six shaft half widths at least, `most` at most.
fn head_px(pens: f32, hw: f32, most: f32) -> f32 {
    return min(max(pens * line.thickness, hw * 6.0), most);
}

// How far the shaft runs under a head past its base: a pixel's reach at least, so the seam has no gap.
fn tuck(head: f32, half: f32, hw: f32) -> f32 {
    return min(clamp(head * (1.0 - (hw + 1.0) / max(half, 1e-3)) - 1.0, FILTER_REACH, 1.0), head * 0.5);
}

// Segments a head may span; a longer run of tiny chords is left uncut past this.
const HEAD_STEPS: u32 = 8u;
// No cut: an offset nothing reaches.
const NO_CUT: vec2<f32> = vec2<f32>(0.0, 3.0e38);

// Object point `q` of row `id` in screen px, with clip w; w is 0 when the near plane cuts it.
fn screen_of(id: u32, q: vec3<f32>) -> vec3<f32> {
    let c = mvp * vec4<f32>(place(id, q), 1.0);

    if (c.w <= 0.0 || c.z > c.w) {
        return vec3<f32>(0.0);
    }

    return vec3<f32>((c.xy / c.w * 0.5 + 0.5) * vec2<f32>(line.vp_w, line.vp_h), c.w);
}

// An arrowhead on a curve is drawn by the vector lane; the curve itself must stop under the head's base.
// The head may span several short segments, so walk the chain to the headed end and return one straight cut line.
// Cut under the head at the chain's end toward `next` (or `previous`): pixels with dot(p, dir(angle)) >= offset go.
// `near` and `far` are this segment's ends in px with clip w, `far` toward the head; `floor_hw` the selection's width.
fn head_plane(iid: u32, forward: bool, near: vec3<f32>, far: vec3<f32>, radius: f32, floor_hw: f32) -> vec2<f32> {
    var row = iid;
    var back = near;
    var at = far;
    var gone = 0.0; // chain length from this segment's end to `at`
    let most = 4.0 * max(HEAD_PENS * line.thickness, 6.0 * max(half_width_px(radius, far.z), floor_hw));

    for (var k = 0u; k < HEAD_STEPS; k++) {
        let link = select(segments[row].previous, segments[row].next, forward);

        if (link == HEAD_MARK) {
            // the head the vector lane draws on this segment: tip at `at`, aimed from `back`
            let hw_tip = max(half_width_px(radius, at.z), floor_hw);
            let hw = max(hw_tip, max(half_width_px(radius, back.z), floor_hw));
            let head = head_px(HEAD_PENS, hw_tip, 3.0e38);
            let under = head - tuck(head, head * HEAD_ASPECT, hw);
            let run = at.xy - back.xy;

            if (gone >= under || dot(run, run) < 1e-12) {
                return NO_CUT;
            }

            let dir = normalize(run);
            return vec2<f32>(atan2(dir.y, dir.x), dot(at.xy, dir) - under);
        }

        if (link >= arrayLength(&segments) || gone > most) {
            return NO_CUT;
        }

        let seg = placed_segment(link);
        let q = screen_of(seg.instance_id, select(vec3<f32>(seg.p0x, seg.p0y, seg.p0z), vec3<f32>(seg.p1x, seg.p1y, seg.p1z), forward));

        if (q.z <= 0.0) {
            return NO_CUT;
        }

        back = at;
        at = q;
        gone += distance(back.xy, at.xy);
        row = link;
    }

    return NO_CUT;
}

// True when a head cut drops the pixel at `p`.
fn head_cut(p: vec2<f32>, cut: vec2<f32>) -> bool {
    return dot(p, vec2<f32>(cos(cut.x), sin(cut.x))) >= cut.y;
}

// Coverage = the share of a pixel's square the shape covers, 0..1; used as alpha it gives smooth edges without MSAA.
// Fraction of a pixel square lying below signed distance `t` from a line.
fn box_cdf(t: f32, hi: f32, lo: f32, m: f32, q: f32) -> f32 {
    let s = clamp(t, -hi, hi);
    let e = hi - abs(s);
    let tail = select(e * e / q, 1.0 - e * e / q, s > 0.0);
    return select(tail, 0.5 + s / m, abs(s) <= lo);
}

// Exact area of this pixel within `hw` of the line, `d` away, direction `g`.
fn band_area(d: f32, hw: f32, g: vec2<f32>) -> f32 {
    let a = abs(g.x);
    let b = abs(g.y);
    let hi = 0.5 * (a + b);
    let lo = 0.5 * abs(a - b);
    let m = max(max(a, b), 1e-6);
    let q = max(2.0 * a * b, 1e-6);
    return box_cdf(hw - d, hi, lo, m, q) + box_cdf(hw + d, hi, lo, m, q) - 1.0;
}

// Never thinner than one pixel.
fn floor_hairline(px: f32) -> f32 {
    return max(px, 0.5);
}

// Alpha for a line thinner than a pixel.
fn hairline_fade(px: f32) -> f32 {
    if (px < 0.5) {
        return max(px / 0.5, HAIRLINE_MIN_ALPHA);
    }

    return 1.0;
}

// What the vertex shader hands the fragment shader.
// flat = every pixel gets the value of one vertex unchanged; linear = blended across the triangle.
struct VsOut {
    @builtin(position) pos: vec4<f32>, // clip position
    @location(0) color: vec4<f32>, // rgba
    @location(1) @interpolate(linear) p: vec2<f32>, // this corner, screen px
    @location(2) @interpolate(flat) a: vec2<f32>, // start point, screen px
    @location(3) @interpolate(flat) b: vec2<f32>, // end point, screen px
    @location(4) @interpolate(flat) hw0: f32, // half width at the start, px
    @location(5) @interpolate(flat) hw1: f32, // half width at the end, px
    @location(6) @interpolate(flat) style: vec3<f32>, // x: 1 = a mesh edge, never fades; y, z: 1 = flat start, flat end
    @location(7) @interpolate(flat) inst_id: u32, // object row
    @location(8) @interpolate(flat) segment_index: u32, // segment row
    @location(9) @interpolate(flat) end_depth: vec2<f32>, // depth at start and end
    @location(10) @interpolate(flat) source_edge: u32, // source edge, or none
    @location(11) @interpolate(flat) start_join: vec4<f32>, // cut plane at the start joint: normal, point
    @location(12) @interpolate(flat) end_join: vec4<f32>, // cut plane at the end joint
    @location(13) @interpolate(flat) head_cuts: vec4<f32>, // cuts under the end and start heads: angle, offset each
};

// (half width, alpha) at fraction `h` along the segment.
fn resolve_width(in: VsOut, h: f32) -> vec2<f32> {
    let raw = mix(in.hw0, in.hw1, h);
    return vec2<f32>(floor_hairline(raw), select(hairline_fade(raw), 1.0, in.style.x > 0.5));
}

// A vertex placed off screen, so nothing is drawn.
fn dead_vertex() -> VsOut {
    var dead: VsOut; // all zero; only the position matters
    dead.pos = vec4<f32>(3.0, 3.0, 0.5, 1.0);
    return dead;
}

// Quad corner of vertex `k` of 6: 0 start-, 1 start+, 2 end-, 3 end+.
fn corner_of(k: u32) -> u32 {
    if (k == 0u) {
        return 0u;
    }

    if (k == 1u) {
        return 1u;
    }

    if (k == 2u || k == 3u) {
        return 2u;
    }

    if (k == 4u) {
        return 1u;
    }

    return 3u;
}

// True in the color pass: back edges show faint through translucent faces; set by the vertex entry points.
// var<private> is a global of one shader invocation: each vertex gets its own copy.
var<private> through_faces: bool = false;

// True when the segment is drawn: a face beside it faces the camera, or the faces are glass.
// A back edge of a see-through solid still draws, faded by through_glass; lesson 36 makes the faces see-through.
fn neighbor_visible(seg: StrokeSegment) -> bool {
    let inst = instances[seg.instance_id];
    let glass = through_faces && line.opacity < 1.0; // hidden ink fades to 1 - opacity, never pops

    if ((inst.flags & (FLAG_INSIDE | FLAG_OPEN)) != 0u || seg.facing == FACING_UNKNOWN || line.opacity <= 0.0 || glass) {
        return true;
    }

    let p0 = place(seg.instance_id, vec3<f32>(seg.p0x, seg.p0y, seg.p0z));
    let p1 = place(seg.instance_id, vec3<f32>(seg.p1x, seg.p1y, seg.p1z));
    let n0 = face_normal(inst.model, oct16_decode(seg.facing & 0xffffu));
    let n1 = face_normal(inst.model, oct16_decode(seg.facing >> 16u));
    return edge_faces_camera(seg.facing, n0, n1, toward_eye((p0+p1)*0.5));
}

// Object row of an instanced draw, or none; set by the vertex entry points.
var<private> slot_row: u32 = 0xffffffffu;

// Segment `index` as drawn: in an instanced draw its row is the instance's.
fn placed_segment(index: u32) -> StrokeSegment {
    var seg = segments[index];
    seg.instance_id = select(slot_row, seg.instance_id, slot_row == 0xffffffffu);
    return seg;
}

// Cut plane between two joined segments: (normal, point), or zero for no joint.
// Both ribbons overlap at a joint; each keeps only its side of the bisector, so no pixel is blended twice.
fn join_plane(before: u32, after: u32) -> vec4<f32> {
    if (before == 0xffffffffu || after == 0xffffffffu || before >= arrayLength(&segments) || after >= arrayLength(&segments)) {
        return vec4<f32>(0.0);
    }

    let a = placed_segment(before);
    let b = placed_segment(after);

    if (!neighbor_visible(a) || !neighbor_visible(b)) {
        return vec4<f32>(0.0);
    }

    let c0 = mvp * vec4<f32>(place(a.instance_id, vec3<f32>(a.p0x, a.p0y, a.p0z)), 1.0);
    let c1 = mvp * vec4<f32>(place(a.instance_id, vec3<f32>(a.p1x, a.p1y, a.p1z)), 1.0);
    let c2 = mvp * vec4<f32>(place(b.instance_id, vec3<f32>(b.p1x, b.p1y, b.p1z)), 1.0);

    if (c0.w <= 0.0 || c1.w <= 0.0 || c2.w <= 0.0 || c0.z > c0.w || c1.z > c1.w || c2.z > c2.w) {
        return vec4<f32>(0.0);
    }

    let vp = vec2<f32>(line.vp_w, line.vp_h);
    let p0 = (c0.xy/c0.w*0.5+0.5)*vp;
    let p1 = (c1.xy/c1.w*0.5+0.5)*vp;
    let p2 = (c2.xy/c2.w*0.5+0.5)*vp;
    let d0 = p1-p0;
    let d1 = p2-p1;

    if (dot(d0, d0) < 1e-8 || dot(d1, d1) < 1e-8) {
        return vec4<f32>(0.0);
    }

    // bisector of the two directions
    let normal = normalize(d0)+normalize(d1);

    if (dot(normal, normal) < 1e-8) {
        return vec4<f32>(0.0);
    }

    return vec4<f32>(normalize(normal), p1);
}

// One quad corner of segment `vid / 6`; layer 0 all, 1 unselected, 2 selected.
fn stroke_vertex(vid: u32, layer: u32) -> VsOut {
    let iid = vid / 6u;
    let corner = corner_of(vid % 6u);
    let seg = placed_segment(iid);
    let inst = instances[seg.instance_id];
    // selected object, or the selected source edge
    let selected = (inst.flags & FLAG_SELECTED) != 0u ||
        (edge_selection.x == seg.instance_id && edge_selection.y != 0xffffffffu &&
         edge_selection.y == source_edges[iid]);

    if ((layer == 1u && selected) || (layer == 2u && !selected)) {
        return dead_vertex();
    }

    if ((inst.flags & FLAG_HIDDEN) != 0u) {
        return dead_vertex();
    }

    if (!neighbor_visible(seg)) {
        return dead_vertex();
    }

    let model = inst.model;

    let w0 = place(seg.instance_id, vec3<f32>(seg.p0x, seg.p0y, seg.p0z));
    let w1 = place(seg.instance_id, vec3<f32>(seg.p1x, seg.p1y, seg.p1z));

    // one clipping plane cuts the whole segment away
    if (clip_active() && clip_cut_both(inst.flags, w0, w1)) {
        return dead_vertex();
    }

    let c0 = mvp * vec4<f32>(w0, 1.0);
    let c1 = mvp * vec4<f32>(w1, 1.0);
    let at_end1 = corner >= 2u;
    let side = select(-1.0, 1.0, (corner & 1u) == 1u);

    // clip to the near plane before dividing by w; a point behind the eye has w <= 0 and would flip across the screen
    let f0 = c0.z - c0.w;
    let f1 = c1.z - c1.w;

    if (f0 > 0.0 && f1 > 0.0) {
        return dead_vertex();
    }

    let e0 = select(c0, mix(c0, c1, f0 / (f0 - f1)), f0 > 0.0);
    let e1 = select(c1, mix(c1, c0, f1 / (f1 - f0)), f1 > 0.0);
    let clip = select(e0, e1, at_end1);

    // both ends in screen pixels
    let vp = vec2<f32>(line.vp_w, line.vp_h);
    let s0 = (e0.xy / e0.w * 0.5 + 0.5) * vp;
    let s1 = (e1.xy / e1.w * 0.5 + 0.5) * vp;
    let d = s1 - s0;
    let len = length(d);
    let dir = select(vec2<f32>(1.0, 0.0), d / len, len > 1e-6);
    let n = vec2<f32>(-dir.y, dir.x);

    // half widths at both ends; a selected stroke is at least a full pen wide
    let raw0 = max(half_width_px(seg.radius, e0.w), select(0.0, line.thickness, selected));
    let raw1 = max(half_width_px(seg.radius, e1.w), select(0.0, line.thickness, selected));
    let px = floor_hairline(select(raw0, raw1, at_end1));
    // corner: sideways by the width, outward by the filter reach, so the soft edge pixels are inside the quad
    let along = select(-1.0, 1.0, at_end1);
    let p = select(s0, s1, at_end1) + (n * side + dir * along) * (px + FILTER_REACH);

    var o: VsOut;
    let ndc = (p / vp - 0.5) * 2.0;
    // times w: the GPU divides by w again, and the depth stays the segment's own
    o.pos = vec4<f32>(ndc * clip.w, clip.z, clip.w);
    var color = edge_color(unpack4x8unorm(seg.color), inst);

    if (selected) {
        color = vec4<f32>(SELECT_COLOR, color.a);
    }

    o.color = color;
    o.p = p;
    o.a = s0;
    o.b = s1;
    o.hw0 = raw0;
    o.hw1 = raw1;
    o.inst_id = seg.instance_id;
    o.segment_index = iid;
    o.source_edge = source_edges[iid];
    o.end_depth = vec2<f32>(e0.z / e0.w, e1.z / e1.w);
    o.start_join = join_plane(seg.previous, iid);
    o.end_join = join_plane(iid, seg.next);

    // a curve stops flat under its heads' bases, unless the near plane cut that end; headless curves skip the walk
    let floor_hw = select(0.0, line.thickness, selected);
    let near = vec3<f32>(s0, e0.w);
    let far = vec3<f32>(s1, e1.w);
    let headed = (inst.flags & FLAG_HEADS) != 0u && seg.facing == FACING_UNKNOWN;
    var cuts = vec4<f32>(NO_CUT, NO_CUT);

    if (headed && f1 <= 0.0) {
        cuts = vec4<f32>(head_plane(iid, true, near, far, seg.radius, floor_hw), cuts.zw);
    }

    if (headed && f0 <= 0.0) {
        cuts = vec4<f32>(cuts.xy, head_plane(iid, false, far, near, seg.radius, floor_hw));
    }

    o.head_cuts = cuts;
    // a headed curve's bare open ends are flat at their points, as the vector lane's
    o.style = vec3<f32>(
        select(0.0, 1.0, seg.facing != FACING_UNKNOWN),
        select(0.0, 1.0, headed && seg.previous == 0xffffffffu),
        select(0.0, 1.0, headed && seg.next == 0xffffffffu),
    );
    return o;
}

// Six entry points share stroke_vertex; each pipeline picks one by name.
@vertex
fn vs_main(@builtin(vertex_index) vid: u32, @location(0) slot: u32) -> VsOut {
    slot_row = slot;
    through_faces = true;
    return stroke_vertex(vid, 0u);
}

@vertex
fn vs_unselected(@builtin(vertex_index) vid: u32, @location(0) slot: u32) -> VsOut {
    slot_row = slot;
    through_faces = true;
    return stroke_vertex(vid, 1u);
}

@vertex
fn vs_selected(@builtin(vertex_index) vid: u32, @location(0) slot: u32) -> VsOut {
    slot_row = slot;
    through_faces = true;
    return stroke_vertex(vid, 2u);
}

// Pick ids and outline masks drop hidden ink, so they keep culling back edges.
@vertex
fn vs_front(@builtin(vertex_index) vid: u32, @location(0) slot: u32) -> VsOut {
    slot_row = slot;
    return stroke_vertex(vid, 0u);
}

@vertex
fn vs_front_unselected(@builtin(vertex_index) vid: u32, @location(0) slot: u32) -> VsOut {
    slot_row = slot;
    return stroke_vertex(vid, 1u);
}

@vertex
fn vs_front_selected(@builtin(vertex_index) vid: u32, @location(0) slot: u32) -> VsOut {
    slot_row = slot;
    return stroke_vertex(vid, 2u);
}

// How much of this pixel the stroke covers, 0..1, times the hairline alpha.
fn coverage(in: VsOut) -> f32 {
    let pixel = vec2<f32>(in.pos.x, line.vp_h-in.pos.y);

    // past the start joint: the previous segment draws it
    if (dot(pixel-in.start_join.zw, in.start_join.xy) < 0.0) {
        return 0.0;
    }

    // past the end joint: the next segment draws it
    if (any(in.end_join.xy != vec2<f32>(0.0)) && dot(pixel-in.end_join.zw, in.end_join.xy) >= 0.0) {
        return 0.0;
    }

    // under a head: the vector lane draws it
    if (head_cut(pixel, in.head_cuts.xy) || head_cut(pixel, in.head_cuts.zw)) {
        return 0.0;
    }

    // distance from the pixel to the segment: project onto it, clamp h to 0..1, measure what is left
    let pa = in.p - in.a;
    let ba = in.b - in.a;
    let h = clamp(dot(pa, ba) / max(dot(ba, ba), 1e-6), 0.0, 1.0);
    let v = pa - ba * h;
    let d = length(v);
    let hf = resolve_width(in, h);
    let len = length(ba);

    // near a flat end: a band across times the pixel's share on the inner side of the end
    if (len > 1e-6 && any(in.style.yz > vec2<f32>(0.5))) {
        let dir = ba / len;
        let t = dot(pa, dir);
        let reach = 0.5 * (abs(dir.x) + abs(dir.y));
        let flat0 = in.style.y > 0.5 && t < reach;
        let flat1 = in.style.z > 0.5 && t > len - reach;

        if (flat0 || flat1) {
            let n = vec2<f32>(-dir.y, dir.x);
            let across = clamp(band_area(abs(dot(pa, n)), hf.x, n), 0.0, 1.0);
            let a = abs(dir.x);
            let b = abs(dir.y);
            let lo = 0.5 * abs(a - b);
            let m = max(max(a, b), 1e-6);
            let q = max(2.0 * a * b, 1e-6);
            let inside0 = select(1.0, box_cdf(t, reach, lo, m, q), flat0);
            let inside1 = select(1.0, box_cdf(len - t, reach, lo, m, q), flat1);
            return across * inside0 * inside1 * hf.y;
        }
    }

    let g = select(vec2<f32>(1.0, 0.0), v / d, d > 1e-6);
    return clamp(band_area(d, hf.x, g), 0.0, 1.0) * hf.y;
}

// The stroke's center line as this fragment sees it.
fn ink_axis(in: VsOut) -> InkAxis {
    let ba = in.b - in.a;
    let len2 = max(dot(ba, ba), 1e-6);
    let h = clamp(dot(in.p - in.a, ba) / len2, 0.0, 1.0);
    let at = in.a + ba * h;
    let len = sqrt(len2);
    let along = select(vec2<f32>(1.0, 0.0), vec2<f32>(ba.x, -ba.y) / len, len > 1e-3);
    let slope = (in.end_depth.y - in.end_depth.x) / max(len, 1e-3);
    return InkAxis(vec2<f32>(at.x, line.vp_h - at.y), mix(in.end_depth.x, in.end_depth.y, h), along, slope);
}

// True when a clipping plane cuts the center line away beside this fragment.
fn axis_cut(in: VsOut) -> bool {
    if (!clip_active()) {
        return false;
    }

    let axis = ink_axis(in);
    return clip_cut_ndc(instances[in.inst_id].flags, clip_ndc(axis.at + line.origin, line.frame, axis.depth));
}

@fragment
// Color: the stroke, faded where geometry hides it.
// sample_index makes the shader run once per MSAA sample, so each sample tests depth on its own.
fn fs_main(in: VsOut, @builtin(sample_index) sample: u32) -> InkColor {
    let covered = coverage(in);

    // no coverage: no depth reads
    if (covered <= 0.0 || axis_cut(in)) {
        discard;
    }

    let hidden = !ink_visible(in.pos.xy, ink_axis(in), sample, (instances[in.inst_id].flags & FLAG_SMOOTH) != 0u);
    let alpha = covered * through_glass(hidden);

    if (alpha <= 0.0) {
        discard;
    }

    return InkColor(vec4<f32>(in.color.rgb, in.color.a * alpha));
}

// Visible stroke coverage into an outline mask.
@fragment
fn fs_mask(in: VsOut, @builtin(sample_index) sample: u32) -> @location(0) vec4<f32> {
    let alpha = coverage(in);

    if (alpha <= 0.0 || axis_cut(in) || !ink_visible(in.pos.xy, ink_axis(in), sample, (instances[in.inst_id].flags & FLAG_SMOOTH) != 0u)) {
        discard;
    }

    return vec4<f32>(alpha);
}

// Output into both outline masks at once.
struct MaskPair {
    @location(0) solid: vec4<f32>, // every solid's mask
    @location(1) selected: vec4<f32>, // the selection's mask
};

// Unselected stroke: into the solid mask only.
@fragment
fn fs_masks(in: VsOut, @builtin(sample_index) sample: u32) -> MaskPair {
    let alpha = coverage(in);

    if (alpha <= 0.0 || axis_cut(in) || !ink_visible(in.pos.xy, ink_axis(in), sample, (instances[in.inst_id].flags & FLAG_SMOOTH) != 0u)) {
        discard;
    }

    return MaskPair(vec4<f32>(alpha), vec4<f32>(0.0));
}

@fragment
// Selected stroke: into both masks.
fn fs_masks_selected(in: VsOut, @builtin(sample_index) sample: u32) -> MaskPair {
    let alpha = coverage(in);

    if (alpha <= 0.0 || axis_cut(in) || !ink_visible(in.pos.xy, ink_axis(in), sample, (instances[in.inst_id].flags & FLAG_SMOOTH) != 0u)) {
        discard;
    }

    return MaskPair(vec4<f32>(alpha), vec4<f32>(alpha));
}

// Bit that marks a pick id as a stroke.
const SEGMENT_BIT: u32 = 0x80000000u;

@fragment
// Pick id: object row + 1 and tagged segment row + 1.
fn fs_id(in: VsOut) -> @location(0) vec2<u32> {
    if (coverage(in) <= 0.0 || axis_cut(in) || !ink_visible(in.pos.xy, ink_axis(in), 0u, (instances[in.inst_id].flags & FLAG_SMOOTH) != 0u)) {
        discard;
    }

    return vec2<u32>(in.inst_id + 1u, (in.segment_index + 1u) | SEGMENT_BIT);
}

// Pick id for edge picks; segments without a source edge are skipped.
@fragment
fn fs_edge_id(in: VsOut) -> @location(0) vec2<u32> {
    if (in.source_edge == 0xffffffffu || coverage(in) <= 0.0 || axis_cut(in) || !ink_visible(in.pos.xy, ink_axis(in), 0u, (instances[in.inst_id].flags & FLAG_SMOOTH) != 0u)) {
        discard;
    }

    // same tag as SEGMENT_BIT
    return vec2<u32>(in.inst_id + 1u, (in.segment_index + 1u) | 0x80000000u);
}

// One vector: a shaft from `start` to `end` with an arrowhead at either end, 48 bytes; matches VectorRow in Rust.
struct VectorRow {
    start: vec3<f32>, // start point, object space
    radius: f32, // 0 = pen; > 0 world mm; < 0 pen multiplier
    end: vec3<f32>, // end point, object space
    instance_id: u32, // object row
    color: u32, // packed rgba
    head: f32, // arrowhead length in pens; 0 = HEAD_PENS
    heads: u32, // HEAD_END | HEAD_START | HEAD_ONLY
    pad: u32, // to 48 bytes
};

@group(3) @binding(0) var<storage, read> vectors: array<VectorRow>; // one row per vector

// VectorRow.heads bits.
const HEAD_END: u32 = 1u; // a head whose tip is `end`
const HEAD_START: u32 = 2u; // a head whose tip is `start`
const HEAD_ONLY: u32 = 4u; // no shaft: `start` only aims the heads
// Default arrowhead length, in pen widths.
const HEAD_PENS: f32 = 10.0;
// Half the arrowhead's base width over its length.
const HEAD_ASPECT: f32 = 0.4;
// Share of the vector the heads may take together.
const HEAD_SHARE: f32 = 0.6;
// Half a pixel's diagonal: how far a pixel reaches from its center.
const FILTER_REACH: f32 = 0.70711;
// Quad corner of vertex `k` of 6: 0 back-, 1 back+, 2 front-, 3 front+; two triangles share corners 1 and 2.
const CORNERS = array<u32, 6>(0u, 1u, 2u, 2u, 1u, 3u);

// What the vertex shader hands the fragment shader.
struct VsOut {
    @builtin(position) pos: vec4<f32>, // clip position
    @location(0) color: vec4<f32>, // rgba
    @location(1) @interpolate(linear) p: vec2<f32>, // this corner, screen px
    @location(2) @interpolate(flat) ends: vec4<f32>, // start and end point, screen px
    @location(3) @interpolate(flat) shaft: vec4<f32>, // the shaft's two flat ends, screen px
    @location(4) @interpolate(flat) head_end: vec4<f32>, // end head: base center, then base center to a corner, px
    @location(5) @interpolate(flat) head_start: vec4<f32>, // start head, the same
    @location(6) @interpolate(flat) widths: vec4<f32>, // shaft half width at start and end, px; depth at both
    @location(7) @interpolate(flat) inst_id: u32, // object row
};

// Half width in px at depth `w`, from the radius field.
fn half_width_px(radius: f32, w: f32) -> f32 {
    if (radius < 0.0) { return -radius * line.thickness; }
    if (radius > 0.0) {
        if (line.ortho_h > 0.0) {
            return radius * line.vp_h * 0.5 / line.ortho_h;
        }

        return radius * line.proj_y * line.vp_h * 0.5 / w;
    }

    return line.thickness * 0.5;
}

// Arrowhead length in px: `pens` pen widths, six shaft half widths at least, `most` at most.
fn head_px(pens: f32, hw: f32, most: f32) -> f32 {
    return min(max(pens * line.thickness, hw * 6.0), most);
}

// How far the shaft runs under a head past its base: a pixel's reach at least, so the seam has no gap.
fn tuck(head: f32, half: f32, hw: f32) -> f32 {
    return min(clamp(head * (1.0 - (hw + 1.0) / max(half, 1e-3)) - 1.0, FILTER_REACH, 1.0), head * 0.5);
}

// A vertex placed off screen, so nothing is drawn.
fn dead_vertex() -> VsOut {
    var dead: VsOut; // all zero; only the position matters
    dead.pos = vec4<f32>(3.0, 3.0, 0.5, 1.0);
    return dead;
}

// Corner `vid` of 18 of vector `row`: 0-5 the shaft, 6-11 the end head, 12-17 the start head.
// instance_index is the row: one draw call runs these 18 corners once per vector.
@vertex
fn vs_main(@builtin(vertex_index) vid: u32, @builtin(instance_index) row: u32) -> VsOut {
    let v = vectors[row];
    let inst = instances[v.instance_id];

    if ((inst.flags & FLAG_HIDDEN) != 0u) {
        return dead_vertex();
    }

    // one clipping plane cuts the whole vector away
    if (clip_active() && clip_cut_both(inst.flags, place(v.instance_id, v.start), place(v.instance_id, v.end))) {
        return dead_vertex();
    }

    let c0 = mvp * vec4<f32>(place(v.instance_id, v.start), 1.0);
    let c1 = mvp * vec4<f32>(place(v.instance_id, v.end), 1.0);

    // clip to the near plane before dividing by w
    let f0 = c0.z - c0.w;
    let f1 = c1.z - c1.w;

    if (f0 > 0.0 && f1 > 0.0) {
        return dead_vertex();
    }

    let e0 = select(c0, mix(c0, c1, f0 / (f0 - f1)), f0 > 0.0);
    let e1 = select(c1, mix(c1, c0, f1 / (f1 - f0)), f1 > 0.0);

    // both ends in screen pixels
    let vp = vec2<f32>(line.vp_w, line.vp_h);
    let s0 = (e0.xy / e0.w * 0.5 + 0.5) * vp;
    let s1 = (e1.xy / e1.w * 0.5 + 0.5) * vp;
    let d = s1 - s0;
    let len = length(d);
    let dir = select(vec2<f32>(1.0, 0.0), d / len, len > 1e-6);
    let n = vec2<f32>(-dir.y, dir.x);

    // a selected shaft is at least a full pen wide
    let selected = (inst.flags & FLAG_SELECTED) != 0u;
    let hw0 = max(half_width_px(v.radius, e0.w), select(0.0, line.thickness, selected));
    let hw1 = max(half_width_px(v.radius, e1.w), select(0.0, line.thickness, selected));
    let hw = max(hw0, hw1);

    // tips on the points, no head at an end the near plane cut; the heads share part of the vector
    // e.g. a 40 px arrow with one head: the head is at most 0.6 x 40 = 24 px, however thick the pen
    let only = (v.heads & HEAD_ONLY) != 0u;
    let at_end = (v.heads & HEAD_END) != 0u && f1 <= 0.0;
    let at_start = (v.heads & HEAD_START) != 0u && f0 <= 0.0;
    let most = select(len * HEAD_SHARE / select(1.0, 2.0, at_end && at_start), 3.0e38, only);
    let pens = select(HEAD_PENS, v.head, v.head > 0.0);
    let head1 = select(0.0, head_px(pens, hw1, most), at_end);
    let head0 = select(0.0, head_px(pens, hw0, most), at_start);
    let half1 = head1 * HEAD_ASPECT;
    let half0 = head0 * HEAD_ASPECT;

    // the shaft ends flat on a bare point and just under a head's base, px from the start
    // tuck = the shaft runs up to a pixel under the head, so no light seam shows between them
    let t0 = head0 - select(0.0, tuck(head0, half0, hw), at_start);
    let t1 = len - head1 + select(0.0, tuck(head1, half1, hw), at_end);

    // the three quads meet at seams, so no pixel is blended twice; a pixel on the seam belongs to one quad only
    var seam0 = select(-FILTER_REACH, head0 + FILTER_REACH, at_start);
    var seam1 = select(len + FILTER_REACH, len - head1 - FILTER_REACH, at_end);

    if (at_start && at_end && seam0 > seam1) {
        seam0 = (seam0 + seam1) * 0.5;
        seam1 = seam0;
    }

    let k = vid % 6u;
    let part = vid / 6u;
    let corner = CORNERS[k];
    let front = corner >= 2u;
    let side = select(-1.0, 1.0, (corner & 1u) == 1u);
    var along: f32;
    var across: f32;

    // a seam's corners are shared exactly, so no pixel on it falls between two quads
    let wide = max(max(half0, half1), max(hw, 0.5)) + FILTER_REACH;
    let narrow = max(hw, 0.5) + FILTER_REACH;

    if (part == 0u) {
        if (only) {
            return dead_vertex();
        }

        along = select(seam0, seam1, front);
        across = select(select(narrow, wide, at_start), select(narrow, wide, at_end), front);
    } else {
        let head = select(head0, head1, part == 1u);
        let half = select(half0, half1, part == 1u);

        if (head <= 0.0) {
            return dead_vertex();
        }

        // a sharp tip antialiases past itself by the reach over the tip half-angle's sine
        let past = FILTER_REACH * sqrt(head * head + half * half) / max(half, 1e-3);
        let span = select(vec2<f32>(-past, seam0), vec2<f32>(seam1, len + past), part == 1u);
        along = select(span.x, span.y, front);
        across = wide;
    }

    let p = s0 + dir * along + n * side * across;
    let depth = clamp(select(e0.z / e0.w, e1.z / e1.w, front), 0.0, 1.0);

    var o: VsOut;
    // w = 1: p is already in screen pixels, so no perspective divide is left to do
    o.pos = vec4<f32>((p / vp - 0.5) * 2.0, depth, 1.0);
    var color = edge_color(unpack4x8unorm(v.color), inst);

    if (selected) {
        color = vec4<f32>(SELECT_COLOR, color.a);
    }

    o.color = color;
    o.p = p;
    o.ends = vec4<f32>(s0, s1);
    o.shaft = select(vec4<f32>(s0 + dir * t0, s0 + dir * t1), vec4<f32>(s0, s0), only);
    o.head_end = vec4<f32>(s1 - dir * head1, n * half1);
    o.head_start = vec4<f32>(s0 + dir * head0, n * half0);
    o.widths = vec4<f32>(hw0, hw1, e0.z / e0.w, e1.z / e1.w);
    o.inst_id = v.instance_id;
    return o;
}

// Fraction of a pixel square lying below signed distance `t` from a line.
fn box_cdf(t: f32, hi: f32, lo: f32, m: f32, q: f32) -> f32 {
    let s = clamp(t, -hi, hi);
    let e = hi - abs(s);
    let tail = select(e * e / q, 1.0 - e * e / q, s > 0.0);
    return select(tail, 0.5 + s / m, abs(s) <= lo);
}

// Exact area of this pixel within `hw` of the line, `d` away, direction `g`; the ribbon filter.
fn band_area(d: f32, hw: f32, g: vec2<f32>) -> f32 {
    let a = abs(g.x);
    let b = abs(g.y);
    let hi = 0.5 * (a + b);
    let lo = 0.5 * abs(a - b);
    let m = max(max(a, b), 1e-6);
    let q = max(2.0 * a * b, 1e-6);
    return box_cdf(hw - d, hi, lo, m, q) + box_cdf(hw + d, hi, lo, m, q) - 1.0;
}

// A head's coverage is its signed distance turned into alpha: 0.5 px outside fades to 0, 0.5 px inside is 1.
// Signed distance from `p` to triangle (p0, p1, p2), negative inside.
fn triangle_distance(p: vec2<f32>, p0: vec2<f32>, p1: vec2<f32>, p2: vec2<f32>) -> f32 {
    let e0 = p1 - p0;
    let e1 = p2 - p1;
    let e2 = p0 - p2;
    let v0 = p - p0;
    let v1 = p - p1;
    let v2 = p - p2;
    let q0 = v0 - e0 * clamp(dot(v0, e0) / max(dot(e0, e0), 1e-6), 0.0, 1.0);
    let q1 = v1 - e1 * clamp(dot(v1, e1) / max(dot(e1, e1), 1e-6), 0.0, 1.0);
    let q2 = v2 - e2 * clamp(dot(v2, e2) / max(dot(e2, e2), 1e-6), 0.0, 1.0);
    // winding, so inside is negative either way round
    let s = select(-1.0, 1.0, e0.x * e2.y - e0.y * e2.x >= 0.0);
    let d = min(min(
        vec2<f32>(dot(q0, q0), s * (v0.x * e0.y - v0.y * e0.x)),
        vec2<f32>(dot(q1, q1), s * (v1.x * e1.y - v1.y * e1.x))),
        vec2<f32>(dot(q2, q2), s * (v2.x * e2.y - v2.y * e2.x)));
    return -sqrt(d.x) * select(-1.0, 1.0, d.y >= 0.0);
}

// How much of this pixel the head with its tip at `tip` covers; `head` is its base center and half base.
fn head_coverage(p: vec2<f32>, tip: vec2<f32>, head: vec4<f32>) -> f32 {
    if (dot(head.zw, head.zw) < 1e-6) {
        return 0.0;
    }

    return clamp(0.5 - triangle_distance(p, tip, head.xy + head.zw, head.xy - head.zw), 0.0, 1.0);
}

// How much of this pixel the shaft or the heads cover, 0..1.
fn coverage(in: VsOut) -> f32 {
    var alpha = 0.0;
    let run = in.shaft.zw - in.shaft.xy;
    let span = length(run);

    // the shaft: a band across times a band along, so both ends are flat; a round cap would poke past the point
    if (span > 1e-6) {
        let dir = run / span;
        let n = vec2<f32>(-dir.y, dir.x);
        let rel = in.p - in.shaft.xy;
        let whole = in.ends.zw - in.ends.xy;
        let h = clamp(dot(in.p - in.ends.xy, whole) / max(dot(whole, whole), 1e-6), 0.0, 1.0);
        let raw = mix(in.widths.x, in.widths.y, h);
        // thinner than a pixel: keep half a pixel, fade instead
        let fade = select(1.0, max(raw / 0.5, HAIRLINE_MIN_ALPHA), raw < 0.5);
        let across = clamp(band_area(abs(dot(rel, n)), max(raw, 0.5), n), 0.0, 1.0);
        let lengthwise = clamp(band_area(abs(dot(rel, dir) - span * 0.5), span * 0.5, dir), 0.0, 1.0);
        alpha = across * lengthwise * fade;
    }

    alpha = max(alpha, head_coverage(in.p, in.ends.zw, in.head_end));
    return max(alpha, head_coverage(in.p, in.ends.xy, in.head_start));
}

// The vector's center line as this fragment sees it.
fn ink_axis(in: VsOut) -> InkAxis {
    let ba = in.ends.zw - in.ends.xy;
    let len2 = max(dot(ba, ba), 1e-6);
    let h = clamp(dot(in.p - in.ends.xy, ba) / len2, 0.0, 1.0);
    let at = in.ends.xy + ba * h;
    let len = sqrt(len2);
    let along = select(vec2<f32>(1.0, 0.0), vec2<f32>(ba.x, -ba.y) / len, len > 1e-3);
    let slope = (in.widths.w - in.widths.z) / max(len, 1e-3);
    return InkAxis(vec2<f32>(at.x, line.vp_h - at.y), mix(in.widths.z, in.widths.w, h), along, slope);
}

// True when a clipping plane cuts the center line away beside this fragment.
fn axis_cut(in: VsOut) -> bool {
    if (!clip_active()) {
        return false;
    }

    let axis = ink_axis(in);
    return clip_cut_ndc(instances[in.inst_id].flags, clip_ndc(axis.at + line.origin, line.frame, axis.depth));
}

@fragment
// Color: the arrow, faded where geometry hides it.
fn fs_main(in: VsOut, @builtin(sample_index) sample: u32) -> InkColor {
    let covered = coverage(in);

    // no coverage: no depth reads
    if (covered <= 0.0 || axis_cut(in)) {
        discard;
    }

    let hidden = !ink_visible(in.pos.xy, ink_axis(in), sample, (instances[in.inst_id].flags & FLAG_SMOOTH) != 0u);
    let alpha = covered * through_glass(hidden);

    if (alpha <= 0.0) {
        discard;
    }

    return InkColor(vec4<f32>(in.color.rgb, in.color.a * alpha));
}

@fragment
// Pick id: object row + 1 and a marker tag.
fn fs_id(in: VsOut) -> @location(0) vec2<u32> {
    if (coverage(in) <= 0.0 || axis_cut(in) || !ink_visible(in.pos.xy, ink_axis(in), 0u, (instances[in.inst_id].flags & FLAG_SMOOTH) != 0u)) {
        discard;
    }

    return vec2<u32>(in.inst_id + 1u, DISC_ID_TAG);
}

use super::buffers::{GpuCtx, GrowBuf, ROWS, Template, bind_group};
use super::frame::Binds;
use super::upload::drop_rows;
use crate::engine::pipelines::{
    ColorWrite, DepthMode, Layouts, Pipeline, PipelineDesc, Shader, Target, build, ink_module,
    template_layout,
};
use wgpu::PrimitiveTopology::TriangleList;

/// Shader sources the tests compare against the files.
#[cfg(test)]
pub const SHADERS: &[(&str, &str)] = &[
    ("sphere.wgsl", shader!("sphere.wgsl")),
    ("glyph.wgsl", shader!("glyph.wgsl")),
];

/// Vertices per dot: one triangle around the disc, half the corners of a quad.
const DOT_VERTS: u32 = 3;

// Marker = a round spot on a mesh vertex, hidden on the back side like the edges.
// Dot = a round spot on a free point, drawn whichever way it faces.
/// One marker or dot, 48 bytes, as the shaders read it.
#[repr(C)]
#[derive(Clone, Copy, bytemuck::Pod, bytemuck::Zeroable)]
pub struct GlyphPoint {
    pub center: [f32; 3],     // world position
    pub radius: f32,          // 0 = pen width; > 0 world mm; < 0 screen px
    pub color: [f32; 4],      // rgba
    pub instance_id: u32,     // object row
    pub facing: u32,          // two face normals around the vertex, 16 bits each
    pub facing_ext: [u32; 2], // four more, six normals in all
}

const _: () = assert!(std::mem::size_of::<GlyphPoint>() == 48);

/// Marker and dot rows of one upload.
#[derive(Default)]
pub struct GlyphRows {
    pub spheres: Vec<GlyphPoint>, // vertex markers, shaded
    pub dots: Vec<GlyphPoint>,    // flat dots
}

impl GlyphRows {
    /// Empty both tables and free their memory.
    pub fn drop_rows(&mut self) {
        drop_rows(&mut self.spheres);
        drop_rows(&mut self.dots);
    }
}

/// One glyph buffer and its bind group.
struct GlyphTable {
    label: &'static str,    // name shown in GPU errors
    buf: GrowBuf,           // the rows
    group: wgpu::BindGroup, // group 3, binds the rows
}

impl GlyphTable {
    /// An empty table and its bind group.
    fn new(ctx: &GpuCtx, l: &Layouts, label: &'static str) -> Self {
        let buf = GrowBuf::new(ctx, label, std::mem::size_of::<GlyphPoint>() as u64, ROWS);
        let group = bind_group(ctx, &l.ink_rows, label, &[&buf.buf]);
        Self { label, buf, group }
    }

    /// Rebuild the bind group after the buffer moved.
    fn rebind(&mut self, ctx: &GpuCtx, l: &Layouts) {
        self.group = bind_group(ctx, &l.ink_rows, self.label, &[&self.buf.buf]);
    }
}

/// The two glyph shaders.
struct GlyphShaders {
    sphere: Shader, // shaded markers
    dot: Shader,    // flat dots
}

/// The five glyph pipelines.
struct GlyphPipelines {
    sphere: Pipeline,     // markers in color
    dot: Pipeline,        // dots in color
    id_sphere: Pipeline,  // marker object ids
    id_dot: Pipeline,     // dot object ids
    source_dot: Pipeline, // dot pick ids
}

/// Markers and dots on the GPU.
pub struct GlyphLane {
    spheres: GlyphTable,   // marker rows
    dots: GlyphTable,      // dot rows
    template: Template,    // one quad in a vertex buffer, drawn once per marker row
    shaders: GlyphShaders, // shader modules
    gpu: GlyphPipelines,   // pipelines
}

impl GlyphLane {
    /// Overwrite one marker or dot row.
    pub(crate) fn patch_marker(
        &mut self,
        ctx: &GpuCtx,
        index: u32,
        sphere: bool,
        glyph: GlyphPoint,
    ) {
        let table = if sphere {
            &mut self.spheres
        } else {
            &mut self.dots
        };
        table.buf.write_at(ctx, index, &[glyph]);
    }

    /// Overwrite one object's rows in place.
    pub(crate) fn patch(&mut self, ctx: &GpuCtx, at: super::patch::Counts, up: &GlyphRows) {
        self.spheres.buf.write_at(ctx, at.spheres, &up.spheres);
        self.dots.buf.write_at(ctx, at.dots, &up.dots);
    }

    /// Hand `count` marker or dot rows from `first` to the hidden row `sink`; as for strokes, undo stays instant.
    pub(crate) fn kill(&mut self, ctx: &GpuCtx, spheres: bool, first: u32, count: u32, sink: u32) {
        let table = if spheres { &self.spheres } else { &self.dots };
        let dead = GlyphPoint {
            instance_id: sink,
            ..bytemuck::Zeroable::zeroed()
        };
        table.buf.fill(ctx, first, count, &dead);
    }

    /// Bytes reserved on the GPU by this lane.
    pub fn allocated_bytes(&self) -> u64 {
        self.spheres.buf.buf.size()
            + self.dots.buf.buf.size()
            + self.template.vbo.size()
            + self.template.ibo.size()
    }

    /// Create the lane: quad, shaders, pipelines, empty tables.
    pub fn new(ctx: &GpuCtx, l: &Layouts, target: Target) -> Self {
        let (q_v, q_i) = unit_quad();
        let template = Template::new(ctx, "quad.template", &q_v, &q_i);
        let shaders = GlyphShaders {
            sphere: ink_module(ctx, "sphere.shader", shader!("sphere.wgsl")),
            dot: ink_module(ctx, "glyph.shader", shader!("glyph.wgsl")),
        };
        let gpu = build_pipelines(ctx, l, &shaders, target);
        let spheres = GlyphTable::new(ctx, l, "spheres");
        let dots = GlyphTable::new(ctx, l, "dots");
        Self {
            spheres,
            dots,
            template,
            shaders,
            gpu,
        }
    }

    /// Rebuild the pipelines for a new MSAA sample count.
    pub fn retarget(&mut self, ctx: &GpuCtx, l: &Layouts, target: Target) {
        self.gpu = build_pipelines(ctx, l, &self.shaders, target);
    }

    /// Append one upload's rows to both tables.
    pub fn append(&mut self, ctx: &GpuCtx, l: &Layouts, up: &GlyphRows) {
        if self.spheres.buf.append(ctx, &up.spheres) {
            self.spheres.rebind(ctx, l);
        }

        if self.dots.buf.append(ctx, &up.dots) {
            self.dots.rebind(ctx, l);
        }
    }

    /// Draw the markers in color.
    pub fn draw_spheres(&self, pass: &mut wgpu::RenderPass<'_>, b: &Binds) -> u32 {
        self.draw_markers(pass, b, &self.gpu.sphere)
    }

    /// Draw the dots in color.
    pub fn draw_dots(&self, pass: &mut wgpu::RenderPass<'_>, b: &Binds) -> u32 {
        self.draw_dot_table(pass, b, &self.gpu.dot)
    }

    /// Draw marker object ids.
    pub fn draw_sphere_ids(&self, pass: &mut wgpu::RenderPass<'_>, b: &Binds) -> u32 {
        self.draw_markers(pass, b, &self.gpu.id_sphere)
    }

    /// Draw dot object ids.
    pub fn draw_dot_ids(&self, pass: &mut wgpu::RenderPass<'_>, b: &Binds) -> u32 {
        self.draw_dot_table(pass, b, &self.gpu.id_dot)
    }

    /// Draw dot pick ids.
    pub fn draw_source_ids(&self, pass: &mut wgpu::RenderPass<'_>, b: &Binds) -> u32 {
        self.draw_dot_table(pass, b, &self.gpu.source_dot)
    }

    /// Draw every marker with `pipeline`; returns the draw count.
    fn draw_markers(&self, pass: &mut wgpu::RenderPass<'_>, b: &Binds, pipeline: &Pipeline) -> u32 {
        if self.spheres.buf.is_empty() {
            return 0;
        }

        pass.set_pipeline(pipeline);
        b.set(pass);
        pass.set_bind_group(3, &self.spheres.group, &[]);
        self.template.bind(pass);
        // the quad's 6 indices, once per marker row: the shader reads row `instance_index`
        pass.draw_indexed(0..self.template.index_count, 0, 0..self.spheres.buf.len());
        1
    }

    /// Draw every dot with `pipeline`; returns the draw count.
    fn draw_dot_table(
        &self,
        pass: &mut wgpu::RenderPass<'_>,
        b: &Binds,
        pipeline: &Pipeline,
    ) -> u32 {
        if self.dots.buf.is_empty() {
            return 0;
        }

        pass.set_pipeline(pipeline);
        b.set(pass);
        pass.set_bind_group(3, &self.dots.group, &[]);
        // three vertices per dot, placed by the shader
        pass.draw(0..DOT_VERTS * self.dots.buf.len(), 0..1);
        1
    }

    /// Forget every row; keep the buffers.
    pub fn reset(&mut self) {
        self.spheres.buf.reset();
        self.dots.buf.reset();
    }

    /// Free both buffers.
    pub fn release(&mut self, ctx: &GpuCtx, l: &Layouts) {
        self.spheres.buf.release(ctx);
        self.dots.buf.release(ctx);
        self.spheres.rebind(ctx, l);
        self.dots.rebind(ctx, l);
    }

    /// Marker rows on the GPU.
    pub fn sphere_count(&self) -> u32 {
        self.spheres.buf.len()
    }

    /// Dot rows on the GPU.
    pub fn dot_count(&self) -> u32 {
        self.dots.buf.len()
    }
}

/// Build the five glyph pipelines.
fn build_pipelines(ctx: &GpuCtx, l: &Layouts, s: &GlyphShaders, target: Target) -> GlyphPipelines {
    let groups = [&l.mvp, &l.line, &l.ink_instance, &l.ink_rows];
    let template = [template_layout()];
    // markers: quad template, always drawn
    let marker = PipelineDesc::new(&s.sphere, &groups, &template, TriangleList)
        .scene_samples(target.samples)
        .depth(DepthMode::Always);
    // dots: no vertex buffer, always drawn
    let disc = PipelineDesc::new(&s.dot, &groups, &[], TriangleList)
        .scene_samples(target.samples)
        .depth(DepthMode::Always);

    GlyphPipelines {
        sphere: build(
            ctx,
            target,
            &marker.with("sphere", "fs_main").color(ColorWrite::Blended),
        ),
        dot: build(
            ctx,
            target,
            &disc.with("glyph", "fs_main").color(ColorWrite::Blended),
        ),
        id_sphere: build(
            ctx,
            Target::ID,
            &marker
                .with("sphere.id", "fs_id")
                .vertex("vs_front")
                .scene_samples(1),
        ),
        id_dot: build(
            ctx,
            Target::ID,
            &disc.with("glyph.id", "fs_id").scene_samples(1),
        ),
        source_dot: build(
            ctx,
            Target::ID,
            &disc
                .with("glyph.source", "fs_source_id")
                .vertex("vs_source")
                .scene_samples(1)
                // only the dot in front survives, so a pick hits the point you see
                .depth(DepthMode::OpaqueEqual),
        ),
    }
}

/// A square from -1 to 1; the shader cuts it to a circle.
fn unit_quad() -> (Vec<[f32; 3]>, Vec<u32>) {
    let v = vec![
        [-1.0, -1.0, 0.0],
        [1.0, -1.0, 0.0],
        [1.0, 1.0, 0.0],
        [-1.0, 1.0, 0.0],
    ];
    let idx = vec![0u32, 1, 2, 0, 2, 3];
    (v, idx)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::engine::gpu::instance::wgsl_fields;

    /// Both shaders declare the same GlyphPoint fields.
    #[test]
    fn glyph_point_mirror() {
        let rust = [
            "center",
            "radius",
            "color",
            "instance_id",
            "facing",
            "facing_ext",
        ];

        for (name, src) in SHADERS {
            assert_eq!(
                wgsl_fields(src, "GlyphPoint"),
                rust,
                "{name}: GlyphPoint fields"
            );
        }

        assert_eq!(std::mem::size_of::<GlyphPoint>(), 48);
        assert_eq!(std::mem::offset_of!(GlyphPoint, facing_ext), 40);
    }
}

// The same Lane trait as the strokes: one loop in Gpu retargets, resets and releases both.
impl super::lane::Lane for GlyphLane {
    fn on_retarget(&mut self, ctx: &GpuCtx, layouts: &Layouts, target: Target) {
        self.retarget(ctx, layouts, target);
    }

    fn on_reset(&mut self, _ctx: &GpuCtx) {
        self.reset();
    }

    fn on_release(&mut self, ctx: &GpuCtx, layouts: &Layouts) {
        self.release(ctx, layouts);
    }

    fn bytes(&self) -> (u64, u64) {
        (self.allocated_bytes(), 0)
    }
}

