// One marker or dot, 48 bytes; matches GlyphPoint in Rust.
struct GlyphPoint {
    center: vec3<f32>, // world position
    radius: f32, // 0 = pen width; > 0 world mm; < 0 screen px
    color: vec4<f32>, // rgba
    instance_id: u32, // object row
    facing: u32, // packed normals of the faces around it
    facing_ext: vec2<u32>, // more packed normals
};

@group(3) @binding(0) var<storage, read> glyphs: array<GlyphPoint>; // one row per marker

// One triangle around the disc; the fragment shader cuts the circle.
// The corners sit 2 units from the center, so the unit circle just fits inside the triangle.
const CORNERS = array<vec2<f32>, 3>(
    vec2<f32>(0.0, 2.0),
    vec2<f32>(-1.7320508, -1.0),
    vec2<f32>(1.7320508, -1.0),
);

// What the vertex shader hands the fragment shader.
struct VsOut {
    @builtin(position) pos: vec4<f32>, // clip position
    @location(0) color: vec4<f32>, // rgba
    @location(1) corner: vec2<f32>, // -1..1 across the disc
    @location(2) @interpolate(linear) px: f32, // disc radius, px
    @location(3) @interpolate(linear) fade: f32, // alpha for discs thinner than a pixel
    @location(4) @interpolate(flat) inst_id: u32, // object row
    @location(5) @interpolate(flat) centre: vec2<f32>, // disc center, screen px
    @location(6) @interpolate(flat) depth: f32, // disc depth, 0..1
    @location(7) @interpolate(flat) point_index: u32, // row in the glyph table
};

// A vertex placed off screen, so nothing is drawn.
fn dead_dot() -> VsOut {
    var dead: VsOut; // all zero; only the position matters
    dead.pos = vec4<f32>(3.0, 3.0, 0.5, 1.0);
    return dead;
}

// Place one corner of a dot's triangle.
fn glyph_vertex(vid: u32) -> VsOut {
    let g = glyphs[vid / 3u];
    let inst = instances[g.instance_id];

    if ((inst.flags & FLAG_HIDDEN) != 0u) {
        return dead_dot();
    }

    let world = place(g.instance_id, g.center);

    // cut away by a clipping plane
    if (clip_active() && clip_cut(inst.flags, world)) {
        return dead_dot();
    }

    let clip = mvp * vec4<f32>(world, 1.0);

    // behind the camera
    if (clip.z - clip.w > 0.0) {
        return dead_dot();
    }

    // radius in px: pen width, world mm projected, or fixed px
    var px = line.thickness * 0.5;

    if (g.radius < 0.0) {
        px = -g.radius;
    } else if (g.radius > 0.0) {
        if (line.ortho_h > 0.0) {
            px = g.radius * line.vp_h * 0.5 / line.ortho_h;
        } else {
            px = g.radius * line.proj_y * line.vp_h * 0.5 / max(clip.w, 1e-6);
        }
    }

    // bigger than the screen: skip
    if (px > max(line.frame.x, line.frame.y)) {
        return dead_dot();
    }

    var fade = 1.0;

    // thinner than a pixel: keep half a pixel, fade instead
    if (px < 0.5) {
        fade = max(px / 0.5, HAIRLINE_MIN_ALPHA);
        px = 0.5;
    }

    let corner = CORNERS[vid % 3u];
    // corner offset in clip units: px to the -1..1 range is 2 / size, and times w survives the divide
    let off = corner * (px + 0.5 * line.feather) * 2.0 / vec2<f32>(line.vp_w, line.vp_h) * clip.w;

    var o: VsOut;
    o.pos = vec4<f32>(clip.xy + off, clip.z, clip.w);
    var color = edge_color(g.color, inst);

    if ((inst.flags & FLAG_SELECTED) != 0u) {
        color = vec4<f32>(SELECT_COLOR, color.a);
    }

    o.color = color;
    o.corner = corner;
    o.px = px;
    o.fade = fade;
    o.inst_id = g.instance_id;
    // clip to screen pixels
    o.centre = vec2<f32>((clip.x / clip.w * 0.5 + 0.5) * line.vp_w, (0.5 - clip.y / clip.w * 0.5) * line.vp_h);
    o.depth = clip.z / clip.w;
    o.point_index = vid / 3u;
    return o;
}

// Edge softness in px, never wider than the disc itself.
fn ramp(half_width: f32) -> f32 {
    return min(line.feather, 2.0 * half_width);
}

// How much of this pixel the disc covers, 0..1: 1 inside the radius, falling to 0 across the feather.
fn coverage(in: VsOut) -> f32 {
    let d = length(in.corner) * (in.px + 0.5 * line.feather);
    let f = ramp(in.px);
    return clamp((in.px + 0.5 * f - d) / f, 0.0, 1.0) * in.fade;
}

@fragment
// Color: the disc, faded where geometry hides it.
fn fs_main(in: VsOut, @builtin(sample_index) sample: u32) -> InkColor {
    let covered = coverage(in);

    // no coverage: no depth reads
    if (covered <= 0.0) {
        discard;
    }

    let hidden = !ink_disc_visible(in.pos.xy, in.centre, in.depth, sample);
    let alpha = covered * through_glass(hidden);

    if (alpha <= 0.0) {
        discard;
    }

    return InkColor(vec4<f32>(in.color.rgb, in.color.a * alpha));
}

@fragment
// Pick id: object row + 1 and a marker tag.
fn fs_id(in: VsOut) -> @location(0) vec2<u32> {
    if (coverage(in) < 0.5 || !ink_disc_visible(in.pos.xy, in.centre, in.depth, 0u)) {
        discard;
    }

    return vec2<u32>(in.inst_id + 1u, DISC_ID_TAG | (in.point_index + 1u));
}

// Ordinary dots.
@vertex
fn vs_main(@builtin(vertex_index) vid: u32) -> VsOut {
    return glyph_vertex(vid);
}

@vertex
// Dots standing for cloud points; facing_ext.x holds the point row.
fn vs_source(@builtin(vertex_index) vid: u32) -> VsOut {
    var out = glyph_vertex(vid);
    out.point_index = glyphs[vid / 3u].facing_ext.x;
    return out;
}

@fragment
// Pick id: object row + 1 and point row + 1.
fn fs_source_id(in: VsOut) -> @location(0) vec2<u32> {
    if (coverage(in) < 0.5) {
        discard;
    }

    return vec2<u32>(in.inst_id + 1u, in.point_index + 1u);
}

// A marker is an impostor: a camera-facing quad cut to a disc in the fragment shader,
// 4 vertices where a sphere mesh would need hundreds, and it looks the same from every side.
// One marker or dot, 48 bytes; matches GlyphPoint in Rust.
struct GlyphPoint {
    center: vec3<f32>, // world position
    radius: f32, // 0 = pen width; > 0 world mm; < 0 screen px
    color: vec4<f32>, // rgba
    instance_id: u32, // object row
    facing: u32, // packed normals of the faces around it
    facing_ext: vec2<u32>, // more packed normals
};

@group(3) @binding(0) var<storage, read> glyphs: array<GlyphPoint>; // one row per marker

// Markers shrink when vertices are closer than this many diameters.
const MARKER_MIN_DIAMS: f32 = 3.0;
// Markers never shrink below this factor.
const TAPER_MIN: f32 = 0.15; // a wire never thins below this

// World radius that projects to the pen width at this depth.
fn pen_world_radius(clip_w: f32) -> f32 {
    if (line.ortho_h > 0.0) {
        return line.thickness * line.ortho_h / line.vp_h;
    }

    return line.thickness * clip_w / (line.proj_y * line.vp_h);
}

// A world length in px at depth `w`.
fn to_px(world: f32, w: f32) -> f32 {
    if (line.ortho_h > 0.0) {
        return world * line.vp_h * 0.5 / line.ortho_h;
    }

    return world * line.proj_y * line.vp_h * 0.5 / max(w, 1e-6);
}

// What the vertex shader hands the fragment shader.
struct VsOut {
    @builtin(position) pos: vec4<f32>, // clip position
    @location(0) color: vec4<f32>, // rgba
    @location(1) corner: vec2<f32>, // -1..1 across the disc
    @location(2) @interpolate(flat) px: f32, // disc radius, px
    @location(3) @interpolate(flat) inst_id: u32, // object row
    @location(4) @interpolate(flat) centre: vec2<f32>, // disc center, screen px
    @location(5) @interpolate(flat) depth: f32, // disc depth, 0..1
};

// A vertex placed off screen, so nothing is drawn.
fn dead_dot() -> VsOut {
    var dead: VsOut; // all zero; only the position matters
    dead.pos = vec4<f32>(3.0, 3.0, 0.5, 1.0);
    return dead;
}

// (has face normals, one of them faces the camera).
// A vertex on the back of a closed mesh has every face turned away: its marker hides like the edges there.
fn faces_front(g: GlyphPoint, model: mat4x4<f32>, to_eye: vec3<f32>) -> vec2<bool> {
    let fwords = array<u32, 3>(g.facing, g.facing_ext.x, g.facing_ext.y);
    var known = false;

    for (var w = 0u; w < 3u; w = w + 1u) {
        let fw = fwords[w];

        if (fw == FACING_UNKNOWN) {
            continue;
        }

        known = true;

        // each word holds two normals: bits 0-15 and bits 16-31
        for (var h = 0u; h < 2u; h = h + 1u) {
            let n = face_normal(model, oct16_decode((fw >> (16u * h)) & 0xffffu));

            if (dot(n, to_eye) > 0.0) {
                return vec2<bool>(true, true);
            }
        }
    }

    return vec2<bool>(known, false);
}

@vertex
// Place one corner of a marker's quad; back markers show faint through translucent faces.
fn vs_main(@location(0) tmpl: vec3<f32>, @builtin(instance_index) gi: u32) -> VsOut {
    return marker_vertex(tmpl, gi, true);
}

@vertex
// Marker corner for pick ids, which drop hidden markers anyway.
fn vs_front(@location(0) tmpl: vec3<f32>, @builtin(instance_index) gi: u32) -> VsOut {
    return marker_vertex(tmpl, gi, false);
}

// One corner of marker `gi`'s quad; `through_faces` keeps back markers behind glass.
fn marker_vertex(tmpl: vec3<f32>, gi: u32, through_faces: bool) -> VsOut {
    let g = glyphs[gi];
    let inst = instances[g.instance_id];

    if ((inst.flags & FLAG_HIDDEN) != 0u) {
        return dead_dot();
    }

    let centre = place(g.instance_id, g.center);

    // cut away by a clipping plane
    if (clip_active() && clip_cut(inst.flags, centre)) {
        return dead_dot();
    }

    let clip = mvp * vec4<f32>(centre, 1.0);

    // behind the camera
    if (clip.z - clip.w > 0.0) {
        return dead_dot();
    }

    // radius: the object's, or the pen
    let r = select(pen_world_radius(clip.w), g.radius, g.radius > 0.0);
    var px = to_px(r, clip.w);

    // shrink where vertices crowd
    if (inst.spacing > 0.0) {
        let sp_px = to_px(inst.spacing, clip.w);
        px = px * clamp(sp_px / max(MARKER_MIN_DIAMS * 2.0 * px, 1e-6), TAPER_MIN, 1.0);
    }

    // bigger than the screen: skip
    if (px > max(line.frame.x, line.frame.y)) {
        return dead_dot();
    }

    px = max(px, 0.5);

    let off = tmpl.xy * (px + 0.5 * line.feather) * 2.0 / vec2<f32>(line.vp_w, line.vp_h) * clip.w;

    // no markers on sampled surfaces
    if ((inst.flags & FLAG_SMOOTH) != 0u) {
        return dead_dot();
    }

    // back-facing vertices are skipped, unless inside, open, x-ray or behind glass
    // glass: see-through faces (lesson 36) let back markers show faint, as ribbon.wgsl does for back edges
    let glass = through_faces && line.opacity < 1.0;
    let inside = (inst.flags & (FLAG_INSIDE | FLAG_OPEN)) != 0u || line.opacity <= 0.0 || glass;

    if (!inside) {
        let kf = faces_front(g, inst.model, toward_eye(centre));

        if (kf.x && !kf.y) {
            return dead_dot();
        }
    }

    var o: VsOut;
    o.pos = vec4<f32>(clip.xy + off, clip.z, clip.w);
    var color = edge_color(g.color, inst);

    if ((inst.flags & FLAG_SELECTED) != 0u) {
        color = vec4<f32>(SELECT_COLOR, color.a);
    }

    o.color = color;
    o.corner = tmpl.xy;
    o.px = px;
    o.inst_id = g.instance_id;
    // clip to screen pixels
    o.centre = vec2<f32>((clip.x / clip.w * 0.5 + 0.5) * line.vp_w, (0.5 - clip.y / clip.w * 0.5) * line.vp_h);
    o.depth = clip.z / clip.w;
    return o;
}

// Edge softness in px, never wider than the disc itself.
fn ramp(half_width: f32) -> f32 {
    return min(line.feather, 2.0 * half_width);
}

// How much of this pixel the disc covers, 0..1.
fn coverage(in: VsOut) -> f32 {
    let d = length(in.corner) * (in.px + 0.5 * line.feather);
    let f = ramp(in.px);
    return clamp((in.px + 0.5 * f - d) / f, 0.0, 1.0);
}

@fragment
// Color: the disc, faded where geometry hides it.
fn fs_main(in: VsOut, @builtin(sample_index) sample: u32) -> InkColor {
    let covered = coverage(in);

    // no coverage: no depth reads
    if (covered <= 0.0) {
        discard;
    }

    let hidden = !ink_disc_visible(in.pos.xy, in.centre, in.depth, sample);
    let alpha = covered * through_glass(hidden);

    if (alpha <= 0.0) {
        discard;
    }

    return InkColor(vec4<f32>(in.color.rgb, in.color.a * alpha));
}

@fragment
// Pick id: object row + 1 and a marker tag.
fn fs_id(in: VsOut) -> @location(0) vec2<u32> {
    if (coverage(in) < 0.5 || !ink_disc_visible(in.pos.xy, in.centre, in.depth, 0u)) {
        discard;
    }

    return vec2<u32>(in.inst_id + 1u, DISC_ID_TAG);
}

use super::buffers::{GpuCtx, GrowBuf, ROWS};
use super::upload::drop_rows;
use crate::engine::pipelines::Layouts;

/// Marker for a cloud that has no normals.
pub const NO_NORMALS: u32 = u32::MAX;

// A large cloud streams in batches: 13.8 million points arrive as many uploads, each drawn as soon as it lands.
/// One batch of points added to a cloud.
pub struct CloudDraw {
    pub instance: u32,   // object row of the cloud
    pub from: u32,       // first point index within the cloud
    pub count: u32,      // points in this batch
    pub first: u32,      // row of the first point in the upload
    pub spacing: f32,    // typical distance between points
    pub node_first: u32, // first octree node in the upload
    pub node_count: u32, // octree nodes; 0 = no octree
    pub nrm_first: u32,  // first normal row, or NO_NORMALS
}

/// One box of the cloud's octree: a box split into 8 child boxes, again and again, with each box's points stored in one run.
#[derive(Clone, Copy)]
pub struct LodNode {
    pub center: [f32; 3],   // box center
    pub size: f32,          // box edge length
    pub spacing: f32,       // point spacing inside the box
    pub first: u32,         // first point of the box, within the cloud
    pub count: u32,         // points in the box
    pub children: [i32; 8], // child node indices, -1 = none
}

/// A run of cloud points stored on the GPU.
#[derive(Clone, Copy)]
pub struct Chunk {
    pub from: u32, // first point index within the cloud
    pub to: u32,   // one past the last point index
    pub row: u32,  // GPU row of the first point
    pub nrm: u32,  // GPU row of its first normal, or NO_NORMALS
}

impl Chunk {
    /// GPU row of cloud point `i`.
    pub fn row_of(&self, i: u32) -> u32 {
        self.row + (i - self.from)
    }
}

/// One point cloud on the GPU.
pub struct Cloud {
    pub instance: u32,      // object row
    pub spacing: f32,       // typical distance between points
    pub node_first: u32,    // first octree node
    pub node_count: u32,    // octree nodes; 0 = no octree
    pub resident: u32,      // points uploaded so far
    pub chunks: Vec<Chunk>, // where those points live
}

impl Cloud {
    /// GPU row of cloud point `i`, None if not uploaded.
    pub fn row_of(&self, i: u32) -> Option<u32> {
        for chunk in &self.chunks {
            if i >= chunk.from && i < chunk.to {
                return Some(chunk.row_of(i));
            }
        }

        None
    }
}

/// Point rows of one upload.
#[derive(Default)]
pub struct CloudRows {
    pub pos: Vec<f32>,         // x, y, z per point
    pub col: Vec<u32>,         // packed color per point
    pub nrm: Vec<u32>,         // packed normal per point
    pub draws: Vec<CloudDraw>, // point batches in this upload
    pub nodes: Vec<LodNode>,   // octree nodes in this upload
    pub expect: u32,           // points known to follow this upload
    pub expect_normals: u32,   // normals known to follow this upload
}

impl CloudRows {
    /// Points in this upload so far.
    pub fn point_count(&self) -> u32 {
        (self.pos.len() / 3) as u32
    }

    /// Empty every table and free its memory.
    pub fn drop_rows(&mut self) {
        drop_rows(&mut self.pos);
        drop_rows(&mut self.col);
        drop_rows(&mut self.nrm);
        drop_rows(&mut self.draws);
        drop_rows(&mut self.nodes);
    }
}

/// The three point buffers, borrowed for binding.
pub struct PointBufs<'a> {
    pub pos: &'a wgpu::Buffer,
    pub col: &'a wgpu::Buffer,
    pub nrm: &'a wgpu::Buffer,
}

/// All point clouds on the GPU.
pub struct CloudLane {
    pos: GrowBuf,            // positions
    col: GrowBuf,            // colors
    nrm: GrowBuf,            // normals
    pub clouds: Vec<Cloud>,  // one entry per cloud
    pub buried: Vec<Cloud>,  // deleted clouds an undo may draw again, points kept on the GPU
    pub nodes: Vec<LodNode>, // octree nodes of every cloud
    pub point_count: u32,    // points on the GPU
}

impl CloudLane {
    /// Bytes reserved on the GPU by this lane.
    pub fn allocated_bytes(&self) -> u64 {
        self.pos.buf.size() + self.col.buf.size() + self.nrm.buf.size()
    }

    /// Create the lane with empty buffers.
    pub fn new(ctx: &GpuCtx) -> Self {
        Self {
            pos: GrowBuf::new(ctx, "points.buffer", 4, ROWS),
            col: GrowBuf::new(ctx, "points.col.buffer", 4, ROWS),
            nrm: GrowBuf::new(ctx, "points.nrm.buffer", 4, ROWS),
            clouds: Vec::new(),
            buried: Vec::new(),
            nodes: Vec::new(),
            point_count: 0,
        }
    }

    /// True when `more` points fit in the largest buffers this device allows.
    pub fn fits(&self, ctx: &GpuCtx, more: u32) -> bool {
        let more = u64::from(more);
        self.pos.fits(ctx, more * 3) && self.col.fits(ctx, more) && self.nrm.fits(ctx, more)
    }

    /// Append one upload; returns true if a buffer was replaced.
    pub fn append(&mut self, ctx: &GpuCtx, up: &CloudRows) -> bool {
        debug_assert_eq!(up.col.len() * 3, up.pos.len());

        // past the device's largest buffer the upload is dropped, not the device
        if !self.fits(ctx, up.point_count()) {
            log::warn!(
                "{} cloud points do not fit beside the {} on the GPU; not drawn",
                up.point_count(),
                self.point_count
            );
            return false;
        }

        // rows before this upload
        let point_base = self.point_count;
        let nrm_base = self.nrm.len();
        let node_base = self.nodes.len() as u32;

        // a full buffer grows to exactly the points known to come, not by half:
        // 13.8 M points need 166 MB of positions; growing by half would reserve up to 83 MB more for nothing
        let (expect, normals) = (u64::from(up.expect), u64::from(up.expect_normals));
        let mut moved = self.pos.reserve(ctx, up.pos.len() as u64, expect * 3);
        moved |= self.col.reserve(ctx, up.col.len() as u64, expect);
        moved |= self.nrm.reserve(ctx, up.nrm.len() as u64, normals);
        moved |= self.pos.append(ctx, &up.pos);
        moved |= self.col.append(ctx, &up.col);
        moved |= self.nrm.append(ctx, &up.nrm);
        self.point_count = self.pos.len() / 3;
        self.nodes.extend_from_slice(&up.nodes);

        for d in &up.draws {
            let chunk = Chunk {
                from: d.from,
                to: d.from + d.count,
                row: point_base + d.first,
                nrm: if d.nrm_first == NO_NORMALS {
                    NO_NORMALS
                } else {
                    nrm_base + d.nrm_first
                },
            };

            // a later batch extends an existing cloud
            if d.from > 0 {
                self.extend(d.instance, chunk);
                continue;
            }

            // first batch opens a new cloud
            self.clouds.push(Cloud {
                instance: d.instance,
                spacing: d.spacing,
                node_first: d.node_first + node_base,
                node_count: d.node_count,
                resident: chunk.to,
                chunks: vec![chunk],
            });
        }

        moved
    }

    /// Add a batch to the cloud on object row `instance`.
    fn extend(&mut self, instance: u32, chunk: Chunk) {
        for cloud in self.clouds.iter_mut().chain(self.buried.iter_mut()) {
            if cloud.instance != instance {
                continue;
            }

            // batches must arrive in order
            if chunk.from != cloud.resident {
                log::warn!(
                    "cloud chunk [{}, {}) does not continue the {} resident points; dropped",
                    chunk.from,
                    chunk.to,
                    cloud.resident
                );
                return;
            }

            cloud.resident = chunk.to;
            cloud.chunks.push(chunk);
            return;
        }

        log::warn!("cloud chunk for row {instance} arrived before its cloud; dropped");
    }

    /// Stop drawing the cloud on object row `instance`, buried or not; returns its resident points, now dead.
    pub fn kill_instance(&mut self, instance: u32) -> u32 {
        if let Some(at) = self.clouds.iter().position(|c| c.instance == instance) {
            return self.clouds.remove(at).resident;
        }

        match self.buried.iter().position(|c| c.instance == instance) {
            Some(at) => self.buried.remove(at).resident,
            None => 0,
        }
    }

    /// Stop drawing the cloud on object row `instance` but keep its points for an undo; false when none is drawn.
    /// Undo is instant: burying moves one small entry between two lists, the points never leave the GPU.
    pub fn bury_instance(&mut self, instance: u32) -> bool {
        let Some(at) = self.clouds.iter().position(|c| c.instance == instance) else {
            return false;
        };

        let cloud = self.clouds.remove(at);
        self.buried.push(cloud);
        true
    }

    /// Draw a buried cloud again; false when none is buried on that row.
    pub fn unbury_instance(&mut self, instance: u32) -> bool {
        let Some(at) = self.buried.iter().position(|c| c.instance == instance) else {
            return false;
        };

        let cloud = self.buried.remove(at);
        self.clouds.push(cloud);
        true
    }

    /// Copy the live clouds' points, normals and nodes into buffers of exact size; the old ones are freed.
    pub fn compact(&mut self, ctx: &GpuCtx) {
        let mut pos = Vec::new(); // (first row, rows) runs to keep
        let mut col = Vec::new();
        let mut nrm = Vec::new();
        let mut nodes = Vec::new();
        let mut points = 0u32;
        let mut normals = 0u32;

        // buried clouds move too: an undo still finds their points
        for cloud in self.clouds.iter_mut().chain(self.buried.iter_mut()) {
            for chunk in &mut cloud.chunks {
                let count = chunk.to - chunk.from;
                pos.push((chunk.row * 3, count * 3));
                col.push((chunk.row, count));
                chunk.row = points;
                points += count;

                if chunk.nrm != NO_NORMALS {
                    nrm.push((chunk.nrm, count));
                    chunk.nrm = normals;
                    normals += count;
                }
            }

            let first = cloud.node_first as usize;
            let end = (first + cloud.node_count as usize).min(self.nodes.len());
            cloud.node_first = nodes.len() as u32;
            nodes.extend_from_slice(&self.nodes[first.min(end)..end]);
        }

        // the copies run on the GPU, buffer to buffer; no point passes through the CPU
        let mut encoder = ctx.device.create_command_encoder(&Default::default());
        let fresh = [
            self.pos.packed(ctx, &mut encoder, &pos),
            self.col.packed(ctx, &mut encoder, &col),
            self.nrm.packed(ctx, &mut encoder, &nrm),
        ];
        ctx.queue.submit([encoder.finish()]);
        let [p, c, n] = fresh;
        self.pos.swap_in(p);
        self.col.swap_in(c);
        self.nrm.swap_in(n);
        self.nodes = nodes;
        self.point_count = points;
    }

    /// Cloud of a GPU point row: (object row, point index).
    pub fn row_of(&self, row: u32) -> Option<(u32, u32)> {
        for c in &self.clouds {
            for k in &c.chunks {
                if row >= k.row && row < k.row + (k.to - k.from) {
                    return Some((c.instance, k.from + (row - k.row)));
                }
            }
        }

        None
    }

    /// The three point buffers.
    pub fn buffers(&self) -> PointBufs<'_> {
        PointBufs {
            pos: &self.pos.buf,
            col: &self.col.buf,
            nrm: &self.nrm.buf,
        }
    }

    /// Points uploaded across every cloud.
    pub fn resident(&self) -> u32 {
        let mut resident = 0;

        for cloud in &self.clouds {
            resident += cloud.resident;
        }

        resident
    }

    /// Forget every row; keep the buffers.
    pub fn reset(&mut self) {
        self.pos.reset();
        self.col.reset();
        self.nrm.reset();
        self.point_count = 0;
        self.clouds.clear();
        self.buried.clear();
        self.nodes.clear();
    }

    /// Forget every row and free the buffers.
    pub fn release(&mut self, ctx: &GpuCtx) {
        self.reset();
        self.pos.release(ctx);
        self.col.release(ctx);
        self.nrm.release(ctx);
        self.clouds.shrink_to_fit();
        self.buried.shrink_to_fit();
        self.nodes.shrink_to_fit();
    }
}

// No on_retarget: this lane has buffers only; the pipelines that draw clouds live in splat.rs.
impl super::lane::Lane for CloudLane {
    fn on_reset(&mut self, _ctx: &GpuCtx) {
        self.reset();
    }

    fn on_release(&mut self, ctx: &GpuCtx, _layouts: &Layouts) {
        self.release(ctx);
    }

    fn bytes(&self) -> (u64, u64) {
        (self.allocated_bytes(), 0)
    }
}

// A second impl block, as for SegRows: the merge comes at the end of the file.
impl CloudRows {
    /// Move `other`'s points after these, its batches shifted to match.
    pub fn merge(&mut self, other: &mut CloudRows) {
        let cloud = self;
        let points = cloud.point_count();
        let nodes = cloud.nodes.len() as u32;
        let normals = cloud.nrm.len() as u32;

        for mut draw in other.draws.drain(..) {
            draw.first += points;
            draw.node_first += nodes;

            if draw.nrm_first != NO_NORMALS {
                draw.nrm_first += normals;
            }

            cloud.draws.push(draw);
        }

        cloud.pos.append(&mut other.pos);
        cloud.col.append(&mut other.col);
        cloud.nrm.append(&mut other.nrm);
        cloud.nodes.append(&mut other.nodes);
    }
}

/// The extreme points of every vertex, segment end and marker one walk wrote, with `more`; None
/// when the walk wrote rows without points here, or its points do not span `bounds`.
pub fn hull_of(up: &Upload, more: &[[f32; 3]], bounds: &AABB) -> Option<Hull> {
    let seg = &up.seg;
    let lanes = super::patch::Counts::of(up)
        .lanes
        .iter()
        .any(|rows| *rows > 0);
    let unread = lanes || !up.cloud.pos.is_empty() || !seg.sheet_rows.is_empty();

    if unread || !bounds.is_valid() {
        return None;
    }

    // each source on its own first: a mesh's vertices are never gathered
    let sources = [
        Points::of(&up.arena.verts, &[0]),
        Points::of(&seg.pipes, &[0, 4]),
        Points::of(&seg.ribbons, &[0, 4]),
        Points::of(&up.glyph.spheres, &[0]),
        Points::of(&up.glyph.dots, &[0]),
    ];
    let mut points = more.to_vec();

    for source in sources {
        points.extend(extreme_points(source)?);
    }

    let hull = extreme_points(Points::of(&points, &[0]))?;
    spans(&hull, bounds).then(|| Hull::from(hull))
}

