use crate::engine::gpu::vectors::VectorRows;
use crate::engine::gpu::{Instance, Upload};
use session_rust::{AABB, Xform};

/// Table lengths before a file is walked, so the rows it added can be found afterwards.
#[derive(Default)]
pub struct Baselines {
    pub obj: usize,    // object rows so far
    pub pipe: usize,   // pipe segments so far
    pub ribbon: usize, // ribbon segments so far
    pub vector: usize, // vector rows so far
}

impl Baselines {
    /// Every table's length now.
    pub fn capture(t: &Upload) -> Self {
        Self {
            obj: t.obj.rows.len(),
            pipe: t.seg.pipes.len(),
            ribbon: t.seg.ribbons.len(),
            vector: t.lanes.get::<VectorRows>().map_or(0, |v| v.rows.len()),
        }
    }
}

/// World box of every object added since `from`.
pub fn file_extent(t: &Upload, from: &Baselines) -> AABB {
    let mut out = AABB::empty();

    for r in t.obj.rows.iter().skip(from.obj) {
        // a dead row is never drawn: the sink, or a definition its instances place
        if r.flags & Instance::FLAG_DEAD == 0 {
            out.union_with(&crate::engine::gpu::objects::world_box(r));
        }
    }

    out
}

// Band = the thin z range a flat drawing lies in; rows inside a sheet's band belong to that sheet (lesson 19).
/// The z band [lowest, highest] of the new rows when every one is flat at one placement.
pub fn planar_band(t: &Upload, from: &Baselines, place: &Xform) -> Option<[f64; 2]> {
    let mut lo = f64::INFINITY;
    let mut hi = f64::NEG_INFINITY;

    for r in t.obj.rows.iter().skip(from.obj) {
        if r.flags & Instance::FLAG_DEAD != 0 {
            continue;
        }

        if r.place != *place {
            return None;
        }

        if !r.bounds.is_valid() {
            continue;
        }

        lo = lo.min(r.bounds.cz - r.bounds.hz); // lowest z
        hi = hi.max(r.bounds.cz + r.bounds.hz); // highest z
    }

    (lo.is_finite() && (hi - lo).abs() < 1e-3).then_some([lo, hi]) // thinner than a micron
}

/// True when one row lies flat inside a sheet's band, at the sheet's placement.
pub fn in_band(band: [f64; 2], bounds: &AABB, place: &Xform, sheet: &Xform) -> bool {
    if place != sheet {
        return false;
    }

    if !bounds.is_valid() {
        return true;
    }

    let lo = bounds.cz - bounds.hz;
    let hi = bounds.cz + bounds.hz;
    hi - lo < 1e-3 && lo >= band[0] - 1e-3 && hi <= band[1] + 1e-3
}

/// Give every pipe, ribbon and arrowhead added since `from` without a pen a 1 mm one.
pub fn mark_pens_from(t: &mut Upload, from: &Baselines) {
    for s in t
        .seg
        .pipes
        .iter_mut()
        .skip(from.pipe)
        .chain(t.seg.ribbons.iter_mut().skip(from.ribbon))
    {
        if s.radius <= 0.0 {
            s.radius = 0.5; // half width in mm
        }
    }

    // heads keep the width of the curve they end; no table is made where no head was walked
    if t.lanes.get::<VectorRows>().is_none() {
        return;
    }

    for v in t
        .lanes
        .get_mut::<VectorRows>()
        .rows
        .iter_mut()
        .skip(from.vector)
    {
        if v.radius <= 0.0 {
            v.radius = 0.5;
        }
    }
}

/// Flag every new row as sheet content with a 1 mm pen.
pub fn mark_sheet(t: &mut Upload, from: &Baselines) {
    for o in t.obj.rows.iter_mut().skip(from.obj) {
        o.flags |= Instance::FLAG_SHEET;
    }

    mark_pens_from(t, from);
}

// BRep = a solid or shell described by its boundary: surface patches and the curves where they meet.
// Face = one patch of one surface, cut to shape by trim loops drawn in that surface's own (u, v) coordinates.
// Edge = the curve two faces share; both face meshes must put vertices on the same points of it, or cracks and double lines appear.
// Seam = the edge where a closed surface meets itself, e.g. a cylinder's u = 0 and u = 2π.
// Hidden line = ink a face covers; the walk only records each edge's faces and normals, lesson 05's test hides it per pixel.
use super::brep_edges::{EdgeChain, EdgePen, edge_chains, push_edge_pipes};
use super::brep_orient::face_signs;
use super::curves::{push_polyline, sample_nurbscurve};
use super::encode::{Pen, encode_width, pack_rgba};
use super::mesh::mesh_spacing;
use super::mesh_ink::Ink;
use super::{Row, WalkCx};
use crate::app::knobs;
use crate::engine::gpu::Instance;
use crate::engine::gpu::arena::ArenaRows;
use session_rust::AABB;
use session_rust::{BRep, Color, Mesh, NurbsSurface, RenderMesh};

/// Mesh quality: 5° between samples, chord sag 0.001 of the size, e.g. at most 0.1 mm on a 100 mm cylinder.
pub const QUALITY: (f64, f64) = (5.0, 0.001);

/// Every face uploaded so far.
struct Solid {
    pos: Vec<[f32; 3]>, // vertex positions
    tris: Vec<u32>,     // triangle indices into `pos`
    bounds: AABB,       // box of all vertices
}

/// Append one face mesh to the arena.
fn push_face(arena: &mut ArenaRows, rm: &RenderMesh, cx: &WalkCx, solid: &mut Solid, face: usize) {
    // one source face address for every triangle
    let address = arena.face_sources.len() as u32;
    arena
        .face_sources
        .push(crate::engine::gpu::faces::FaceSource {
            parent: cx.row,
            face,
        });
    arena
        .face_ids
        .extend(std::iter::repeat_n(address, rm.indices.len() / 3));
    let base = cx.vert_base + arena.verts.len() as u32; // first GPU vertex index
    let local = solid.pos.len() as u32; // first index in `solid`
    arena.verts.reserve(rm.vertices.len());
    arena.vids.reserve(rm.vertices.len());

    for v in &rm.vertices {
        solid.bounds.union_with_point(
            v.position[0] as f64,
            v.position[1] as f64,
            v.position[2] as f64,
        );
        solid.pos.push(v.position);
        arena.verts.push(*v);
        arena.vids.push(cx.row);
    }

    arena.idx.reserve(rm.indices.len());

    for &i in &rm.indices {
        arena.idx.push(base + i);
        solid.tris.push(local + i);
    }
}

/// A BRep: every face meshed and uploaded, then its edges.
pub fn walk_brep(arena: &mut ArenaRows, ink: &mut Ink, b: &BRep, cx: &WalkCx) -> Row {
    let mut fms = b.face_meshes_q(Some(QUALITY)); // one mesh per face, meshed by the kernel
    let chains = edge_chains(b, &fms); // edge polylines on the meshes
    let signs = face_signs(b, &fms, &chains); // +1 or -1 per face
    let mut solid = Solid {
        pos: Vec::new(),
        tris: Vec::new(),
        bounds: AABB::empty(),
    };
    let mut verts = 0; // vertex total for spacing
    let mut boundary_vertices = Vec::with_capacity(fms.len()); // per face: vertex key to GPU index

    for (fi, fm) in fms.iter_mut().enumerate() {
        fm.set_objectcolor(b.surfacecolor.clone());
        verts += fm.vertex.len();
        let mut rm = fm.to_render();

        // an inside-out face (sign -1, lesson 09): flip normals and winding, so its front faces out of the solid
        if signs[fi] < 0.0 {
            for vertex in &mut rm.vertices {
                for component in &mut vertex.normal {
                    *component = -*component;
                }
            }

            for triangle in rm.indices.chunks_exact_mut(3) {
                triangle.swap(1, 2);
            }
        }

        let mut keys: Vec<_> = fm.vertex.keys().copied().collect();
        keys.sort_unstable();
        boundary_vertices.push(
            keys.into_iter()
                .enumerate()
                .map(|(i, key)| (key, arena.verts.len() as u32 + i as u32))
                .collect::<std::collections::HashMap<_, _>>(),
        );
        let surface_index = b.m_faces[fi].surface_index as usize;
        cache_samples(arena, fm, &rm, &b.m_surfaces[surface_index], surface_index); // uv per vertex for live edits
        push_face(arena, &rm, cx, &mut solid, fi);
    }

    let mut flags = Instance::FLAG_SMOOTH; // vertices are samples

    if !b.is_solid() {
        flags |= Instance::FLAG_OPEN;
    }

    // closed shells, faces turned outward: a clipping plane caps it
    if b.is_solid() {
        flags |= Instance::FLAG_CLOSED;
    }

    if b.face_count() == 1 {
        flags |= Instance::FLAG_SINGLE;
    }

    let mut row = Row {
        bounds: solid.bounds,
        spacing: mesh_spacing(&solid.bounds, verts),
        flags,
        faces: true,
    };

    if !knobs::no_edges() {
        let pen = Pen {
            row: cx.row,
            radius: encode_width(b.width),
            color: pack_rgba(Color::black().to_f32()),
        };
        let ep = EdgePen::new(&fms, &signs, pen);
        walk_brep_edges(
            ink,
            b,
            &chains,
            (&ep, &mut row.bounds),
            arena,
            &boundary_vertices,
        );
    }

    row
}

/// Every BRep edge as pipes, or as a ribbon when no mesh owns it.
fn walk_brep_edges(
    ink: &mut Ink,
    b: &BRep,
    chains: &[Option<EdgeChain>],
    out: (&EdgePen, &mut AABB),
    arena: &mut ArenaRows,
    boundary_vertices: &[std::collections::HashMap<usize, u32>],
) {
    let (ep, bounds) = out;

    for (ei, chain) in chains.iter().enumerate() {
        match chain {
            Some(c) => {
                let mut pipe = ink.seg.pipes.len() as u32;
                push_edge_pipes(ink.seg, c, ep, bounds);
                // remember which vertices each pipe joins
                for pair in c.keys.windows(2) {
                    let ends = [
                        boundary_vertices[c.face][&pair[0]],
                        boundary_vertices[c.face][&pair[1]],
                    ];
                    let a = arena.verts[ends[0] as usize].position;
                    let b = arena.verts[ends[1] as usize].position;
                    if a == b || !a.into_iter().chain(b).all(f32::is_finite) {
                        continue;
                    }
                    arena.surface_boundaries.push((pipe, ends));
                    pipe += 1;
                }
            }
            None => {
                if !b.m_edges[ei].degenerated && !b.edge_faces(ei).is_empty() {
                    log::warn!(
                        "BREP {:?} edge {ei}: missing tessellation boundary mapping; analytic display fallback is not a coherent CAD boundary",
                        b.name
                    );
                }

                push_curve_ribbon(ink, b, ei, (&ep.pen, bounds));
            }
        }
    }
}

/// An edge sampled from its 3D curve as a ribbon.
fn push_curve_ribbon(ink: &mut Ink, b: &BRep, ei: usize, out: (&Pen, &mut AABB)) {
    let edge = &b.m_edges[ei];

    if edge.degenerated || edge.curve_3d_index < 0 {
        return;
    }

    let points: Vec<[f32; 3]> = sample_nurbscurve(&b.m_curves_3d[edge.curve_3d_index as usize])
        .into_iter()
        .map(super::curves::render_position)
        .collect();

    if points.len() < 2 {
        return;
    }

    push_polyline(ink.seg, &points, out.0, out.1);
}

// A bare NURBS surface has no trims and no BRep edges: a (u, v) grid, 4 steps per control point, 16 to 96 each way.
/// A NURBS surface as a fixed UV grid with its four border edges.
pub fn walk_surface(arena: &mut ArenaRows, ink: &mut Ink, s: &NurbsSurface, cx: &WalkCx) -> Row {
    let (Some((u0, u1)), Some((v0, v1))) = (s.domain(0), s.domain(1)) else {
        return Row::thin(AABB::empty());
    };
    let nu = (s.m_cv_count[0] * 4).clamp(16, 96); // grid steps in u
    let nv = (s.m_cv_count[1] * 4).clamp(16, 96); // grid steps in v
    let first = arena.verts.len(); // index of this surface's first vertex
    let base = cx.vert_base + first as u32; // first GPU vertex index
    let color = s.facecolors.first().cloned().unwrap_or_default().to_f32();
    let mut bounds = AABB::empty();
    // one vertex per grid point
    for i in 0..=nu {
        for j in 0..=nv {
            let u = u0 + (u1 - u0) * i as f64 / nu as f64;
            let v = v0 + (v1 - v0) * j as f64 / nv as f64;
            let point = s.point_at(u, v).unwrap_or_default();
            let normal = s.normal_at(u, v);
            bounds.union_with_point(point[0], point[1], point[2]);
            arena
                .surface_samples
                .push(crate::engine::gpu::arena::Sample {
                    index: arena.verts.len() as u32,
                    surface: 0,
                    uv: [u, v],
                    sign: 1.0,
                });
            arena.verts.push(session_rust::RenderVertex {
                position: point.to_f32(),
                normal: [normal[0] as f32, normal[1] as f32, normal[2] as f32],
                color,
            });
            arena.vids.push(cx.row);
        }
    }
    let address = arena.face_sources.len() as u32;
    arena
        .face_sources
        .push(crate::engine::gpu::faces::FaceSource {
            parent: cx.row,
            face: 0,
        });
    // two triangles per grid cell
    for i in 0..nu {
        for j in 0..nv {
            let a = base + (i * (nv + 1) + j) as u32;
            let b = a + (nv + 1) as u32;
            arena.idx.extend_from_slice(&[a, b, b + 1, a, b + 1, a + 1]);
            arena.face_ids.extend_from_slice(&[address, address]);
        }
    }
    if !knobs::no_edges() {
        ink.seg.pipe_ids.resize(ink.seg.pipes.len(), u32::MAX);
        // the four border edges, skipping a closed direction
        for edge in 0..4 {
            let direction = edge / 2;
            if s.is_closed(direction) {
                continue;
            }
            let indices: Vec<_> = match edge {
                0 => (0..=nv).collect(),
                1 => (0..=nv).map(|j| nu * (nv + 1) + j).collect(),
                2 => (0..=nu).map(|i| i * (nv + 1)).collect(),
                _ => (0..=nu).map(|i| i * (nv + 1) + nv).collect(),
            };
            let start = ink.seg.pipes.len() as u32;
            for ends in indices.windows(2) {
                ink.seg.pipes.push(crate::engine::gpu::CylinderSegment {
                    p0: arena.verts[first + ends[0]].position,
                    p1: arena.verts[first + ends[1]].position,
                    radius: encode_width(s.width),
                    instance_id: cx.row,
                    color: super::encode::BLACK,
                    facing: super::encode::FACING_UNKNOWN,
                });
                arena.surface_boundaries.push((
                    ink.seg.pipes.len() as u32 - 1,
                    [(first + ends[0]) as u32, (first + ends[1]) as u32],
                ));
                ink.seg.pipe_ids.push(edge as u32);
            }
            ink.seg.pipe_chains.push(start..ink.seg.pipes.len() as u32);
        }
    }
    Row {
        bounds,
        spacing: mesh_spacing(&bounds, (nu + 1) * (nv + 1)),
        flags: Instance::FLAG_SINGLE | Instance::FLAG_SMOOTH | Instance::FLAG_OPEN,
        faces: true,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::app::walk::brep_edges::edge_chains;
    use crate::engine::gpu::Instance;
    use crate::engine::gpu::glyphs::GlyphRows;
    use crate::engine::gpu::segments::SegRows;

    /// Walk one BRep at row 5.
    fn walked(b: &BRep) -> (ArenaRows, SegRows, GlyphRows, Row) {
        let mut arena = ArenaRows::default();
        let mut seg = SegRows::default();
        let mut glyph = GlyphRows::default();
        let cx = WalkCx {
            vert_base: 100,
            cloud_px: 0.0,
            row: 5,
            attributes: false,
        };
        let row = {
            let mut ink = Ink {
                seg: &mut seg,
                glyph: &mut glyph,
            };
            walk_brep(&mut arena, &mut ink, b, &cx)
        };
        (arena, seg, glyph, row)
    }

    /// The teapot's pipes lie on its authored edge curves.
    #[test]
    fn teapot_ink_is_only_authored_patch_boundaries() {
        let scene = session_rust::Session::pb_load(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/assets/pb/view_mixed_teapot.pb"
        ))
        .unwrap();
        let brep = &scene.objects.breps[0];
        let (arena, seg, glyph, _) = walked(brep);
        assert!(seg.ribbons.is_empty() && glyph.spheres.is_empty());
        assert_eq!(arena.surface_boundaries.len(), seg.pipes.len());
        let curves: Vec<Vec<_>> = brep
            .m_edges
            .iter()
            .map(|edge| {
                if edge.curve_3d_index < 0 {
                    return Vec::new();
                }
                let curve = &brep.m_curves_3d[edge.curve_3d_index as usize];
                let (a, b) = curve.domain();
                (0..=1024)
                    .map(|i| curve.point_at(a + (b - a) * i as f64 / 1024.0).to_f32())
                    .collect()
            })
            .collect();
        for &(pipe, ends) in &arena.surface_boundaries {
            let edge = seg.pipe_ids[pipe as usize] as usize;
            for index in ends {
                let p = arena.verts[index as usize].position;
                let distance = curves[edge]
                    .windows(2)
                    .map(|pair| {
                        let d = std::array::from_fn::<_, 3, _>(|i| pair[1][i] - pair[0][i]);
                        let q = std::array::from_fn::<_, 3, _>(|i| p[i] - pair[0][i]);
                        let length: f32 = d.iter().map(|v| v * v).sum();
                        let t = ((0..3).map(|i| q[i] * d[i]).sum::<f32>() / length.max(1e-20))
                            .clamp(0.0, 1.0);
                        (0..3)
                            .map(|i| (q[i] - d[i] * t).powi(2))
                            .sum::<f32>()
                            .sqrt()
                    })
                    .fold(f32::INFINITY, f32::min);
                assert!(
                    distance < 0.01,
                    "edge {edge} endpoint {p:?} is {distance} from its authored curve"
                );
            }
            assert_eq!(
                seg.pipes[pipe as usize].p0,
                arena.verts[ends[0] as usize].position
            );
            assert_eq!(
                seg.pipes[pipe as usize].p1,
                arena.verts[ends[1] as usize].position
            );
            assert!((seg.pipe_ids[pipe as usize] as usize) < brep.m_edges.len());
        }
    }

    /// A cylinder uploads unwelded faces with unit normals.
    #[test]
    fn cylinder_walks_unwelded_with_normals() {
        let b = BRep::create_cylinder(150.0, 400.0);
        let fms = b.face_meshes_q(Some(QUALITY));
        let verts: usize = fms.iter().map(|m| m.vertex.len()).sum();
        let tris: usize = fms.iter().map(|m| m.to_render().indices.len()).sum();
        let segments: usize = edge_chains(&b, &fms)
            .iter()
            .flatten()
            .map(|c| c.keys.len() - 1)
            .sum();
        let (arena, seg, glyph, row) = walked(&b);
        assert_eq!(arena.verts.len(), verts);
        assert_eq!(arena.vids.len(), verts);
        assert_eq!(arena.idx.len(), tris);
        assert!(
            arena
                .idx
                .iter()
                .all(|&i| i >= 100 && i < 100 + verts as u32)
        );

        for v in &arena.verts {
            let n = v.normal;
            let l = (n[0] * n[0] + n[1] * n[1] + n[2] * n[2]).sqrt();
            assert!((l - 1.0).abs() < 1e-3, "normal {n:?}");
        }

        assert_eq!(seg.pipes.len(), segments);
        assert!(seg.ribbons.is_empty());
        assert!(glyph.spheres.is_empty());
        assert_ne!(row.flags & Instance::FLAG_SMOOTH, 0);
        assert_eq!(row.flags & Instance::FLAG_OPEN, 0);
        assert!(row.faces);
        assert!(row.bounds.diagonal() > 400.0);
    }

    /// A shell without a solid is flagged open.
    #[test]
    fn open_brep_is_flagged_open() {
        let mut b = BRep::create_box(400.0, 300.0, 250.0);
        b.m_solids.clear();
        let (_, _, _, row) = walked(&b);
        assert_ne!(row.flags & Instance::FLAG_OPEN, 0);
    }

    /// Flipped face uses upload the same vertices and triangles.
    #[test]
    fn reversed_solid_uses_repair_faces_and_boundaries_together() {
        let b = BRep::create_cylinder(150.0, 400.0);
        let mut reversed = b.clone();

        for face in reversed.m_shells[0].faces.iter_mut().take(2) {
            face.orientation = session_rust::brep::brep_reverse(face.orientation);
        }

        let (expected, _, _, _) = walked(&b);
        let (actual, _, _, _) = walked(&reversed);
        assert_eq!(actual.idx.len(), expected.idx.len());

        for (a, b) in actual.idx.chunks_exact(3).zip(expected.idx.chunks_exact(3)) {
            assert!(a == b || a == [b[1], b[2], b[0]] || a == [b[2], b[0], b[1]]);
        }

        assert_eq!(actual.verts.len(), expected.verts.len());

        for (a, b) in actual.verts.iter().zip(&expected.verts) {
            assert_eq!(a.position, b.position);
            assert_eq!(a.normal, b.normal);
        }
    }

    /// A surface's four border edges carry ids 0 to 3.
    #[test]
    fn surface_domain_edges_have_source_ids_and_open_visibility() {
        let b = BRep::create_box(40.0, 30.0, 25.0);
        let mut arena = ArenaRows::default();
        let mut seg = SegRows::default();
        let mut glyph = GlyphRows::default();
        let mut ink = Ink {
            seg: &mut seg,
            glyph: &mut glyph,
        };
        let cx = WalkCx {
            vert_base: 0,
            cloud_px: 0.0,
            row: 7,
            attributes: false,
        };
        let row = walk_surface(&mut arena, &mut ink, &b.m_surfaces[0], &cx);
        assert_ne!(row.flags & Instance::FLAG_OPEN, 0);
        assert_eq!(seg.pipe_ids.len(), seg.pipes.len());
        let mut ids = seg.pipe_ids.clone();
        ids.sort_unstable();
        ids.dedup();
        assert_eq!(ids, vec![0, 1, 2, 3]);
    }

    /// Sphere poles and box corners keep unit normals.
    #[test]
    fn poles_and_sharp_faces_keep_finite_unit_normals() {
        for b in [
            BRep::create_sphere(180.0),
            BRep::create_cone(150.0, 400.0),
            BRep::create_box(40.0, 30.0, 25.0),
        ] {
            let (arena, seg, _, _) = walked(&b);

            for vertex in &arena.verts {
                let [x, y, z] = vertex.normal;
                assert!(
                    (x * x + y * y + z * z - 1.0).abs() < 1e-5,
                    "{} normal {:?}",
                    b.name,
                    vertex.normal
                );
                assert!(vertex.position.iter().all(|value| value.is_finite()));
            }

            for pipe in &seg.pipes {
                assert_ne!(pipe.p0, pipe.p1);
            }
        }

        let (arena, _, _, _) = walked(&BRep::create_box(40.0, 30.0, 25.0));

        for vertex in &arena.verts {
            assert_eq!(
                vertex
                    .normal
                    .iter()
                    .filter(|component| component.abs() > 0.0)
                    .count(),
                1
            );
        }
    }

    /// Each pyramid side keeps its own normal at the apex.
    #[test]
    fn pyramid_planar_faces_keep_constant_normals_through_collapsed_apex() {
        /// Dot product in f32.
        fn dot(a: [f32; 3], b: [f32; 3]) -> f32 {
            a[0] * b[0] + a[1] * b[1] + a[2] * b[2]
        }
        let pyramid = BRep::create_pyramid(400.0, 350.0);
        let (arena, _, _, _) = walked(&pyramid);
        let mut apex_normals = Vec::new();

        for triangle in arena.idx.chunks_exact(3) {
            let a = arena.verts[triangle[0] as usize - 100];
            let b = arena.verts[triangle[1] as usize - 100];
            let c = arena.verts[triangle[2] as usize - 100];
            let mut ab = [0.0; 3];
            let mut ac = [0.0; 3];

            for axis in 0..3 {
                ab[axis] = b.position[axis] - a.position[axis];
                ac[axis] = c.position[axis] - a.position[axis];
            }

            let mut face = [
                ab[1] * ac[2] - ab[2] * ac[1],
                ab[2] * ac[0] - ab[0] * ac[2],
                ab[0] * ac[1] - ab[1] * ac[0],
            ];
            let length = dot(face, face).sqrt();

            for component in &mut face {
                *component /= length;
            }

            for vertex in [a, b, c] {
                let normal = vertex.normal;
                assert!(
                    dot(normal, face) > 1.0 - 1e-6,
                    "planar face normal {normal:?} differs from {face:?}"
                );

                if vertex.position[2] == 350.0 {
                    apex_normals.push(normal);
                }
            }
        }

        assert_eq!(
            apex_normals.len(),
            4,
            "each separate planar side owns its apex vertex"
        );

        for first in 0..apex_normals.len() {
            for second in first + 1..apex_normals.len() {
                assert!(
                    dot(apex_normals[first], apex_normals[second]) < 0.9,
                    "distinct BRep faces must not share a smoothed apex normal"
                );
            }
        }
    }
}

/// Remember each vertex's uv on its surface.
fn cache_samples(
    arena: &mut ArenaRows,
    mesh: &Mesh,
    render: &RenderMesh,
    surface: &NurbsSurface,
    index: usize,
) {
    let mut rows: Vec<_> = mesh.vertex.iter().collect();
    rows.sort_unstable_by_key(|&(key, _)| *key);

    if rows.len() != render.vertices.len() {
        return; // vertices were split, no mapping
    }

    for (offset, ((_, vertex), rendered)) in rows.into_iter().zip(&render.vertices).enumerate() {
        let (Some(&u), Some(&v)) = (vertex.attributes.get("u"), vertex.attributes.get("v")) else {
            continue;
        };
        let normal = surface.normal_at(u, v);
        // sign flips when the rendered normal was reversed
        let dot = (0..3)
            .map(|d| normal[d] * rendered.normal[d] as f64)
            .sum::<f64>();
        arena
            .surface_samples
            .push(crate::engine::gpu::arena::Sample {
                index: arena.verts.len() as u32 + offset as u32,
                surface: index as u32,
                uv: [u, v],
                sign: if dot < 0.0 { -1.0 } else { 1.0 },
            });
    }
}

use session_rust::Mesh;
use session_rust::brep::{BRep, BRepOrientation};

use super::encode::{Pen, pack_facing};
use crate::engine::gpu::CylinderSegment;
use crate::engine::gpu::segments::SegRows;
use session_rust::AABB;

// f64 has no total order because of NaN: partial_cmp returns None for it, total_cmp puts NaN in a fixed place.
/// Order two floats, NaN counts as equal.
fn sample_order(a: &f64, b: &f64) -> std::cmp::Ordering {
    a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal)
}

/// Order by parameter, then by vertex key.
fn parameter_order(a: &(f64, usize), b: &(f64, usize)) -> std::cmp::Ordering {
    sample_order(&a.0, &b.0).then(a.1.cmp(&b.1))
}

/// Order by parameter with a total float order, then by key.
fn total_parameter_order(a: &(f64, usize), b: &(f64, usize)) -> std::cmp::Ordering {
    a.0.total_cmp(&b.0).then(a.1.cmp(&b.1))
}

/// True when two samples share a parameter.
fn same_parameter(a: &mut (f64, usize), b: &mut (f64, usize)) -> bool {
    a.0 == b.0
}

/// Parse a sample index, None when not a number.
fn parse_sample_index(value: &str) -> Option<usize> {
    value.parse().ok()
}

// Each face that borders an edge uses it in its own direction, forward or reversed.
/// One use of an edge by a face.
pub struct EdgeUse {
    pub edge: usize,                  // edge index
    pub face: usize,                  // face index
    pub orientation: BRepOrientation, // which way the face runs it
}

/// The two UV ends of a straight pcurve. Pcurve = the edge drawn in one face's (u, v) coordinates.
fn pcurve_ends(b: &BRep, eu: &EdgeUse) -> Option<([f64; 2], [f64; 2])> {
    let ci = b.pcurve_index(eu.edge, eu.face, eu.orientation);

    if ci < 0 {
        return None;
    }

    let c = b.m_curves_2d.get(ci as usize)?;

    if c.degree() != 1 || c.is_rational() || c.cv_count() != 2 {
        return None; // not a straight line
    }

    let p0 = c.get_cv(0)?;
    let p1 = c.get_cv(c.cv_count().checked_sub(1)?)?;
    Some(([p0[0], p0[1]], [p1[0], p1[1]]))
}

/// Sorted distinct values of one vertex attribute; the kernel mesher tags each vertex with its "u" and "v".
fn sample_values(fm: &Mesh, name: &str) -> Vec<f64> {
    let mut vals = Vec::new();

    for vertex in fm.vertex.values() {
        if let Some(value) = vertex.attributes.get(name) {
            vals.push(*value);
        }
    }

    vals.sort_unstable_by(sample_order);
    vals.dedup();
    vals
}

/// The sample value nearest `target`, also across a wrap: on a closed direction u = end is u = start.
fn nearest_sample(vals: &[f64], target: f64, wrap: Option<(f64, f64)>) -> Option<f64> {
    let mut best: Option<(f64, f64)> = None;

    for &v in vals {
        let mut d = (v - target).abs();

        if let Some((start, end)) = wrap {
            d = d.min((v - (target - (end - start))).abs());
        }

        if match best {
            Some((bd, _)) => d < bd,
            None => true,
        } {
            best = Some((d, v));
        }
    }

    Some(best?.1)
}

// Iso line = a line of constant u or v; a seam or a grid border runs along one, and its vertices sit exactly on it.
/// Vertex keys along a grid edge, in parameter order.
pub fn iso_chain(b: &BRep, fm: &Mesh, eu: &EdgeUse) -> Option<Vec<usize>> {
    let e = b.m_edges.get(eu.edge)?;

    if e.degenerated {
        return None;
    }

    let (p0, p1) = pcurve_ends(b, eu)?;

    if !p0.into_iter().chain(p1).all(f64::is_finite) || (p0[0] != p1[0] && p0[1] != p1[1]) {
        return None;
    }

    // the parameter that does not change along the edge
    let fixed = if (p1[0] - p0[0]).abs() <= (p1[1] - p0[1]).abs() {
        0
    } else {
        1
    };
    let (fixed_name, free_name) = if fixed == 0 { ("u", "v") } else { ("v", "u") };
    let vals = sample_values(fm, fixed_name);

    if vals.is_empty() {
        return None;
    }

    let face = b.m_faces.get(eu.face)?;
    let srf = b.m_surfaces.get(face.surface_index as usize)?;
    let wrap = if srf.is_closed(fixed) {
        srf.domain(fixed) // closed: end equals start
    } else {
        None
    };
    let at = nearest_sample(&vals, p0[fixed], wrap)?;
    let wrapped_start = match wrap {
        Some((start, end)) => p0[fixed] - (end - start) == at,
        None => false,
    };

    if at != p0[fixed] && !wrapped_start {
        return None;
    }

    let mut on_line: Vec<(f64, usize)> = Vec::new(); // (free parameter, key)

    for (&key, vd) in fm.vertex.iter() {
        let (Some(&f), Some(&t)) = (vd.attributes.get(fixed_name), vd.attributes.get(free_name))
        else {
            continue;
        };
        let lo = p0[1 - fixed].min(p1[1 - fixed]);
        let hi = p0[1 - fixed].max(p1[1 - fixed]);

        if f == at && t >= lo && t <= hi {
            on_line.push((t, key));
        }
    }

    if on_line.len() < 2 {
        return None;
    }

    on_line.sort_unstable_by(parameter_order);
    let mut keys = Vec::with_capacity(on_line.len());

    for (_, key) in on_line {
        keys.push(key);
    }

    if e.start_vertex == e.end_vertex {
        keys.push(keys[0]); // closed edge
    }

    Some(keys)
}

/// The mesh vertices one BRep edge runs along.
pub struct EdgeChain {
    pub edge: usize,          // BRep edge index
    pub face: usize,          // face mesh the keys belong to
    pub keys: Vec<usize>,     // vertex keys along the edge
    pub other: Option<usize>, // the face on the other side
}

/// Vertex keys along edge `edge` from the mesher's labels: a vertex it put on edge 7, use 0, sample 3 carries `brep_edge/7/0/3`.
fn constrained_chain(fm: &Mesh, edge: usize) -> Option<Vec<usize>> {
    let prefix = format!("brep_edge/{edge}/");
    // BTreeMap keeps its keys sorted, so the samples come out in order
    let mut uses =
        std::collections::BTreeMap::<usize, std::collections::BTreeMap<usize, usize>>::new(); // use id -> sample -> key

    for (&key, vertex) in &fm.vertex {
        for name in vertex.attributes.keys() {
            let Some(suffix) = name.strip_prefix(&prefix) else {
                continue;
            };
            let Some((use_id, sample)) = suffix.split_once('/') else {
                continue;
            };
            let (Ok(use_id), Ok(sample)) = (use_id.parse::<usize>(), sample.parse::<usize>())
            else {
                continue;
            };
            let value = uses.entry(use_id).or_default().entry(sample).or_insert(key);
            *value = (*value).min(key); // smallest key wins
        }
    }

    for (&use_id, samples) in &uses {
        if samples.len() < 2 {
            continue;
        }

        let mut keys = Vec::with_capacity(samples.len());

        for (expected, (&sample, &key)) in samples.iter().enumerate() {
            if expected != sample {
                return None; // a sample is missing
            }

            keys.push(key);
        }

        // vertices inserted between samples carry a 0..1 position
        let interval_prefix = format!("brep_edge_interval/{edge}/{use_id}/");
        let mut ordered = Vec::with_capacity(keys.len());

        for (sample, key) in keys.into_iter().enumerate() {
            ordered.push((sample as f64, key));
        }

        for (&key, vertex) in &fm.vertex {
            for name in vertex.attributes.keys() {
                if let Some(sample) = name
                    .strip_prefix(&interval_prefix)
                    .and_then(parse_sample_index)
                    && let Some(&t) = vertex.attributes.get(name)
                    && sample + 1 < samples.len()
                    && t.is_finite()
                    && t > 0.0
                    && t < 1.0
                {
                    ordered.push((sample as f64 + t, key));
                }
            }
        }

        ordered.sort_unstable_by(total_parameter_order);
        ordered.dedup_by(same_parameter);
        let mut keys = Vec::with_capacity(ordered.len());

        for (_, key) in ordered {
            keys.push(key);
        }

        return Some(keys);
    }

    None
}

// Shared boundary: the chain is read from one face's mesh; the other face was meshed on the same edge samples, so one run of pipes serves both.
/// One chain per BRep edge, None when no mesh carries it.
pub fn edge_chains(b: &BRep, fms: &[Mesh]) -> Vec<Option<EdgeChain>> {
    let mut out = Vec::with_capacity(b.m_edges.len());

    for (ei, e) in b.m_edges.iter().enumerate() {
        if e.degenerated {
            out.push(None);
            continue;
        }

        let uses = b.edge_faces(ei);
        let mut found: Option<EdgeChain> = None;

        for (k, u) in uses.iter().enumerate() {
            let eu = EdgeUse {
                edge: ei,
                face: u.index as usize,
                orientation: u.orientation,
            };
            let keys = match constrained_chain(&fms[eu.face], ei) {
                Some(keys) => keys,
                None => match iso_chain(b, &fms[eu.face], &eu) {
                    Some(keys) => keys,
                    None => continue,
                },
            };
            // the neighbouring face, if a different one
            let mut other = None;

            for (j, candidate) in uses.iter().enumerate() {
                if j != k && candidate.index as usize != eu.face {
                    other = Some(candidate.index as usize);
                    break;
                }
            }

            found = Some(EdgeChain {
                edge: ei,
                face: eu.face,
                keys,
                other,
            });
            break;
        }

        out.push(found);
    }

    out
}

// Facet = one triangle of a face mesh. Two face meshes share positions, not vertex keys, so an edge is found by the bits of its two end positions.
/// A triangle edge keyed by its two end positions.
type FacetEdge = [[u64; 3]; 2];

/// The triangles meeting at one edge.
#[derive(Default)]
struct FacetPair {
    normals: [Option<[f64; 3]>; 2], // first two triangle normals
    count: usize,                   // how many triangles in total
}

/// Position as bits; -0.0 equals 0.0 but has other bits, so it is mapped to 0.
fn position_bits(position: [f64; 3]) -> [u64; 3] {
    let mut bits = [0; 3];

    for axis in 0..3 {
        bits[axis] = if position[axis] == 0.0 {
            0
        } else {
            position[axis].to_bits()
        };
    }

    bits
}

/// Edge key for two positions, in either order.
fn facet_edge(a: [f64; 3], b: [f64; 3]) -> FacetEdge {
    let a = position_bits(a);
    let b = position_bits(b);

    if a <= b { [a, b] } else { [b, a] }
}

/// Triangle normals at every edge of one face mesh.
fn face_facets(mesh: &Mesh) -> std::collections::HashMap<FacetEdge, FacetPair> {
    let mut result = std::collections::HashMap::<FacetEdge, FacetPair>::new();
    let mut faces: Vec<_> = mesh.face.keys().copied().collect();
    faces.sort_unstable();

    for key in faces {
        let vertices = &mesh.face[&key];

        if vertices.len() != 3 {
            continue;
        }

        let mut p = [[0.0; 3]; 3];

        for corner in 0..3 {
            let v = &mesh.vertex[&vertices[corner]];
            p[corner] = [v.x, v.y, v.z];
        }

        let mut a = [0.0; 3];
        let mut b = [0.0; 3];

        for axis in 0..3 {
            a[axis] = p[1][axis] - p[0][axis];
            b[axis] = p[2][axis] - p[0][axis];
        }

        let mut normal = [
            a[1] * b[2] - a[2] * b[1],
            a[2] * b[0] - a[0] * b[2],
            a[0] * b[1] - a[1] * b[0],
        ];
        let length = (normal[0] * normal[0] + normal[1] * normal[1] + normal[2] * normal[2]).sqrt();

        if !length.is_finite() || length <= 0.0 {
            continue;
        }

        for component in &mut normal {
            *component /= length;
        }

        for edge in 0..3 {
            let pair = result
                .entry(facet_edge(p[edge], p[(edge + 1) % 3]))
                .or_default();

            if pair.count < 2 {
                pair.normals[pair.count] = Some(normal);
            }

            pair.count += 1;
        }
    }

    result
}

/// What every edge pipe of one BRep needs.
pub struct EdgePen<'a> {
    pub fms: &'a [Mesh],                                          // face meshes
    pub signs: &'a [f64],                                         // +1 or -1 per face
    pub pen: Pen,                                                 // row, width, colour
    facets: Vec<std::collections::HashMap<FacetEdge, FacetPair>>, // per face: triangles at each edge
}

impl<'a> EdgePen<'a> {
    /// Index the triangles of every face once.
    pub fn new(fms: &'a [Mesh], signs: &'a [f64], pen: Pen) -> Self {
        let mut facets = Vec::with_capacity(fms.len());

        for mesh in fms {
            facets.push(face_facets(mesh));
        }

        Self {
            fms,
            signs,
            pen,
            facets,
        }
    }

    /// Facing word of one pipe: the normals of the triangle on each side, one per face; unknown when ambiguous.
    fn facing(&self, chain: &EdgeChain, a: [f64; 3], b: [f64; 3]) -> u32 {
        let key = facet_edge(a, b);
        let Some(owner) = self.facets[chain.face].get(&key) else {
            return pack_facing(None, None);
        };

        if owner.count == 0 || owner.count > 2 {
            return pack_facing(None, None);
        }

        let first = scaled_normal(owner.normals[0], self.signs[chain.face]);
        let second = if let Some(other) = chain.other {
            let Some(pair) = self.facets[other].get(&key) else {
                return pack_facing(None, None);
            };

            if pair.count != 1 || owner.count != 1 {
                return pack_facing(None, None);
            }

            scaled_normal(pair.normals[0], self.signs[other])
        } else if owner.count == 2 {
            scaled_normal(owner.normals[1], self.signs[chain.face])
        } else {
            first
        };
        pack_facing(first.as_ref(), second.as_ref())
    }
}

/// A normal turned outward by its face's sign.
fn scaled_normal(normal: Option<[f64; 3]>, sign: f64) -> Option<[f64; 3]> {
    let n = normal?;
    Some([n[0] * sign, n[1] * sign, n[2] * sign])
}

/// One pipe per chain segment; returns how many were pushed.
pub fn push_edge_pipes(
    seg: &mut SegRows,
    chain: &EdgeChain,
    ep: &EdgePen,
    bounds: &mut AABB,
) -> usize {
    let fm = &ep.fms[chain.face];

    let first = seg.pipes.len() as u32;
    seg.pipes.reserve(chain.keys.len().saturating_sub(1));
    let mut count = 0;

    for w in chain.keys.windows(2) {
        let (a, b) = (&fm.vertex[&w[0]], &fm.vertex[&w[1]]);
        let p0 = [a.x, a.y, a.z];
        let p1 = [b.x, b.y, b.z];
        let p0f = super::curves::render_position(p0);
        let p1f = super::curves::render_position(p1);

        // skip a segment that collapses in f32
        if p0f == p1f || !p0f.into_iter().chain(p1f).all(f32::is_finite) {
            continue;
        }

        bounds.union_with_point(p0f[0] as f64, p0f[1] as f64, p0f[2] as f64);
        bounds.union_with_point(p1f[0] as f64, p1f[1] as f64, p1f[2] as f64);
        seg.pipes.push(CylinderSegment {
            p0: p0f,
            radius: ep.pen.radius,
            p1: p1f,
            instance_id: ep.pen.row,
            color: ep.pen.color,
            facing: ep.facing(chain, p0, p1),
        });
        // try_from fails above u32::MAX; unwrap_or turns that into "no edge id"
        seg.pipe_ids
            .push(u32::try_from(chain.edge).unwrap_or(u32::MAX)); // edge id for picking
        count += 1;
    }

    seg.pipe_chains.push(first..seg.pipes.len() as u32); // one joined stroke
    count
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::app::walk::brep::QUALITY;

    /// Labelled samples and inserted nodes form one ordered chain.
    #[test]
    fn constrained_chain_keeps_inserted_crease_nodes_and_source_identity() {
        let mut mesh = Mesh::new();

        for (key, name, value) in [
            (10, "brep_edge/7/2/0", 1.0),
            (20, "brep_edge_interval/7/2/0", 0.25),
            (21, "brep_edge_interval/7/2/0", 0.25),
            (30, "brep_edge/7/2/1", 1.0),
        ] {
            mesh.add_vertex(session_rust::Point::new(key as f64, 0.0, 0.0), Some(key));
            mesh.vertex
                .get_mut(&key)
                .unwrap()
                .attributes
                .insert(name.to_string(), value);
        }

        assert_eq!(constrained_chain(&mesh, 7), Some(vec![10, 20, 30]));
        assert_eq!(constrained_chain(&mesh, 8), None);
        mesh.vertex
            .get_mut(&30)
            .unwrap()
            .attributes
            .remove("brep_edge/7/2/1");
        assert_eq!(constrained_chain(&mesh, 7), None);
    }

    /// First use of every edge.
    fn first_uses(b: &BRep) -> Vec<EdgeUse> {
        let mut out = Vec::new();

        for ei in 0..b.m_edges.len() {
            let uses = b.edge_faces(ei);
            let Some(u) = uses.first() else { continue };
            out.push(EdgeUse {
                edge: ei,
                face: u.index as usize,
                orientation: u.orientation,
            });
        }

        out
    }

    /// The chain starts exactly on BRep vertex `vi`.
    fn ends_on(b: &BRep, fm: &Mesh, keys: &[usize], vi: usize) -> bool {
        let p = fm.vertex[&keys[0]].position();
        let v = &b.m_vertices[vi].point;
        p[0] == v[0] && p[1] == v[1] && p[2] == v[2]
    }

    /// A cylinder: two closed circles and a two-key seam.
    #[test]
    fn cylinder_chains_follow_the_grid() {
        let b = BRep::create_cylinder(150.0, 400.0);
        let fms = b.face_meshes_q(Some(QUALITY));
        let uses = first_uses(&b);
        let chains: Vec<Vec<usize>> = uses
            .iter()
            .map(|u| iso_chain(&b, &fms[u.face], u).expect("grid use"))
            .collect();
        assert_eq!(chains.len(), 3);

        for k in 0..2 {
            assert_eq!(chains[k].first(), chains[k].last());
            assert!(chains[k].len() > 4);
            assert!(ends_on(
                &b,
                &fms[uses[k].face],
                &chains[k],
                b.m_edges[k].start_vertex as usize
            ));
        }

        assert_eq!(chains[0].len(), chains[1].len());
        assert_eq!(chains[2].len(), 2);
        assert!(ends_on(&b, &fms[uses[2].face], &chains[2], 0));
        let top = fms[uses[2].face].vertex[chains[2].last().unwrap()].position();
        assert_eq!(
            [top[0], top[1], top[2]],
            [
                b.m_vertices[1].point[0],
                b.m_vertices[1].point[1],
                b.m_vertices[1].point[2]
            ]
        );
    }

    /// A sphere's seam runs from pole to pole.
    #[test]
    fn sphere_seam_reaches_both_poles() {
        let b = BRep::create_sphere(180.0);
        let fms = b.face_meshes_q(Some(QUALITY));
        let uses = first_uses(&b);
        let seam = iso_chain(&b, &fms[0], &uses[0]).expect("seam");
        assert!(seam.len() > 10);
        assert_ne!(seam.first(), seam.last());
        assert!(ends_on(&b, &fms[0], &seam, 0));
        let north = fms[0].vertex[seam.last().unwrap()].position();
        assert_eq!(north[2], b.m_vertices[1].point[2]);
        assert!(iso_chain(&b, &fms[0], &uses[1]).is_none());
        assert!(iso_chain(&b, &fms[0], &uses[2]).is_none());
    }

    /// A torus has two closed seams; a cap has no iso chain.
    #[test]
    fn torus_seams_close_and_cdt_faces_decline() {
        let b = BRep::create_torus(220.0, 70.0);
        let fms = b.face_meshes_q(Some(QUALITY));

        for u in first_uses(&b) {
            let c = iso_chain(&b, &fms[u.face], &u).expect("seam");
            assert_eq!(c.first(), c.last());
            assert!(ends_on(&b, &fms[u.face], &c, 0));
        }

        let cyl = BRep::create_cylinder(150.0, 400.0);
        let cfm = cyl.face_meshes_q(Some(QUALITY));
        let cap = cyl.edge_faces(0)[1];
        let eu = EdgeUse {
            edge: 0,
            face: cap.index as usize,
            orientation: cap.orientation,
        };
        assert!(iso_chain(&cyl, &cfm[eu.face], &eu).is_none());
    }

    /// Every real edge of the mixed scene gets a chain.
    #[test]
    fn every_solid_edge_has_a_chain() {
        let solids = [
            BRep::create_box(400.0, 300.0, 250.0),
            BRep::create_cylinder(150.0, 400.0),
            BRep::create_cone(150.0, 400.0),
            BRep::create_sphere(180.0),
            BRep::create_torus(220.0, 70.0),
            BRep::create_block_with_hole(500.0, 300.0, 200.0, 80.0),
            BRep::create_pyramid(400.0, 350.0),
        ];

        for b in &solids {
            let fms = b.face_meshes_q(Some(QUALITY));
            let chains = edge_chains(b, &fms);
            assert_eq!(chains.len(), b.m_edges.len());

            for (ei, e) in b.m_edges.iter().enumerate() {
                let uses = b.edge_faces(ei);

                match &chains[ei] {
                    None => assert!(e.degenerated, "{} edge {ei}", b.name),
                    Some(c) => {
                        assert!(
                            uses.iter().any(|u| u.index as usize == c.face),
                            "{} edge {ei}",
                            b.name
                        );
                        let other = uses
                            .iter()
                            .find(|u| u.index as usize != c.face)
                            .map(|u| u.index as usize);
                        assert_eq!(c.other, other, "{} edge {ei}", b.name);
                    }
                }
            }
        }
    }

    /// The teapot's front meridian stays visible.
    #[test]
    fn teapot_front_meridian_is_not_self_occluded() {
        use session_rust::{Line, Point, Session};
        let scene = Session::pb_load(concat!(
            env!("CARGO_MANIFEST_DIR"),
            "/assets/pb/view_mixed_teapot.pb"
        ))
        .unwrap();
        let brep = &scene.objects.breps[0];
        let meshes = brep.face_meshes_q(Some(QUALITY));
        let chains = edge_chains(brep, &meshes);
        let chain = chains[14].as_ref().expect("authored front meridian");
        let owner = &meshes[chain.face];
        let mut triangles = Vec::new();

        for mesh in &meshes {
            assert!(!mesh.face.is_empty(), "every authored patch remains meshed");

            for keys in mesh.face.values() {
                triangles.push(
                    keys.iter()
                        .map(|key| mesh.vertex[key].position())
                        .collect::<Vec<_>>(),
                );
            }
        }

        let eye = Point::new(-222.278644, -422.587076, 439.224717);
        let mut checked = 0;

        for pair in chain.keys.windows(2) {
            let a = owner.vertex[&pair[0]].position();
            let b = owner.vertex[&pair[1]].position();
            let at = Point::new(
                (a[0] + b[0]) * 0.5,
                (a[1] + b[1]) * 0.5,
                (a[2] + b[2]) * 0.5,
            );
            assert!(at[0].abs() < 1e-9 && at[1] < -140.0 && at[2] >= 90.0 && at[2] <= 240.0);
            let ray = Line::new(eye[0], eye[1], eye[2], at[0], at[1], at[2]);
            let distance = eye.distance(&at, None);

            for triangle in &triangles {
                if let Some(hit) = session_rust::intersection::ray_triangle(
                    &ray,
                    &triangle[0],
                    &triangle[1],
                    &triangle[2],
                    1e-12,
                ) {
                    assert!(
                        eye.distance(&hit, None) >= distance - 1e-6,
                        "front meridian at {:?} buried by {:?}",
                        at,
                        triangle
                    );
                }
            }

            checked += 1;
        }

        assert!(checked >= 8);
    }

    /// Cylinder pipes carry both neighbouring face normals.
    #[test]
    fn pipes_face_both_adjacent_faces() {
        use crate::app::walk::encode::{FACING_UNKNOWN, Pen, encode_width, pack_rgba};
        use crate::engine::gpu::segments::SegRows;
        use session_rust::AABB;
        let b = BRep::create_cylinder(150.0, 400.0);
        let fms = b.face_meshes_q(Some(QUALITY));
        let chains = edge_chains(&b, &fms);
        let signs = vec![1.0; fms.len()];
        let ep = EdgePen::new(
            &fms,
            &signs,
            Pen {
                row: 3,
                radius: encode_width(1.0),
                color: pack_rgba([0.0, 0.0, 0.0, 1.0]),
            },
        );
        let mut seg = SegRows::default();
        let mut bounds = AABB::empty();
        let circle = push_edge_pipes(&mut seg, chains[0].as_ref().unwrap(), &ep, &mut bounds);
        assert_eq!(circle, chains[0].as_ref().unwrap().keys.len() - 1);

        for p in &seg.pipes {
            assert_ne!(
                p.facing, FACING_UNKNOWN,
                "missing incident facet for {:?} → {:?}",
                p.p0, p.p1
            );
            assert_ne!(p.facing & 0xffff, p.facing >> 16);
            assert_eq!(p.instance_id, 3);
        }

        let before = seg.pipes.len();
        let seam = push_edge_pipes(&mut seg, chains[2].as_ref().unwrap(), &ep, &mut bounds);
        assert_eq!(seam, 1);
        let p = &seg.pipes[before];
        assert_ne!(p.facing & 0xffff, p.facing >> 16);
        assert!(seg.ribbons.is_empty());
        assert_eq!(seg.pipe_ids.len(), seg.pipes.len());
        assert!(seg.pipe_ids[..before].iter().all(|&id| id == 0));
        assert_eq!(seg.pipe_ids[before], 2);
    }

    /// The cone seam faces by its triangles, not the apex fan.
    #[test]
    fn cone_seam_facing_uses_both_incident_facets() {
        let cone = BRep::create_cone(150.0, 400.0);
        let meshes = cone.face_meshes_q(Some(QUALITY));
        let chains = edge_chains(&cone, &meshes);
        let signs = vec![1.0; meshes.len()];
        let pen = EdgePen::new(
            &meshes,
            &signs,
            Pen {
                row: 4,
                radius: 1.0,
                color: 0,
            },
        );
        let mut segments = SegRows::default();
        push_edge_pipes(
            &mut segments,
            chains[1].as_ref().unwrap(),
            &pen,
            &mut AABB::empty(),
        );
        assert_eq!(segments.pipes.len(), 1);
        assert_eq!(segments.pipe_ids, vec![1]);
        let facing = segments.pipes[0].facing;
        assert_ne!(facing & 0xffff, facing >> 16);

        for code in [facing & 0xffff, facing >> 16] {
            // Both cone facet normals occupy the positive-Z octahedron hemisphere.
            let x = (code as u8 as i8) as f64 / 127.0;
            let y = ((code >> 8) as u8 as i8) as f64 / 127.0;
            let z = 1.0 - x.abs() - y.abs();
            let length = (x * x + y * y + z * z).sqrt();
            assert!(
                (z / length - 150.0f64 / (150.0f64.powi(2) + 400.0f64.powi(2)).sqrt()).abs() < 0.02,
                "physical cone facet normal must retain its slope; apex shading average gives z=0.822"
            );
        }
    }

