    };
}

// Two definitions of `Lap`, one per target: `#[cfg]` keeps exactly one, so callers never test the target.
/// A lap timer printing when profiling is on.
#[cfg(not(target_arch = "wasm32"))]
pub struct Lap {
    on: bool,               // profiling enabled
    at: std::time::Instant, // last mark
    prefix: &'static str,   // caller name in each line
}

/// No timer in the browser.
#[cfg(target_arch = "wasm32")]
pub struct Lap;

#[cfg(not(target_arch = "wasm32"))]
impl Lap {
    /// Start the timer.
    pub fn start(prefix: &'static str) -> Self {
        Self {
            on: knobs::profile(),
            at: std::time::Instant::now(),
            prefix,
        }
    }

    /// Print the time since the last mark.
    pub fn mark(&mut self, name: &str) {
        if self.on {
            eprintln!("  {} {name:<20} {:?}", self.prefix, self.at.elapsed());
            self.at = std::time::Instant::now();
        }
    }
}

#[cfg(target_arch = "wasm32")]
impl Lap {
    /// No clock on wasm32.
    pub fn start(_prefix: &'static str) -> Self {
        Self
    }

    /// No clock on wasm32.
    pub fn mark(&mut self, _name: &str) {}
}

// The returned list borrows from `arena`, so both carry the same lifetime 'a.
/// The index list this mesh's triangles join.
fn index_run<'a>(arena: &'a mut ArenaRows, m: &Mesh, sheet: bool) -> &'a mut Vec<u32> {
    if !sheet {
        return &mut arena.idx;
    }

    if m.name == "text" {
        &mut arena.idx_text // lettering draws last
    } else {
        &mut arena.idx_print
    }
}

/// Context and options for one mesh.
pub struct MeshCx<'a> {
    pub cx: &'a WalkCx,     // where rows go
    pub opts: &'a MeshOpts, // how to walk
}

/// A mesh: triangles, then edges and dots.
pub fn walk_mesh(arena: &mut ArenaRows, ink: &mut Ink, m: &Mesh, mc: &MeshCx) -> Row {
    let (cx, o) = (mc.cx, mc.opts);
    let base = cx.vert_base + arena.verts.len() as u32; // first vertex index
    let mut lap = Lap::start("walk_mesh");
    let rm = m.to_render(); // triangles from the kernel
    lap.mark("to_render");

    let print = is_print_fill(m);
    let decorated = rm.indices.len() / 3 <= MESH_RAW_MIN && !print; // gets edges and dots
    let keys = if decorated { m.vertices() } else { Vec::new() }; // sorted vertex keys
    let slots = SlotMap::new(&keys);
    let mut vpos64 = Vec::with_capacity(keys.len()); // positions by slot
    let mut vpos = Vec::with_capacity(keys.len()); // same in f32

    for &key in &keys {
        let point = &m.vertex[&key];
        vpos64.push([point.x, point.y, point.z]);
        vpos.push([point.x as f32, point.y as f32, point.z as f32]);
    }

    let topo = if decorated {
        Some(mesh_topology(m, &keys, &vpos64, &slots))
    } else {
        None
    };
    let mut bounds = AABB::empty();
    arena.verts.reserve(rm.vertices.len());
    arena.vids.reserve(rm.vertices.len());

    // triangles into the arena
    for v in &rm.vertices {
        bounds.union_with_point(
            v.position[0] as f64,
            v.position[1] as f64,
            v.position[2] as f64,
        );
        arena.verts.push(*v);
        arena.vids.push(cx.row);
    }

    let idx = index_run(arena, m, o.sheet_lanes && print);
    idx.reserve(rm.indices.len());

    for &i in &rm.indices {
        idx.push(base + i);
    }

    // Source face = the kernel face a triangle came from; picking (lesson 12) maps a triangle back to it.
    if !(o.sheet_lanes && print) {
        // a smooth surface is one source face
        append_face_ids(arena, m, cx.row, o.smooth, rm.indices.len() / 3);
    }

    lap.mark("vert+idx push");
    let mut flags = if o.sheet_lanes && print {
        Instance::FLAG_PRINT
    } else {
        0
    };
    let smooth = o.smooth && !knobs::seams(); // knob shows seams

    if smooth {
        flags |= Instance::FLAG_SMOOTH;
    }

    if m.number_of_faces() == 1 {
        flags |= Instance::FLAG_SINGLE;
    }

    let row = Row {
        bounds,
        spacing: mesh_spacing(&bounds, m.number_of_vertices()),
        flags,
        faces: true,
    };

    // closed and wound one way, checked once a clipping plane cut: a section caps it
    // bool.then(f) is Some(f()) when true; flatten turns Option<Option<T>> into Option<T>
    let solid = (!print && super::plane::solids_verified())
        .then(|| super::plane::solid_orientation(m))
        .flatten();
    let row = Row {
        flags: row.flags | super::plane::solid_flags(solid),
        ..row
    };

    if !decorated || knobs::no_edges() {
        return row; // triangles only
    }

    let topo = topo.expect("decorated mesh has topology");
    lap.mark("topology");
    let mut icx = InkCx {
        row: cx.row,
        vpos: &vpos,
        slots: &slots,
        smooth,
        lap: &mut lap,
    };
    edges_and_dots(ink, m, &topo, &mut icx);

    // an open mesh keeps its back faces
    let open = o.allow_open && !topo.closed;
    Row {
        flags: if open {
            row.flags | Instance::FLAG_OPEN
        } else {
            row.flags
        },
        ..row
    }
}

/// One source face address per triangle.
fn append_face_ids(
    arena: &mut ArenaRows,
    mesh: &Mesh,
    parent: u32,
    surface: bool,
    triangles: usize,
) {
    // a `use` inside a function is visible only in that function
    use crate::engine::gpu::faces::FaceSource;

    // a surface is one face
    if surface {
        let address = arena.face_sources.len() as u32;
        arena.face_sources.push(FaceSource { parent, face: 0 });
        arena
            .face_ids
            .extend(std::iter::repeat_n(address, triangles));
        return;
    }

    let start = arena.face_ids.len();
    let mut keys: Vec<_> = mesh.face.keys().copied().collect();
    keys.sort_unstable();

    for face in keys {
        let address = arena.face_sources.len() as u32;
        arena.face_sources.push(FaceSource { parent, face });
        let valid =
            |triangle: &[usize; 3]| triangle.iter().all(|key| mesh.vertex.contains_key(key));
        // triangles of this face: cached, else a fan
        let count = if let Some(cached) = mesh
            .triangulation
            .get(&face)
            .filter(|tris| !tris.is_empty())
        {
            cached.iter().filter(|tri| valid(tri)).count()
        } else {
            let corners = &mesh.face[&face];
            (1..corners.len().saturating_sub(1))
                .filter(|&i| valid(&[corners[0], corners[i], corners[i + 1]]))
                .count()
        };
        arena.face_ids.extend(std::iter::repeat_n(address, count));
    }

    assert_eq!(
        arena.face_ids.len() - start,
        triangles,
        "source face IDs must match the kernel triangle stream"
    );
}

use super::encode::{BLACK, FACING_UNKNOWN, encode_width, oct16, pack_facing};
use super::mesh::{COPLANAR_DOT, CREASE_COS, Lap, WIREFRAME_BLACK_MIN};
use super::mesh_topology::{MeshTopo, SlotMap};
use crate::app::knobs;
use crate::engine::gpu::glyphs::GlyphRows;
use crate::engine::gpu::segments::SegRows;
use crate::engine::gpu::{CylinderSegment, GlyphPoint};
use session_rust::Mesh;
use session_rust::mesh::ColorMode;

/// Where a mesh's edges and vertex dots go.
pub struct Ink<'a> {
    pub seg: &'a mut SegRows,     // edge pipes
    pub glyph: &'a mut GlyphRows, // vertex spheres
}

/// What the ink pass needs from the face pass.
pub struct InkCx<'a> {
    pub row: u32,             // object row
    pub vpos: &'a [[f32; 3]], // vertex positions by slot
    pub slots: &'a SlotMap,   // vertex key to slot
    pub smooth: bool,         // only borders and creases are ink
    pub lap: &'a mut Lap,     // profiling timer
}

/// Pen width of edge `i`; one entry applies to all.
fn width_at(w: &[f64], i: usize) -> f64 {
    if w.len() == 1 {
        w[0]
    } else {
        w.get(i).copied().unwrap_or(1.0)
    }
}

/// Width 0 hides the edge.
fn hidden(w: &[f64], i: usize) -> bool {
    width_at(w, i) == 0.0
}

/// Normal of one of an edge's two faces.
fn normal_of(topo: &MeshTopo, faces: [u32; 2], side: usize) -> Option<[f64; 3]> {
    if faces[side] == u32::MAX {
        return None;
    }

    topo.normals[faces[side] as usize]
}

/// The two outward normals of edge `ei`.
fn edge_normals(topo: &MeshTopo, ei: usize) -> (Option<[f64; 3]>, Option<[f64; 3]>) {
    let f = topo.edge_faces[ei];
    let n0 = normal_of(topo, f, 0);
    let n1 = normal_of(topo, f, 1);

    if topo.opposed[ei] {
        return (n0, n1);
    }

    (n0, n1.map(reversed_normal)) // badly wound: flip the second
}

/// Dot product of two vectors.
fn dot3(a: &[f64; 3], b: &[f64; 3]) -> f64 {
    a[0] * b[0] + a[1] * b[1] + a[2] * b[2]
}

// Crease = an edge where a smooth surface turns more than 25°; it is drawn like a real edge.
/// True for a border or crease edge of a smooth mesh.
fn smooth_feature(topo: &MeshTopo, ei: usize, pair: (Option<[f64; 3]>, Option<[f64; 3]>)) -> bool {
    if topo.edge_faces[ei][1] == u32::MAX {
        return true; // border
    }

    match pair {
        (Some(n0), Some(n1)) => dot3(&n0, &n1) < CREASE_COS,
        _ => true,
    }
}

/// Append edge `ei`'s faces to `fkeys`, deduped.
fn push_faces(edge_faces: &[[u32; 2]], ei: usize, fkeys: &mut Vec<usize>) {
    for &f in edge_faces[ei].iter() {
        if f == u32::MAX {
            continue;
        }

        let fk = f as usize;

        if !fkeys.contains(&fk) {
            fkeys.push(fk);
        }
    }
}

/// Two normal codes packed into word `k`.
fn facing_word(codes: &[u32], k: usize) -> u32 {
    match (codes.get(2 * k).copied(), codes.get(2 * k + 1).copied()) {
        (Some(a), b) => {
            let v = a | b.unwrap_or(a) << 16;

            if v == FACING_UNKNOWN { v ^ 1 } else { v }
        }
        _ => FACING_UNKNOWN,
    }
}

/// One pipe per drawn edge.
fn push_pipes(ink: &mut Ink, m: &Mesh, topo: &MeshTopo, cx: &InkCx) {
    let w = m.widths();
    let black_wire = topo.edges.len() >= WIREFRAME_BLACK_MIN; // dense mesh: black edges
    ink.seg.pipes.reserve(topo.edges.len());

    for (i, (a, b, col)) in topo.edges.iter().enumerate() {
        let (na, nb) = edge_normals(topo, i);
        let facing = pack_facing(na.as_ref(), nb.as_ref());

        if hidden(w, i) {
            continue;
        }

        // skip a diagonal inside a flat region, e.g. the one that splits a flat quad into two triangles
        if let (Some(n0), Some(n1)) = (na, nb)
            && dot3(&n0, &n1) >= COPLANAR_DOT
            && !knobs::all_edges()
        {
            continue;
        }

        if cx.smooth && !smooth_feature(topo, i, (na, nb)) {
            continue;
        }

        ink.seg
            .pipe_ids
            .push(if cx.smooth { u32::MAX } else { i as u32 }); // edge id for picking
        ink.seg.pipes.push(CylinderSegment {
            p0: cx.vpos[cx.slots.slot(*a)],
            radius: encode_width(width_at(w, i)),
            p1: cx.vpos[cx.slots.slot(*b)],
            instance_id: cx.row,
            color: if black_wire { BLACK } else { *col },
            facing,
        });
    }
}

/// Which edges touch each vertex.
struct Incidence {
    best: Vec<(f64, usize)>, // per vertex: widest edge (width, index)
    vstart: Vec<u32>,        // per vertex: start into `vinc`
    vinc: Vec<u32>,          // edge indices, grouped by vertex
}

/// Build the vertex to edge tables.
fn incidence(m: &Mesh, topo: &MeshTopo, cx: &InkCx) -> Incidence {
    let w = m.widths();
    let nv = cx.vpos.len();
    let mut best = vec![(f64::NEG_INFINITY, 0usize); nv];

    for (i, (a, b, _)) in topo.edges.iter().enumerate() {
        if hidden(w, i) {
            continue;
        }

        let wi = width_at(w, i);

        for vk in [*a, *b] {
            let e = &mut best[cx.slots.slot(vk)];

            if wi > e.0 {
                *e = (wi, i);
            }
        }
    }

    // count edges per vertex, then prefix sum: counts 2, 3, 1 become starts 0, 2, 5, 6,
    // so vertex v's edges sit in vinc[vstart[v]..vstart[v + 1]]
    let mut vstart = vec![0u32; nv + 1];

    for (a, b, _) in topo.edges.iter() {
        vstart[cx.slots.slot(*a) + 1] += 1;
        vstart[cx.slots.slot(*b) + 1] += 1;
    }

    for i in 0..nv {
        vstart[i + 1] += vstart[i];
    }

    // fill each vertex's edge list
    let mut vinc = vec![0u32; 2 * topo.edges.len()];
    let mut cur = vstart.clone();

    for (i, (a, b, _)) in topo.edges.iter().enumerate() {
        for vk in [*a, *b] {
            let s = cx.slots.slot(vk);
            vinc[cur[s] as usize] = i as u32;
            cur[s] += 1;
        }
    }

    Incidence { best, vstart, vinc }
}

// Two lifetimes: the struct borrows an InkCx for 'a, and that InkCx borrows mesh data for 'b.
/// What the marker loop reads.
struct MarkerCx<'a, 'b> {
    cx: &'a InkCx<'b>,  // ink context
    inc: &'a Incidence, // vertex to edge tables
}

/// One dot per vertex with a visible edge.
fn push_markers(ink: &mut Ink, m: &Mesh, topo: &MeshTopo, input: &MarkerCx) {
    let (cx, inc) = (input.cx, input.inc);
    let pc = m.get_pointcolors();
    let dots_colored = m.color_mode == ColorMode::POINTCOLORS && pc.len() == m.number_of_vertices(); // per-vertex colours
    let nv = cx.vpos.len();
    let mut fkeys: Vec<usize> = Vec::new(); // faces around one vertex
    let mut codes: Vec<u32> = Vec::new(); // packed normals of those faces
    ink.glyph.spheres.reserve(nv);

    for (i, &(vw, ei)) in inc.best.iter().enumerate().take(nv) {
        if vw == f64::NEG_INFINITY {
            continue; // no visible edge
        }

        fkeys.clear();
        push_faces(&topo.edge_faces, ei, &mut fkeys);

        for &j in &inc.vinc[inc.vstart[i] as usize..inc.vstart[i + 1] as usize] {
            push_faces(&topo.edge_faces, j as usize, &mut fkeys);
        }

        codes.clear();

        for fk in &fkeys {
            // let chain: `if let ... && let ... && cond` binds and tests in one condition
            if let Some(n) = topo.normals[*fk]
                && let Some(code) = oct16(&n)
                && !codes.contains(&code)
            {
                codes.push(code);
            }
        }

        ink.glyph.spheres.push(GlyphPoint {
            center: cx.vpos[i],
            radius: encode_width(vw),
            color: if dots_colored {
                pc[i].to_f32()
            } else {
                [0.1, 0.1, 0.1, 1.0]
            },
            instance_id: cx.row,
            // more than six faces: always draw
            facing: if codes.len() > 6 {
                FACING_UNKNOWN
            } else {
                facing_word(&codes, 0)
            },
            facing_ext: if codes.len() > 6 {
                [FACING_UNKNOWN; 2]
            } else {
                [facing_word(&codes, 1), facing_word(&codes, 2)]
            },
        });
    }
}

/// Edges, then vertex dots.
pub fn edges_and_dots(ink: &mut Ink, m: &Mesh, topo: &MeshTopo, cx: &mut InkCx) {
    let inc = incidence(m, topo, cx);
    cx.lap.mark("incidence");
    push_pipes(ink, m, topo, cx);
    cx.lap.mark("pipe loop");

    if knobs::no_dots() {
        return;
    }

    push_markers(ink, m, topo, &MarkerCx { cx, inc: &inc });
    cx.lap.mark("markers");
}

/// The opposite direction.
fn reversed_normal(n: [f64; 3]) -> [f64; 3] {
    [-n[0], -n[1], -n[2]]
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::app::walk::WalkCx;
    use crate::app::walk::mesh::{MeshCx, MeshOpts, walk_mesh};
    use crate::engine::gpu::arena::ArenaRows;
    use session_rust::Point;

    /// How many pipes one mesh pushes when walked under `opts`.
    fn walk_pipes(mesh: &Mesh, opts: &MeshOpts) -> usize {
        let mut arena = ArenaRows::default();
        let mut segments = SegRows::default();
        let mut glyphs = GlyphRows::default();
        let mut ink = Ink {
            seg: &mut segments,
            glyph: &mut glyphs,
        };
        let cx = WalkCx {
            vert_base: 0,
            cloud_px: 0.0,
            row: 0,
            attributes: false,
        };
        walk_mesh(&mut arena, &mut ink, mesh, &MeshCx { cx: &cx, opts });
        segments.pipes.len()
    }

    /// A slightly bulged 3x3 quad grid: 24 edges, 12 on the border.
    fn bulged_grid() -> Mesh {
        let mut points = Vec::with_capacity(16);

        for i in 0..4 {
            for j in 0..4 {
                let (x, y) = (i as f64 * 100.0, j as f64 * 100.0);
                points.push(Point::new(x, y, 2e-4 * (x * x + y * y)));
            }
        }

        let mut faces = Vec::with_capacity(9);

        for i in 0..3 {
            for j in 0..3 {
                let k = i * 4 + j;
                faces.push(vec![k, k + 4, k + 5, k + 1]);
            }
        }

        Mesh::from_vertices_and_faces(points, faces)
    }

    /// Two quads at a right angle: 7 edges, one a fold.
    fn folded_pair() -> Mesh {
        let points = vec![
            Point::new(0.0, 0.0, 0.0),
            Point::new(100.0, 0.0, 0.0),
            Point::new(100.0, 100.0, 0.0),
            Point::new(0.0, 100.0, 0.0),
            Point::new(100.0, 0.0, 100.0),
            Point::new(100.0, 100.0, 100.0),
        ];
        Mesh::from_vertices_and_faces(points, vec![vec![0, 1, 2, 3], vec![1, 4, 5, 2]])
    }

    /// A box has 12 edges and 8 dots.
    #[test]
    fn box_ink_rows() {
        let mesh = Mesh::create_box(10.0, 20.0, 30.0);
        let mut arena = ArenaRows::default();
        let mut segments = SegRows::default();
        let mut glyphs = GlyphRows::default();
        let mut ink = Ink {
            seg: &mut segments,
            glyph: &mut glyphs,
        };
        let cx = WalkCx {
            vert_base: 50,
            cloud_px: 0.0,
            row: 7,
            attributes: false,
        };
        walk_mesh(
            &mut arena,
            &mut ink,
            &mesh,
            &MeshCx {
                cx: &cx,
                opts: &MeshOpts::OBJECT,
            },
        );
        assert_eq!(segments.pipes.len(), 12);
        assert_eq!(glyphs.spheres.len(), 8);

        for segment in &segments.pipes {
            assert_ne!(segment.facing, FACING_UNKNOWN);
            assert_eq!(segment.instance_id, 7);
        }
    }

    /// A smooth mesh draws only borders and creases.
    #[test]
    fn smooth_mesh_inks_borders_and_creases_only() {
        let grid = bulged_grid();
        assert_eq!(walk_pipes(&grid, &MeshOpts::OBJECT), 24);
        assert_eq!(walk_pipes(&grid, &MeshOpts::SURFACE), 12);
        assert_eq!(walk_pipes(&folded_pair(), &MeshOpts::SURFACE), 7);
    }
}

use super::encode::{BLACK, pack_rgba};
use session_rust::{Mesh, Tolerance};

// Slot = a vertex's place in the sorted key list; kernel keys may have gaps (0, 5, 900), slots never do.
/// Vertex key to its position in the sorted key list.
pub struct SlotMap {
    dense: Vec<u32>,                               // key indexes directly
    sparse: std::collections::HashMap<usize, u32>, // used for sparse keys
}

impl SlotMap {
    /// Build from the sorted vertex keys.
    pub fn new(keys: &[usize]) -> Self {
        let max_key = keys.last().copied().unwrap_or(0);

        // dense when keys are not too spread out
        if max_key < 4 * keys.len().max(1) {
            let mut dense = vec![u32::MAX; max_key + 1];

            for (s, &k) in keys.iter().enumerate() {
                dense[k] = s as u32;
            }

            return Self {
                dense,
                sparse: std::collections::HashMap::new(),
            };
        }

        let mut sparse = std::collections::HashMap::with_capacity(keys.len());

        for (s, &k) in keys.iter().enumerate() {
            sparse.insert(k, s as u32);
        }

        Self {
            dense: Vec::new(),
            sparse,
        }
    }

    /// The slot of key `k`.
    pub fn slot(&self, k: usize) -> usize {
        if self.dense.is_empty() {
            self.sparse[&k] as usize
        } else {
            self.dense[k] as usize
        }
    }
}

/// Edges, faces and normals of one mesh.
pub struct MeshTopo {
    pub edges: Vec<(usize, usize, u32)>, // (low key, high key, pen colour)
    pub edge_faces: Vec<[u32; 2]>,       // two faces per edge, u32::MAX = none
    pub opposed: Vec<bool>,              // per edge: faces wind opposite ways
    pub normals: Vec<Option<[f64; 3]>>,  // per face, None when degenerate
    pub closed: bool,                    // every edge has two faces
}

/// Unit normal of one face, None when degenerate.
fn face_normal(vs: &[usize], vpos: &[[f64; 3]], slots: &SlotMap) -> Option<[f64; 3]> {
    if vs.len() < 3 {
        return None;
    }

    // Newell's method: sum over every edge, so a five-corner face that is slightly bent still gets a sound normal
    let mut n = [0.0f64; 3];

    for i in 0..vs.len() {
        let a = vpos[slots.slot(vs[i])];
        let b = vpos[slots.slot(vs[(i + 1) % vs.len()])];
        n[0] += (a[1] - b[1]) * (a[2] + b[2]);
        n[1] += (a[2] - b[2]) * (a[0] + b[0]);
        n[2] += (a[0] - b[0]) * (a[1] + b[1]);
    }

    let len = (n[0] * n[0] + n[1] * n[1] + n[2] * n[2]).sqrt();

    if len > Tolerance::ZERO_TOLERANCE {
        Some([n[0] / len, n[1] / len, n[2] / len])
    } else {
        None
    }
}

/// Sort key of a face.
fn face_key(face: &(usize, &Vec<usize>)) -> usize {
    face.0
}

/// Collect unique edges, their faces and the face normals.
pub fn mesh_topology(m: &Mesh, keys: &[usize], vpos: &[[f64; 3]], slots: &SlotMap) -> MeshTopo {
    let mut faces: Vec<(usize, &Vec<usize>)> = Vec::with_capacity(m.face.len());

    for (k, v) in m.face.iter() {
        faces.push((*k, v));
    }

    faces.sort_unstable_by_key(face_key);
    let cols = m.get_linecolors();

    let normals: Vec<_> = faces
        .iter()
        .map(|(_, vs)| face_normal(vs, vpos, slots))
        .collect();
    let mut edges: Vec<(usize, usize, u32)> = Vec::new();
    let mut edge_faces: Vec<[u32; 2]> = Vec::new();
    let mut dir0: Vec<u8> = Vec::new(); // direction the first face walked each edge
    let mut opposed: Vec<bool> = Vec::new();
    // one linked list of edges per low vertex, kept in two flat Vecs instead of a HashMap
    let mut head: Vec<u32> = vec![u32::MAX; keys.len()]; // first edge at each low vertex
    let mut next: Vec<u32> = Vec::new(); // next edge at the same low vertex

    // Keep the kernel's outer-edge ordering for colors, widths and picking ids.
    for holes in [false, true] {
        for (fs, (key, vs)) in faces.iter().enumerate() {
            let rings: &[Vec<usize>] = if holes {
                m.face_holes.get(key).map_or(&[], Vec::as_slice)
            } else {
                std::slice::from_ref(*vs)
            };
            for ring in rings {
                // Hole rings may be stored in either direction; a face walks them opposite its border.
                let reverse = holes
                    && normals[fs]
                        .zip(face_normal(ring, vpos, slots))
                        .is_some_and(|(a, b)| {
                            a.iter().zip(b).map(|(x, y)| x * y).sum::<f64>() > 0.0
                        });
                let n = ring.len();

                for i in 0..n {
                    let (u, v) = (ring[i], ring[(i + 1) % n]);
                    let (lo, hi, dir) = if u < v { (u, v, 0) } else { (v, u, 1) }; // edge key
                    let dir = dir ^ u8::from(reverse);
                    let ls = slots.slot(lo);
                    let mut ei = head[ls];

                    // look for the edge among those at `lo`
                    while ei != u32::MAX && edges[ei as usize].1 != hi {
                        ei = next[ei as usize];
                    }

                    // new edge
                    if ei == u32::MAX {
                        ei = edges.len() as u32;
                        let pen = match cols.get(edges.len()) {
                            Some(color) => pack_rgba(color.to_f32()),
                            None => BLACK,
                        };
                        edges.push((lo, hi, pen));
                        edge_faces.push([u32::MAX; 2]);
                        dir0.push(dir);
                        opposed.push(true);
                        next.push(head[ls]);
                        head[ls] = ei;
                    }

                    // record this face on the edge, first free slot
                    let ef = &mut edge_faces[ei as usize];

                    if ef[0] == u32::MAX {
                        ef[0] = fs as u32;
                        dir0[ei as usize] = dir;
                    } else if ef[1] == u32::MAX && ef[0] != fs as u32 {
                        ef[1] = fs as u32;
                        // two faces that agree on winding walk their shared edge in opposite directions
                        opposed[ei as usize] = dir != dir0[ei as usize];
                    }
                }
            }
        }
    }

    // closed when no edge is missing its second face
    let mut closed = !m.vertex.is_empty();

    for f in edge_faces.iter() {
        if f[1] == u32::MAX {
            closed = false;
        }
    }

    MeshTopo {
        edges,
        edge_faces,
        opposed,
        normals,
        closed,
    }
}

