use super::buffers::GpuCtx;
// #[path] names the file of a child module; the two helpers sit beside this file as text_plane.rs and text_plate.rs.
#[path = "text_plane.rs"]
mod plane;
#[path = "text_plate.rs"]
mod plate;
use crate::engine::pipelines::Layouts;
use crate::engine::pipelines::Target;
use crate::engine::text::{TextDocument, TextLabel, TextPlacement, TextRun};
use glyphon::{
    Cache, Color, ColorMode, Resolution, SwashCache, TextArea, TextAtlas, TextBounds, TextRenderer,
    Viewport,
};
use serde::Serialize;
use std::collections::{HashMap, HashSet};

/// Camera and canvas facts the text lane needs each frame.
// PartialEq lets prepare compare this frame with the last one and skip the work when they match.
#[derive(Clone, Debug, PartialEq)]
pub struct TextFrame {
    pub mvp: [f32; 16], // camera matrix, column by column
    // the scene anchor: a position minus it is taken in f64, then cast to f32
    pub origin: [f64; 3],
    pub framebuffer: [u32; 2],  // real pixels
    pub logical: [f64; 2],      // CSS px; framebuffer / logical is the device scale
    pub ortho_half_height: f32, // 0 = perspective
    // clipping planes as (normal, offset): all zero until lesson 18b, and a zero plane cuts nothing
    pub clip: [[f64; 4]; super::frame::MAX_PLANES],
}

/// Text counters shown in the diagnostics panel.
#[derive(Clone, Debug, Default, Serialize)]
pub struct TextStats {
    pub preparations: u64,         // frames that rebuilt the text
    pub skipped_preparations: u64, // frames that reused it
    pub shape_count: u64,
    pub shaping_ms: f64,
    pub requested_glyphs: usize,            // glyphs drawn this frame
    pub distinct_raster_keys: usize,        // different glyph rasters seen
    pub new_raster_keys: usize,             // new ones this frame
    pub raster_images: usize,               // glyph images kept on the CPU
    pub new_raster_images: usize,           // new ones this frame
    pub raster_image_capacity_bytes: usize, // bytes of those images
    pub atlas_resets: u64,
    pub preparation_ms: f64,           // time of the last rebuild
    pub active_instance_bytes: usize,  // 28 bytes per drawn glyph
    pub missing_glyphs: usize,         // glyphs no font had
    pub nameplate_capacity_bytes: u64, // bytes of the plate vertex buffer
    pub world_plane_buffer_bytes: u64, // bytes of the plane vertex buffer
    pub world_plane_texture_bytes: u64,
    pub world_plane_rasterizations: u64, // plane textures made so far
}

/// Draws every text label: screen overlays, anchored labels, plates and planes.
// Atlas = one texture holding every glyph image drawn so far; each glyph on screen is a small quad that samples it.
// Rasterize = turn a glyph outline into pixels; SwashCache does it on the CPU and keeps the images.
pub struct TextLane {
    pub document: TextDocument,
    pub stats: TextStats,
    cache: Cache, // glyphon's shaders and layouts, shared by its renderers
    atlas: TextAtlas,
    viewport: Viewport, // canvas size, as a uniform glyphon's shader reads
    raster: SwashCache,
    overlay: TextRenderer,                   // labels always on top
    anchored: TextRenderer,                  // labels behind geometry are hidden
    plates: plate::Plates,                   // label backgrounds
    planes: plane::Planes,                   // labels on a world plane
    target: Target,                          // scene color format and samples
    atlas_font_revision: u64,                // font set the atlas was built with
    prepared: Option<(u64, u64, TextFrame)>, // what the last rebuild was for
    raster_keys: HashSet<glyphon::CacheKey>, // glyph rasters seen since the last reset
    overlay_count: u32,                      // 1 when there are overlay labels to draw
    anchored_count: u32,                     // 1 when there are anchored labels to draw
}

impl TextLane {
    /// Bytes reserved by the plate and plane buffers.
    pub fn allocated_bytes(&self) -> u64 {
        self.plates.allocated_bytes() + self.planes.buffer_bytes()
    }

    /// Bytes of the plane textures.
    pub fn texture_bytes(&self) -> u64 {
        self.planes.texture_bytes()
    }

    /// Create the atlas, renderers, plates and planes.
    pub fn new(ctx: &GpuCtx, target: Target) -> Self {
        let cache = Cache::new(&ctx.device);
        let viewport = Viewport::new(&ctx.device, &cache);
        let mut atlas = make_atlas(ctx, &cache, target.format);
        // two renderers share one atlas and differ only in the depth test
        let overlay = renderer(ctx, &mut atlas, target, wgpu::CompareFunction::Always);
        let anchored = renderer(ctx, &mut atlas, target, wgpu::CompareFunction::GreaterEqual);
        Self {
            document: TextDocument::new(),
            stats: TextStats::default(),
            cache,
            atlas,
            viewport,
            raster: SwashCache::new(),
            overlay,
            anchored,
            plates: plate::Plates::new(ctx, target),
            planes: plane::Planes::new(ctx, target),
            target,
            atlas_font_revision: 1,
            prepared: None,
            raster_keys: HashSet::new(),
            overlay_count: 0,
            anchored_count: 0,
        }
    }

    /// Replace every label; an invalid set keeps the old ones.
    pub fn set_labels(&mut self, labels: Vec<TextLabel>) -> anyhow::Result<()> {
        self.document.set_labels(labels)
    }

    /// Rebuild the renderers for a new MSAA sample count.
    // A pipeline is fixed to one sample count, so switching 1x and 4x MSAA needs new ones.
    pub fn retarget(&mut self, ctx: &GpuCtx, target: Target) {
        self.target = target;
        self.plates.retarget(ctx, target);
        self.planes.retarget(ctx, target);
        self.overlay = renderer(ctx, &mut self.atlas, target, wgpu::CompareFunction::Always);
        self.anchored = renderer(
            ctx,
            &mut self.atlas,
            target,
            wgpu::CompareFunction::GreaterEqual,
        );
        self.prepared = None;
    }

    /// Place every label for this frame, unless nothing changed.
    pub fn prepare(&mut self, ctx: &GpuCtx, frame: &TextFrame) -> anyhow::Result<()> {
        // labels fixed on screen ignore the camera
        let fixed = self
            .document
            .runs
            .iter()
            .all(|run| matches!(run.label.placement, TextPlacement::Screen { .. }));
        // skip when labels, fonts and whatever they follow are unchanged
        let key = (
            self.document.revision,
            self.document.font_revision,
            if fixed { frame.canvas() } else { frame.clone() },
        );

        if self.prepared.as_ref() == Some(&key) {
            self.stats.skipped_preparations += 1;
            return Ok(());
        }

        self.overlay_count = 0;
        self.anchored_count = 0;
        self.plates.reset();
        let scale = frame.scale()?;
        let start = crate::engine::performance::now_ms();
        let fonts_changed = self.atlas_font_revision != self.document.font_revision;

        // rebuild the atlas when fonts changed or it grew large
        // zooming world text asks for a new raster at every size, so 4096 keys caps that growth
        if fonts_changed || self.raster_keys.len() > 4096 {
            self.rebuild_resources(ctx);
        }

        let raster_images_before = self.raster.image_cache.values().flatten().count();
        self.planes
            .prepare(ctx, &mut self.document, &mut self.raster, frame)?;
        self.atlas.trim();
        self.viewport.update(
            &ctx.queue,
            Resolution {
                width: frame.framebuffer[0],
                height: frame.framebuffer[1],
            },
        );
        let mut overlays = Vec::new();
        let mut anchors = Vec::new();
        let mut depths = HashMap::new();
        let mut plates = Vec::new();
        self.stats.new_raster_keys = 0;
        self.stats.requested_glyphs = 0;
        self.stats.missing_glyphs = 0;

        // screen position, plate and depth of every label
        for run in &self.document.runs {
            // let-else: bind the value or leave the loop body; a label off screen is skipped
            let Some(mut placed) = place(&run.label, frame, scale) else {
                continue;
            };

            if let Some(rectangle) = text_rectangle(run, &mut placed, frame, scale) {
                plates.push(rectangle);
            }

            // TextArea = one shaped buffer plus where and how big glyphon should draw it
            let area = TextArea {
                buffer: &run.buffer,
                left: placed.left,
                top: placed.top,
                scale: placed.scale,
                bounds: clip_bounds(&run.label, frame, scale),
                default_color: Color::rgba(
                    run.label.ink_color()[0],
                    run.label.ink_color()[1],
                    run.label.ink_color()[2],
                    run.label.ink_color()[3],
                ),
                custom_glyphs: &[],
            };

            // box around the shaped lines
            for line in run.buffer.layout_runs() {
                for glyph in line.glyphs {
                    self.stats.requested_glyphs += 1;
                    self.stats.missing_glyphs += usize::from(glyph.glyph_id == 0);
                    // the cache key is glyph, font, size and sub-pixel offset: one raster per distinct key
                    let physical = glyph.physical((placed.left, placed.top), placed.scale);
                    self.stats.new_raster_keys +=
                        usize::from(self.raster_keys.insert(physical.cache_key));
                }
            }

            // note whether each renderer has anything to draw
            if !run.label.text.is_empty() {
                match run.label.placement {
                    TextPlacement::Screen { .. } | TextPlacement::Nameplate { .. } => {
                        self.overlay_count = 1
                    }
                    _ => self.anchored_count = 1,
                }
            }

            if let Some(depth) = placed.depth {
                depths.insert(run.label.id as usize, depth);
                anchors.push(area);
            } else {
                overlays.push(area);
            }
        }

        // prepare rasterizes missing glyphs into the atlas and writes one 28-byte instance per glyph
        self.overlay.prepare(
            &ctx.device,
            &ctx.queue,
            &mut self.document.fonts,
            &mut self.atlas,
            &self.viewport,
            overlays,
            &mut self.raster,
        )?;
        // glyphon asks for each label's depth by id
        self.anchored.prepare_with_depth(
            &ctx.device,
            &ctx.queue,
            &mut self.document.fonts,
            &mut self.atlas,
            &self.viewport,
            anchors,
            &mut self.raster,
            |id| depth_for(&depths, id),
        )?;
        self.plates.prepare(ctx, &plates, frame.framebuffer);
        self.stats.raster_images = 0;
        self.stats.raster_image_capacity_bytes = 0;

        for image in self.raster.image_cache.values().flatten() {
            self.stats.raster_images += 1;
            self.stats.raster_image_capacity_bytes += image.data.capacity();
        }

        self.stats.new_raster_images = self
            .stats
            .raster_images
            .saturating_sub(raster_images_before);
        self.stats.preparations += 1;
        self.stats.shape_count = self.document.shape_count;
        self.stats.shaping_ms = self.document.shaping_ms;
        self.stats.distinct_raster_keys = self.raster_keys.len();
        self.stats.active_instance_bytes = self.stats.requested_glyphs * 28;
        self.stats.nameplate_capacity_bytes = self.plates.allocated_bytes();
        self.stats.world_plane_buffer_bytes = self.planes.buffer_bytes();
        self.stats.world_plane_texture_bytes = self.planes.texture_bytes();
        self.stats.world_plane_rasterizations = self.planes.rasterizations;
        self.stats.preparation_ms = crate::engine::performance::now_ms() - start;
        self.prepared = Some(key);
        Ok(())
    }

    /// Draw object ids of planes and plates.
    pub fn draw_ids(
        &self,
        pass: &mut wgpu::RenderPass<'_>,
        pick_transform: &wgpu::BindGroup,
    ) -> u32 {
        self.planes.draw_ids(pass, pick_transform) + self.plates.draw_ids(pass, pick_transform)
    }

    /// Draw planes, anchored plates and text, then overlay plates and text.
    // The order is the layering: each later draw lands on top of the earlier ones.
    pub fn draw(&self, pass: &mut wgpu::RenderPass<'_>) -> u32 {
        let mut draws = self.planes.draw(pass);
        draws += self.plates.draw(pass, false);

        if self.anchored_count != 0 {
            match self.anchored.render(&self.atlas, &self.viewport, pass) {
                Ok(()) => draws += 1,
                Err(error) => log::error!("anchored text render: {error}"),
            }
        }

        draws += self.plates.draw(pass, true);

        if self.overlay_count != 0 {
            match self.overlay.render(&self.atlas, &self.viewport, pass) {
                Ok(()) => draws += 1,
                Err(error) => log::error!("overlay text render: {error}"),
            }
        }

        draws
    }

    /// Forget every label.
    pub fn reset(&mut self) {
        self.document.clear();
        self.prepared = None;
        self.overlay_count = 0;
        self.anchored_count = 0;
        self.plates.reset();
        self.planes.reset();
    }

    /// Forget every label and free the buffers and atlas.
    pub fn release(&mut self, ctx: &GpuCtx) {
        self.reset();
        self.plates.release(ctx);
        self.planes.release(ctx);
        self.stats.nameplate_capacity_bytes = self.plates.allocated_bytes();
        self.stats.world_plane_buffer_bytes = self.planes.buffer_bytes();
        self.stats.world_plane_texture_bytes = 0;
        self.rebuild_resources(ctx);
    }

    /// Rebuild the atlas, renderers and glyph cache from scratch.
    fn rebuild_resources(&mut self, ctx: &GpuCtx) {
        // a renderer holds bind groups of the old atlas, so both are made again together
        self.atlas = make_atlas(ctx, &self.cache, self.target.format);
        self.overlay = renderer(
            ctx,
            &mut self.atlas,
            self.target,
            wgpu::CompareFunction::Always,
        );
        self.anchored = renderer(
            ctx,
            &mut self.atlas,
            self.target,
            wgpu::CompareFunction::GreaterEqual,
        );
        self.raster = SwashCache::new();
        self.raster_keys.clear();
        self.stats.raster_images = 0;
        self.stats.new_raster_images = 0;
        self.stats.raster_image_capacity_bytes = 0;
        self.stats.atlas_resets += 1;
        self.atlas_font_revision = self.document.font_revision;
        self.prepared = None;
    }
}

impl TextFrame {
    /// This frame without its camera: all a label fixed on screen depends on.
    fn canvas(&self) -> TextFrame {
        // `..self.clone()` fills every field not named here from the clone
        TextFrame {
            mvp: [0.0; 16],
            origin: [0.0; 3],
            ortho_half_height: 0.0,
            clip: [[0.0; 4]; super::frame::MAX_PLANES],
            ..self.clone()
        }
    }

    /// True when a clipping plane cuts world point `p` away.
    // A point is cut when it lies on the negative side of a plane; the plane (0, 0, 0, 0) gives 0 and never cuts.
    pub fn cut(&self, p: [f64; 3]) -> bool {
        self.clip
            .iter()
            .any(|k| k[0] * p[0] + k[1] * p[1] + k[2] * p[2] + k[3] < 0.0)
    }

    /// Framebuffer pixels per CSS pixel; fails on a stretched canvas.
    pub fn scale(&self) -> anyhow::Result<f32> {
        anyhow::ensure!(
            self.framebuffer[0] > 0 && self.framebuffer[1] > 0,
            "empty text framebuffer"
        );
        anyhow::ensure!(
            self.logical[0].is_finite()
                && self.logical[1].is_finite()
                && self.logical[0] > 0.0
                && self.logical[1] > 0.0,
            "empty text CSS box"
        );
        let x = self.framebuffer[0] as f64 / self.logical[0];
        let y = self.framebuffer[1] as f64 / self.logical[1];
        // rounding the pixel size may shift x and y by one pixel each, e.g. 1601 / 800 against 1200 / 600
        let tolerance = 1.0 / self.logical[0] + 1.0 / self.logical[1];
        anyhow::ensure!(
            (x - y).abs() <= tolerance,
            "text canvas is stretched non-uniformly"
        );
        Ok(y as f32)
    }
}

/// Where a label lands on screen, in framebuffer pixels.
struct PlacedText {
    left: f32,
    top: f32,
    scale: f32,         // font pixels per font unit
    depth: Option<f32>, // scene depth; None = always on top
}

/// Screen position of a label; None when off screen or on a world plane.
fn place(label: &TextLabel, frame: &TextFrame, scale: f32) -> Option<PlacedText> {
    let (world, offset, world_height) = match label.placement {
        TextPlacement::WorldPlane { .. } => return None,
        TextPlacement::Screen { left, top } => {
            return Some(PlacedText {
                left: left * scale,
                top: top * scale,
                scale,
                depth: None,
            });
        }
        TextPlacement::Anchor { world, offset } => (world, offset, None),
        TextPlacement::Nameplate { world, .. } => (world, [0.0; 2], None),
        TextPlacement::WorldBillboard {
            world,
            world_height,
        } => (world, [0.0; 2], Some(world_height)),
    };

    // cut away by a clipping plane: not drawn
    if frame.cut(world) {
        return None;
    }

    let p = [
        (world[0] - frame.origin[0]) as f32,
        (world[1] - frame.origin[1]) as f32,
        (world[2] - frame.origin[2]) as f32,
    ];
    let m = &frame.mvp;
    // behind the camera: not drawn
    // w is the fourth row of the matrix times the point; w <= 0 means the point is behind the eye
    let w = m[3] * p[0] + m[7] * p[1] + m[11] * p[2] + m[15];

    if !w.is_finite() || w <= 0.0 {
        return None;
    }

    // outside near and far: not drawn
    let z = (m[2] * p[0] + m[6] * p[1] + m[10] * p[2] + m[14]) / w;

    if !(0.0..=1.0).contains(&z) {
        return None;
    }

    // dividing by w gives normalized device coordinates: -1 to 1 across the canvas
    let x = (m[0] * p[0] + m[4] * p[1] + m[8] * p[2] + m[12]) / w;
    let y = (m[1] * p[0] + m[5] * p[1] + m[9] * p[2] + m[13]) / w;
    // world-sized text scales with distance
    let raster_scale = match world_height {
        Some(height) => {
            // the em height in screen pixels at this distance, divided by the font size
            let projection = (m[1] * m[1] + m[5] * m[5] + m[9] * m[9]).sqrt();
            height as f32 * projection * frame.framebuffer[1] as f32 / (2.0 * w * label.font_size)
        }
        None => scale,
    };

    if !raster_scale.is_finite() || raster_scale <= 0.0 {
        return None;
    }

    // NDC to pixels: x = -1 is the left edge, y = +1 the top edge
    Some(PlacedText {
        left: (x + 1.0) * 0.5 * frame.framebuffer[0] as f32 + offset[0] * scale,
        top: (1.0 - y) * 0.5 * frame.framebuffer[1] as f32 + offset[1] * scale,
        scale: raster_scale,
        depth: match label.placement {
            TextPlacement::Nameplate { .. } => None,
            _ => Some(z),
        },
    })
}

/// The background rectangle of a label, if it has one.
fn text_rectangle(
    run: &TextRun,
    placed: &mut PlacedText,
    frame: &TextFrame,
    scale: f32,
) -> Option<plate::Rectangle> {
    // a label that belongs to an object gets a rounded plate 2/9 em taller than its text, so it can be picked
    let (mut padding, rounded, centered) = match run.label.placement {
        TextPlacement::Nameplate {
            padding, rounded, ..
        } => (padding, rounded, true),
        _ if run.label.object.is_some() => ([0.0, run.label.font_size * 2.0 / 9.0], true, false),
        _ => return None,
    };

    if run.label.text.is_empty() {
        return None;
    }

    let mut width = 0.0f32;
    let mut top = f32::INFINITY;
    let mut bottom = f32::NEG_INFINITY;

    for line in run.buffer.layout_runs() {
        width = width.max(line.line_w);
        top = top.min(line.line_top);
        bottom = bottom.max(line.line_top + line.line_height);
    }

    if !top.is_finite() || !bottom.is_finite() {
        return None;
    }

    if rounded {
        // round caps need a full half-height at each end
        padding[0] = padding[0].max((bottom - top) * 0.5 + padding[1]);
    }

    let raster = placed.scale;

    // nameplates sit centered on their anchor
    if centered {
        placed.left -= width * raster * 0.5;
        placed.top -= (top + bottom) * raster * 0.5;
    }

    let bounds = clip_bounds(&run.label, frame, scale);
    let bounds = [
        bounds.left as f32,
        bounds.top as f32,
        bounds.right as f32,
        bounds.bottom as f32,
    ];
    Some(plate::Rectangle {
        bounds: [
            placed.left - padding[0] * raster,
            placed.top + (top - padding[1]) * raster,
            placed.left + (width + padding[0]) * raster,
            placed.top + (bottom + padding[1]) * raster,
        ],
        clip: bounds,
        rounded,
        depth: placed.depth,
        object: run.label.object,
    })
}

/// The label's clip box in framebuffer pixels, or the whole canvas.
fn clip_bounds(label: &TextLabel, frame: &TextFrame, scale: f32) -> TextBounds {
    // floor and ceil round outward, so a glyph on the box edge is never cut short
    match label.clip {
        Some(c) => TextBounds {
            left: (c[0] * scale).floor() as i32,
            top: (c[1] * scale).floor() as i32,
            right: (c[2] * scale).ceil() as i32,
            bottom: (c[3] * scale).ceil() as i32,
        },
        None => TextBounds {
            left: 0,
            top: 0,
            right: frame.framebuffer[0] as i32,
            bottom: frame.framebuffer[1] as i32,
        },
    }
}

/// A glyphon renderer with the given depth test.
// Depth in this viewer is reversed, 1 = near and 0 = far: GreaterEqual draws a glyph only where nothing nearer is.
fn renderer(
    ctx: &GpuCtx,
    atlas: &mut TextAtlas,
    target: Target,
    compare: wgpu::CompareFunction,
) -> TextRenderer {
    TextRenderer::new(
        atlas,
        &ctx.device,
        wgpu::MultisampleState {
            count: target.samples,
            ..Default::default()
        },
        Some(wgpu::DepthStencilState {
            format: wgpu::TextureFormat::Depth32Float,
            depth_write_enabled: Some(false), // text reads depth but never hides what is drawn after it
            depth_compare: Some(compare),
            stencil: Default::default(),
            bias: Default::default(),
        }),
    )
}

/// A glyph atlas for the canvas color format.
// An sRGB canvas turns linear colours into screen colours by itself; Accurate converts the label colour for it, Web passes it as is.
fn make_atlas(ctx: &GpuCtx, cache: &Cache, format: wgpu::TextureFormat) -> TextAtlas {
    let mode = if format.is_srgb() {
        ColorMode::Accurate
    } else {
        ColorMode::Web
    };
    TextAtlas::with_color_mode(&ctx.device, &ctx.queue, cache, format, mode)
}

/// Depth of the label with this id.
fn depth_for(depths: &HashMap<usize, f32>, id: usize) -> f32 {
    depths.get(&id).copied().unwrap_or(0.0)
}

