use crate::State;

// Gesture = one left-button tool, e.g. dragging an object; each lives in its own file beside this one.
/// One left-button tool: which presses it takes, how it follows the pointer, how it ends.
pub struct Gesture {
    pub name: &'static str, // what tests call it
    // `Option<fn ...>`: a tool without this step leaves it None and never takes such a press
    pub press: Option<fn(&mut State, (f64, f64), f64) -> bool>, // takes a press on its target, reach in CSS px
    pub start: Option<fn(&mut State, (f64, f64), (f64, f64)) -> bool>, // takes a plain press once it leaves the click slop
    pub drag: fn(&mut State, (f64, f64)) -> bool, // the pointer moved; true redraws
    pub release: fn(&mut State, (f64, f64), bool) -> bool, // let go, true when it stayed a click; true redraws
}

/// Every left-button tool, tried in this order.
// Empty at lesson 12; lesson 21 adds the control, gizmo and object drags, one line each.
pub const GESTURES: &[&Gesture] = &[
];

/// The first tool that takes a press at `at`.
pub fn press(state: &mut State, at: (f64, f64), reach: f64) -> Option<&'static Gesture> {
    GESTURES
        .iter()
        .copied()
        .find(|gesture| gesture.press.is_some_and(|take| take(state, at, reach)))
}

/// The first tool that takes a plain press at `down` dragged to `at`.
pub fn start(state: &mut State, down: (f64, f64), at: (f64, f64)) -> Option<&'static Gesture> {
    GESTURES
        .iter()
        .copied()
        .find(|gesture| gesture.start.is_some_and(|take| take(state, down, at)))
}

use super::gesture::{self, Gesture};
use super::touch::{Act, TAP_SLOP, Touches};
use crate::State;
use winit::event::{ElementState, MouseButton, MouseScrollDelta, TouchPhase, WindowEvent};
use winit::keyboard::Key;

/// A press moving less than this many pixels is a click.
const CLICK_SLOP: f64 = 4.0;

/// How far from a handle a mouse press still takes it, CSS pixels.
const MOUSE_REACH: f64 = 8.0;

/// How far from a handle a finger still takes it, CSS pixels.
const TOUCH_REACH: f64 = 18.0;

/// Mouse, keyboard and finger state between events.
pub struct Input {
    orbiting: bool,                          // right button held
    panning: bool,                           // middle button held
    ctrl: bool,                              // Ctrl held
    shift: bool,                             // Shift held
    // `&'static` = a reference that lives as long as the program: an entry of the GESTURES table
    gesture: Option<&'static Gesture>,       // the left-button tool in charge
    last_cursor: (f64, f64),                 // last pointer position in pixels
    left_down: Option<(f64, f64)>,           // where the left button went down
    plain: bool,             // that press had no Ctrl or Shift and may still start a tool
    dragged: bool,           // that press, or the editing finger, left its slop
    touch: Touches,          // camera finger gestures
    touch_edit: Option<u64>, // finger running a tool
    touch_down: (f64, f64),  // where that finger landed
    fingers: std::collections::HashSet<u64>, // fingers on the screen
    touch_cancelled: bool,   // waiting for all fingers to lift
    tool_held: bool,         // a running command follows this drag, e.g. a lasso
}

impl Default for Input {
    /// Same as `new`.
    fn default() -> Self {
        Self::new()
    }
}

impl Input {
    /// Nothing held, cursor at the origin.
    pub fn new() -> Self {
        Self {
            orbiting: false,
            panning: false,
            ctrl: false,
            shift: false,
            gesture: None,
            last_cursor: (0.0, 0.0),
            left_down: None,
            plain: false,
            dragged: false,
            touch: Touches::new(),
            touch_edit: None,
            touch_down: (0.0, 0.0),
            fingers: std::collections::HashSet::new(),
            touch_cancelled: false,
            tool_held: false,
        }
    }

    /// One key press; true when the frame must be redrawn.
    pub fn key(&mut self, state: &mut State, key: Key<&str>) -> bool {
        let Some(binding) = super::keys::binding(&key, self.ctrl, self.shift) else {
            return false;
        };
        (binding.run)(state); // the parentheses call the function stored in the field
        true
    }

    /// One mouse or touch event; true when the frame must be redrawn.
    pub fn mouse(&mut self, state: &mut State, event: &WindowEvent) -> bool {
        let viewport = state.viewport();

        match event {
            WindowEvent::MouseInput {
                // `state: btn` renames the event's field so it does not hide our `state`; `..` skips the rest
                state: btn,
                button: MouseButton::Right,
                ..
            } => {
                self.orbiting = *btn == ElementState::Pressed;
                state.interacting = self.orbiting || self.panning;
                false
            }
            WindowEvent::MouseInput {
                state: btn,
                button: MouseButton::Middle,
                ..
            } => {
                self.panning = *btn == ElementState::Pressed;
                state.interacting = self.orbiting || self.panning;
                false
            }
            WindowEvent::MouseInput {
                state: btn,
                button: MouseButton::Left,
                ..
            } => self.left(state, *btn),
            WindowEvent::CursorMoved { position, .. } => {
                let scale = crate::engine::gpu::view::surface_per_physical(); // window to canvas pixels
                let at = (position.x * scale, position.y * scale);

                // leaving the click slop turns the press into a drag
                if let Some(down) = self.left_down
                    && (at.0 - down.0).abs().max((at.1 - down.1).abs())
                        > CLICK_SLOP * device_pixel_ratio()
                {
                    self.dragged = true;
                }

                // a running command draws with the button held
                if self.tool_held {
                    self.last_cursor = at;
                }

                // a plain press dragged past the slop may start a tool, once
                if self.gesture.is_none()
                    && self.plain
                    && self.dragged
                    && let Some(down) = self.left_down
                {
                    self.plain = false;
                    self.gesture = gesture::start(state, down, at);
                }

                if let Some(active) = self.gesture {
                    self.last_cursor = at;
                    return (active.drag)(state, at);
                }

                let dragging = self.orbiting || self.panning;

                // camera moves in CSS pixels
                if dragging {
                    let dx = ((at.0 - self.last_cursor.0) / device_pixel_ratio()) as f32;
                    let dy = ((at.1 - self.last_cursor.1) / device_pixel_ratio()) as f32;

                    if self.panning || self.ctrl {
                        state.camera.pan(dx, dy);
                    } else {
                        state.camera.orbit(dx, dy);
                    }
                }

                self.last_cursor = at;
                let mut redraw = dragging;
                redraw
            }
            WindowEvent::MouseWheel { delta, .. } => {
                // a mouse wheel reports lines, a touchpad pixels: 100 px count as one line
                let amount = match delta {
                    MouseScrollDelta::LineDelta(_, y) => *y,
                    MouseScrollDelta::PixelDelta(p) => p.y as f32 / 100.0,
                };
                state.camera.zoom_at(amount, self.last_cursor, viewport);
                true
            }
            WindowEvent::ModifiersChanged(mods) => {
                self.ctrl = mods.state().control_key();
                self.shift = mods.state().shift_key();
                false
            }
            WindowEvent::Focused(false) => {
                self.cancel();
                state.interacting = false;
                true
            }
            WindowEvent::Touch(t) => {
                let scale = crate::engine::gpu::view::surface_per_physical();
                let t = &winit::event::Touch {
                    location: winit::dpi::PhysicalPosition::new(
                        t.location.x * scale,
                        t.location.y * scale,
                    ),
                    ..*t // every other field copied from the original touch
                };
                let at = (t.location.x, t.location.y);

                if t.phase == TouchPhase::Started {
                    self.fingers.insert(t.id);
                }

                // a second finger cancels a one-finger edit
                if self.touch_edit.is_some()
                    && t.phase == TouchPhase::Started
                    && self.fingers.len() > 1
                {
                    self.touch_edit = None;
                    self.gesture = None;
                    self.tool_held = false;
                    self.touch_cancelled = true;
                }

                // ignore everything until every finger lifts
                if self.touch_cancelled {
                    if matches!(t.phase, TouchPhase::Ended | TouchPhase::Cancelled) {
                        self.fingers.remove(&t.id);
                    }

                    if self.fingers.is_empty() {
                        self.touch_cancelled = false;
                        self.touch = Touches::new();
                    }

                    state.interacting = false;
                    return true;
                }

                // a first finger closes the number box and may grab a control or a handle
                if t.phase == TouchPhase::Started && self.fingers.len() == 1 {
                    self.last_cursor = at;
                    self.touch_down = at;
                    self.dragged = false;
                    // while drawing, a tap is only a point, like a mouse press
                    let mut drawing = false;

                    if !drawing {
                        self.gesture = gesture::press(state, at, TOUCH_REACH);
                    }

                    if self.gesture.is_some() || self.tool_held {
                        self.touch_edit = Some(t.id);
                    }
                }

                // the editing finger
                if self.touch_edit == Some(t.id) {
                    self.last_cursor = at;
                    let moved = (at.0 - self.touch_down.0).hypot(at.1 - self.touch_down.1);
                    self.dragged |= moved / device_pixel_ratio() > TAP_SLOP; // once away, a drag even if it comes back

                    match (t.phase, self.gesture) {
                        (TouchPhase::Moved, None) if self.tool_held => {
                        }
                        (TouchPhase::Ended, None) if self.tool_held => {
                        }
                        (TouchPhase::Moved, Some(active)) => {
                            (active.drag)(state, at);
                        }
                        (TouchPhase::Ended, Some(active)) => {
                            // a finger that stayed put is a tap
                            let tap = !self.dragged;
                            (active.release)(state, at, tap);

                        }
                        _ => {}
                    }

                    if matches!(t.phase, TouchPhase::Ended | TouchPhase::Cancelled) {
                        self.fingers.remove(&t.id);
                        self.touch_edit = None;
                        self.gesture = None;
                        self.tool_held = false;
                        self.touch = Touches::new();
                    }

                    state.interacting = self.touch_edit.is_some();
                    return true;
                }

                if matches!(t.phase, TouchPhase::Ended | TouchPhase::Cancelled) {
                    self.fingers.remove(&t.id);
                }

                state.interacting = matches!(t.phase, TouchPhase::Started | TouchPhase::Moved);

                // otherwise the fingers move the camera
                match self
                    .touch
                    .event(&mut state.camera, t, viewport, device_pixel_ratio())
                {
                    Act::None => false,
                    Act::Moved => true,
                    Act::Tap(at) => {
                        // a command waiting for a point takes the tap, like a mouse click
                        let mut drawing = false;

                        if drawing {
                        }

                        state.request_selection(at.0 as u32, at.1 as u32, false, false);
                        false
                    }
                    // a command waiting for points takes both taps
                    Act::Fit(_) => {
                        state.fit_all();
                        true
                    }
                }
            }
            _ => false,
        }
    }

    /// True while a running command follows a left drag, e.g. a lasso.
    pub fn tool_held(&self) -> bool {
        self.tool_held
    }

    /// Forget every gesture in progress.
    pub fn cancel(&mut self) {
        self.orbiting = false;
        self.panning = false;
        self.ctrl = false;
        self.shift = false;
        self.gesture = None;
        self.left_down = None;
        self.plain = false;
        self.dragged = false;
        self.touch = Touches::new();
        self.touch_edit = None;
        self.fingers.clear();
        self.touch_cancelled = false;
        self.tool_held = false;
    }

    /// Left button: a tool from the registry, else a click.
    fn left(&mut self, state: &mut State, btn: ElementState) -> bool {
        match btn {
            ElementState::Pressed => {
                let mut closed = false;
                self.left_down = Some(self.last_cursor);
                self.dragged = false;
                // a running command that draws with the button, e.g. a lasso

                if self.tool_held {
                    self.plain = false;
                    return true;
                }

                // while drawing, a press is only a click
                let mut drawing = false;
                self.plain = !self.ctrl && !self.shift && !drawing;

                if self.plain {
                    self.gesture = gesture::press(state, self.last_cursor, MOUSE_REACH);
                }

                closed
            }
            ElementState::Released => {
                let down = self.left_down.take();
                self.plain = false;

                if self.tool_held {
                    self.tool_held = false;
                }

                // the tool in charge takes the release; a press that never left the slop is a click
                if let Some(active) = self.gesture.take() {
                    return (active.release)(state, self.last_cursor, !self.dragged);
                }

                let Some(down) = down else {
                    return false;
                };
                let moved = (self.last_cursor.0 - down.0)
                    .abs()
                    .max((self.last_cursor.1 - down.1).abs());

                if moved > CLICK_SLOP * device_pixel_ratio() {
                    return false; // a drag, not a click
                }

                let mut drawing = false;

                if drawing {
                }
                state.additive_selection = self.shift && !self.ctrl; // Shift adds to the selection
                state.request_selection(
                    self.last_cursor.0 as u32,
                    self.last_cursor.1 as u32,
                    self.ctrl,
                    self.ctrl && self.shift,
                );
                false
            }
        }
    }
}

// The browser may take a pointer away mid-drag, e.g. to scroll the page; winit never reports that.
/// A `pointercancel` listener on the canvas.
#[cfg(target_arch = "wasm32")]
pub struct PointerCancellation {
    canvas: web_sys::HtmlCanvasElement, // the canvas listened to
    // a `Closure` lets JavaScript call Rust; it must live as long as the listener, so the struct keeps it
    callback: wasm_bindgen::closure::Closure<dyn FnMut(web_sys::Event)>, // the JS callback
}

#[cfg(target_arch = "wasm32")]
impl PointerCancellation {
    /// Install the listener; it sends one message per event.
    pub fn new(
        canvas: web_sys::HtmlCanvasElement,
        proxy: winit::event_loop::EventLoopProxy<crate::Msg>, // sends messages to the app
    ) -> Result<Self, wasm_bindgen::JsValue> {
        use wasm_bindgen::JsCast;
        let callback =
            wasm_bindgen::closure::Closure::<dyn FnMut(web_sys::Event)>::new(move |_| {
                cancel_pointer(&proxy)
            });
        // `unchecked_ref` presents the closure as the JS function type the DOM expects
        canvas
            .add_event_listener_with_callback("pointercancel", callback.as_ref().unchecked_ref())?;
        Ok(Self { canvas, callback })
    }
}

#[cfg(target_arch = "wasm32")]
impl Drop for PointerCancellation {
    /// Remove the listener.
    fn drop(&mut self) {
        use wasm_bindgen::JsCast;
        let _ = self.canvas.remove_event_listener_with_callback(
            "pointercancel",
            self.callback.as_ref().unchecked_ref(),
        );
    }
}

/// Send the cancel message to the event loop.
#[cfg(target_arch = "wasm32")]
fn cancel_pointer(proxy: &winit::event_loop::EventLoopProxy<crate::Msg>) {
    let _ = proxy.send_event(crate::Msg::CancelPointer);
}

/// Physical pixels per CSS pixel.
fn device_pixel_ratio() -> f64 {
    crate::engine::gpu::view::device_pixel_ratio()
}

// Inspection = a JSON snapshot of the viewer written onto the canvas, so browser tests read counters without a debugger.
#[cfg(target_arch = "wasm32")]
use crate::State;

/// Write the viewer state onto the canvas for browser tests.
#[cfg(target_arch = "wasm32")]
pub fn publish(state: &State) {
    if super::route::query("inspect").as_deref() != Some("1") {
        return; // only with ?inspect=1
    }

    let Some(window) = web_sys::window() else {
        return;
    };
    let Some(document) = window.document() else {
        return;
    };
    let Some(canvas) = document.get_element_by_id("canvas") else {
        return;
    };
    let (buffers, textures) = state.gpu.allocated_bytes();
    let parent = state.scene.selected;
    let model = match parent {
        Some(row) => state.gpu.objects.anchored_model(row),
        None => None,
    };
    let identity = selected_identity(state);
    // `json!` builds a JSON value in JSON syntax; any Rust expression can fill a value slot
    let mut snapshot = serde_json::json!({
        "submitted_at_ms": crate::engine::performance::now_ms(),
        "frames": state.gpu.performance.frames,
        "draw_calls": state.gpu.performance.draws,
        "selected": parent,
        "hidden_count": state.scene.hidden.len(),
        "identity": identity,
        "selection": state.selection,
        "controls": state.inspected_controls(),
        "markers": state.gpu.controls.dot_count(),
        "control_segments": state.gpu.control_net.ribbon_count(),
        "pick_busy": state.gpu.pick.busy(),
        "objects": state.scene.object_count(),
        "cloud_points": state.gpu.cloud.resident(),
        "vertices": state.gpu.arena.vert_count(),
        "pipes": state.gpu.segments.pipe_count(),
        "ribbons": state.gpu.segments.ribbon_count(),
        "mvp": state.gpu.frame.mvp_f32,
        "model": model,
        "origin": state.gpu.objects.anchor(),
        "canvas": [state.gpu.config.width, state.gpu.config.height],
        "logical_canvas": state.gpu.logical_size,
        "samples": state.gpu.targets.samples,
        "outlines": state.gpu.view.show_outlines,
        "text_cpu_raster_image_capacity_bytes": state.gpu.text.stats.raster_image_capacity_bytes,
        "text_cpu_scope": "Swash image byte-vector capacity only; font/shaper/layout/hash metadata excluded",
        "gpu_buffer_capacity_bytes": buffers,
        "gpu_texture_estimate_bytes": textures,
        "egui_private_gpu_capacity": "renderer buffers and font atlas are managed by egui; excluded from totals",
        "glyphon_private_gpu_capacity": "not exposed by pinned dependency; separate from totals",
        "text": state.gpu.text.stats,
        "text_labels": text_labels(state),
        "wasm_capacity_bytes": crate::engine::performance::heap_mb() * 1_048_576.0,
    });
    snapshot["selected_rows"] = serde_json::json!(state.selected_rows());
    snapshot["selected_models"] = serde_json::json!(
        state
            .selected_rows()
            .iter()
            .map(|r| state.gpu.objects.anchored_model(*r))
            .collect::<Vec<_>>()
    );
    snapshot["ssao"] = serde_json::json!(state.gpu.view.ssao);
    snapshot["locked_count"] = serde_json::json!(state.scene.locked.len());
    snapshot["color_count"] = serde_json::json!(state.scene.colors.len());
    snapshot["edge_color_count"] = serde_json::json!(state.scene.edge_colors.len());
    snapshot["source_faces"] =
        serde_json::json!(parent.and_then(|row| match state.scene.geometry(row)? {
            session_rust::Geometry::BRep(brep) => Some(brep.face_count()),
            session_rust::Geometry::Element(element) => match element.geometry() {
                session_rust::element::ElementGeometry::BRep(brep) => Some(brep.face_count()),
                _ => None,
            },
            _ => None,
        }));
    snapshot["selected_kind"] =
        serde_json::json!(parent.and_then(|row| state.scene.geometry(row).map(kind)));
    snapshot["selected_bounds"] = serde_json::json!(parent.and_then(|row| {
        let b = state.gpu.objects.row_bounds(row)?;
        Some([
            [b.cx - b.hx, b.cy - b.hy, b.cz - b.hz],
            [b.cx + b.hx, b.cy + b.hy, b.cz + b.hz],
        ])
    }));
    snapshot["scene_revision"] = serde_json::json!(state.scene.row_revision);
    let docs = &state.scene.docs;
    let slots = &state.gpu.arena.source_faces.slots;
    snapshot["instancing"] = serde_json::json!({
        "definitions": docs.iter().map(|d| d.session.definition_lookup.len()).sum::<usize>(),
        "instances": docs.iter().map(|d| d.session.instance_lookup.len()).sum::<usize>(),
        "gpu_draws": slots.draws().len(),
        "gpu_instances": slots.instances(),
    });
    let _ = canvas.set_attribute("data-viewer-inspection", &snapshot.to_string()); // a test reads it with getAttribute
}

/// Document index and guid of the selected row.
#[cfg(target_arch = "wasm32")]
fn selected_identity(state: &State) -> Option<(usize, String)> {
    let row = state.scene.selected?;
    let (document, guid) = state.scene.identity_of(row)?;
    Some((document, guid.to_string()))
}

/// Every drawn text label, as JSON.
#[cfg(target_arch = "wasm32")]
fn text_labels(state: &State) -> Vec<serde_json::Value> {
    use crate::engine::text::TextPlacement;
    let mut labels = Vec::new();

    for run in &state.gpu.text.document.runs {
        let (kind, world, padding) = match run.label.placement {
            TextPlacement::Screen { .. } => ("screen", None, None),
            TextPlacement::Anchor { world, .. } => ("anchor", Some(world), None),
            TextPlacement::WorldBillboard { world, .. } => ("world_billboard", Some(world), None),
            TextPlacement::WorldPlane { world, .. } => ("world_plane", Some(world), None),
            TextPlacement::Nameplate { world, padding, .. } => {
                ("nameplate", Some(world), Some(padding))
            }
        };
        let mut width = 0.0f32;
        let mut height = 0.0f32;

        for line in run.buffer.layout_runs() {
            width = width.max(line.line_w);
            height = height.max(line.line_top + line.line_height);
        }

        labels.push(serde_json::json!({
            "id": run.label.id,
            "object": run.label.object.map(|object| object.row),
            "text": run.label.text,
            "font_size": run.label.font_size,
            "line_height": run.label.line_height,
            "color": run.label.ink_color(),
            "placement": kind,
            "world": world,
            "world_height": match run.label.placement {
                TextPlacement::WorldBillboard { world_height, .. } => Some(world_height),
                _ => None,
            },
            "padding": padding,
            "rounded": matches!(run.label.placement, TextPlacement::Nameplate { rounded: true, .. }),
            "line_box": [width, height],
            "plane": match run.label.placement {
                TextPlacement::WorldPlane { right, up, world_height, .. } => Some((right, up, world_height)),
                _ => None,
            },
        }));
    }

    labels
}

/// The geometry's variant name, e.g. `BRep`.
#[cfg(target_arch = "wasm32")]
fn kind(geometry: &session_rust::Geometry) -> &'static str {
    use session_rust::Geometry;

    match geometry {
        Geometry::OBB(_) => "OBB",
        Geometry::BRep(_) => "BRep",
        Geometry::Element(_) => "Element",
        Geometry::Line(_) => "Line",
        Geometry::Mesh(_) => "Mesh",
        Geometry::NurbsCurve(_) => "NurbsCurve",
        Geometry::NurbsSurface(_) => "NurbsSurface",
        Geometry::Plane(_) => "Plane",
        Geometry::Point(_) => "Point",
        Geometry::PointCloud(_) => "PointCloud",
        Geometry::Polyline(_) => "Polyline",
    }
}

use crate::State;
use crate::camera::View;
use winit::keyboard::{Key, NamedKey};

/// What a key press runs, and what must be held with it.
pub struct Binding {
    pub trigger: Trigger,    // the key itself
    pub ctrl: bool,          // Ctrl must be held
    pub shift: Option<bool>, // Some(true) = Shift held, Some(false) = not held, None = either
    pub run: fn(&mut State), // what it does
}

/// The key a binding answers to.
pub enum Trigger {
    Chars(&'static [&'static str]), // typed characters, upper and lower
    Named(NamedKey),                // a named key such as Enter
}

impl Binding {
    /// True when this press, with these modifiers, is the one.
    fn matches(&self, key: &Key<&str>, ctrl: bool, shift: bool) -> bool {
        if (self.ctrl && !ctrl) || self.shift.is_some_and(|want| want != shift) {
            return false;
        }

        match (&self.trigger, key) {
            (Trigger::Named(named), Key::Named(pressed)) => named == pressed,
            (Trigger::Chars(chars), Key::Character(typed)) => chars.iter().any(|c| c == typed),
            _ => false,
        }
    }
}

/// The binding for one press, if any key claims it.
pub fn binding(key: &Key<&str>, ctrl: bool, shift: bool) -> Option<&'static Binding> {
    KEYS.iter()
        .find(|binding| binding.matches(key, ctrl, shift))
}

// A `const fn` can run at compile time, so the KEYS table below exists before the program starts.
/// A press with no modifier requirement.
const fn plain(chars: &'static [&'static str], run: fn(&mut State)) -> Binding {
    Binding {
        trigger: Trigger::Chars(chars),
        ctrl: false,
        shift: None,
        run,
    }
}

/// A press of a named key, such as Enter.
const fn named(key: NamedKey, run: fn(&mut State)) -> Binding {
    Binding {
        trigger: Trigger::Named(key),
        ctrl: false,
        shift: None,
        run,
    }
}

/// Every keyboard shortcut, first match wins.
pub const KEYS: &[Binding] = &[
    // register:projection
    named(NamedKey::Space, |s| {
        s.refresh_bounds();
        s.camera.toggle_projection_framed(&s.gpu.bounds, s.aspect())
    }),
    // the first Esc cancels the command and keeps the selection, the next one clears it
    named(NamedKey::Escape, |s| s.escape()),
    // register:view-front
    plain(&["1"], |s| s.camera.set_view(View::Front)),
    // register:view-back
    plain(&["2"], |s| s.camera.set_view(View::Back)),
    // register:view-left
    plain(&["3"], |s| s.camera.set_view(View::Left)),
    // register:view-right
    plain(&["4"], |s| s.camera.set_view(View::Right)),
    // register:view-top
    plain(&["5"], |s| s.camera.set_view(View::Top)),
    // register:view-bottom
    plain(&["6"], |s| s.camera.set_view(View::Bottom)),
    // register:view-iso
    plain(&["7"], |s| s.camera.set_view(View::Iso)),
    // register:camera-reset
    plain(&["c", "C"], |s| s.camera.reset()),
    plain(&["f", "F"], |s| s.fit_selected_or_all()),
    // register:show-points
    plain(&["q", "Q"], |s| {
        s.gpu.view.show_points = !s.gpu.view.show_points
    }),
    // register:show-lines
    plain(&["w", "W"], |s| {
        s.gpu.view.show_lines = !s.gpu.view.show_lines
    }),
    // register:show-mesh-edges
    plain(&["e", "E"], |s| {
        s.gpu.view.show_mesh_edges = !s.gpu.view.show_mesh_edges
    }),
    // register:show-outlines
    plain(&["o", "O"], |s| {
        s.gpu.view.show_outlines = !s.gpu.view.show_outlines
    }),
    // register:ssao
    plain(&["g", "G"], |s| s.gpu.view.set_arctic(!s.gpu.view.ssao)),
    // register:lit
    plain(&["d", "D"], |s| s.gpu.view.lit = !s.gpu.view.lit),
    plain(&["h", "H"], |s| s.hide_selected()),
    // register:show-all
    plain(&["s", "S"], |s| s.show_all()),
    // register:names
    plain(&["t", "T"], |s| s.toggle_selected_names()),
    // register:backface
    plain(&["b", "B"], |s| s.gpu.view.backface = !s.gpu.view.backface),
    // register:xray
    plain(&["p", "P"], |s| s.toggle_xray()),
    // register:cloud-smaller
    plain(&["["], |s| s.set_cloud_size(s.gpu.view.cloud_size - 0.25)),
    // register:cloud-bigger
    plain(&["]"], |s| s.set_cloud_size(s.gpu.view.cloud_size + 0.25)),
];

// A scene route = the URL of a scene file plus the prefix its `file` entries are joined to.
/// The public bucket scenes come from: R2 is Cloudflare's file storage, served over plain HTTPS.
pub const DATA_BASE: &str = "https://pub-dfd304db921140a09a9ad44c30e0aceb.r2.dev/";

/// The scene a local `trunk serve` shows.
pub const LOCAL_SCENE: &str = "view_local.yaml";

/// Spacing for items without a placement; zero stacks them.
pub const AUTO_GRID: [f64; 2] = [0.0, 0.0];

/// True for a localhost URL.
pub fn is_local_url(url: &str) -> bool {
    url.starts_with("http://localhost:")
        || url.starts_with("http://127.0.0.1:")
        || url.starts_with("http://[::1]:")
}

/// Where a scene and its files are.
#[derive(Clone)]
pub struct SceneRoute {
    pub manifest: String, // the scene file URL
    pub base: String,     // prefix for its `file` entries
}

pub use crate::engine::gpu::view::query;

/// An integer knob from the query string.
pub fn knob_u32(name: &str) -> Option<u32> {
    query(name)?.parse().ok() // `?` returns None early; `.ok()` turns the parse Result into an Option
}

/// True when the page is served from localhost.
pub fn page_is_local() -> bool {
    let Some(window) = web_sys::window() else {
        return false;
    };
    let Ok(hostname) = window.location().hostname() else {
        return false;
    };
    matches!(
        hostname.as_str(),
        "localhost" | "127.0.0.1" | "[::1]" | "::1"
    )
}

/// The scene named by the last path segment, e.g. `/view_lines`.
pub fn path_scene() -> Option<String> {
    let path = web_sys::window()?.location().pathname().ok()?;
    let last = path.rsplit('/').next()?.to_string();
    let safe = !last.is_empty()
        && !last.ends_with(".html")
        && !last.contains(':')
        && !last.starts_with('.');
    safe.then_some(last)
}

/// The `?scene=` value, refused when it escapes the tree.
pub fn query_scene() -> Option<String> {
    let decoded = query("scene")?;

    // `?scene=../x` would reach outside the scene tree
    for segment in decoded.split('/') {
        if segment == ".." {
            return None;
        }
    }

    let safe = !decoded.is_empty()
        && !decoded.starts_with('/')
        && !decoded.contains("//")
        && !decoded.contains(':');
    safe.then_some(decoded)
}

/// The data URL prefix: `?data=`, `off` for this origin, else the bucket.
pub fn data_base() -> String {
    let base = match query("data") {
        None => DATA_BASE.to_string(),
        Some(v) if v == "off" || v.is_empty() => return String::new(),
        Some(v) if v.starts_with("https://") || is_local_url(&v) => v,
        Some(other) => {
            log::warn!("data: ignoring `?data={other}`; using {DATA_BASE}");
            DATA_BASE.to_string()
        }
    };

    if base.ends_with('/') {
        base
    } else {
        base + "/"
    }
}

/// `base` + `file`, unless `file` is already a full URL.
pub fn join(base: &str, file: &str) -> String {
    if file.starts_with("https://") || file.starts_with("http://") {
        return file.to_string();
    }

    format!("{}{}", base, file.trim_start_matches("./"))
}

/// The route of a scene name, `.yaml` and `scenes/` implied.
pub fn named_scene(path: &str) -> SceneRoute {
    let path = if path.contains('.') {
        path.to_string()
    } else {
        format!("{path}.yaml")
    };
    let path = if path.contains('/') {
        path
    } else {
        format!("scenes/{path}")
    };
    let base = data_base();
    SceneRoute {
        manifest: join(&base, &path),
        base,
    }
}

/// The scene this page asks for; None means the live source.
pub fn scene_route() -> Option<SceneRoute> {
    if let Some(path) = query_scene().or_else(path_scene) {
        return Some(named_scene(&path));
    }

    if page_is_local() {
        Some(SceneRoute {
            manifest: LOCAL_SCENE.to_string(),
            base: String::new(),
        })
    } else {
        None
    }
}

// A lost device = the browser took the GPU away, e.g. after a driver reset; the page reloads once, lighter.
/// Reload once at reduced quality after a lost GPU device.
#[cfg(target_arch = "wasm32")]
pub fn recover_from_device_loss(message: &str) -> bool {
    if !message.contains("device lost") || crate::engine::gpu::view::reduced() {
        return false;
    }

    let Some(window) = web_sys::window() else {
        return false;
    };
    let location = window.location();
    let Ok(search) = location.search() else {
        return false;
    };
    let mut query = query_without(&search, "recovered");

    if !query.is_empty() {
        query.push('&');
    }

    let reason: String = message.chars().take(200).collect();
    query.push_str("recovered=");
    query.push_str(&String::from(js_sys::encode_uri_component(&reason)));
    let Ok(hash) = location.hash() else {
        return false;
    };
    let Ok(path) = location.pathname() else {
        return false;
    };
    log::warn!("{message}; reloading at device scale 1 without antialiasing");
    location.replace(&format!("{path}?{query}{hash}")).is_ok()
}

/// The query string without `?` and without `name=`.
#[cfg(target_arch = "wasm32")]
fn query_without(search: &str, name: &str) -> String {
    let prefix = format!("{name}=");
    let kept: Vec<&str> = search
        .strip_prefix('?')
        .unwrap_or("")
        .split('&')
        .filter(|pair| !pair.is_empty() && !pair.starts_with(&prefix) && *pair != name)
        .collect();
    kept.join("&")
}

#[cfg(target_arch = "wasm32")]
static RECOVERED: std::sync::OnceLock<String> = std::sync::OnceLock::new();

/// After a recovery reload: draw reduced, clean the URL, return the notice.
#[cfg(target_arch = "wasm32")]
pub fn adopt_recovery() -> Option<&'static str> {
    let reason = query("recovered")?;
    crate::engine::gpu::view::reduce();

    if let Some(window) = web_sys::window() {
        let location = window.location();

        if let (Ok(path), Ok(search), Ok(hash), Ok(history)) = (
            location.pathname(),
            location.search(),
            location.hash(),
            window.history(),
        ) {
            let query = query_without(&search, "recovered");
            let url = if query.is_empty() {
                format!("{path}{hash}")
            } else {
                format!("{path}?{query}{hash}")
            };
            let _ = history.replace_state_with_url(&wasm_bindgen::JsValue::NULL, "", Some(&url));
        }
    }

    let reason = if reason.is_empty() {
        "WebGPU device lost".to_string()
    } else {
        reason
    };
    let notice =
        format!("{reason}; drawing at device scale 1 without antialiasing until the next reload");
    Some(RECOVERED.get_or_init(|| notice).as_str())
}

/// The recovery notice, if this page reloaded after a device loss.
#[cfg(target_arch = "wasm32")]
pub fn recovered_notice() -> Option<&'static str> {
    RECOVERED.get().map(String::as_str)
}

#[path = "scene_rows.rs"]
pub(crate) mod rows;

use crate::app::walk::bounds::{Baselines, file_extent, mark_sheet, planar_band};
use crate::app::walk::mesh::Lap;
use crate::app::walk::{Walk, WalkCx, is_drawable, walk_geometry};
use crate::engine::gpu::patch::{Counts, LaneId, Span};
use crate::engine::gpu::{Gpu, Instance, ObjectRow, Pick, Upload};
use rows::{Cap, DocState, FREE, Footprint, Ids, Note, SINK, Spans, Staged, TOMB, Tomb};
use session_rust::{Geometry, Session, TreeNode, Xform};
use std::cell::RefCell;
use std::collections::{HashMap, HashSet};
use std::rc::{Rc, Weak};

/// Why a streamed object refuses an edit.
pub const READ_ONLY: &str =
    "Streamed objects are display only: select, hide and query them, but they cannot be edited";

/// One loaded file and its placement.
pub struct FileDoc {
    pub name: String,         // display name
    pub place: Xform,         // world placement
    pub session: Rc<Session>, // the kernel document, shared when a file is loaded twice
    pub point_px: f32,        // point size override, 0 = the file's own
    pub display_only: bool,   // a streamed shell with no kernel objects
}

/// What a pick landed on.
#[derive(Clone, Debug)]
pub struct Picked {
    pub doc: String,                // document name
    pub guid: String,               // object guid
    pub row: u32,                   // object row
    pub point: Option<PickedPoint>, // the point, for a cloud
    pub entity: Option<u32>,        // the entity id, for a sheet
}

/// A picked cloud point.
#[derive(Clone, Debug)]
pub struct PickedPoint {
    pub local: u32,         // index in the cloud
    pub id: u32,            // the point's stable id
    pub position: [f64; 3], // world position
}

/// Names a row has before its geometry's own: a text's, a sheet entity's, an instance's, a released row's.
// `for<'a>`: each function takes any borrow of the scene and returns a name that lives as long as that borrow.
const NAMERS: &[for<'a> fn(&'a Scene, u32) -> Option<&'a str>] = &[
];

/// The open documents and their object rows; a row id stays with its object for the object's life.
pub struct Scene {
    pub docs: Vec<FileDoc>,                              // loaded files
    pub tables: Upload,                                  // rows walked but not yet uploaded
    pub hidden: HashSet<(usize, Rc<str>)>,               // (document, guid) hidden
    pub locked: HashSet<(usize, Rc<str>)>,               // (document, guid) not selectable
    pub colors: HashMap<(usize, Rc<str>), [u8; 3]>,      // face colour overrides
    pub edge_colors: HashMap<(usize, Rc<str>), [u8; 3]>, // edge colour overrides
    pub selected: Option<u32>,                           // selected object row
    pub attributes: bool,                                // element features drawn
    order: Vec<Rc<str>>,                                 // guid of each row, empty when free
    owners: Vec<usize>,   // document of each row, or TEXT, FREE, SINK
    feet: Vec<Footprint>, // lane rows of each row
    nodes: Vec<Weak<RefCell<TreeNode>>>, // tree node each row was placed from; a cache
    spans: Spans,         // footprints spanning several lanes
    caps: HashMap<u32, Cap>, // rows owning more lane rows than they fill
    graves: HashMap<(usize, Rc<str>), Footprint>, // an object's last allocation, kept for its return
    ids: Ids,                                     // row ids nothing holds
    sink: Option<u32>,                            // the hidden row dead lane rows point at
    empty: Rc<str>,                               // the guid of free and sink rows
    doc_state: Vec<DocState>,                     // per document: sheet band, node cache source
    pending: Vec<(usize, Note)>,                  // what edits did, not yet synced
    hints: Vec<(usize, Weak<RefCell<TreeNode>>)>, // tree nodes edit sites already hold
    staged: Staged,                               // GPU work of the last sync
    dead: Counts,                                 // lane rows holding nothing live
    dead_points: u32,                             // cloud points of dropped clouds
    compactions: u32,                             // editable lanes walked again
    loaded: bool,                                 // rows of a new document wait in the tables
    pub(crate) bounds_stale: bool,                // the scene box may be larger than what is left
    edge_sources: Vec<(u32, u32)>,                // (object row, edge index) of each pipe
    guid_to_row: HashMap<(usize, Rc<str>), u32>,  // (document, guid) to row
    object_rows: u32,                             // object rows already on the GPU
    uploaded: Counts,                             // editable lane rows already on the GPU
    pub(crate) undo_steps: Vec<Vec<(usize, String)>>, // each edit: (document, undo label) per document it changed
    pub(crate) redo_steps: Vec<Vec<(usize, String)>>, // undone edits, the newest last
    pub(crate) created_doc: Option<usize>,            // the `Created` document
    pub(crate) row_revision: u64,                     // bumped when rows come or go
    pub(crate) current_layer: Option<(usize, String)>, // (document, tree node) new objects go to
    pub(crate) layer_steps: u64,                      // layer steps made, for unique labels
    pub(crate) groups: HashSet<(usize, Rc<str>)>, // (document, tree node guid) of each group
    pub(crate) text_rows: Vec<u32>, // text rows an undo, redo or delete showed or hid, for the GPU
    #[cfg(test)]
    pub(crate) ledger: HashMap<u32, ObjectRow>, // object rows as the GPU would hold them
    #[cfg(test)]
    pub(crate) searches: usize,   // tree walks the syncs needed
}

impl Default for Scene {
    /// Same as `new`.
    fn default() -> Self {
        Self::new()
    }
}

impl Scene {
    /// True when the row is not locked.
    pub fn selectable(&self, row: u32) -> bool {
        self.identity_of(row)
            .is_some_and(|id| !self.locked.contains(&id))
    }

    /// Empty: no documents, no rows.
    pub fn new() -> Self {
        Self {
            docs: Vec::new(),
            tables: Upload::default(),
            hidden: HashSet::new(),
            locked: HashSet::new(),
            colors: HashMap::new(),
            edge_colors: HashMap::new(),
            selected: None,
            attributes: true,
            order: Vec::new(),
            owners: Vec::new(),
            feet: Vec::new(),
            nodes: Vec::new(),
            spans: Spans::default(),
            caps: HashMap::new(),
            graves: HashMap::new(),
            ids: Ids::default(),
            sink: None,
            empty: Rc::from(""),
            doc_state: Vec::new(),
            pending: Vec::new(),
            hints: Vec::new(),
            staged: Staged::default(),
            dead: Counts::default(),
            dead_points: 0,
            compactions: 0,
            loaded: false,
            bounds_stale: false,
            edge_sources: Vec::new(),
            guid_to_row: HashMap::new(),
            object_rows: 0,
            uploaded: Counts::default(),
            undo_steps: Vec::new(),
            redo_steps: Vec::new(),
            created_doc: None,
            row_revision: 0,
            current_layer: None,
            layer_steps: 0,
            groups: HashSet::new(),
            text_rows: Vec::new(),
            #[cfg(test)]
            ledger: HashMap::new(),
            #[cfg(test)]
            searches: 0,
        }
    }

    /// Drop every document and its GPU rows.
    pub fn clear(&mut self, gpu: &mut Gpu) {
        self.created_doc = None;
        self.undo_steps.clear();
        self.redo_steps.clear();
        self.current_layer = None;
        self.groups.clear();
        self.docs.clear();
        self.doc_state.clear();
        self.text_rows.clear();
        self.hidden.clear();
        self.locked.clear();
        self.colors.clear();
        self.edge_colors.clear();
        self.reset_rows();
        gpu.release();
    }

    /// Forget every row.
    fn reset_rows(&mut self) {
        self.row_revision = self.row_revision.wrapping_add(1);
        self.tables = Upload::default();
        self.order.clear();
        self.owners.clear();
        self.feet.clear();
        self.nodes.clear();
        self.spans.clear();
        self.caps.clear();
        self.graves.clear();
        self.ids.clear();
        self.sink = None;
        self.pending.clear();
        self.hints.clear();
        self.staged = Staged::default();
        self.dead = Counts::default();
        self.dead_points = 0;
        self.loaded = false;
        self.bounds_stale = false;
        self.edge_sources.clear();
        self.guid_to_row.clear();
        self.selected = None;
        self.object_rows = 0;
        self.uploaded = Counts::default();
        #[cfg(test)]
        self.ledger.clear();
    }

    /// Add a document and its viewer state.
    pub(crate) fn push_doc(&mut self, doc: FileDoc, state: DocState) {
        self.docs.push(doc);
        self.doc_state.push(state);
    }

    /// Write what the last sync staged, then append the walked tables and clear them.
    pub fn upload_to(&mut self, gpu: &mut Gpu) {
        // staged edits first (hide, kill, rewrite rows in place), then brand-new rows appended at the end
        let staged = std::mem::take(&mut self.staged);
        let sink = self.sink.unwrap_or(u32::MAX);

        if !staged.retire.is_empty() {
            gpu.objects.retire_many(&gpu.ctx, &staged.retire);

            for &row in &staged.retire {
                gpu.set_selected(row, false);
            }
        }

        for &row in &staged.bury {
            gpu.set_selected(row, false);

            if gpu.cloud.bury_instance(row) {
                gpu.splat.invalidate();
            }
        }

        gpu.objects.bury_many(&gpu.ctx, &staged.bury);

        for &row in &staged.clouds {
            self.dead_points += gpu.cloud.kill_instance(row);
            gpu.splat.invalidate();
        }

        for (lane, first, count) in runs(staged.kills) {
            gpu.kill_rows(lane, first, count, sink);

            if lane == LaneId::Pipes {
                self.forget_edges(first, count);
            }
        }

        for (lane, first, count, vertex) in staged.tails {
            gpu.degenerate_rows(lane, first, count, vertex);
        }

        for (at, up) in &staged.patches {
            gpu.write_rows(*at, up);
            self.write_edges(at.pipes, up);
        }

        if !self.tables_empty() {
            for (index, pipe) in self.tables.seg.pipes.iter().enumerate() {
                let edge = self
                    .tables
                    .seg
                    .pipe_ids
                    .get(index)
                    .copied()
                    .unwrap_or(u32::MAX);
                self.edge_sources.push((pipe.instance_id, edge));
            }

            // clouds coming back would not fit beside the dead points: pack the live ones first
            let incoming = self.tables.cloud.point_count();

            if incoming > 0 && self.dead_points > 0 && !gpu.cloud.fits(&gpu.ctx, incoming) {
            }

            gpu.set_scene(&self.tables);

            // a loaded document re-centres the origin at the camera, as it always did; an edit keeps it
            if std::mem::take(&mut self.loaded) {
                gpu.objects.forget_anchor();
            }

            self.object_rows += self.tables.obj.rows.len() as u32;
            self.uploaded = self.uploaded.plus(Counts::of(&self.tables));
            self.tables.drop_uploaded();
        }

        for (row, object) in &staged.rows {
            gpu.objects.set_row(&gpu.ctx, *row, object);
            gpu.grew_bounds(*row);
        }

        for (row, object) in &staged.unbury {
            gpu.objects.unbury(&gpu.ctx, *row, object);
            gpu.grew_bounds(*row);

            if gpu.cloud.unbury_instance(*row) {
                gpu.splat.invalidate();
            }
        }

        for (row, object) in &staged.geometry {
            gpu.objects.update_geometry(&gpu.ctx, *row, object);
            gpu.grew_bounds(*row);
        }

        for (row, place) in &staged.places {
            if gpu.objects.placement_matches(*row, place) {
                continue;
            }

            gpu.objects.set_placement(&gpu.ctx, *row, place);
            gpu.grew_bounds(*row);
            self.bounds_stale = true;
        }

        let mut dead = self.dead;
        gpu.set_dead(dead, self.dead_points);
        gpu.refresh_samples();
    }

    /// True when nothing waits to be appended.
    fn tables_empty(&self) -> bool {
        let t = &self.tables;
        t.obj.rows.is_empty()
            && Counts::of(t).is_empty()
            && t.cloud.pos.is_empty()
            && t.cloud.draws.is_empty()
            && t.seg.sheet_rows.is_empty()
            && t.seg.sheets.is_empty()
    }

    /// Pipes no longer carry a source edge.
    fn forget_edges(&mut self, first: u32, count: u32) {
        let end = (first + count) as usize;

        for edge in self.edge_sources.iter_mut().take(end).skip(first as usize) {
            *edge = (u32::MAX, u32::MAX);
        }
    }

    /// Pipes rewritten from `first` take the source edges of `up`.
    fn write_edges(&mut self, first: u32, up: &Upload) {
        for (index, pipe) in up.seg.pipes.iter().enumerate() {
            let edge = up.seg.pipe_ids.get(index).copied().unwrap_or(u32::MAX);

            if let Some(slot) = self.edge_sources.get_mut(first as usize + index) {
                *slot = (pipe.instance_id, edge);
            }
        }
    }

    /// An object row with the colors its identity was given.
    fn object_row(&self, owner: usize, guid: &Rc<str>, place: Xform, flags: u32) -> ObjectRow {
        let mut object = ObjectRow::new(place, flags);
        let key = (owner, Rc::clone(guid));

        if let Some(color) = self.colors.get(&key) {
            object.color = [
                color[0] as f32 / 255.,
                color[1] as f32 / 255.,
                color[2] as f32 / 255.,
                1.,
            ];
            object.flags |= Instance::FLAG_COLOR;
        }

        if let Some(color) = self.edge_colors.get(&key) {
            object.edge_color = u32::from_le_bytes([color[0], color[1], color[2], 255]);
            object.flags |= Instance::FLAG_EDGE_COLOR;
        }

        object
    }

    /// Add one object row for `guid` of document `owner`, after every other row.
    pub(super) fn push_row(&mut self, owner: usize, guid: &str, place: Xform, flags: u32) -> u32 {
        self.row_revision = self.row_revision.wrapping_add(1);
        self.loaded = true;
        let row = self.object_rows + self.tables.obj.rows.len() as u32;
        let guid: Rc<str> = Rc::from(guid);
        let object = self.object_row(owner, &guid, place, flags);
        self.tables.obj.rows.push(object);
        self.guid_to_row.insert((owner, Rc::clone(&guid)), row);
        self.order.push(guid);
        self.owners.push(owner);
        self.feet.push(Footprint::None);
        self.nodes.push(Weak::new());
        row
    }

    /// Add one document: one row per object, then the file sweeps.
    pub fn add_file(&mut self, doc: FileDoc) {
        self.row_revision = self.row_revision.wrapping_add(1);
        // destructuring moves each field of `doc` into its own variable; `_` drops the one not needed
        let FileDoc {
            name,
            session,
            place,
            point_px,
            display_only: _,
        } = doc;
        let index = self.docs.len();
        let from = Baselines::capture(&self.tables);
        let world = session.world_xforms();
        let mut lap = Lap::start("walk");
        let count = session.lookup.len() + session.instance_lookup.len();
        self.tables.obj.rows.reserve(count);
        self.order.reserve(count);
        self.guid_to_row.reserve(count);

        let baked = baked_attributes(&session);
        let order = session.order();
        let mut placed: HashMap<&str, u32> = HashMap::with_capacity(count); // guid to row, for the node cache

        for guid in &order {
            let Some(geom) = session.lookup.get(guid) else {
                continue;
            };

            if !is_drawable(geom) || baked.contains(guid.as_str()) {
                continue;
            }

            let flags = if self.hidden.contains(&(index, Rc::from(guid.as_str()))) {
                Instance::FLAG_HIDDEN
            } else {
                0
            };
            let object_place = placement(&world, &place, guid);
            let row = self.push_row(index, guid, object_place, flags);
            placed.insert(guid, row);
            let cx = WalkCx {
                vert_base: self.uploaded.verts,
                cloud_px: point_px,
                row,
                attributes: self.attributes,
            };
            // lane counts before and after the walk bracket the rows this object added
            let start = self.uploaded.plus(Counts::of(&self.tables));
            let r = walk_geometry(&mut Walk::of(&mut self.tables), &cx, geom); // lessons 06-09: geometry to GPU rows
            let end = self.uploaded.plus(Counts::of(&self.tables));
            self.feet[row as usize] = if matches!(geom, Geometry::PointCloud(_)) {
                Footprint::Cloud
            } else {
                self.spans.foot(Span {
                    start,
                    count: end.minus(start),
                })
            };
            let o = self.tables.obj.rows.last_mut().unwrap();
            o.flags |= r.flags;
            o.bounds = r.bounds;
            o.spacing = r.spacing;
            o.faces = r.faces;

            if r.faces {
                o.flags |= Instance::FLAG_HAS_FACES;
            }
        }

        lap.mark("objects");

        // each row remembers the tree node it was placed from
        for node in session.tree.nodes() {
            if let Some(&row) = placed.get(node.borrow().name.as_str()) {
                self.nodes[row as usize] = Rc::downgrade(&node);
            }
        }

        drop(placed);
        let extent = file_extent(&self.tables, &from);
        self.tables.bounds.union_with(&extent);

        // a flat file is a drawing sheet, unless it was drawn here
        let sheet = if self.created_doc != Some(index) {
            planar_band(&self.tables, &from, &place)
        } else {
            None
        };

        if sheet.is_some() {
            mark_sheet(&mut self.tables, &from);
        }

        lap.mark("sweeps");

        let nodes_from = tree_key(&session);
        self.push_doc(
            FileDoc {
                name,
                place,
                session,
                point_px,
                display_only: false,
            },
            DocState { sheet, nodes_from },
        );
    }

    /// What a GPU pick landed on.
    pub fn resolve(&self, pick: Pick, gpu: &Gpu) -> Option<Picked> {
        let (_, guid) = self.identity_of(pick.row)?;
        let mut point = None;

        if let Some((parent, local)) = gpu.cloud.row_of(pick.sub)
            && parent == pick.row
        {
            point = self.point_at(pick.row, local);
        }

        let mut entity = None;

        let doc = match self.document(pick.row) {
            Some(document) => document.name.clone(),
            None => String::new(),
        };
        Some(Picked {
            doc,
            guid: guid.to_string(),
            row: pick.row,
            point,
            entity,
        })
    }

    /// True for the row of a streamed sheet or cloud, which is never edited.
    pub fn display_only(&self, row: u32) -> bool {
        self.document(row).is_some_and(|file| file.display_only)
    }

    /// The document a row belongs to.
    pub fn document(&self, row: u32) -> Option<&FileDoc> {
        self.docs.get(*self.owners.get(row as usize)?)
    }

    /// The kernel geometry of a row.
    pub fn geometry(&self, row: u32) -> Option<&Geometry> {
        self.document(row)?
            .session
            .lookup
            .get(self.order.get(row as usize)?.as_ref())
    }

    /// The row's name, or its type when unnamed.
    pub fn object_name(&self, row: u32) -> &str {
        for namer in NAMERS {
            if let Some(name) = namer(self, row) {
                return name;
            }
        }

        let (name, kind) = match self.geometry(row) {
            Some(Geometry::OBB(value)) => (value.name.as_str(), "Box"),
            Some(Geometry::BRep(value)) => (value.name.as_str(), "BRep"),
            Some(Geometry::Element(value)) => (value.name.as_str(), "Element"),
            Some(Geometry::Line(value)) => (value.name.as_str(), "Line"),
            Some(Geometry::Mesh(value)) => (value.name.as_str(), "Mesh"),
            Some(Geometry::NurbsCurve(value)) => (value.name.as_str(), "NURBS curve"),
            Some(Geometry::NurbsSurface(value)) => (value.name.as_str(), "NURBS surface"),
            Some(Geometry::Plane(value)) => (value.name.as_str(), "Plane"),
            Some(Geometry::Point(value)) => (value.name.as_str(), "Point"),
            Some(Geometry::PointCloud(value)) => (value.name.as_str(), "Point cloud"),
            Some(Geometry::Polyline(value)) => (value.name.as_str(), "Polyline"),
            None => ("", "Object"),
        };

        if name.trim().is_empty() { kind } else { name }
    }

    /// The edge index a pipe pick landed on; an instance's edges are its definition's.
    pub fn edge_at(&self, pick: Pick) -> Option<u32> {
        // bit 31 marks a pipe pick, a mesh edge; the other 31 bits are the pipe's row
        if pick.sub & 0x8000_0000 == 0 {
            return None;
        }

        let &(parent, edge) = self.edge_sources.get((pick.sub & 0x7fff_ffff) as usize)?;
        let mut own = parent == pick.row;
        (own && edge != u32::MAX).then_some(edge)
    }

    /// The solid face indices a row draws, and whether an instance draws them from its definition.
    pub fn solid_faces(&self, row: u32) -> Option<(std::ops::Range<u32>, bool)> {
        let mut faces = self.face_range(row).map(|range| (range, false));
        faces
    }

    /// Point `local` of the cloud on `row`; None when streamed.
    pub fn point_at(&self, row: u32, local: u32) -> Option<PickedPoint> {
        let Some(Geometry::PointCloud(pc)) = self.geometry(row) else {
            return None;
        };
        let c = pc.coords();
        let i = local as usize * 3;

        if i + 2 >= c.len() {
            return None;
        }

        Some(PickedPoint {
            local,
            id: pc.point_id(local as usize),
            position: [c[i], c[i + 1], c[i + 2]],
        })
    }

    /// The ribbon rows of one object.
    pub fn ribbon_range(&self, row: u32) -> Option<std::ops::Range<u32>> {
        let span = self.spans.span(*self.feet.get(row as usize)?);
        let start = span.start.ribbons;
        (span.count.ribbons > 0).then_some(start..start + span.count.ribbons)
    }

    /// The solid face indices of one object.
    pub fn face_range(&self, row: u32) -> Option<std::ops::Range<u32>> {
        let span = self.spans.span(*self.feet.get(row as usize)?);
        let start = span.start.faces;
        (span.count.faces > 0).then_some(start..start + span.count.faces)
    }

    /// The row of one object, by document and guid.
    pub fn row_of(&self, doc: usize, guid: &str) -> Option<u32> {
        self.guid_to_row.get(&(doc, Rc::from(guid))).copied()
    }

    /// The document and guid of a row; None for a free id and the sink.
    pub fn identity_of(&self, row: u32) -> Option<(usize, Rc<str>)> {
        let owner = *self.owners.get(row as usize)?;

        if owner == FREE || owner == SINK || owner == TOMB {
            return None;
        }

        Some((owner, Rc::clone(self.order.get(row as usize)?)))
    }

    /// The rows currently hidden.
    pub fn hidden_rows(&self) -> Vec<u32> {
        let mut rows = Vec::new();

        for identity in &self.hidden {
            if let Some(&row) = self.guid_to_row.get(identity) {
                rows.push(row);
            }
        }

        rows
    }

    /// Row ids handed out so far, live or not; loops over rows run to here.
    pub fn row_count(&self) -> usize {
        self.order.len()
    }

    /// Rows holding an object, a text or a streamed shell.
    pub fn object_count(&self) -> usize {
        self.order.len()
            - self.ids.len()
            - usize::from(self.sink.is_some())
    }
}

/// File placement times the object's own transform.
fn placement(world: &HashMap<String, Xform>, place: &Xform, guid: &str) -> Xform {
    match world.get(guid) {
        Some(local) => place * local,
        None => place.clone(),
    }
}

/// Guids under an `attributes` group; they get no row. The root is named after the session, never a group.
fn baked_attributes(session: &Session) -> HashSet<String> {
    let mut out = HashSet::new();
    let mut stack: Vec<_> = session
        .tree
        .root()
        .into_iter()
        .flat_map(|root| root.borrow().children())
        .map(|n| (n, false))
        .collect();

    while let Some((node, inside)) = stack.pop() {
        let node = node.borrow();
        let inside = inside || node.name == "attributes";

        if inside && session.lookup.contains_key(&node.name) {
            out.insert(node.name.clone());
        }

        stack.extend(node.children().into_iter().map(|c| (c, inside)));
    }

    out
}

/// Kills sorted and joined into contiguous runs per lane.
fn runs(mut kills: Vec<(LaneId, u32, u32)>) -> Vec<(LaneId, u32, u32)> {
    kills.retain(|kill| kill.2 > 0);
    kills.sort_unstable();
    let mut out: Vec<(LaneId, u32, u32)> = Vec::with_capacity(kills.len());

    for (lane, first, count) in kills {
        match out.last_mut() {
            Some(last) if last.0 == lane && last.1 + last.2 >= first => {
                last.2 = last.2.max(first + count - last.1);
            }
            _ => out.push((lane, first, count)),
        }
    }

    out
}

