// A range gate lets 3 reads of a scene run at once and queues the rest in order: 40 parallel reads would split the bandwidth and all arrive late.
use std::cell::{Cell, RefCell};
use std::collections::VecDeque;
use std::future::Future;
use std::pin::Pin;
use std::rc::Rc;
use std::task::{Context, Poll, Waker};

/// Range reads a scene keeps in flight; the rest wait their turn.
pub const RANGE_READS: usize = 3;

// A Waker is the handle the async runtime gives a waiting future; `wake()` asks the runtime to poll that future again.
/// A waiting read's place in the queue.
#[derive(Default)]
struct Turn {
    given: Cell<bool>,             // a slot was handed to it
    waker: RefCell<Option<Waker>>, // wakes its read
}

impl Turn {
    /// Wake the read waiting on this turn.
    fn wake(&self) {
        if let Some(waker) = self.waker.take() {
            waker.wake();
        }
    }
}

/// Lets a few reads run at once, first come first served; a closed gate turns waiting reads away.
pub struct RangeGate {
    limit: usize,                       // slots
    running: Cell<usize>,               // slots taken
    queue: RefCell<VecDeque<Rc<Turn>>>, // waiting reads, oldest first
    closed: Cell<bool>,                 // its scene is gone
}

impl RangeGate {
    /// A gate with `limit` slots.
    pub fn new(limit: usize) -> Rc<Self> {
        Rc::new(Self {
            limit: limit.max(1),
            running: Cell::new(0),
            queue: RefCell::new(VecDeque::new()),
            closed: Cell::new(false),
        })
    }

    // `self: &Rc<Self>`: a method on the shared pointer itself, so the returned future can keep its own clone of the gate
    /// Wait for a slot; None once the gate closed.
    pub fn enter(self: &Rc<Self>) -> Enter {
        Enter {
            gate: self.clone(),
            turn: None,
        }
    }

    /// Turn every waiting read away.
    pub fn close(&self) {
        self.closed.set(true);

        for turn in self.queue.take() {
            turn.wake();
        }
    }

    /// The gate's scene is gone.
    pub fn is_closed(&self) -> bool {
        self.closed.get()
    }

    /// Reads running and waiting.
    pub fn load(&self) -> (usize, usize) {
        (self.running.get(), self.queue.borrow().len())
    }

    /// A slot came free: hand it to the oldest waiting read.
    fn release(&self) {
        let next = self.queue.borrow_mut().pop_front();

        match next {
            Some(turn) => {
                turn.given.set(true);
                turn.wake();
            }
            None => self.running.set(self.running.get().saturating_sub(1)),
        }
    }
}

/// A read waiting at the gate.
pub struct Enter {
    gate: Rc<RangeGate>,    // the gate
    turn: Option<Rc<Turn>>, // its place in the queue, once queued
}

// A hand-written Future: the runtime calls `poll`; Ready(v) ends the `.await` with v, Pending parks it until its waker is called.
impl Future for Enter {
    type Output = Option<Permit>;

    /// A slot when one is free and no older read waits.
    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Self::Output> {
        // `Pin` promises the future stays at one address while polled; `get_mut` is allowed because Enter holds no pointer into itself
        let this = self.get_mut();
        let gate = this.gate.clone();

        if gate.closed.get() {
            this.turn = None;
            return Poll::Ready(None);
        }

        match &this.turn {
            None if gate.running.get() < gate.limit && gate.queue.borrow().is_empty() => { // a free slot and nobody queued ahead
                gate.running.set(gate.running.get() + 1);
                Poll::Ready(Some(Permit { gate }))
            }
            None => {
                let turn = Rc::new(Turn::default());
                *turn.waker.borrow_mut() = Some(cx.waker().clone());
                gate.queue.borrow_mut().push_back(turn.clone());
                this.turn = Some(turn);
                Poll::Pending
            }
            Some(turn) if turn.given.get() => { // `release` handed this turn its slot
                this.turn = None;
                Poll::Ready(Some(Permit { gate }))
            }
            Some(turn) => {
                *turn.waker.borrow_mut() = Some(cx.waker().clone());
                Poll::Pending
            }
        }
    }
}

// Dropping a future cancels it, e.g. when the scene is replaced; it must then leave the queue or pass its slot on, or the slot is lost.
impl Drop for Enter {
    /// A read dropped while waiting leaves the queue, or passes on a slot it was given.
    fn drop(&mut self) {
        let Some(turn) = self.turn.take() else {
            return;
        };

        if turn.given.get() {
            self.gate.release();
        } else {
            self.gate
                .queue
                .borrow_mut()
                .retain(|queued| !Rc::ptr_eq(queued, &turn));
        }
    }
}

// A guard: the slot is held exactly as long as the Permit lives, so every return path of a read frees it.
/// A slot at the gate, freed when dropped.
pub struct Permit {
    gate: Rc<RangeGate>, // the gate it came from
}

impl Drop for Permit {
    /// Free the slot.
    fn drop(&mut self) {
        self.gate.release();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Poll once with a waker that does nothing.
    fn poll(enter: &mut Enter) -> Poll<Option<Permit>> {
        let mut cx = Context::from_waker(Waker::noop());
        Pin::new(enter).poll(&mut cx)
    }

    /// The first reads run, the rest wait and enter oldest first as slots free.
    #[test]
    fn gate_runs_a_few_reads_and_queues_the_rest_in_order() {
        let gate = RangeGate::new(2);
        let mut first = gate.enter();
        let mut second = gate.enter();
        let mut third = gate.enter();
        let mut fourth = gate.enter();
        let one = poll(&mut first);
        let two = poll(&mut second);
        assert!(matches!(one, Poll::Ready(Some(_))));
        assert!(matches!(two, Poll::Ready(Some(_))));
        assert!(poll(&mut third).is_pending());
        assert!(poll(&mut fourth).is_pending());
        assert_eq!(gate.load(), (2, 2));

        drop(one);
        assert!(poll(&mut fourth).is_pending());
        let three = poll(&mut third);
        assert!(matches!(three, Poll::Ready(Some(_))));
        assert_eq!(gate.load(), (2, 1));

        drop(two);
        drop(three);
        assert!(matches!(poll(&mut fourth), Poll::Ready(Some(_))));
        assert_eq!(gate.load(), (0, 0));
    }

    /// A newcomer does not jump the queue while a freed slot waits for its reader.
    #[test]
    fn gate_is_first_come_first_served() {
        let gate = RangeGate::new(1);
        let mut first = gate.enter();
        let mut second = gate.enter();
        let one = poll(&mut first);
        assert!(poll(&mut second).is_pending());
        drop(one);

        let mut late = gate.enter();
        assert!(poll(&mut late).is_pending());
        assert!(matches!(poll(&mut second), Poll::Ready(Some(_))));
    }

    /// A read dropped while waiting leaves the queue; one dropped after its slot came passes it on.
    #[test]
    fn dropped_waiters_leave_or_pass_their_slot_on() {
        let gate = RangeGate::new(1);
        let mut first = gate.enter();
        let mut second = gate.enter();
        let mut third = gate.enter();
        let one = poll(&mut first);
        assert!(poll(&mut second).is_pending());
        assert!(poll(&mut third).is_pending());

        drop(one);
        drop(second);
        let three = poll(&mut third);
        assert!(matches!(three, Poll::Ready(Some(_))));
        assert_eq!(gate.load(), (1, 0));

        let mut fourth = gate.enter();
        assert!(poll(&mut fourth).is_pending());
        drop(fourth);
        assert_eq!(gate.load(), (1, 0));
    }

    /// Closing turns waiting reads away; running ones finish.
    #[test]
    fn closed_gate_turns_waiting_reads_away() {
        let gate = RangeGate::new(1);
        let mut first = gate.enter();
        let mut second = gate.enter();
        let one = poll(&mut first);
        assert!(poll(&mut second).is_pending());

        gate.close();
        assert!(gate.is_closed());
        assert!(matches!(poll(&mut second), Poll::Ready(None)));
        assert!(matches!(poll(&mut gate.enter()), Poll::Ready(None)));
        drop(one);
        assert_eq!(gate.load(), (0, 0));
    }
}

// Validation checks every count, index and number of a file before the kernel allocates from it: a bad file fails with a message, not a crash.
use prost::Message;
use session_rust::proto;

/// Source objects a scene may hold.
pub const MAX_OBJECTS: usize = 2_000_000;

/// Why a scene with more objects is refused.
pub const TOO_MANY: &str = "scene exceeds two million source objects";

/// Deepest tree level a scene may have.
pub const MAX_DEPTH: usize = 64;

/// Why a scene with a deeper tree is refused.
pub const TOO_DEEP: &str = "scene hierarchy exceeds 64 levels";

// `any(feature = ..., test)`: compiled when the Cargo feature is on, and always for the tests
#[cfg(any(feature = "json-sessions", test))]
/// Check every NURBS record in session JSON before it is parsed.
pub fn json(text: &str) -> Result<(), String> {
    let source: serde_json::Value = serde_json::from_str(text).map_err(json_error)?;
    let mut pending = vec![(&source, 0usize)];

    // a stack of pending values instead of recursion: a file nested 100,000 levels deep cannot overflow the call stack
    while let Some((value, depth)) = pending.pop() {
        if depth > 64 {
            return Err("session JSON exceeds 64 nested levels".into());
        }

        match value {
            serde_json::Value::Object(fields) => {
                if fields.contains_key("control_points")
                    && (fields.contains_key("cv_count") || fields.contains_key("cv_count_u"))
                {
                    json_controls(value)?;
                }

                for child in fields.values() {
                    pending.push((child, depth + 1));
                }
            }
            serde_json::Value::Array(values) => {
                for child in values {
                    pending.push((child, depth + 1));
                }
            }
            _ => {}
        }
    }

    Ok(())
}

#[cfg(any(feature = "json-sessions", test))]
/// A JSON parse error as a message.
fn json_error(error: serde_json::Error) -> String {
    format!("invalid session JSON: {error}")
}

#[cfg(any(feature = "json-sessions", test))]
/// A count field, defaulted and capped.
fn json_count(
    source: &serde_json::Value,
    key: &str,
    default: u64,
    maximum: u64,
) -> Result<usize, String> {
    let count = match source.get(key) {
        Some(value) => match value.as_u64() {
            Some(value) => value,
            None => return Err(format!("invalid JSON {key}")),
        },
        None => default,
    };

    if count > maximum {
        return Err(format!("JSON {key} exceeds its supported count"));
    }

    Ok(count as usize)
}

/// The highest control index a surface reads, None on overflow.
fn addressed_surface_controls(
    rows: usize,
    columns: usize,
    stride_u: usize,
    stride_v: usize,
    size: usize,
) -> Option<usize> {
    // `checked_mul` / `checked_add` return None on overflow instead of wrapping around to a small, wrong index
    (rows - 1)
        .checked_mul(stride_u)?
        .checked_add((columns - 1).checked_mul(stride_v)?)?
        .checked_add(size)
}

#[cfg(any(feature = "json-sessions", test))]
/// Check one JSON curve or surface's controls against its counts.
fn json_controls(source: &serde_json::Value) -> Result<(), String> {
    let controls = source["control_points"]
        .as_array()
        .ok_or("JSON controls must be an array")?;
    let dimension = json_count(source, "dimension", 3, 3)?;

    if dimension < 2 {
        return Err("invalid JSON control dimension".into());
    }

    let size = dimension + usize::from(source["is_rational"].as_bool().unwrap_or(false));

    if source.get("cv_count_u").is_some() {
        let rows = json_count(source, "cv_count_u", 0, 1_000_000)?;
        let columns = json_count(source, "cv_count_v", 0, 1_000_000)?;
        let total = rows as u64 * columns as u64;

        if total > 4_000_000 || controls.len() as u64 != total * size as u64 {
            return Err("JSON surface controls disagree with their declared counts".into());
        }

        json_axis(source, "order_u", rows, "nurbsknots_u")?;
        json_axis(source, "order_v", columns, "nurbsknots_v")?;
    } else {
        let count = json_count(source, "cv_count", 0, 1_000_000)?;
        let stride = json_count(source, "cv_stride", size as u64, 4)?;

        if count != controls.len() || stride != size {
            return Err("JSON curve controls disagree with their declared count or stride".into());
        }

        for control in controls {
            if control.as_array().map(Vec::len) != Some(size) {
                return Err("incomplete JSON curve control".into());
            }
        }

        json_axis(source, "order", count, "nurbsknots")?;
    }

    Ok(())
}

#[cfg(any(feature = "json-sessions", test))]
/// Check one JSON knot vector.
fn json_axis(
    source: &serde_json::Value,
    order_key: &str,
    count: usize,
    knots_key: &str,
) -> Result<(), String> {
    let order = json_count(source, order_key, 4, 64)?;
    let values = source[knots_key]
        .as_array()
        .ok_or("missing JSON NURBS knots")?;
    let mut knots = Vec::with_capacity(values.len());

    for value in values {
        knots.push(value.as_f64().ok_or("invalid JSON NURBS knot")?);
    }

    axis(order as i32, count as i32, &knots)?;
    Ok(())
}

/// Check every geometry of a loaded session.
pub fn retained(source: &session_rust::Session) -> Result<(), String> {
    for item in &source.objects.meshes {
        mesh(&item.to_proto())?;
    }

    for item in &source.objects.pointclouds {
        cloud(&item.to_proto())?;
    }

    for item in &source.objects.nurbscurves {
        curve(&item.to_proto())?;
    }

    for item in &source.objects.nurbssurfaces {
        surface(&item.to_proto())?;
    }

    for item in &source.objects.breps {
        brep(&item.to_proto())?;
    }

    Ok(())
}

/// Check every record of a protobuf session.
pub fn session(source: &proto::Session) -> Result<(), String> {
    if let Some(objects) = &source.objects {
        let count = objects.points.len()
            + objects.lines.len()
            + objects.polylines.len()
            + objects.meshes.len()
            + objects.pointclouds.len()
            + objects.nurbscurves.len()
            + objects.nurbssurfaces.len()
            + objects.breps.len()
            + objects.elements.len();

        if count > MAX_OBJECTS {
            return Err(TOO_MANY.into());
        }

        for item in &objects.points {
            point(item)?;
        }

        for item in &objects.lines {
            line(item)?;
        }

        for item in &objects.polylines {
            polyline(item)?;
        }

        for item in &objects.meshes {
            mesh(item)?;
        }

        for item in &objects.pointclouds {
            cloud(item)?;
        }

        for item in &objects.nurbscurves {
            curve(item)?;
        }

        for item in &objects.nurbssurfaces {
            surface(item)?;
        }

        for item in &objects.breps {
            brep(item)?;
        }

        for item in &objects.elements {
            element(item)?;
        }
    }

    for entry in &source.xforms {
        xform(entry)?;
    }

    if let Some(tree) = &source.tree
        && let Some(root) = &tree.root
    {
        let mut pending = vec![(root, 0usize)];

        while let Some((node, depth)) = pending.pop() {
            if depth > MAX_DEPTH {
                return Err(TOO_DEEP.into());
            }

            for child in &node.children {
                pending.push((child, depth + 1));
            }
        }
    }

    Ok(())
}

