//! Load each file twice and report any difference between the two loads.
use session_rust::{Session, Xform};
use session_viewer::app::scene::{FileDoc, Scene};

/// The GPU tables of one load.
fn tables(bytes: &[u8]) -> Scene {
    let s = Session::pb_loads(bytes).expect("pb_loads");
    let mut sc = Scene::new();
    sc.add_file(FileDoc {
        name: "d".into(),
        session: std::rc::Rc::new(s),
        place: Xform::identity(),
        point_px: 0.0,
        display_only: false,
    });
    sc
}

/// Check every file in the arguments; exit 1 if any differs.
fn main() {
    let mut bad = 0;
    for path in std::env::args().skip(1) {
        let Ok(bytes) = std::fs::read(&path) else {
            continue;
        };
        let name = path.rsplit('/').next().unwrap_or(&path).to_string();
        let mut fails: Vec<String> = Vec::new();

        // 1. GPU tables
        let (a, b) = (tables(&bytes), tables(&bytes));
        macro_rules! same {
            ($l:ident.$f:ident) => {
                if bytemuck::cast_slice::<_, u8>(&a.tables.$l.$f)
                    != bytemuck::cast_slice::<_, u8>(&b.tables.$l.$f)
                {
                    fails.push(format!("tables.{}.{}", stringify!($l), stringify!($f)));
                }
            };
        }
        same!(arena.verts);
        same!(arena.idx);
        same!(seg.ribbons);
        same!(seg.pipes);
        same!(glyph.spheres);
        same!(glyph.dots);
        same!(cloud.pos);
        same!(cloud.col);
        same!(cloud.nrm);
        if a.tables.bounds != b.tables.bounds {
            fails.push("tables.bounds".into())
        }

        // 2. mesh readers
        let (sa, sb) = (
            Session::pb_loads(&bytes).unwrap(),
            Session::pb_loads(&bytes).unwrap(),
        );
        for (i, (ma, mb)) in sa.objects.meshes.iter().zip(&sb.objects.meshes).enumerate() {
            let mut m = |what: &str| fails.push(format!("mesh[{i}].{what}"));
            if ma.area().to_bits() != mb.area().to_bits() {
                m("area")
            }
            if ma.volume().to_bits() != mb.volume().to_bits() {
                m("volume")
            }
            let (ca, cb) = (ma.centroid(), mb.centroid());
            if ca.to_f32() != cb.to_f32() {
                m("centroid")
            }
            if ma.is_closed() != mb.is_closed() {
                m("is_closed")
            }
            if ma
                .edges_with_colors()
                .iter()
                .map(|e| (e.0, e.1))
                .ne(mb.edges_with_colors().iter().map(|e| (e.0, e.1)))
            {
                m("edges_with_colors")
            }
            if ma.edge_face_map() != mb.edge_face_map() {
                m("edge_face_map")
            }
            if ma.to_vertices_and_faces().1 != mb.to_vertices_and_faces().1 {
                m("to_vertices_and_faces")
            }
            if ma.jsondump().unwrap() != mb.jsondump().unwrap() {
                m("jsondump");
                if std::env::var("DETAIL").is_ok() {
                    let (x, y) = (ma.jsondump().unwrap(), mb.jsondump().unwrap());
                    let at = x
                        .bytes()
                        .zip(y.bytes())
                        .position(|(p, q)| p != q)
                        .unwrap_or(x.len().min(y.len()));
                    let lo = at.saturating_sub(120);
                    println!(
                        "    jsondump differs at {at}:\n      A: ...{}\n      B: ...{}",
                        &x[lo..(at + 60).min(x.len())],
                        &y[lo..(at + 60).min(y.len())]
                    );
                }
            }
            // encoded bytes differ by map order; PB_BYTES=1 checks them anyway
            if std::env::var("PB_BYTES").is_ok() && ma.pb_dumps() != mb.pb_dumps() {
                m("pb_dumps")
            }
            let (wa, wb) = (ma.weld(0.001), mb.weld(0.001));
            if wa.to_vertices_and_faces().1 != wb.to_vertices_and_faces().1 {
                m("weld")
            }
            let (mut ua, mut ub) = ((**ma).clone(), (**mb).clone());
            ua.unify_winding();
            ub.unify_winding();
            if ua.to_vertices_and_faces().1 != ub.to_vertices_and_faces().1 {
                m("unify_winding")
            }
            if fails.len() > 40 {
                break;
            }
        }

        if fails.is_empty() {
            println!("{name}: DETERMINISTIC");
        } else {
            bad += 1;
            let mut seen: Vec<String> = Vec::new();
            for f in &fails {
                let kind = f.split('.').next_back().unwrap_or(f).to_string();
                if !seen.contains(&kind) {
                    seen.push(kind)
                }
            }
            println!("{name}: FLAKY -> {}", seen.join(", "));
        }
    }
    if bad > 0 {
        std::process::exit(1)
    }
}

//! Fixture scene for tests/interaction.cjs: one object of each kind plus pick targets.
use session_rust::{
    BRep, Color, Line, Mesh, NurbsCurve, NurbsSurface, Point, PointCloud, Polyline, Session, Xform,
};

/// Write the scene to `argv[1]` and the pick targets to `argv[1].json`.
fn main() {
    let output = std::env::args()
        .nth(1)
        .unwrap_or("/tmp/viewer-interaction.pb".into());
    let mut scene = Session::new("interaction regression");
    let mut cases = Vec::new();
    let mut mesh = Mesh::create_box(2.0, 2.0, 0.4);
    mesh.name = "interaction mesh".into();
    let guid = mesh.guid().to_string();
    scene.add_mesh(mesh, None);
    scene.set_xform(&guid, Xform::translation(-9.0, 3.0, 0.0));
    cases.push(case(
        "mesh",
        &guid,
        [-9.0, 3.0, 0.2],
        Some([-9.0, 4.0, 0.2]),
        8,
    ));
    let mut line = Line::new(-4.0, 3.0, 0.0, -2.0, 3.0, 0.0);
    line.name = "interaction line".into();
    line.width = 0.02;
    let guid = line.guid().to_string();
    scene.add_line(line, None);
    cases.push(case(
        "line",
        &guid,
        [-3.0, 3.0, 0.0],
        Some([-3.0, 3.0, 0.0]),
        2,
    ));
    let mut polyline = Polyline::new(vec![p(2.0, 3.0), p(3.0, 4.0), p(4.0, 3.0)]);
    polyline.name = "interaction polyline".into();
    polyline.width = 0.02;
    let guid = polyline.guid().to_string();
    scene.add_polyline(polyline, None);
    cases.push(case(
        "polyline",
        &guid,
        [2.5, 3.5, 0.0],
        Some([2.5, 3.5, 0.0]),
        3,
    ));
    let mut curve = NurbsCurve::create(false, 2, &[p(8.0, 3.0), p(9.0, 4.0), p(10.0, 3.0)]);
    curve.name = "interaction curve".into();
    curve.width = 0.02;
    let guid = curve.guid().to_string();
    scene.add_nurbscurve(curve, None);
    cases.push(case(
        "curve",
        &guid,
        [9.0, 3.5, 0.0],
        Some([9.0, 3.5, 0.0]),
        3,
    ));
    let mut surface = NurbsSurface::create(
        false,
        false,
        1,
        1,
        2,
        2,
        &[p(0., 0.), p(1., 0.), p(0., 1.), p(1., 1.)],
    )
    .unwrap();
    for u in 0..2 {
        for v in 0..2 {
            surface.set_cv(u, v, &p(-10.0 + 2.0 * u as f64, -4.0 + 2.0 * v as f64));
        }
    }
    surface.name = "interaction surface".into();
    let guid = surface.guid().to_string();
    scene.add_nurbssurface(surface, None);
    cases.push(case(
        "surface",
        &guid,
        [-9.0, -3.0, 0.0],
        Some([-9.0, -2.0, 0.0]),
        4,
    ));
    let mut brep = BRep::create_box(2.0, 2.0, 0.4);
    brep.name = "interaction brep".into();
    let guid = brep.guid().to_string();
    scene.add_brep(brep, None);
    scene.set_xform(&guid, Xform::translation(-3.0, -3.0, 0.0));
    cases.push(case(
        "brep",
        &guid,
        [-3.0, -3.0, 0.2],
        Some([-3.0, -2.0, 0.2]),
        8,
    ));
    let mut points = Vec::with_capacity(25);
    for x in 0..5 {
        for y in 0..5 {
            points.push(p(2.0 + f64::from(x) * 0.5, -4.0 + f64::from(y) * 0.5));
        }
    }
    let mut cloud = PointCloud::new(points, vec![], vec![Color::black(); 25]);
    cloud.name = "interaction resident cloud".into();
    let guid = cloud.guid().to_string();
    scene.add_pointcloud(cloud, None);
    cases.push(case("cloud", &guid, [3.0, -3.0, 0.0], None, 0));
    scene.pb_dump(&output);
    std::fs::write(
        format!("{output}.json"),
        serde_json::to_vec_pretty(&cases).unwrap(),
    )
    .unwrap();
    println!("wrote {output} and {output}.json");
}
/// A point on z = 0.
fn p(x: f64, y: f64) -> Point {
    Point::new(x, y, 0.0)
}
/// One pick target as JSON.
fn case(
    kind: &str,
    guid: &str,
    pick: [f64; 3],
    edge: Option<[f64; 3]>,
    minimum_controls: usize,
) -> serde_json::Value {
    serde_json::json!({"kind":kind,"guid":guid,"pick":pick,"edge":edge,"minimum_controls":minimum_controls})
}

//! Probe scene: a plate with a BRep cylinder, a cone and a NURBS surface.
use session_rust::brep::{BRep, brep_reverse};
use session_rust::{Color, Mesh, NurbsSurface, Point, Session, Xform};

/// Write the scene to `argv[1]`; BREP_PROBE_FLIPPED reverses two cylinder faces.
fn main() {
    let out = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "target/brep_probe.pb".into());
    let mut plate = Mesh::create_box(2800.0, 1000.0, 40.0);
    plate.transform(&Xform::translation(0.0, 0.0, -20.0));
    plate.set_objectcolor(Color::grey());
    let count = plate.edges_with_colors().len();
    plate.set_linecolors(vec![Color::black(); count], vec![0.0; count]);

    let mut cylinder = BRep::create_cylinder(150.0, 400.0);
    cylinder.transform(&Xform::translation(-900.0, 0.0, 0.0));
    cylinder.surfacecolor = Color::grey();
    if std::env::var("BREP_PROBE_FLIPPED").is_ok() {
        for face in cylinder.m_shells[0].faces.iter_mut().take(2) {
            face.orientation = brep_reverse(face.orientation);
        }
    }
    let mut cone = BRep::create_cone(150.0, 400.0);
    cone.transform(&Xform::translation(900.0, 0.0, 0.0));
    cone.surfacecolor = Color::grey();

    let coord: [f64; 4] = [-450.0, -150.0, 150.0, 450.0];
    let mut points = Vec::with_capacity(16);
    for &x in &coord {
        for &y in &coord {
            let z = 250.0 + 150.0 * (x / 200.0).sin() * (y / 200.0).cos();
            points.push(Point::new(x, y, z));
        }
    }
    let mut surface =
        NurbsSurface::create(false, false, 3, 3, 4, 4, &points).expect("probe surface");
    surface.facecolors = vec![Color::grey()];

    let mut s = Session::new("brep_probe");
    s.add_mesh(plate, None);
    s.add_brep(cylinder, None);
    s.add_brep(cone, None);
    s.add_nurbssurface(surface, None);
    s.pb_dump(&out);
    println!("wrote {out}");
}

