//! Probe scene: grey covers over magenta ink that must stay hidden, blue ink that shows.

use session_rust::{Color, Mesh, NurbsCurve, Point, Polyline, Session, Xform};

/// A box of `size` with its top at `top`.
fn slab(size: [f64; 3], centre: [f64; 2], top: f64) -> Mesh {
    let mut mesh = Mesh::create_box(size[0], size[1], size[2]);
    mesh.transform(&Xform::translation(
        centre[0],
        centre[1],
        top - size[2] * 0.5,
    ));
    mesh
}

/// Grey, with zero-width edges.
fn cover_style(mesh: &mut Mesh) {
    let count = mesh.edges_with_colors().len();
    mesh.set_objectcolor(Color::grey());
    mesh.set_linecolors(vec![Color::black(); count], vec![0.0; count]);
    assert!(
        mesh.widths().len() > 1,
        "cover must remain physical mesh geometry, not a print fill"
    );
}

/// Magenta edges and vertex dots.
fn hidden_style(mesh: &mut Mesh) {
    let count = mesh.edges_with_colors().len();
    mesh.set_linecolors(vec![Color::magenta(); count], vec![-1.0; count]);
    mesh.set_pointcolors(vec![Color::magenta(); mesh.number_of_vertices()]);
    mesh.color_mode = session_rust::mesh::ColorMode::POINTCOLORS;
}

/// A closed rectangle at `height`.
fn outline(centre: [f64; 2], half: [f64; 2], height: f64, color: Color) -> Polyline {
    let [x, y] = centre;
    let [a, b] = half;
    let mut line = Polyline::new(vec![
        Point::new(x - a, y - b, height),
        Point::new(x + a, y - b, height),
        Point::new(x + a, y + b, height),
        Point::new(x - a, y + b, height),
        Point::new(x - a, y - b, height),
    ]);
    line.linecolor = color;
    line.width = -1.0;
    line
}

/// Cover and hidden box as one mesh.
fn combine(cover: &Mesh, hidden: &Mesh) -> Mesh {
    let (mut points, mut faces) = cover.to_vertices_and_faces();
    let (other, triangles) = hidden.to_vertices_and_faces();
    let base = points.len();
    points.extend(other);
    for face in triangles {
        faces.push(face.into_iter().map(|key| key + base).collect());
    }
    let mut mesh = Mesh::from_vertices_and_faces(points, faces);
    let edges = mesh.edges_with_colors();
    let mut colors = Vec::with_capacity(edges.len());
    let mut widths = Vec::with_capacity(edges.len());
    for (a, b, _) in edges {
        let hidden_edge = a >= base && b >= base;
        colors.push(if hidden_edge {
            Color::magenta()
        } else {
            Color::black()
        });
        widths.push(if hidden_edge { -1.0 } else { 0.0 });
    }
    mesh.set_objectcolor(Color::grey());
    mesh.set_linecolors(colors, widths);
    let mut points = vec![Color::grey(); base];
    points.extend(vec![Color::magenta(); mesh.number_of_vertices() - base]);
    mesh.set_pointcolors(points);
    mesh.color_mode = session_rust::mesh::ColorMode::POINTCOLORS;
    mesh
}

/// An L-shaped cover with its own triangulation.
fn concave_cover() -> Mesh {
    let ring = [
        [-500.0, -400.0],
        [500.0, -400.0],
        [500.0, -100.0],
        [0.0, -100.0],
        [0.0, 400.0],
        [-500.0, 400.0],
    ];
    let mut points = Vec::new();
    for z in [0.0, -40.0] {
        for p in ring {
            points.push(Point::new(p[0], p[1], z));
        }
    }
    let mut faces = vec![vec![0, 1, 2, 3, 4, 5], vec![11, 10, 9, 8, 7, 6]];
    for i in 0..6 {
        let j = (i + 1) % 6;
        faces.push(vec![i, i + 6, j + 6, j]);
    }
    let mut mesh = Mesh::from_vertices_and_faces(points, faces);
    let triangles = vec![[0, 1, 2], [0, 2, 3], [0, 3, 5], [3, 4, 5]];
    mesh.triangulation.insert(0, triangles.clone());
    mesh.triangulation.insert(
        1,
        triangles
            .into_iter()
            .map(|t| [t[2] + 6, t[1] + 6, t[0] + 6])
            .collect(),
    );
    mesh
}

/// The instance transform of tile `tile`.
fn placement(tile: usize) -> Xform {
    let mut place = Xform::identity();
    place.m[2] = [0.45, -0.55, 0.35, -0.3][tile];
    if tile == 2 {
        place.m[0] = 1.4;
        place.m[5] = 0.7;
        place.m[10] = 1.8;
    }
    place.m[12] = if tile.is_multiple_of(2) {
        -850.0
    } else {
        850.0
    };
    place.m[13] = if tile < 2 { -650.0 } else { 650.0 };
    place
}

/// Add a mesh under `place`.
fn add_mesh(session: &mut Session, mesh: Mesh, place: &Xform) {
    let guid = mesh.guid().to_owned();
    session.add_mesh(mesh, None);
    session.set_xform(&guid, place.clone());
}

/// Add a polyline under `place`.
fn add_line(session: &mut Session, line: Polyline, place: &Xform) {
    let guid = line.guid().to_owned();
    session.add_polyline(line, None);
    session.set_xform(&guid, place.clone());
}

/// A folded roof as one warped quad.
fn warped_roof(scale: f64, top: f64, bottom: f64) -> Mesh {
    let ring = [
        [-500.0, -400.0, 0.0],
        [500.0, -400.0, 0.0],
        [500.0, 400.0, 0.0],
        [-500.0, 400.0, 300.0],
    ];
    let mut points = Vec::new();
    for p in ring {
        points.push(Point::new(p[0] * scale, p[1] * scale, p[2] * scale + top));
    }
    for p in ring {
        points.push(Point::new(p[0] * scale, p[1] * scale, bottom));
    }
    Mesh::from_vertices_and_faces(
        points,
        vec![
            vec![0, 1, 2, 3],
            vec![7, 6, 5, 4],
            vec![0, 4, 5, 1],
            vec![1, 5, 6, 2],
            vec![2, 6, 7, 3],
            vec![3, 7, 4, 0],
        ],
    )
}

/// Write the warped-roof scene to `out`.
fn warped_probe(out: &str) {
    let mut session = Session::new("warped_hidden_line_probe");
    let mut cover = warped_roof(1.0, 0.0, -100.0);
    let mut hidden = warped_roof(0.5, -4.0, -24.0);
    cover_style(&mut cover);
    hidden_style(&mut hidden);
    session.add_mesh(cover, None);
    session.add_mesh(hidden, None);
    let mut visible = Polyline::new(vec![
        Point::new(-250.0, -200.0, 0.0),
        Point::new(250.0, -200.0, 0.0),
        Point::new(250.0, 200.0, 0.0),
        Point::new(-250.0, 200.0, 150.0),
        Point::new(-250.0, -200.0, 0.0),
    ]);
    visible.linecolor = Color::blue();
    session.add_polyline(visible, None);
    session.pb_dump(out);
    println!("wrote {out}: warped covering polygons, zero magenta expected from above");
}

/// Write the free-dots and curve scene to `out`.
fn authored_probe(out: &str) {
    let mut session = Session::new("authored_hidden_line_probe");
    let place = placement(2);
    let height = 0.123456789;
    let mut cover = slab([1000.0, 800.0, 40.0], [0.0; 2], height);
    cover_style(&mut cover);
    add_mesh(&mut session, cover, &place);
    for hidden in [false, true] {
        let z = height - if hidden { 4.0 } else { 0.0 };
        let y = if hidden { -220.0 } else { 60.0 };
        let mut curve = NurbsCurve::create(
            false,
            2,
            &[
                Point::new(-300.0, y, z),
                Point::new(0.0, y + 240.0, z),
                Point::new(300.0, y, z),
            ],
        );
        curve.linecolors = vec![if hidden {
            Color::magenta()
        } else {
            Color::blue()
        }];
        curve.width = -1.0;
        let guid = curve.guid().to_string();
        session.add_nurbscurve(curve, None);
        session.set_xform(&guid, place.clone());
        for x in [-280.0, -140.0, 0.0, 140.0, 280.0] {
            let mut point = Point::new(x, if hidden { -300.0 } else { -50.0 }, z);
            point.pointcolor = if hidden {
                Color::magenta()
            } else {
                Color::green()
            };
            point.width = 24.0;
            let guid = point.guid().to_string();
            session.add_point(point, None);
            session.set_xform(&guid, place.clone());
        }
    }
    session.pb_dump(out);
    println!(
        "wrote {out}: visible blue NURBS and five green coplanar dots; 4 mm lower magenta controls must be absent"
    );
}

/// Write the probe named by `argv[2]` to `argv[1]`.
fn main() {
    let out = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "/tmp/hidden_line_probe.pb".into());
    if std::env::var_os("HIDDEN_LINE_PROBE_CLOSEUP").is_some() {
        let mut session = Session::new("grey_box_red_edges_black_vertices");
        let mut mesh = Mesh::create_box(400.0, 400.0, 400.0);
        mesh.set_objectcolor(Color::grey());
        let edges = mesh.edges_with_colors().len();
        mesh.set_linecolors(vec![Color::red(); edges], vec![10.0; edges]);
        session.add_mesh(mesh, None);
        session.pb_dump(&out);
        return;
    }
    if std::env::var_os("HIDDEN_LINE_PROBE_AUTHORED").is_some() {
        authored_probe(&out);
        return;
    }
    if std::env::var_os("HIDDEN_LINE_PROBE_WARPED").is_some() {
        warped_probe(&out);
        return;
    }
    let mut session = Session::new("hidden_line_probe");
    for tile in 0..4 {
        let place = placement(tile);
        let centre = if tile == 3 { [-250.0, 0.0] } else { [0.0, 0.0] };
        let half = if tile == 3 {
            [100.0, 120.0]
        } else {
            [230.0, 130.0]
        };
        let mut cover = if tile == 3 {
            concave_cover()
        } else {
            slab([1000.0, 800.0, 40.0], [0.0; 2], 0.0)
        };
        let mut hidden = slab([half[0] * 2.0, half[1] * 2.0, 20.0], centre, -4.0);
        if tile == 1 {
            add_mesh(&mut session, combine(&cover, &hidden), &place);
        } else {
            cover_style(&mut cover);
            hidden_style(&mut hidden);
            add_mesh(&mut session, cover, &place);
            add_mesh(&mut session, hidden, &place);
        }
        add_line(
            &mut session,
            outline(
                centre,
                [half[0] - 20.0, half[1] - 20.0],
                -4.0,
                Color::magenta(),
            ),
            &place,
        );
        add_line(
            &mut session,
            outline(centre, half, 0.0, Color::blue()),
            &place,
        );
        if tile == 3 {
            add_line(
                &mut session,
                outline([250.0, 200.0], [100.0, 100.0], -4.0, Color::blue()),
                &place,
            );
        }
    }
    session.pb_dump(&out);
    println!("wrote {out}: magenta must be zero looking from above; blue must remain continuous");
}

//! Probe scene: four touching-solid cases; red edges must show, magenta never.
use session_rust::{Color, Mesh, Point, Polyline, Session, Xform};

/// A grey box with zero-width edges.
fn slab(size: [f64; 3], at: [f64; 3]) -> Mesh {
    let mut m = Mesh::create_box(size[0], size[1], size[2]);
    m.transform(&Xform::translation(at[0], at[1], at[2]));
    m.set_objectcolor(Color::grey());
    let n = m.edges_with_colors().len();
    m.set_linecolors(vec![Color::black(); n], vec![0.0; n]);
    m
}

/// A 400 mm box; edges whose both ends pass `special` get `color`, the rest blue.
fn marked_box(at: [f64; 3], special: fn(&Point) -> bool, color: Color) -> Mesh {
    let mut m = Mesh::create_box(400.0, 400.0, 400.0);
    m.transform(&Xform::translation(at[0], at[1], at[2]));
    m.set_objectcolor(Color::grey());
    let edges = m.edges_with_colors();
    let mut colors = Vec::with_capacity(edges.len());
    for (a, b, _) in &edges {
        let (pa, pb) = (m.vertex_point(*a).unwrap(), m.vertex_point(*b).unwrap());
        colors.push(if special(&pa) && special(&pb) {
            color.clone()
        } else {
            Color::blue()
        });
    }
    m.set_linecolors(colors, vec![-1.0; edges.len()]);
    m
}

/// Write the four cases, 2000 mm apart along x, to `argv[1]`.
fn main() {
    let out = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "target/joint_probe.pb".into());
    let mut s = Session::new("joint_probe");

    // 1. box on a plate
    s.add_mesh(slab([1200.0, 1200.0, 40.0], [0.0, 0.0, -20.0]), None);
    s.add_mesh(
        marked_box([0.0, 0.0, 200.0], |p| p[2].abs() < 1e-9, Color::red()),
        None,
    );

    // 2. two boxes sharing a face
    s.add_mesh(
        marked_box(
            [2000.0, 0.0, 200.0],
            |p| (p[0] - 2200.0).abs() < 1e-9,
            Color::red(),
        ),
        None,
    );
    s.add_mesh(slab([400.0, 400.0, 400.0], [2400.0, 0.0, 200.0]), None);

    // 3. box top 3 mm inside a beam
    s.add_mesh(
        marked_box(
            [4000.0, 0.0, 200.0],
            |p| (p[2] - 400.0).abs() < 1e-9,
            Color::magenta(),
        ),
        None,
    );
    s.add_mesh(slab([1200.0, 600.0, 200.0], [4000.0, 0.0, 497.0]), None);

    // 4. plate outline 4 mm under a beam
    s.add_mesh(slab([1200.0, 300.0, 40.0], [6000.0, 0.0, -20.0]), None);
    let mut outline = Polyline::new(vec![
        Point::new(5420.0, -130.0, 0.0),
        Point::new(6580.0, -130.0, 0.0),
        Point::new(6580.0, 130.0, 0.0),
        Point::new(5420.0, 130.0, 0.0),
        Point::new(5420.0, -130.0, 0.0),
    ]);
    outline.linecolor = Color::magenta();
    s.add_polyline(outline, None);
    s.add_mesh(slab([1400.0, 400.0, 200.0], [6000.0, 0.0, 104.0]), None);

    s.pb_dump(&out);
    println!("wrote {out}");
}

//! Scene of seven BReps, four curves, two surfaces and a polyline in two rows.
use session_rust::brep::BRep;
use session_rust::{Color, NurbsCurve, NurbsSurface, Point, Polyline, Session, Xform};

/// Slot spacing along a row, mm.
const STEP: f64 = 700.0;

/// Distance between the rows, mm.
const ROW: f64 = 900.0;

/// Slots per row.
const PER_ROW: usize = 7;

/// Half width of the patches and the cube.
const HALF: f64 = 300.0;

/// The x of slot `i`.
fn slot(i: usize) -> f64 {
    (i % PER_ROW) as f64 * STEP
}

/// The y of slot `i`.
fn row(i: usize) -> f64 {
    (i / PER_ROW) as f64 * ROW
}

/// Move `b` into slot `i`, lift it by `up`, colour it.
fn place(b: &mut BRep, i: usize, up: f64, color: Color) {
    b.transform(&Xform::translation(slot(i), row(i), up));
    b.surfacecolor = color;
}

/// A two-turn helix in slot `i`.
fn helix_points(i: usize) -> Vec<Point> {
    let mut points = Vec::with_capacity(12);
    for k in 0..12 {
        let t = k as f64 / 11.0;
        let a = t * 4.0 * std::f64::consts::PI;
        points.push(Point::new(
            slot(i) + 200.0 * a.cos(),
            row(i) + 200.0 * a.sin(),
            300.0 + 600.0 * t,
        ));
    }
    points
}

/// An S curve in slot `i`.
fn s_curve_points(i: usize) -> Vec<Point> {
    let mut points = Vec::with_capacity(7);
    for k in 0..7 {
        let t = k as f64 / 6.0;
        let a = t * 2.0 * std::f64::consts::PI;
        points.push(Point::new(
            slot(i) + 250.0 * a.sin(),
            row(i),
            300.0 + 600.0 * t,
        ));
    }
    points
}

/// A tilted rational circle in slot `i`.
fn circle(i: usize) -> NurbsCurve {
    let mut circle = session_rust::Primitives::circle(0.0, 0.0, 0.0, 250.0);
    circle.transform(&Xform::rotation_x((120.0_f64 / 250.0).atan(), false));
    circle.transform(&Xform::translation(slot(i), row(i), 600.0));
    circle.linecolors = vec![Color::blue()];
    circle.name = "circle".into();
    circle
}

/// Points on the box top in slot `i`.
fn box_top_points(i: usize, z: f64) -> Vec<Point> {
    let mut points = Vec::with_capacity(5);
    for k in 0..5 {
        let t = k as f64 / 4.0;
        points.push(Point::new(
            slot(i) - 150.0 + 300.0 * t,
            row(i) + 100.0 * (t * 6.0).sin(),
            z,
        ));
    }
    points
}

/// A cubic curve through `points`.
fn curve(points: &[Point], color: Color, name: &str) -> NurbsCurve {
    let mut c = NurbsCurve::create(false, 3, points);
    c.linecolors = vec![color];
    c.name = name.to_string();
    c
}

/// The dome's control grid in slot `i`.
fn dome_points(i: usize) -> Vec<Point> {
    let coord = [-HALF, -HALF / 3.0, HALF / 3.0, HALF];
    let mut points = Vec::with_capacity(16);
    for &x in &coord {
        for &y in &coord {
            let r = (x * x + y * y).sqrt();
            points.push(Point::new(
                slot(i) + x,
                row(i) + y,
                300.0 + 200.0 * (r / 250.0).cos(),
            ));
        }
    }
    points
}

/// The saddle's control grid in slot `i`.
fn saddle_points(i: usize) -> Vec<Point> {
    let coord = [-HALF, -HALF / 3.0, HALF / 3.0, HALF];
    let mut points = Vec::with_capacity(16);
    for &x in &coord {
        for &y in &coord {
            points.push(Point::new(
                slot(i) + x,
                row(i) + y,
                250.0 + 0.0006 * (x * x - y * y),
            ));
        }
    }
    points
}

/// A grey bicubic patch over `points`.
fn surface(points: &[Point], name: &str) -> NurbsSurface {
    let mut s = NurbsSurface::create(false, false, 3, 3, 4, 4, points).expect("mixed patch");
    s.facecolors = vec![Color::grey()];
    s.name = name.to_string();
    s
}

/// All cube edges in slot `i` as one polyline.
fn cube_polyline(i: usize) -> Polyline {
    let h = HALF;
    let corner = [
        [-h, -h, 0.0],
        [h, -h, 0.0],
        [h, h, 0.0],
        [-h, h, 0.0],
        [-h, -h, 2.0 * h],
        [h, -h, 2.0 * h],
        [h, h, 2.0 * h],
        [-h, h, 2.0 * h],
    ];
    let route = [0, 1, 2, 3, 0, 4, 5, 1, 5, 6, 2, 6, 7, 3, 7, 4];
    let mut points = Vec::with_capacity(route.len());
    for &v in &route {
        let c = corner[v];
        points.push(Point::new(slot(i) + c[0], row(i) + c[1], c[2]));
    }
    let mut p = Polyline::new(points);
    p.name = "cube_edges".to_string();
    p
}

/// Write the whole scene to `argv[1]`.
fn main() {
    let out = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "target/mixed_solids.pb".into());
    let mut s = Session::new("mixed_solids");

    // slots 0..6: the BReps
    let mut solid = BRep::create_box(400.0, 300.0, 250.0);
    place(&mut solid, 0, 125.0, Color::new(0.86, 0.81, 0.72, 1.0));
    s.add_brep(solid, None);

    let mut solid = BRep::create_cylinder(150.0, 400.0);
    place(&mut solid, 1, 0.0, Color::grey());
    s.add_brep(solid, None);

    let mut solid = BRep::create_cone(150.0, 400.0);
    place(&mut solid, 2, 0.0, Color::new(0.78, 0.87, 0.82, 1.0));
    s.add_brep(solid, None);

    let mut solid = BRep::create_sphere(180.0);
    place(&mut solid, 3, 180.0, Color::new(0.82, 0.85, 0.91, 1.0));
    s.add_brep(solid, None);

    let mut solid = BRep::create_torus(220.0, 70.0);
    place(&mut solid, 4, 70.0, Color::new(0.91, 0.83, 0.80, 1.0));
    s.add_brep(solid, None);

    let mut solid = BRep::create_block_with_hole(500.0, 300.0, 200.0, 80.0);
    place(&mut solid, 5, 100.0, Color::grey());
    s.add_brep(solid, None);

    let mut solid = BRep::create_pyramid(400.0, 350.0);
    place(&mut solid, 6, 0.0, Color::new(0.87, 0.89, 0.76, 1.0));
    s.add_brep(solid, None);

    // slots 7..9: curves; the red one lies on the box top
    s.add_nurbscurve(curve(&helix_points(7), Color::blue(), "helix"), None);
    s.add_nurbscurve(curve(&s_curve_points(8), Color::blue(), "s_curve"), None);
    s.add_nurbscurve(circle(9), None);
    s.add_nurbscurve(
        curve(&box_top_points(0, 250.0), Color::red(), "on_box_top"),
        None,
    );

    // slots 10..11: the two surfaces
    s.add_nurbssurface(surface(&dome_points(10), "dome"), None);
    s.add_nurbssurface(surface(&saddle_points(11), "saddle"), None);

    // slot 12: the polyline cube
    s.add_polyline(cube_polyline(12), None);

    s.pb_dump(&out);
    println!("wrote {out}");
}

//! Probe scene: three plates with a blue top outline and a hidden magenta bottom outline.
use session_rust::{Color, Mesh, Point, Polyline, Session, Xform};

const INSET: f64 = 20.0; // bottom outline inset, mm

/// A closed rectangle at height `z`, inset inside the plate.
fn outline(y0: f64, z: f64, inset: f64, color: Color) -> Polyline {
    let (x0, x1, ya, yb) = (inset, 4000.0 - inset, y0 + inset, y0 + 300.0 - inset);
    let mut pl = Polyline::new(vec![
        Point::new(x0, ya, z),
        Point::new(x1, ya, z),
        Point::new(x1, yb, z),
        Point::new(x0, yb, z),
        Point::new(x0, ya, z),
    ]);
    pl.linecolor = color;
    pl
}

/// Write the three plates and their outlines to `argv[1]`.
fn main() {
    let out = std::env::args()
        .nth(1)
        .unwrap_or("target/plate_outline.pb".to_string());
    let mut s = Session::new("plate_outline");
    for (y0, dz, tilt) in [(0.0, 40.0, 0.0), (600.0, 200.0, 0.0), (1200.0, 40.0, 30.0)] {
        let mut plate = Mesh::create_box(4000.0, 300.0, dz);
        plate.transform(&Xform::translation(2000.0, y0 + 150.0, dz * 0.5));
        plate.set_objectcolor(Color::grey());
        let mut top = outline(y0, dz, 0.0, Color::blue());
        let mut bottom = outline(y0, 0.0, INSET, Color::magenta());
        if tilt != 0.0 {
            let about = Xform::translation(0.0, y0 + 150.0, dz * 0.5)
                * Xform::rotation_x(tilt, true)
                * Xform::translation(0.0, -(y0 + 150.0), -dz * 0.5);
            plate.transform(&about);
            top.transform(&about);
            bottom.transform(&about);
        }
        s.add_mesh(plate, None);
        s.add_polyline(top, None);
        s.add_polyline(bottom, None);
    }
    s.pb_dump(&out);
    println!("wrote {out}");
}

//! Probe scene: one smooth solid alone, `sphere` (default), `torus`, `hole` or `dome`.
use session_rust::brep::BRep;
use session_rust::{Color, NurbsSurface, Point, Session, Xform};

/// Half width of the dome patch.
const HALF: f64 = 300.0;

/// The dome's 4x4 control grid.
fn dome_points() -> Vec<Point> {
    let coord = [-HALF, -HALF / 3.0, HALF / 3.0, HALF];
    let mut points = Vec::with_capacity(16);
    for &x in &coord {
        for &y in &coord {
            let r = (x * x + y * y).sqrt();
            points.push(Point::new(x, y, 300.0 + 200.0 * (r / 250.0).cos()));
        }
    }
    points
}

/// The named solid, lifted onto z = 0.
fn solid(which: &str) -> BRep {
    let (mut b, up, color) = match which {
        "torus" => (
            BRep::create_torus(220.0, 70.0),
            70.0,
            Color::new(0.91, 0.83, 0.80, 1.0),
        ),
        "hole" => (
            BRep::create_block_with_hole(500.0, 300.0, 200.0, 80.0),
            100.0,
            Color::grey(),
        ),
        _ => (
            BRep::create_sphere(180.0),
            180.0,
            Color::new(0.82, 0.85, 0.91, 1.0),
        ),
    };
    b.transform(&Xform::translation(0.0, 0.0, up));
    b.surfacecolor = color;
    b
}

/// Write the chosen solid to `argv[1]`.
fn main() {
    let out = std::env::args()
        .nth(1)
        .unwrap_or_else(|| "target/shade_probe.pb".into());
    let which = std::env::args().nth(2).unwrap_or_else(|| "sphere".into());
    let mut s = Session::new("shade_probe");
    if which == "dome" {
        let mut d =
            NurbsSurface::create(false, false, 3, 3, 4, 4, &dome_points()).expect("dome patch");
        d.facecolors = vec![Color::grey()];
        d.name = "dome".to_string();
        s.add_nurbssurface(d, None);
    } else {
        s.add_brep(solid(&which), None);
    }
    s.pb_dump(&out);
    println!("wrote {out}");
}

