#!/usr/bin/env python3
"""count_colors.py <ppm> [tol]  ->  "blue N magenta N"

Counts pixels of a binary P6 PPM whose every channel is within `tol` (default 60/255) of pure
blue (0,0,255) or pure magenta (255,0,255)."""
import sys


def read_ppm(path):
    with open(path, "rb") as f:
        data = f.read()
    tokens = []
    i = 0
    while len(tokens) < 4:
        while data[i:i + 1].isspace():
            i += 1
        if data[i:i + 1] == b"#":
            while data[i:i + 1] not in (b"\n", b""):
                i += 1
            continue
        j = i
        while not data[j:j + 1].isspace():
            j += 1
        tokens.append(data[i:j])
        i = j
    i += 1
    assert tokens[0] == b"P6", tokens[0]
    w, h = int(tokens[1]), int(tokens[2])
    return w, h, data[i:i + w * h * 3]


def main():
    path = sys.argv[1]
    tol = int(sys.argv[2]) if len(sys.argv) > 2 else 60
    w, h, px = read_ppm(path)
    blue = magenta = 0
    for k in range(0, w * h * 3, 3):
        r, g, b = px[k], px[k + 1], px[k + 2]
        if g <= tol and b >= 255 - tol:
            if r <= tol:
                blue += 1
            elif r >= 255 - tol:
                magenta += 1
    print(f"blue {blue} magenta {magenta}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Render the task camera matrix and census actual original-scene object/segment IDs.

Example (executables must be built from the intended before/after source):
  python3 tests/depth/_hidden_line_matrix.py SELFTEST CENSUS_PLATES FLOOR.pb OUT --require-zero
  python3 tests/depth/_hidden_line_matrix.py SELFTEST CENSUS_PLATES FLOOR.pb OUT --require-zero-scales 1,4

Each census receives the camera actually logged by its render. The JSON records only
render/census knobs, source/binary hashes, and results; it never records the process environment.
"""

import argparse
import hashlib
import json
import os
from pathlib import Path
import subprocess


SCALES = (1, 4, 16)

CAMERAS = {
    "iso": {},
    "down": {"VIEWER_ORBIT": "0,209"},
    "tilted": {"VIEWER_ORBIT": "0,150"},
    "side": {"VIEWER_ORBIT": "200,60"},
    "far2p6": {"VIEWER_ORBIT": "0,209", "VIEWER_ZOOM": "-10"},
    "far4p3": {"VIEWER_ORBIT": "0,209", "VIEWER_ZOOM": "-15"},
    "top": {"VIEWER_VIEW": "top"},
}


def digest(path):
    """Identify the actual executable/fixture rather than its mutable filename."""
    value = hashlib.sha256()
    with path.open("rb") as source:
        for chunk in iter(lambda: source.read(1024 * 1024), b""):
            value.update(chunk)
    return value.hexdigest()


def execute(args, environment, log):
    """Preserve the complete diagnostic log and fail on validation or census errors."""
    result = subprocess.run(args, env=environment, text=True, capture_output=True)
    output = result.stdout + result.stderr
    log.write_text(output)
    if result.returncode:
        raise RuntimeError(f"exit {result.returncode}: inspect {log}\n{output[-4000:]}")
    return output


def enforced_scales(options):
    """Which scales must surface nothing. A far enough camera shrinks the model past what the
    depth rule can resolve, so the near scales are the ones a regression shows up in. Rejecting
    an unknown scale by name keeps a typo from silently enforcing less than it reads."""
    if options.require_zero:
        return set(SCALES)
    if not options.require_zero_scales:
        return set()
    requested = {part.strip() for part in options.require_zero_scales.split(",")}
    if not requested <= {str(scale) for scale in SCALES}:
        raise SystemExit(f"--require-zero-scales accepts only {SCALES}")
    return {int(part) for part in requested}


def main():
    """Run all 21 cases by default; optional filters support focused diagnosis."""
    parser = argparse.ArgumentParser(description=__doc__)
    for argument in ("renderer", "census", "scene", "output"):
        parser.add_argument(argument, type=Path)
    zero = parser.add_mutually_exclusive_group()
    zero.add_argument("--require-zero", action="store_true", help="fail if any fully covered original-source core pixel surfaces, at every scale")
    zero.add_argument("--require-zero-scales", help="comma-separated scales to enforce that on; the rest are still rendered and recorded")
    parser.add_argument("--resume", action="store_true", help="reuse completed cases only when all executable/fixture hashes match")
    parser.add_argument("--camera", choices=CAMERAS)
    parser.add_argument("--scale", type=int, choices=SCALES)
    options = parser.parse_args()
    enforced = enforced_scales(options)
    paths = {key: getattr(options, key).resolve() for key in ("renderer", "census", "scene", "output")}
    paths["output"].mkdir(parents=True, exist_ok=True)
    metadata = {key: {"path": str(paths[key]), "sha256": digest(paths[key])} for key in ("renderer", "census", "scene")}
    metadata["enforced_scales"] = sorted(enforced)
    destination = paths["output"] / "matrix.json"
    report = {"metadata": metadata, "results": []}
    if options.resume and destination.exists():
        report = json.loads(destination.read_text())
        if report["metadata"] != metadata:
            raise RuntimeError("resume requires identical renderer, census, scene and enforced scales")
    done = {(row["camera"], row["scale"], row["style"]) for row in report["results"]}
    environment = {key: value for key, value in os.environ.items() if not key.startswith(("VIEWER_", "CENSUS_"))}
    for camera, settings in CAMERAS.items():
        if options.camera and camera != options.camera:
            continue
        for scale in SCALES:
            if options.scale and scale != options.scale:
                continue
            for style in ("flat",):
                if (camera, scale, style) in done:
                    continue
                stem = f"{camera}_{scale}_{style}"
                output = paths["output"]
                knobs = dict(settings, VIEWER_W="1800", VIEWER_H="1400", VIEWER_MSAA="4", VIEWER_DISTANCE_SCALE=str(scale), VIEWER_IDS=str(output / f"{stem}.ids"))
                rendered = execute([paths["renderer"], output / f"{stem}.ppm", paths["scene"]], dict(environment, **knobs), output / f"{stem}.log")
                camera_log = next(line.split("census camera: ", 1)[1] for line in rendered.splitlines() if "census camera: " in line)
                actual_camera = dict(part.split("=", 1) for part in camera_log.split())
                census_knobs = dict(actual_camera, CENSUS_RENDERED_IDS=knobs["VIEWER_IDS"])
                if scale in enforced:
                    census_knobs["CENSUS_REQUIRE_ZERO"] = "1"
                measured = execute([paths["census"], paths["scene"]], dict(environment, **knobs, **census_knobs), output / f"{stem}_census.log")
                result = next(line for line in measured.splitlines() if line.startswith("RENDERED_IDS covered samples"))
                report["results"].append(dict(camera=camera, scale=scale, style=style, result=result, viewer=knobs, census=census_knobs))
                destination.write_text(json.dumps(report, indent=2) + "\n")
                print(f"{stem}: {result}", flush=True)
    print(f"Recorded {len(report['results'])} completed cases in {destination}")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Check viewer Rust formatting without traversing sibling Session packages."""
import argparse
from pathlib import Path
import subprocess
import sys


def viewer_files(repository):
    """Enumerate handwritten viewer source/examples as explicit rustfmt inputs."""
    files = []
    for directory in (repository / "src", repository / "examples"):
        for file in directory.rglob("*.rs"):
            if file.is_file():
                if not file.resolve().is_relative_to(repository):
                    raise ValueError(f"Rust source escapes the viewer: {file}")
                files.append(file)
    return sorted(files)


def main():
    """Check by default; --write applies the same scoped Rust 2024 formatting policy."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--write", action="store_true", help="format the listed viewer files in place")
    args = parser.parse_args()
    repository = Path(__file__).resolve().parents[1]
    files = viewer_files(repository)
    if not files:
        parser.error("no Rust files found under src/ or examples/")
    command = ["rustfmt", "--edition", "2024", "--config", "skip_children=true"]
    if not args.write:
        command.append("--check")
    command.extend(map(str, files))
    action = "Formatting" if args.write else "Checking formatting of"
    print(f"{action} {len(files)} viewer Rust files", flush=True)
    return subprocess.run(command, cwd=repository, check=False).returncode


if __name__ == "__main__":
    sys.exit(main())

/** Real canvas gestures over deterministic source geometry. See tests/README.md. */
const assert=require('node:assert/strict');
const fs=require('node:fs/promises');
const path=require('node:path');
const {chromium}=require('playwright');
/** Load the generated source fixture and verify both device scales. */
async function main(){
  const fixture=process.env.VIEWER_INTERACTION_FIXTURE || '/tmp/viewer-interaction.pb';
  const bytes=await fs.readFile(fixture),cases=JSON.parse(await fs.readFile(fixture+'.json','utf8'));
  const output=process.env.VIEWER_TEST_OUTPUT || '/tmp/session-viewer-interaction';await fs.mkdir(output,{recursive:true});
  const browser=await chromium.launch({executablePath:process.env.CHROME_BIN || '/usr/bin/google-chrome',headless:process.env.VIEWER_HEADLESS==='1',args:JSON.parse(process.env.VIEWER_CHROME_ARGS || '[]')});
  try{for(const dpr of [1,2])await run(browser,dpr,bytes,cases,output);}finally{await browser.close();}
}
/** Exercise real object, edge and control gestures over every required family. */
async function run(browser,dpr,bytes,cases,output){
  const context=await browser.newContext({viewport:{width:1400,height:900},deviceScaleFactor:dpr});
  const page=await context.newPage(),errors=[],history=[];
  page.on('pageerror',capturePageError);
  page.on('console',captureConsoleError);
  await page.route('**/view_local.yaml',serveManifest);
  await page.route('**/pb/interaction-fixture.pb',serveFixture);
  /** Retain page failures alongside the failing selection snapshot. */
  function capturePageError(error){errors.push(String(error));}
  /** Ignore only the unresolved development reload endpoint in static builds. */
  function captureConsoleError(message){if(message.type()==='error' && !message.text().includes('{{__trunk_address__}}'))errors.push(message.text());}
  /** Supply the deterministic local scene without modifying production assets. */
  function serveManifest(route){return route.fulfill({status:200,contentType:'application/yaml',body:'name: Interaction regression\nitems:\n  - file: "pb/interaction-fixture.pb"\n'});}
  /** Serve the generated source bytes through the real loader path. */
  function serveFixture(route){return route.fulfill({status:200,contentType:'application/octet-stream',body:bytes});}
  try{
    // The yellow-coverage oracles (three pure-yellow pixels) were measured with the 1.5 px pen;
    // the viewer's 1 px default leaves a Ctrl-selected solid edge almost entirely under the
    // black silhouette. Pin the oracle's pen through the same knob the native fixtures use.
    await page.goto(new URL('?data=off&inspect=1&thickness=1.5',process.env.VIEWER_URL || 'http://127.0.0.1:8770/').href,{waitUntil:'networkidle'});
    await page.waitForFunction(sceneReady);
    await page.bringToFront();
    await page.locator('canvas').focus();
    await page.waitForFunction(function focusedCanvas(){return document.hasFocus() && document.activeElement?.id==='canvas';});
    await key(page,'5');
    assert.equal((await snapshot(page)).outlines,false,'surface silhouettes are off by default');
    await key(page,'o');
    assert.equal((await snapshot(page)).outlines,true,'O shows surface silhouettes');
    await key(page,'o');
    assert.equal((await snapshot(page)).outlines,false,'O hides them again');
    // Hide centered names to inspect short strokes; nameplate-scene.cjs checks their default display.
    await key(page,'t');
    await page.screenshot({path:path.join(output,`scene-dpr-${dpr}.png`)});
    const parents=new Set();
    for(const spec of cases){
      await key(page,'Escape');
      await key(page,'f');
      let state=await snapshot(page);
      await click(page,project(state,spec.pick));
      state=await snapshot(page);
      assert.notEqual(state.selected,null,`${spec.kind}: ordinary object click`);
      const parent=state.selected;parents.add(parent);
      assert.equal(state.identity[1],spec.guid,'source GUID survives object picking');
      assert.equal(state.selection,'Object');
      // Fit the selected specimen so a fixed-size gumball cannot cover its entire short line.
      await key(page,'f');state=await snapshot(page);
      await visibleYellow(page,output,`${spec.kind}-object-dpr-${dpr}`);
      if(['mesh','surface','brep'].includes(spec.kind)){
        await page.keyboard.down('Shift');
        await click(page,project(state,spec.pick),true);
        await page.keyboard.up('Shift');
        state=await snapshot(page);
        assert.equal(state.selection.Face?.parent,parent,`${spec.kind}: Ctrl+Shift selects a source face`);
        const face=state.selection.Face.face;
        assert(Number.isInteger(face));
        await visibleYellow(page,output,`${spec.kind}-face-dpr-${dpr}`);
        await page.keyboard.down('Shift');
        await click(page,project(state,spec.pick),true);
        await page.keyboard.up('Shift');
        assert.equal((await snapshot(page)).selection.Face?.face,face,'source face identity remains stable');
        await page.keyboard.down('Shift');
        await click(page,project(state,spec.edge),true);
        await page.keyboard.up('Shift');
        assert.equal((await snapshot(page)).selection.Edge?.parent,parent,'Ctrl+Shift keeps edge precedence');
        await key(page,'Escape');
      }
      if(spec.edge && ['mesh','surface','brep'].includes(spec.kind)){
        await click(page,project(state,spec.edge),true);
        state=await snapshot(page);
        assert.equal(state.selection.Edge?.parent,parent,`${spec.kind}: Ctrl must select a source edge`);
        assert(Number.isInteger(state.selection.Edge.edge));
        const identity=state.selection.Edge.edge;
        await click(page,project(state,spec.edge),true);
        assert.equal((await snapshot(page)).selection.Edge?.edge,identity,'same source edge must retain identity');
        await visibleYellow(page,output,`${spec.kind}-edge-dpr-${dpr}`);
      }
      if(spec.edge && ['line','polyline','curve'].includes(spec.kind)){
        await click(page,project(state,spec.edge),true);
        assert.equal((await snapshot(page)).selection,'Object','standalone curves expose source controls, not fabricated tessellation edges');
      }
      await key(page,'F10');state=await snapshot(page);
      assert.equal(state.selection.Controls?.parent,parent,`${spec.kind}: F10 enters controls for one parent`);
      assert.equal(state.selection.Controls.cloud,spec.kind==='cloud');
      assert(state.controls.length>=spec.minimum_controls,`${spec.kind}: original source controls must be available`);
      if(spec.kind!=='cloud')assert.equal(state.markers,state.controls.length);
      const initial=state;
      await key(page,'F10');state=await snapshot(page);
      assert.deepEqual(state.controls,initial.controls,'repeated F10 must not duplicate controls');
      assert.equal(state.markers,initial.markers);assert.equal(state.control_segments,initial.control_segments);
      let target;
      if(spec.kind==='cloud')target=project(state,spec.pick);
      else {
        let candidate=state.controls[0];
        for(const control of state.controls){if(control.position[2]>candidate.position[2])candidate=control;}
        target=project(state,candidate.position,true);
      }
      await click(page,target);state=await snapshot(page);
      assert.notEqual(state.selection.Controls?.selected,null,`${spec.kind}: visible source control must pick`);
      assert.equal(state.selection.Controls.parent,parent);
      if(spec.kind==='cloud')assert.equal(state.selection.Controls.selected.Point,12,'resident source point ID must survive the pick');
      await visibleYellow(page,output,`${spec.kind}-control-dpr-${dpr}`);
      history.push({kind:spec.kind,state});
      await key(page,'Escape');state=await snapshot(page);
      assert.equal(state.selection,'Object');assert.equal(state.selected,parent);
      assert.equal(state.markers,0);assert.equal(state.control_segments,0);
      assert.equal(state.pick_busy,false);
    }
    assert.equal(parents.size,cases.length,'each disjoint specimen must resolve its own parent');
    // A thin source mesh border: CSS tolerance must behave the same at both device scales.
    const line=findKind(cases,'brep');
    await key(page,'Escape');await key(page,'f');let state=await snapshot(page),at=project(state,line.edge);
    await click(page,[at[0],at[1]+5],true);state=await snapshot(page);
    assert(state.selection.Edge,'five CSS pixels from source edge must hit');
    await key(page,'Escape');await click(page,[at[0],at[1]+10],true);
    assert.equal((await snapshot(page)).selection,'Object','ten CSS pixels from source edge must miss');
    // Ctrl on a new source edge while controls are active clears the old parent's controls.
    const mesh=findKind(cases,'mesh');
    state=await snapshot(page);await click(page,project(state,mesh.edge),true);await key(page,'F10');
    const oldParent=(await snapshot(page)).selected;
    await click(page,at,true);state=await snapshot(page);
    assert(state.selection.Edge && state.selected!==oldParent,'Ctrl on another object replaces the specialized parent');
    assert.equal(state.markers,0);assert.equal(state.control_segments,0);
    await key(page,'Escape');
    assert.deepEqual(errors,[]);
    await fs.writeFile(path.join(output,`interaction-dpr-${dpr}.json`),JSON.stringify(history,null,2));
    console.log(`PASS interaction DPR ${dpr}: seven source kinds, object/edge/controls, identity, repeated F10, Esc, parent replacement and CSS tolerance`);
  }catch(error){await page.screenshot({path:path.join(output,`failure-dpr-${dpr}.png`)});await fs.writeFile(path.join(output,`failure-dpr-${dpr}.json`),JSON.stringify({error:String(error),errors,state:await snapshot(page)},null,2));throw error;}finally{await context.close();}
}
/** Retrieve the last submitted read-only state for assertions. */
async function snapshot(page){return page.evaluate(readSnapshot);}
/** Let input enter the frame loop before testing completion; an egui hover frame can arrive first. */
async function settled(page,after){await page.waitForTimeout(150);await page.waitForFunction(pickFinished,after);}
/** Send a canvas-focused keyboard action and await its resulting state. */
async function key(page,value){const before=(await snapshot(page)).submitted_at_ms;await page.keyboard.press(value);await settled(page,before);}
/** Send one ordinary or Ctrl click without duplicating application selection logic. */
async function click(page,at,ctrl=false){const before=(await snapshot(page)).submitted_at_ms;if(ctrl)await page.keyboard.down('Control');await page.mouse.click(at[0],at[1]);if(ctrl)await page.keyboard.up('Control');await settled(page,before);}
/** Apply a column-major homogeneous transform to a source point. */
function multiply(matrix,point){
  const result=[];
  for(let row=0;row<4;row++)result.push(matrix[row]*point[0]+matrix[4+row]*point[1]+matrix[8+row]*point[2]+matrix[12+row]*point[3]);
  return result;
}
/** Project original source coordinates into the fixed CSS test viewport. */
function project(state,point,local=false){
  const origin=state.origin || [0,0,0];
  const anchored=local?multiply(state.model,[...point,1]):[point[0]-origin[0],point[1]-origin[1],point[2]-origin[2],1];
  const clip=multiply(state.mvp,anchored);
  return [(clip[0]/clip[3]*0.5+0.5)*1400,(0.5-clip[1]/clip[3]*0.5)*900];
}
/** Capture selection output and require yellow coverage, including antialiased one-pixel strokes. */
async function visibleYellow(page,output,name){
  const png=await page.locator('canvas').screenshot({path:path.join(output,name+'.png')});
  const count=await page.evaluate(countYellow,png.toString('base64'));
  assert(count>=3,'selected object/edge/control must draw actual yellow coverage');
}
/** Count actual selection pixels in the browser-decoded canvas screenshot. */
async function countYellow(base64){
  const image=await createImageBitmap(await(await fetch('data:image/png;base64,'+base64)).blob());
  const canvas=document.createElement('canvas');canvas.width=image.width;canvas.height=image.height;
  const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0);image.close();
  const data=ctx.getImageData(0,0,canvas.width,canvas.height).data;let yellow=0;
  for(let i=0;i<data.length;i+=4)if(data[i]>240 && data[i+1]>240 && data[i+2]<220)yellow++;
  return yellow;
}
/** Read only the production opt-in inspection snapshot inside the page. */
function readSnapshot(){return JSON.parse(document.querySelector('canvas').getAttribute('data-viewer-inspection'));}
/** Wait for all deterministic source families to pass the loader. */
function sceneReady(){const raw=document.querySelector('canvas')?.getAttribute('data-viewer-inspection');return raw && JSON.parse(raw).objects>=7;}
/** Wait until the submitted selection readback has completed. */
function pickFinished(after){const raw=document.querySelector('canvas')?.getAttribute('data-viewer-inspection');if(!raw)return false;const state=JSON.parse(raw);return state.submitted_at_ms>after && !state.pick_busy;}
/** Find a fixture family without relying on serialization row order. */
function findKind(cases,kind){for(const item of cases){if(item.kind===kind)return item;}throw new Error('Missing fixture family '+kind);}
/** Fail the process while preserving the test's diagnostic output. */
function fail(error){console.error(error);process.exitCode=1;}
main().catch(fail);

/** Production canvas regression: persistent document text and centered selected source names. */
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const path = require('node:path');
const {chromium} = require('playwright');

/** Read the opt-in submitted state; this hook cannot mutate selection or rendering. */
function readState() { return JSON.parse(document.getElementById('canvas').dataset.viewerInspection); }
/** Wait until source upload and persistent annotation have both reached a rendered frame. */
function ready() {
  const raw=document.getElementById('canvas')?.dataset.viewerInspection;
  if(!raw)return false;
  const state=JSON.parse(raw);
  // Seven geometry families plus the document-title text object, itself a source row.
  return state.objects===8 && state.text_labels?.length>0 && !state.pick_busy;
}
/** Wait for asynchronous picking to drain after an input event. */
function settled() { const state=JSON.parse(document.getElementById("canvas").dataset.viewerInspection);return !state.pick_busy; }
/** Project a source-world anchor using the same rebased frame as the production text lane. */
function project(state, world) {
  const point=[world[0]-state.origin[0],world[1]-state.origin[1],world[2]-state.origin[2],1];
  const clip=[];
  for(let row=0;row<4;row++)clip.push(state.mvp[row]*point[0]+state.mvp[4+row]*point[1]+state.mvp[8+row]*point[2]+state.mvp[12+row]);
  return [(clip[0]/clip[3]*0.5+0.5)*state.canvas[0],(0.5-clip[1]/clip[3]*0.5)*state.canvas[1]];
}
/** Find one source family without assuming protobuf serialization order. */
function family(cases,kind) {for(const item of cases)if(item.kind===kind)return item;throw Error('missing fixture '+kind);}
/** Find the selected source label separately from stable document annotations. */
function selectedLabel(state) {for(const label of state.text_labels)if(label.id===0)return label;return null;}
/** Count black backplate and white glyph pixels inside a predicted nameplate box. */
async function pixelCounts(request) {
  const bitmap=await createImageBitmap(await (await fetch('data:image/png;base64,'+request.png)).blob());
  const canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;
  const context=canvas.getContext('2d');context.drawImage(bitmap,0,0);bitmap.close();
  const data=context.getImageData(0,0,canvas.width,canvas.height).data;
  let black=0,white=0,total=0;
  for(let y=Math.max(0,Math.ceil(request.box[1]));y<Math.min(canvas.height,Math.floor(request.box[3]));y++){
    for(let x=Math.max(0,Math.ceil(request.box[0]));x<Math.min(canvas.width,Math.floor(request.box[2]));x++){
      const offset=(y*canvas.width+x)*4;total++;
      if(data[offset]<8&&data[offset+1]<8&&data[offset+2]<8)black++;
      if(data[offset]>240&&data[offset+1]>240&&data[offset+2]>240)white++;
    }
  }
  return {black,white,total};
}
/** Verify source/style state and actual black/white pixels at its projected source center. */
async function captureLabel(page,state,label,dpr,output,name) {
  const scale=label.id===0?0.75:1;
  assert.equal(label.placement,'nameplate');assert.equal(label.font_size,18*scale);assert.equal(label.line_height,26*scale);
  // Every nameplate is rounded with a full cap outside each end: padding is
  // [line_height/2 + 4*scale, 4*scale], so [12.75,3] for the 0.75-scale selection name and [17,4] for a title.
  assert.deepEqual(label.color,[255,255,255,255]);assert.deepEqual(label.padding,label.id===0?[12.75,3]:[17,4]);assert.equal(label.rounded,true);
  if(label.rounded)assert.ok(label.padding[0]>=label.line_box[1]/2+label.padding[1], 'the complete shaped line must fit between the rounded caps');
  const center=project(state,label.world);
  const width=(label.line_box[0]+2*label.padding[0])*dpr,height=(label.line_box[1]+2*label.padding[1])*dpr;
  const png=await page.locator('#canvas').screenshot({path:path.join(output,`${name}-dpr${dpr}.png`)});
  const pixels=await page.evaluate(pixelCounts,{png:png.toString('base64'),box:[center[0]-width/2+1,center[1]-height/2+1,center[0]+width/2-1,center[1]+height/2-1]});
  assert.ok(pixels.black>pixels.total*0.45,'source-centered plate must be opaque black');
  assert.ok(pixels.white>40*dpr*dpr,'source-centered name must have actual white glyph interiors');
  return {label,center,pixels};
}
/** Exercise both required source names, parent replacement, camera motion, F10 and Escape. */
async function main() {
  const fixture=process.env.VIEWER_INTERACTION_FIXTURE || '/tmp/viewer-interaction.pb';
  const bytes=await fs.readFile(fixture),cases=JSON.parse(await fs.readFile(fixture+'.json','utf8'));
  const output=process.env.VIEWER_TEST_OUTPUT || '/tmp/session-viewer-nameplate-scene';await fs.mkdir(output,{recursive:true});
  const browser=await chromium.launch({executablePath:process.env.CHROME_BIN||'/usr/bin/google-chrome',headless:process.env.VIEWER_HEADLESS==='1',args:JSON.parse(process.env.VIEWER_CHROME_ARGS||'[]')});
