use session_rust::{Point, Vector};

/// A construction plane is the flat sheet a dragged point slides on; here one of the three world planes.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum CPlane {
    Xy, // ground, normal z
    Yz, // normal x
    Xz, // normal y
}

impl CPlane {
    /// The plane the view faces most directly.
    pub fn facing(forward: &Vector) -> Self {
        let (x, y, z) = (forward[0].abs(), forward[1].abs(), forward[2].abs());

        // the largest part of the view direction names the plane the eye sees most squarely
        if z >= x && z >= y {
            CPlane::Xy
        } else if y >= x {
            CPlane::Xz
        } else {
            CPlane::Yz
        }
    }

    /// The plane's unit normal.
    pub fn normal(self) -> Vector {
        match self {
            CPlane::Xy => Vector::new(0.0, 0.0, 1.0),
            CPlane::Yz => Vector::new(1.0, 0.0, 0.0),
            CPlane::Xz => Vector::new(0.0, 1.0, 0.0),
        }
    }

    /// Where a ray hits this plane through `origin`, in front of the eye.
    pub fn hit(self, origin: &Point, from: &Point, direction: &Vector) -> Option<Point> {
        let n = self.normal();
        let denom = direction[0] * n[0] + direction[1] * n[1] + direction[2] * n[2]; // 0 when the ray runs along the plane

        if denom.abs() < 1e-12 {
            return None; // ray parallel to the plane
        }

        let num = (origin[0] - from[0]) * n[0]
            + (origin[1] - from[1]) * n[1]
            + (origin[2] - from[2]) * n[2];
        let t = num / denom; // the point from + direction * t lies on the plane

        if !t.is_finite() || t <= 0.0 {
            return None; // behind the eye
        }

        Some(Point::new(
            from[0] + direction[0] * t,
            from[1] + direction[1] * t,
            from[2] + direction[2] * t,
        ))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Looking down picks the ground plane.
    #[test]
    fn the_plane_is_the_one_the_camera_faces() {
        assert_eq!(CPlane::facing(&Vector::new(0.0, 0.0, -1.0)), CPlane::Xy);
        assert_eq!(CPlane::facing(&Vector::new(0.0, 1.0, 0.0)), CPlane::Xz);
        assert_eq!(CPlane::facing(&Vector::new(-1.0, 0.0, 0.0)), CPlane::Yz);
        // a slightly tilted view still picks the ground
        assert_eq!(CPlane::facing(&Vector::new(0.6, 0.1, -0.79)), CPlane::Xy);
    }

    /// A ray straight down lands at the plane height.
    #[test]
    fn a_ray_lands_where_it_crosses() {
        let hit = CPlane::Xy
            .hit(
                &Point::new(0.0, 0.0, 5.0),
                &Point::new(2.0, 3.0, 20.0),
                &Vector::new(0.0, 0.0, -1.0),
            )
            .expect("a hit");
        assert!((hit[0] - 2.0).abs() < 1e-12);
        assert!((hit[1] - 3.0).abs() < 1e-12);
        assert!((hit[2] - 5.0).abs() < 1e-12);
    }

    /// Parallel and backward rays give no hit.
    #[test]
    fn parallel_and_backward_rays_do_not_resolve() {
        let origin = Point::new(0.0, 0.0, 0.0);
        assert!(
            CPlane::Xy
                .hit(
                    &origin,
                    &Point::new(0.0, 0.0, 4.0),
                    &Vector::new(1.0, 0.0, 0.0)
                )
                .is_none(),
            "parallel"
        );
        assert!(
            CPlane::Xy
                .hit(
                    &origin,
                    &Point::new(0.0, 0.0, 4.0),
                    &Vector::new(0.0, 0.0, 1.0)
                )
                .is_none(),
            "pointing away"
        );
    }

    /// f64 keeps a millimetre a kilometre away.
    #[test]
    fn a_distant_plane_keeps_a_small_offset() {
        let expected = 1.0e6 + 1.0e-3;
        let hit = CPlane::Xy
            .hit(
                &Point::new(0.0, 0.0, expected),
                &Point::new(0.0, 0.0, 1.0e7),
                &Vector::new(0.0, 0.0, -1.0),
            )
            .expect("a hit");
        assert!((hit[2] - expected).abs() < 1.0e-6, "kept, within rounding");
        assert_eq!(expected as f32, 1.0e6_f32, "and f32 would have lost it");
    }
}

use super::selection::{ControlId, Controls, SelectionMode};
use session_rust::{Geometry, Mesh, NurbsSurface, Point, Xform};
use std::collections::HashSet;
use std::rc::Rc;

// A subobject is one part of an object, a vertex, an edge or a face, that moves while the rest stays.
/// The part of a geometry an edit applies to.
#[derive(Clone, Copy, Debug)]
pub enum Target {
    Control(ControlId), // one control point or vertex
    Edge(u32),          // one edge by index
    Face(usize),        // one face by key
}

impl Target {
    /// The target the current selection names, if any.
    pub fn selected(mode: &SelectionMode) -> Option<Self> {
        match *mode { // match the value behind the reference; the Copy ids are copied out
            SelectionMode::Controls {
                selected: Some(id), ..
            } => Some(Self::Control(id)),
            SelectionMode::Edge { edge, .. } => Some(Self::Edge(edge)),
            SelectionMode::Face { face, .. } => Some(Self::Face(face)),
            _ => None,
        }
    }
}

/// The mesh vertex keys a target covers.
pub(crate) fn mesh_keys(mesh: &Mesh, target: Target) -> Result<Vec<usize>, String> {
    match target {
        Target::Control(ControlId::Vertex(key)) if mesh.vertex.contains_key(&key) => Ok(vec![key]),
        Target::Face(key) => {
            let mut keys = mesh.face.get(&key).ok_or("Unknown mesh face")?.clone();

            if let Some(holes) = mesh.face_holes.get(&key) {
                keys.extend(holes.iter().flatten()); // hole rims move with the face
            }

            keys.sort_unstable();
            keys.dedup();
            Ok(keys)
        }
        Target::Edge(index) => {
            // edges are numbered in order of first appearance
            let mut seen = HashSet::new();
            let mut at = 0;

            for face in mesh.faces() {
                let keys = &mesh.face[&face];

                for i in 0..keys.len() {
                    let (a, b) = (keys[i], keys[(i + 1) % keys.len()]);
                    let pair = (a.min(b), a.max(b));

                    if seen.insert(pair) { // true only the first time: a shared edge counts once
                        if at == index {
                            return Ok(vec![pair.0, pair.1]);
                        }

                        at += 1;
                    }
                }
            }

            Err("Unknown mesh edge".into())
        }
        _ => Err("Select a mesh vertex, edge or face".into()),
    }
}

/// The surface control (u, v) pairs a target covers.
fn surface_keys(surface: &NurbsSurface, target: Target) -> Result<Vec<(usize, usize)>, String> {
    let [nu, nv] = surface.m_cv_count; // control grid size
    let all = || (0..nu).flat_map(|u| (0..nv).map(move |v| (u, v))).collect(); // a closure: built only when a face asks

    match target {
        Target::Control(ControlId::Surface { surface: 0, u, v }) if u < nu && v < nv => {
            Ok(vec![(u, v)])
        }
        Target::Face(0) => Ok(all()),
        // edge 0..3: the four sides of the control grid
        Target::Edge(edge) if edge < 4 => Ok((0..nu)
            .flat_map(|u| (0..nv).map(move |v| (u, v)))
            .filter(|&(u, v)| match edge {
                0 => u == 0,
                1 => u + 1 == nu,
                2 => v == 0,
                _ => v + 1 == nv,
            })
            .collect()),
        _ => Err("Unknown surface control, boundary or face".into()),
    }
}

/// The world points a target covers.
pub fn points(geometry: &Geometry, target: Target) -> Result<Vec<Point>, String> {
    match geometry {
        // Results collect into one Result: all the points, or the first Err
        Geometry::Mesh(mesh) => mesh_keys(mesh, target)?
            .into_iter()
            .map(|k| mesh.vertex_point(k).ok_or("Missing mesh vertex".into()))
            .collect(),
        Geometry::NurbsSurface(surface) => surface_keys(surface, target)?
            .into_iter()
            .map(|(u, v)| surface.get_cv(u, v).ok_or("Missing surface control".into()))
            .collect(),
        Geometry::BRep(brep) => match target {
            Target::Face(face) => {
                let face = brep.m_faces.get(face).ok_or("Unknown BRep face")?;
                let surface = brep
                    .m_surfaces
                    .get(face.surface_index as usize)
                    .ok_or("Missing face surface")?;
                Ok((0..surface.m_cv_count[0])
                    .flat_map(|u| {
                        (0..surface.m_cv_count[1]).filter_map(move |v| surface.get_cv(u, v))
                    })
                    .collect())
            }
            Target::Edge(edge) => {
                let edge = brep.m_edges.get(edge as usize).ok_or("Unknown BRep edge")?;
                let curve = brep
                    .m_curves_3d
                    .get(edge.curve_3d_index as usize)
                    .ok_or("Degenerate edge has no movable curve")?;
                Ok((0..curve.cv_count())
                    .filter_map(|i| curve.get_cv(i))
                    .collect())
            }
            Target::Control(id) => control_point(geometry, id).map(|p| vec![p]),
        },
        Geometry::Element(element) => match element.geometry() {
            // an element wraps a mesh or BRep: ask this same function again
            session_rust::element::ElementGeometry::Mesh(mesh) => {
                points(&Geometry::Mesh(Rc::new(mesh.clone())), target)
            }
            session_rust::element::ElementGeometry::BRep(brep) => {
                points(&Geometry::BRep(Rc::new(brep.clone())), target)
            }
            _ => Err("Element has no source geometry".into()),
        },
        _ => match target {
            Target::Control(id) => control_point(geometry, id).map(|p| vec![p]),
            _ => Err("This source has no editable faces or edges".into()),
        },
    }
}

/// One control point of any geometry.
fn control_point(geometry: &Geometry, id: ControlId) -> Result<Point, String> {
    Controls::from_geometry(geometry)
        .points
        .into_iter()
        .find(|p| p.id == id)
        .map(|p| Point::new(p.position[0], p.position[1], p.position[2]))
        .ok_or("Unknown source control".into())
}

/// A copy of the geometry with the target moved by `delta`.
pub fn transform(geometry: &Geometry, target: Target, delta: &Xform) -> Result<Geometry, String> {
    if !delta.m.iter().all(|v| v.is_finite()) {
        return Err("Transform must be finite".into());
    }

    let edited = match geometry {
        Geometry::Mesh(source) => {
            // `**` goes through the reference and the Rc to the Mesh; the edit is a copy, the source stays for undo
            let mut mesh = (**source).clone();

            for key in mesh_keys(&mesh, target)? {
                let point = mesh
                    .vertex_point(key)
                    .ok_or("Missing vertex")?
                    .transformed(delta);
                mesh.vertex
                    .get_mut(&key)
                    .ok_or("Missing vertex")?
                    .set_position(point);
            }

            mesh.clear_triangle_bvh(); // stale after moving vertices
            Geometry::Mesh(Rc::new(mesh))
        }
        Geometry::NurbsSurface(source) => {
            let mut surface = (**source).clone();

            for (u, v) in surface_keys(&surface, target)? {
                let p = surface
                    .get_cv(u, v)
                    .ok_or("Missing surface control")?
                    .transformed(delta);

                if !surface.set_cv(u, v, &p) {
                    return Err("Cannot set surface control".into());
                }
            }

            surface.m_mesh = None; // drop the cached mesh
            Geometry::NurbsSurface(Rc::new(surface))
        }
        Geometry::Polyline(source) => {
            let Target::Control(ControlId::Vertex(i)) = target else {
                return Err("Select a polyline vertex".into());
            };
            let p = source
                .get_point(i)
                .ok_or("Unknown polyline vertex")?
                .transformed(delta);
            let mut next = (**source).clone();
            next.set_point(i, &p);
            Geometry::Polyline(Rc::new(next))
        }
        Geometry::NurbsCurve(source) => {
            let Target::Control(ControlId::Curve { curve: 0, point }) = target else {
                return Err("Select a curve control point".into());
            };
            let p = source
                .get_cv(point)
                .ok_or("Unknown curve control")?
                .transformed(delta);
            let mut next = (**source).clone();

            if !next.set_cv_point(point, &p) {
                return Err("Cannot set curve control".into());
            }

            Geometry::NurbsCurve(Rc::new(next))
        }
        Geometry::Line(source) => {
            let Target::Control(ControlId::Vertex(i @ 0..=1)) = target else {
                return Err("Select a line endpoint".into());
            };
            let mut ends = [source.start(), source.end()];
            ends[i] = ends[i].transformed(delta);
            // a new Line gets a new guid: keep the old guid, name and pen so it stays the same object
            let mut next = session_rust::Line::from_points(&ends[0], &ends[1]);
            next.set_guid(source.guid().to_string());
            next.name = source.name.clone();
            next.width = source.width;
            next.dash = source.dash.clone();
            next.linecolor = source.linecolor.clone();
            next.arrowhead = source.arrowhead;
            Geometry::Line(Rc::new(next))
        }
        Geometry::Point(source) => {
            let Target::Control(ControlId::Vertex(0)) = target else {
                return Err("Unknown point".into());
            };
            Geometry::Point(Rc::new(source.transformed(delta)))
        }
        Geometry::BRep(source) => {
            let selected = points(geometry, target)?;
            let mut next = (**source).clone();
            // every vertex, curve or surface point at a selected position moves
            let matches = |p: &Point| {
                selected
                    .iter()
                    .any(|s| (0..3).all(|i| (s[i] - p[i]).abs() <= 1e-8))
            };

            for vertex in &mut next.m_vertices {
                if matches(&vertex.point) {
                    vertex.point = vertex.point.transformed(delta);
                }
            }

            let mut changed_curves = HashSet::new(); // curves touched
            let mut changed_surfaces = HashSet::new(); // surfaces touched

            for (curve_index, curve) in next.m_curves_3d.iter_mut().enumerate() {
                for i in 0..curve.cv_count() {
                    if let Some(p) = curve.get_cv(i)
                        && matches(&p)
                    {
                        curve.set_cv_point(i, &p.transformed(delta));
                        changed_curves.insert(curve_index);
                    }
                }
            }

            for (surface_index, surface) in next.m_surfaces.iter_mut().enumerate() {
                for u in 0..surface.m_cv_count[0] {
                    for v in 0..surface.m_cv_count[1] {
                        if let Some(p) = surface.get_cv(u, v)
                            && matches(&p)
                        {
                            surface.set_cv(u, v, &p.transformed(delta));
                            changed_surfaces.insert(surface_index);
                        }
                    }
                }

                if changed_surfaces.contains(&surface_index) {
                    surface.m_mesh = None; // drop the cached mesh
                }
            }

            validate_boundaries(&next, &changed_curves, &changed_surfaces)?;
            Geometry::BRep(Rc::new(next))
        }
        Geometry::Element(source) => {
            let mut next = (**source).clone();

            match source.geometry() {
                session_rust::element::ElementGeometry::Mesh(mesh) => {
                    let Geometry::Mesh(mesh) =
                        transform(&Geometry::Mesh(Rc::new(mesh.clone())), target, delta)?
                    else {
                        unreachable!()
                    };
                    next.set_geometry((*mesh).clone());
                }
                session_rust::element::ElementGeometry::BRep(brep) => {
                    let Geometry::BRep(brep) =
                        transform(&Geometry::BRep(Rc::new(brep.clone())), target, delta)?
                    else {
                        unreachable!()
                    };
                    next.set_brep_geometry((*brep).clone());
                }
                _ => return Err("Element has no source geometry".into()),
            }

            Geometry::Element(Rc::new(next))
        }
        _ => return Err("This source control cannot be transformed".into()),
    };
    Ok(edited)
}

// A BRep face is a surface trimmed by edge curves; moving surface points can pull a surface off its edge and break the solid.
/// Refuse an edit whose edges no longer lie on their surfaces.
fn validate_boundaries(
    brep: &session_rust::BRep,
    changed_curves: &HashSet<usize>,
    changed_surfaces: &HashSet<usize>,
) -> Result<(), String> {
    if !brep.is_valid() {
        return Err("Edit would invalidate BRep topology".into());
    }

    for edge in &brep.m_edges {
        if edge.degenerated
            || (!changed_curves.contains(&(edge.curve_3d_index as usize))
                && !edge
                    .pcurves
                    .iter()
                    .any(|pc| changed_surfaces.contains(&(pc.surface_index as usize))))
        {
            continue;
        }

        let curve = &brep.m_curves_3d[edge.curve_3d_index as usize];
        let (a, b) = curve.domain();

        // sample the 3D edge against each surface's 2D curve
        for pc in &edge.pcurves {
            let surface = &brep.m_surfaces[pc.surface_index as usize];

            for ci in [pc.curve_2d_index, pc.curve_2d_index_2] {
                if ci < 0 {
                    continue;
                }

                let uv = &brep.m_curves_2d[ci as usize];
                let (u0, u1) = uv.domain();

                for sample in 0..=16 { // 17 samples along the edge, ends included
                    let t = sample as f64 / 16.0;
                    let p = curve.point_at(a + (b - a) * t);
                    let q = uv.point_at(u0 + (u1 - u0) * t);
                    let actual = surface
                        .point_at(q[0], q[1])
                        .ok_or("Cannot evaluate incident surface")?;
                    let tolerance = edge.tolerance.max(1e-6) * 10.0;

                    if (0..3).any(|i| (p[i] - actual[i]).abs() > tolerance) {
                        return Err("This BRep edit requires rebuilding adjacent trims; the original solid was preserved".into());
                    }
                }
            }
        }
    }

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A quad and a triangle sharing an edge.
    fn mesh() -> Geometry {
        let mut mesh = Mesh::new();

        for (key, p) in [
            (10, [0., 0., 0.]),
            (20, [10., 0., 0.]),
            (30, [10., 10., 0.]),
            (40, [0., 10., 0.]),
            (90, [0., 0., 10.]),
        ] {
            mesh.add_vertex(Point::new(p[0], p[1], p[2]), Some(key));
        }

        mesh.add_face(vec![10, 20, 30, 40], Some(7));
        mesh.add_face(vec![10, 90, 20], Some(19));
        Geometry::Mesh(Rc::new(mesh))
    }

    /// Moving a face moves its vertices only.
    #[test]
    fn mesh_face_moves_shared_source_vertices_not_unrelated_vertices() {
        let source = mesh();
        let Geometry::Mesh(next) =
            transform(&source, Target::Face(7), &Xform::translation(0., 0., 3.)).unwrap()
        else {
            panic!()
        };

        for key in [10, 20, 30, 40] {
            assert_eq!(next.vertex[&key].z, 3.);
        }

        assert_eq!(next.vertex[&90].z, 10.);
        assert_eq!(next.face[&19], vec![10, 90, 20]);
        let Geometry::Mesh(original) = source else {
            panic!()
        };
        assert_eq!(original.vertex[&10].z, 0.);
    }

    /// Edge numbering matches the display edges.
    #[test]
    fn edge_ids_match_the_display_producer_even_with_sparse_keys() {
        let Geometry::Mesh(mesh) = mesh() else {
            panic!()
        };
        let keys = mesh.vertices();
        let positions: Vec<_> = keys
            .iter()
            .map(|k| {
                let p = mesh.vertex_point(*k).unwrap();
                [p[0], p[1], p[2]]
            })
            .collect();
        let slots = super::super::walk::mesh_topology::SlotMap::new(&keys);
        let topo =
            super::super::walk::mesh_topology::mesh_topology(&mesh, &keys, &positions, &slots);

        for (i, &(a, b, _)) in topo.edges.iter().enumerate() {
            assert_eq!(
                mesh_keys(&mesh, Target::Edge(i as u32)).unwrap(),
                vec![a, b]
            );
        }
    }

    /// Moving one surface edge keeps weights and the other edge.
    #[test]
    fn surface_boundary_preserves_weights_and_the_opposite_boundary() {
        let mut surface = NurbsSurface::create(
            false,
            false,
            1,
            1,
            2,
            2,
            &[
                Point::new(0., 0., 0.),
                Point::new(1., 0., 0.),
                Point::new(0., 1., 0.),
                Point::new(1., 1., 0.),
            ],
        )
        .unwrap();
        assert!(surface.to_rational());

        for u in 0..2 {
            for v in 0..2 {
                surface.set_cv_4d(u, v, u as f64 * 2., v as f64 * 2., 0., 2.);
            }
        }

        let Geometry::NurbsSurface(next) = transform(
            &Geometry::NurbsSurface(Rc::new(surface)),
            Target::Edge(0),
            &Xform::translation(0., 0., 5.),
        )
        .unwrap() else {
            panic!()
        };
        assert_eq!(next.get_cv(0, 0).unwrap()[2], 5.);
        assert_eq!(next.get_cv(1, 0).unwrap()[2], 0.);
        assert!(next.m_is_rat);
        assert_eq!(next.weight(0, 0), 2.);
        assert_eq!(next.weight(1, 1), 2.);
    }

    /// Moving a box face keeps the solid valid.
    #[test]
    fn moving_box_face_keeps_edges_on_incident_surfaces() {
        let source = Geometry::BRep(Rc::new(session_rust::BRep::create_box(10., 20., 30.)));
        let Geometry::BRep(next) =
            transform(&source, Target::Face(0), &Xform::translation(0., 0., 2.)).unwrap()
        else {
            panic!()
        };
        assert!(next.is_valid());
        assert!(next.is_closed(0));
        validate_boundaries(
            &next,
            &(0..next.m_curves_3d.len()).collect(),
            &(0..next.m_surfaces.len()).collect(),
        )
        .unwrap();
    }
}

use crate::app::layers::{is_layer_key, newest};
use crate::app::scene::Scene;
use crate::app::scene::rows::TEXT;
use crate::app::scene::sync;
use session_rust::{Geometry, Point, Xform};
use std::rc::Rc;

// Methods of one type may spread over files: this second `impl Scene` adds the edits to the Scene of lesson 12.
impl Scene {
    /// Move several rows by one world delta, one undo step for every document they belong to.
    pub fn transform_rows(
        &mut self,
        rows: &[u32],
        delta: &Xform,
        label: &str,
    ) -> Option<Vec<(u32, Xform)>> {
        // (document, guid, new local transform) per row
        let mut changes = rows
            .iter()
            .map(|&row| {
                let (doc, guid) = self.identity_of(row)?;
                if self.docs.get(doc)?.display_only {
                    return None;
                }
                let base = self.local_xform_of(row)?;
                Some((doc, guid, self.local_for_world_delta(row, delta, &base)?))
            })
            .collect::<Option<Vec<_>>>()?; // one row that cannot be edited refuses the whole move
        let selected: std::collections::HashSet<_> = changes
            .iter()
            .map(|(doc, guid, _)| (*doc, guid.to_string()))
            .collect();
        // drop a child whose parent is also selected
        changes.retain(|(doc, guid, _)| {
            self.row_of(*doc, guid)
                .and_then(|row| self.node_of(row))
                .is_none_or(|(node, _)| {
                    node.borrow()
                        .ancestors()
                        .iter()
                        .all(|ancestor| !selected.contains(&(*doc, ancestor.borrow().name.clone())))
                })
        });
        let mut docs: Vec<_> = changes.iter().map(|c| c.0).collect();
        docs.sort_unstable();
        docs.dedup(); // each document once
        for &doc in &docs {
            // Rc::make_mut = copy on write: a session two placements share is cloned first, so only this one changes
            let session = Rc::make_mut(&mut self.docs[doc].session);
            session.begin(label); // everything until commit is one undo step
            for (_, guid, local) in changes.iter().filter(|c| c.0 == doc) {
                session.set_xform(guid, local.clone());
            }
            let notes = sync::commit(session);
            self.noted(doc, notes);
        }
        self.edited(&docs);
        // a session copied for this edit has a tree of its own: cache it before a lookup per row
        for &doc in &docs {
            self.fresh_nodes(doc);
        }
        rows.iter()
            .map(|&row| Some((row, self.placement_of(row)?)))
            .collect()
    }

    /// The row's document and guid, with its session made private.
    fn writable(&mut self, row: u32) -> Option<(usize, Rc<str>)> {
        let (doc, guid) = self.identity_of(row)?;
        let file = self.docs.get_mut(doc)?;

        if file.display_only {
            return None;
        }

        // copy the session if another placement shares it
        Rc::make_mut(&mut file.session);
        Some((doc, guid))
    }

    /// One row's local transform.
    pub fn local_xform_of(&self, row: u32) -> Option<Xform> {
        let (doc, guid) = self.identity_of(row)?;
        Some(self.docs.get(doc)?.session.xform(&guid))
    }

    /// Set one row's local transform in one undo step.
    pub fn set_row_xform(&mut self, row: u32, local: Xform, label: &str) -> Option<Xform> {
        let (doc, guid) = self.writable(row)?;
        let file = self.docs.get_mut(doc)?;
        let session = Rc::make_mut(&mut file.session);
        session.begin(label);
        session.set_xform(&guid, local);
        let notes = sync::commit(session);
        self.noted(doc, notes);
        self.edited(&[doc]);
        self.placement_of(row)
    }

    /// The local transform that applies a world `delta` on top of `base`.
    pub fn local_for_world_delta(&self, row: u32, delta: &Xform, base: &Xform) -> Option<Xform> {
        let placed = self.placement_of(row)?;
        let parent = &placed * &base.inverse()?; // everything above the object
        let back = parent.inverse()?;
        Some(&(&back * &(delta * &parent)) * base) // parent⁻¹ · delta · parent · base: the world move seen from the parent
    }

    /// Apply a world `delta` to one row; returns its new placement.
    pub fn transform_row(&mut self, row: u32, delta: &Xform, label: &str) -> Option<Xform> {
        let base = self.local_xform_of(row)?;
        let local = self.local_for_world_delta(row, delta, &base)?;
        self.set_row_xform(row, local, label)
    }

    /// Delete one row's object; the caller syncs the rows.
    pub fn delete_row(&mut self, row: u32) -> bool {
        if self.delete_text(row) {
            return true;
        }

        let Some((doc, guid)) = self.writable(row) else {
            return false;
        };
        let Some(file) = self.docs.get_mut(doc) else {
            return false;
        };
        let session = Rc::make_mut(&mut file.session);
        session.begin("delete");
        let removed = session.remove_object(&guid);
        let notes = sync::commit(session);
        self.noted(doc, notes);

        if removed {
            self.edited(&[doc]);
            self.selected = None;
        }

        removed
    }

    /// Delete the objects and texts of `rows` as one undo step across their documents; how many went.
    pub fn delete_rows(&mut self, rows: &[u32]) -> usize {
        let mut texts = Vec::new();
        let mut objects = Vec::new();

        for &row in rows {
            match self.retire_text(row) {
                Some(label) => texts.push((TEXT, label)),
                None => objects.extend(self.writable(row)),
            }
        }

        let mut docs = Vec::new();
        let mut count = texts.len();

        for doc in 0..self.docs.len() {
            if objects.iter().all(|(owner, _)| *owner != doc) {
                continue;
            }

            let session = Rc::make_mut(&mut self.docs[doc].session);
            session.begin("delete");
            let before = count;

            for (_, guid) in objects.iter().filter(|(owner, _)| *owner == doc) {
                count += usize::from(session.remove_object(guid));
            }

            let notes = sync::commit(session);
            self.noted(doc, notes);

            if count > before {
                docs.push(doc);
            }
        }

        self.edited(&docs);

        // texts join the documents' step, so one undo brings everything back
        if !texts.is_empty() {
            match self.undo_steps.last_mut() {
                Some(top) if !docs.is_empty() => top.extend(texts),
                _ => {
                    self.forget_redo();
                    self.undo_steps.push(texts);
                }
            }
        }

        if count > 0 {
            self.selected = None;
        }

        count
    }

    /// Undo the newest edit, whichever documents it changed.
    pub fn undo(&mut self) -> bool {
        self.step_history(true)
    }

    /// Redo the newest undone edit.
    pub fn redo(&mut self) -> bool {
        self.step_history(false)
    }

    /// The newest step of each of `docs` is one new edit: undo reaches it next, nothing is left to redo.
    // undo_steps is the scene's own list: each step names the (document, label) pairs one edit made
    pub(crate) fn edited(&mut self, docs: &[usize]) {
        let step: Vec<(usize, String)> = docs
            .iter()
            .filter_map(|&doc| {
                let label = newest(&self.docs.get(doc)?.session.history, true)?;
                Some((doc, label.to_string()))
            })
            .collect();

        if step.is_empty() {
            return;
        }

        self.forget_redo();
        // the documents of one layer edit share its label and undo together
        let layer = step.iter().all(|(_, label)| is_layer_key(label));
        let joins = layer
            && self
                .undo_steps
                .last()
                .is_some_and(|top| top.iter().any(|(_, label)| *label == step[0].1));

        if joins && let Some(top) = self.undo_steps.last_mut() {
            top.extend(step);
            return;
        }

        self.undo_steps.push(step);

        // the documents forgot anything this old
        if self.undo_steps.len() > 2 * MAX_STEPS {
            self.undo_steps.drain(..MAX_STEPS);
        }
    }

    /// A new edit ends the redo branch in every document, so the purge frees what only it reached.
    fn forget_redo(&mut self) {
        self.redo_steps.clear();

        for file in &mut self.docs {
            if !file.session.history.can_redo() {
                continue;
            }

            let history = &mut Rc::make_mut(&mut file.session).history;

            for undone in history.redo_stack.drain(..) {
                history.dropped += undone.ops.len();
                history.bytes = history.bytes.saturating_sub(undone.bytes);
            }
        }
    }

    /// A text made or deleted is one new edit; `label` is `+key` or `-key`.
    pub(crate) fn text_edited(&mut self, label: String) {
        self.forget_redo();
        self.undo_steps.push(vec![(TEXT, label)]);

        if self.undo_steps.len() > 2 * MAX_STEPS {
            self.undo_steps.drain(..MAX_STEPS);
        }
    }

    /// Undo or redo the newest edit in every document it changed; a layer edit one of them forgot stays.
    fn step_history(&mut self, back: bool) -> bool {
        loop { // a step no document still holds is skipped, and the next one tried
            let stack = if back {
                &mut self.undo_steps
            } else {
                &mut self.redo_steps
            };
            let Some(step) = stack.pop() else {
                return false;
            };
            // the documents still holding it on top; a full history drops its oldest edits
            let held: Vec<(usize, String)> = step
                .iter()
                .filter(|(doc, label)| {
                    *doc == TEXT
                        || self
                            .docs
                            .get(*doc)
                            .and_then(|file| newest(&file.session.history, back))
                            == Some(label.as_str())
                })
                .cloned()
                .collect();

            if held.is_empty() {
                continue;
            }

            // stepping some documents of a layer edit alone would split it
            if held.len() < step.len() && step.iter().any(|(_, label)| is_layer_key(label)) {
                let stack = if back {
                    &mut self.undo_steps
                } else {
                    &mut self.redo_steps
                };
                stack.push(step);
                return false;
            }

            for (doc, label) in &held {
                if *doc == TEXT {
                    self.step_text(label, back);
                } else {
                    self.step_document(*doc, back);
                }
            }

            let other = if back {
                &mut self.redo_steps
            } else {
                &mut self.undo_steps
            };
            other.push(held);
            return true;
        }
    }
}

/// Edits undo keeps in order across documents; each document itself keeps its newest 64.
const MAX_STEPS: usize = 4096;

impl Scene {
    /// Move one control point of a polyline or curve in one undo step.
    pub fn set_control_point(&mut self, row: u32, index: usize, to: &Point) -> bool {
        let Some(back) = self.placement_of(row).and_then(|place| place.inverse()) else {
            return false;
        };
        let local = to.transformed(&back); // world point into the object's frame
        let to = &local;
        let Some((doc, guid)) = self.writable(row) else {
            return false;
        };
        let Some(file) = self.docs.get_mut(doc) else {
            return false;
        };
        let session = Rc::make_mut(&mut file.session);
        let Some(geometry) = session.lookup.get(guid.as_ref()).cloned() else {
            return false;
        };
        let edited = match &geometry {
            Geometry::Polyline(source) => {
                let mut next = (**source).clone();

                if index >= next.point_count() {
                    return false;
                }

                next.set_point(index, to);
                Geometry::Polyline(Rc::new(next))
            }
            Geometry::NurbsCurve(source) => {
                let mut next = (**source).clone();

                if !next.set_cv_point(index, to) {
                    return false;
                }

                Geometry::NurbsCurve(Rc::new(next))
            }
            _ => return false,
        };
        session.begin("edit point");
        let replaced = session.replace(&guid, edited);
        let notes = sync::commit(session);
        self.noted(doc, notes);

        if replaced {
            self.edited(&[doc]);
        }

        replaced
    }
}

#[cfg(test)]
pub(crate) mod tests {
    use super::*;
    use crate::app::scene::FileDoc;
    use session_rust::{Point, Session};

    /// One undo puts every moved row back.
    #[test]
    fn group_transform_undo_restores_every_member_in_one_document() {
        let mut source = Session::new("group");
        source.add_point(Point::new(0.0, 0.0, 0.0), None);
        source.add_point(Point::new(10.0, 0.0, 0.0), None);
        let mut scene = Scene::new();
        scene.add_file(file("group", Rc::new(source)));
        let moved = scene
            .transform_rows(&[0, 1], &Xform::translation(5.0, 0.0, 0.0), "move group")
            .unwrap();
        assert!(moved.iter().all(|(_, m)| m.m[12] == 5.0));
        assert!(scene.undo());
        assert!(
            [0, 1]
                .into_iter()
                .all(|r| scene.placement_of(r).unwrap().m[12] == 0.0)
        );
    }

    /// A child of a moved parent is not moved twice.
    #[test]
    fn selected_child_inherits_the_selected_parents_delta_once() {
        let mut source = Session::new("nested");
        let parent = source.add_point(Point::new(0.0, 0.0, 0.0), None);
        source.add_point(Point::new(10.0, 0.0, 0.0), Some(&parent));
        let mut scene = Scene::new();
        scene.add_file(file("nested", Rc::new(source)));
        let moved = scene
            .transform_rows(&[0, 1], &Xform::translation(5.0, 0.0, 0.0), "move nested")
            .unwrap();
        assert!(moved.iter().all(|(_, m)| m.m[12] == 5.0));
        assert!(scene.undo());
        assert!(
            [0, 1]
                .into_iter()
                .all(|r| scene.placement_of(r).unwrap().m[12] == 0.0)
        );
    }

    /// A document at the origin.
    fn file(name: &str, session: Rc<Session>) -> FileDoc {
        FileDoc {
            name: name.into(),
            session,
            place: Xform::identity(),
            point_px: 0.0,
            display_only: false,
        }
    }

    /// One session placed twice.
    fn one_point_twice() -> Scene {
        let mut source = Session::new("twice");
        source.add_point(Point::new(1.0, 0.0, 0.0), None);
        let shared = Rc::new(source);
        let mut scene = Scene::new();
        scene.add_file(file("first", Rc::clone(&shared)));
        scene.add_file(file("second", Rc::clone(&shared)));
        scene
    }

    /// Moving one placement of a shared file leaves the other.
    #[test]
    fn moving_one_placement_leaves_the_other_where_it_was() {
        let mut scene = one_point_twice();
        assert!(Rc::ptr_eq(&scene.docs[0].session, &scene.docs[1].session));

        let moved = scene
            .transform_row(0, &Xform::translation(5.0, 0.0, 0.0), "move")
            .expect("row 0 is editable");

        assert!(!Rc::ptr_eq(&scene.docs[0].session, &scene.docs[1].session));
        assert_eq!([moved.m[12], moved.m[13], moved.m[14]], [5.0, 0.0, 0.0]);
        let still = scene.placement_of(1).expect("row 1 still exists");
        assert_eq!([still.m[12], still.m[13], still.m[14]], [0.0, 0.0, 0.0]);
    }

    /// A world move lands in world units under a scaled placement.
    #[test]
    fn a_world_delta_moves_the_object_in_the_world() {
        let mut source = Session::new("placed");
        source.add_point(Point::new(0.0, 0.0, 0.0), None);
        let mut scene = Scene::new();
        scene.add_file(FileDoc {
            name: "placed".into(),
            session: Rc::new(source),
            // scaled ten times and shifted
            place: Xform::from_matrix([
                10.0, 0.0, 0.0, 0.0, //
                0.0, 10.0, 0.0, 0.0, //
                0.0, 0.0, 10.0, 0.0, //
                100.0, 0.0, 0.0, 1.0,
            ]),
            point_px: 0.0,
            display_only: false,
        });
        let before = scene.placement_of(0).expect("a placement");
        assert_eq!(
            [before.m[12], before.m[13], before.m[14]],
            [100.0, 0.0, 0.0]
        );

        let moved = scene
            .transform_row(0, &Xform::translation(5.0, 0.0, 0.0), "move")
            .expect("row 0 is editable");
        assert_eq!(
            [moved.m[12], moved.m[13], moved.m[14]],
            [105.0, 0.0, 0.0],
            "five world units, not fifty"
        );
    }

    /// Two moves add up.
    #[test]
    fn a_second_move_starts_from_the_first() {
        let mut scene = one_point_twice();
        scene.transform_row(0, &Xform::translation(5.0, 0.0, 0.0), "move");
        let moved = scene
            .transform_row(0, &Xform::translation(0.0, 2.0, 0.0), "move")
            .expect("row 0 is editable");
        assert_eq!([moved.m[12], moved.m[13], moved.m[14]], [5.0, 2.0, 0.0]);
    }

    /// Undo reverses a move; redo repeats it.
    #[test]
    fn undo_puts_the_object_back() {
        let mut scene = one_point_twice();
        assert!(!scene.undo(), "nothing has been edited yet");

        scene.transform_row(0, &Xform::translation(5.0, 0.0, 0.0), "move");
        assert!(scene.undo());
        let back = scene.placement_of(0).expect("row 0 still exists");
        assert_eq!([back.m[12], back.m[13], back.m[14]], [0.0, 0.0, 0.0]);

        assert!(scene.redo());
        let again = scene.placement_of(0).expect("row 0 still exists");
        assert_eq!([again.m[12], again.m[13], again.m[14]], [5.0, 0.0, 0.0]);
    }

    /// Undo takes back the newest edit whichever document holds it; redo goes forward the same way.
    #[test]
    fn undo_and_redo_cross_documents_newest_first() {
        let mut scene = one_point_twice();
        let x = |scene: &Scene| [0, 1].map(|row| scene.placement_of(row).unwrap().m[12]);
        scene.transform_row(0, &Xform::translation(5.0, 0.0, 0.0), "move");
        scene.transform_row(1, &Xform::translation(7.0, 0.0, 0.0), "move");
        scene.transform_row(0, &Xform::translation(1.0, 0.0, 0.0), "move");
        assert_eq!(x(&scene), [6.0, 7.0]);

        for expected in [[5.0, 7.0], [5.0, 0.0], [0.0, 0.0]] {
            assert!(scene.undo());
            assert_eq!(x(&scene), expected);
        }

        assert!(!scene.undo(), "nothing is left");
        assert!(scene.redo());
        assert!(scene.redo());
        assert_eq!(x(&scene), [5.0, 7.0]);

        // a new edit leaves nothing to redo
        scene.transform_row(1, &Xform::translation(1.0, 0.0, 0.0), "move");
        assert!(!scene.redo());
        assert_eq!(x(&scene), [5.0, 8.0]);
    }

    /// Rows of two documents moved together come back together.
    #[test]
    fn a_move_across_documents_is_one_undo_step() {
        let mut scene = one_point_twice();
        let x = |scene: &Scene| [0, 1].map(|row| scene.placement_of(row).unwrap().m[12]);
        scene
            .transform_rows(&[0, 1], &Xform::translation(5.0, 0.0, 0.0), "move")
            .unwrap();
        assert!(scene.undo());
        assert_eq!(x(&scene), [0.0, 0.0]);
        assert!(!scene.undo());
        assert!(scene.redo());
        assert_eq!(x(&scene), [5.0, 5.0]);
    }

    /// A control point edit undoes.
    #[test]
    fn a_control_point_moves_and_undoes() {
        use session_rust::Polyline;
        let mut source = Session::new("line");
        source.add_polyline(
            Polyline::new(vec![Point::new(0.0, 0.0, 0.0), Point::new(1.0, 0.0, 0.0)]),
            None,
        );
        let mut scene = Scene::new();
        scene.add_file(file("line", Rc::new(source)));

        assert!(scene.set_control_point(0, 1, &Point::new(1.0, 5.0, 0.0)));
        let moved = scene.docs[0].session.lookup.values().next().cloned();
        let Some(session_rust::Geometry::Polyline(line)) = moved else {
            panic!("still a polyline");
        };
        assert_eq!(line.get_point(1).expect("two points")[1], 5.0);

        assert!(scene.undo());
        let back = scene.docs[0].session.lookup.values().next().cloned();
        let Some(session_rust::Geometry::Polyline(line)) = back else {
            panic!("still a polyline");
        };
        assert_eq!(line.get_point(1).expect("two points")[1], 0.0);
    }

    /// A world point edit lands in local units under a placement.
    #[test]
    fn control_edit_converts_world_to_local_under_file_placement() {
        let mut source = Session::new("placed");
        assert!(
            source
                .add_polyline(
                    session_rust::Polyline::new(vec![
                        Point::new(0.0, 0.0, 0.0),
