    fn a_created_text_undoes_redoes_and_deletes() {
        let mut scene = one_point_twice();
        let row = scene.add_text(text(1.0));
        assert_eq!(scene.texts.last().unwrap().key, "created-text/0");
        assert_eq!(scene.visible_texts().len(), 1);
