                .session
                .tree
                .get_node_by_name("walls")
                .is_some()
        );
        assert_eq!(scene.row_count() as u32, rows);

        for row in 0..rows {
            assert!(scene.geometry(row).is_none());
            assert_eq!(scene.released_doc(row), Some(0));
