use crate::app::selection::Controls;
use session_rust::{AABB, Geometry, NurbsCurve, NurbsSurface, Point, Vector, Xform};

/// Polyline segments standing in for a curve.
const CURVE_SAMPLES: usize = 64;

/// Screen cells a row may cover before bins try it on every query instead.
const LARGE_CELLS: f64 = 8.0;

// A snap pulls the pointer onto an exact point of existing geometry, e.g. a line's end, once it comes within a few pixels.
/// Kinds of snap point, best first.
// Ord on an enum compares variants in the order written, so End < Vertex < Mid and `<` ranks two kinds.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum SnapKind {
    End,    // end of an open line
    Vertex, // interior or loop vertex
    Mid,    // middle of a segment
    Center, // centre of a shape
    Perp,   // foot of the perpendicular from the last point
    Near,   // nearest point on a segment
}

// Each switch is one bit, so a set of them fits in one u8: END | MID = 0b101 = 5.
pub const END: u8 = 1; // ends and vertices
pub const NEAR: u8 = 2; // anywhere on a curve or edge
pub const MID: u8 = 4; // segment midpoints
pub const CENTER: u8 = 8; // centres of closed shapes
pub const PERP: u8 = 16; // perpendicular from the last point
pub const DEFAULT: u8 = END | NEAR | MID | CENTER; // modes on at start

/// The snap switch, its kinds and its toolbar.
pub struct Snapping {
    pub enabled: bool, // snap to points while drawing
    pub modes: u8,     // kinds switched on, the bits above
    pub bar: bool,     // toolbar under the command line
}

impl Default for Snapping {
    fn default() -> Self {
        Self {
            enabled: true,
            modes: DEFAULT,
            bar: false,
        }
    }
}

/// The toolbar buttons, by label and mode bit.
pub const MODES: [(&str, u8); 5] = [
    ("End", END),
    ("Near", NEAR),
    ("Mid", MID),
    ("Center", CENTER),
    ("Perp", PERP),
];

impl SnapKind {
    /// The mode bit that turns this kind on.
    pub fn mode(self) -> u8 {
        match self {
            SnapKind::End | SnapKind::Vertex => END,
            SnapKind::Mid => MID,
            SnapKind::Center => CENTER,
            SnapKind::Perp => PERP,
            SnapKind::Near => NEAR,
        }
    }
}

/// The bit of a mode named `word`, any case.
pub fn mode(word: &str) -> Option<u8> {
    MODES
        .iter()
        .find(|(label, _)| label.eq_ignore_ascii_case(word))
        .map(|(_, bit)| *bit)
}

/// One snap candidate.
#[derive(Clone, Debug)]
pub struct Snap {
    pub point: Point,   // where it is
    pub kind: SnapKind, // what it is
    pub owner: u32,     // object row it belongs to
}

/// Add the ends, vertices and midpoints of a polyline.
pub fn from_polyline(points: &[Point], closed: bool, owner: u32, out: &mut Vec<Snap>) {
    if points.is_empty() {
        return;
    }

    let last = points.len() - 1;

    for (i, p) in points.iter().enumerate() {
        let interior = i != 0 && i != last;
        let kind = if closed || interior {
            SnapKind::Vertex
        } else {
            SnapKind::End
        };
        out.push(Snap {
            point: p.clone(),
            kind,
            owner,
        });
    }

    let spans = if closed { points.len() } else { last }; // segment count

    for i in 0..spans {
        let a = &points[i];
        let b = &points[(i + 1) % points.len()]; // % wraps the closing span back to point 0
        out.push(Snap {
            point: Point::new(
                (a[0] + b[0]) * 0.5,
                (a[1] + b[1]) * 0.5,
                (a[2] + b[2]) * 0.5,
            ),
            kind: SnapKind::Mid,
            owner,
        });
    }
}

/// The centre of a closed loop, when the points close.
pub fn from_loop(points: &[Point], owner: u32, out: &mut Vec<Snap>) {
    // a slice pattern: binds the first and last points, and fails for fewer than two
    let [first, .., last] = points else {
        return;
    };

    if points.len() < 4 || first.distance(last, None) > 1e-9 {
        return;
    }

    let corners = &points[..points.len() - 1]; // the repeated end counted once
    let count = corners.len() as f64;
    let sum = |i: usize| corners.iter().map(|p| p[i]).sum::<f64>() / count;
    out.push(Snap {
        point: Point::new(sum(0), sum(1), sum(2)),
        kind: SnapKind::Center,
        owner,
    });
}

/// The point of segment `a`-`b` nearest to `to`.
pub fn nearest_on_segment(a: &Point, b: &Point, to: &Point, owner: u32) -> Snap {
    let ab = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
    let ap = [to[0] - a[0], to[1] - a[1], to[2] - a[2]];
    let len2 = ab[0] * ab[0] + ab[1] * ab[1] + ab[2] * ab[2];
    // t = how far along a-b the foot of the perpendicular lies, clamped to 0..1 so it stays on the segment
    let t = if len2 > 0.0 {
        ((ap[0] * ab[0] + ap[1] * ab[1] + ap[2] * ab[2]) / len2).clamp(0.0, 1.0)
    } else {
        0.0
    };
    Snap {
        point: Point::new(a[0] + ab[0] * t, a[1] + ab[1] * t, a[2] + ab[2] * t),
        kind: SnapKind::Near,
        owner,
    }
}

/// The point of segment `a`-`b` nearest to the ray from `origin` along `direction`.
pub fn nearest_to_ray(a: &Point, b: &Point, origin: &Point, direction: &Vector) -> Point {
    let u = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
    let w = [a[0] - origin[0], a[1] - origin[1], a[2] - origin[2]];
    let d = [direction[0], direction[1], direction[2]];
    let dot = |p: [f64; 3], q: [f64; 3]| p[0] * q[0] + p[1] * q[1] + p[2] * q[2];
    let (uu, ud, dd) = (dot(u, u), dot(u, d), dot(d, d));
    let denominator = uu * dd - ud * ud; // closest points of two lines, the textbook formula
    // parallel: any point is as near, take the start
    let t = if denominator > 1e-12 * uu * dd {
        ((ud * dot(d, w) - dd * dot(u, w)) / denominator).clamp(0.0, 1.0)
    } else {
        0.0
    };
    Point::new(a[0] + u[0] * t, a[1] + u[1] * t, a[2] + u[2] * t)
}

/// The foot of the perpendicular from `from` onto segment `a`-`b`, if it falls inside.
pub fn perpendicular(a: &Point, b: &Point, from: &Point) -> Option<Point> {
    let u = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
    let length = u[0] * u[0] + u[1] * u[1] + u[2] * u[2];

    if length <= 1e-24 {
        return None;
    }

    let t = ((from[0] - a[0]) * u[0] + (from[1] - a[1]) * u[1] + (from[2] - a[2]) * u[2]) / length;
    (t > 1e-9 && t < 1.0 - 1e-9)
        .then(|| Point::new(a[0] + u[0] * t, a[1] + u[1] * t, a[2] + u[2] * t))
}

/// Near and Perp snaps on the wires under the cursor ray.
pub fn along_wires(
    wires: &[(Vec<Point>, u32)],
    ray: &(Point, Vector),
    from: Option<&Point>,
    modes: u8,
    out: &mut Vec<Snap>,
) {
    for (points, owner) in wires {
        for pair in points.windows(2) {
            // `&` keeps the bits both sides have: non-zero when Near is switched on
            if modes & NEAR != 0 {
                out.push(Snap {
                    point: nearest_to_ray(&pair[0], &pair[1], &ray.0, &ray.1),
                    kind: SnapKind::Near,
                    owner: *owner,
                });
            }

            // a let chain: the block runs only when the test holds and the `let` matches
            if modes & PERP != 0
                && let Some(foot) = from.and_then(|p| perpendicular(&pair[0], &pair[1], p))
            {
                out.push(Snap {
                    point: foot,
                    kind: SnapKind::Perp,
                    owner: *owner,
                });
            }
        }
    }
}

// A wire is a chain of points the pointer can snap anywhere along (Near) or square onto (Perp).
/// Snap points and wires of one placed object; `room` caps the edges a mesh or BRep adds as wires.
pub fn of_geometry(
    geometry: &Geometry,
    place: &Xform,
    owner: u32,
    room: usize,
    out: &mut Vec<Snap>,
    wires: &mut Vec<(Vec<Point>, u32)>,
) {
    match geometry {
        Geometry::Point(p) => out.push(Snap {
            point: p.transformed(place),
            kind: SnapKind::End,
            owner,
        }),
        Geometry::Line(line) => {
            let points = vec![
                line.start().transformed(place),
                line.end().transformed(place),
            ];
            from_polyline(&points, false, owner, out);
            wires.push((points, owner));
        }
        Geometry::Polyline(line) => {
            let points: Vec<_> = line
                .get_points()
                .iter()
                .map(|p| p.transformed(place))
                .collect();
            from_polyline(&points, false, owner, out);
            from_loop(&points, owner, out);
            wires.push((points, owner));
        }
        Geometry::NurbsCurve(curve) => {
            let (a, b) = curve.domain();
            for t in [a, b] {
                out.push(Snap {
                    point: curve.point_at(t).transformed(place),
                    kind: SnapKind::End,
                    owner,
                });
            }
            out.push(Snap {
                point: curve.point_at((a + b) * 0.5).transformed(place),
                kind: SnapKind::Mid,
                owner,
            });
            // a fine polyline stands in for the curve
            let (samples, _) = curve.divide_by_count(CURVE_SAMPLES, true);
            let points: Vec<_> = samples.iter().map(|p| p.transformed(place)).collect();
            from_loop(&points, owner, out);
            wires.push((points, owner));
        }
        Geometry::Mesh(_)
        | Geometry::BRep(_)
        | Geometry::NurbsSurface(_)
        | Geometry::Element(_) => {
            let controls = Controls::from_geometry(geometry);
            let points: Vec<_> = controls
                .points
                .iter()
                .map(|p| Point::new(p.position[0], p.position[1], p.position[2]).transformed(place))
                .collect();
            // edges are wires too, while there are not too many
            if controls.links.len() <= room {
                for [a, b] in &controls.links {
                    wires.push((vec![points[*a].clone(), points[*b].clone()], owner));
                }
            }
            out.extend(points.into_iter().map(|point| Snap {
                point,
                kind: SnapKind::Vertex,
                owner,
            }));
        }
        _ => {}
    }
}

/// Control points a mesh, BRep or surface offers, counted without collecting them.
pub fn control_count(geometry: &Geometry) -> usize {
    match geometry {
        Geometry::Mesh(mesh) => mesh.vertex.len(),
        Geometry::BRep(brep) => brep_control_count(brep),
        Geometry::NurbsSurface(surface) => surface.cv_count_total(),
        Geometry::Element(element) => match element.geometry() {
            session_rust::element::ElementGeometry::Mesh(mesh) => mesh.vertex.len(),
            session_rust::element::ElementGeometry::BRep(brep) => brep_control_count(brep),
            session_rust::element::ElementGeometry::None => 0,
        },
        _ => 0,
    }
}

/// Control points a BRep offers: vertices, then curve and surface nets.
fn brep_control_count(brep: &session_rust::BRep) -> usize {
    brep.m_vertices.len()
        + brep
            .m_curves_3d
            .iter()
            .map(NurbsCurve::cv_count)
            .sum::<usize>()
        + brep
            .m_surfaces
            .iter()
            .map(NurbsSurface::cv_count_total)
            .sum::<usize>()
}

/// The best candidate of an enabled mode within `aperture` pixels of the cursor.
pub fn best<F>(
    candidates: &[Snap],
    modes: u8,
    cursor: (f64, f64),
    aperture: f64,
    project: F,
) -> Option<Snap>
where
    F: Fn(&Point) -> Option<(f64, f64)>, // any function or closure from world point to pixels; tests pass a fake one
{
    best_in(candidates, modes, cursor, aperture, project)
}

/// The best candidate from any source of snaps, several lists joined without copying.
pub fn best_in<'a, I, F>(
    candidates: I,
    modes: u8,
    cursor: (f64, f64),
    aperture: f64,
    project: F,
) -> Option<Snap>
where
    I: IntoIterator<Item = &'a Snap>, // a slice, or two lists chained; `'a` says the snaps outlive this call
    F: Fn(&Point) -> Option<(f64, f64)>,
{
    let mut winner: Option<(SnapKind, f64, &Snap)> = None; // kind, pixel distance, the snap

    for c in candidates {
        if modes & c.kind.mode() == 0 {
            continue;
        }

        let Some((x, y)) = project(&c.point) else {
            continue;
        };
        let (dx, dy) = (x - cursor.0, y - cursor.1);
        let d = (dx * dx + dy * dy).sqrt();

        if d > aperture {
            continue;
        }

        // better kind first, then nearer
        let better = match winner {
            None => true,
            Some((kind, best_d, _)) => c.kind < kind || (c.kind == kind && d < best_d),
        };

        if better {
            winner = Some((c.kind, d, c));
        }
    }

    winner.map(|(_, _, c)| c.clone())
}

/// One view's world to pixel mapping, made once and used for many points.
#[derive(Clone, PartialEq)]
pub struct Screen {
    matrix: [f64; 16],    // view projection relative to `origin`, column major
    origin: [f64; 3],     // the point the matrix is anchored at
    pub size: (f64, f64), // viewport, pixels
}

impl Screen {
    /// The view `matrix`, anchored at `origin`, onto a `size` viewport.
    pub fn new(matrix: [f64; 16], origin: [f64; 3], size: (f64, f64)) -> Self {
        Self {
            matrix,
            origin,
            size,
        }
    }

    /// Clip coordinates of a world point.
    fn clip(&self, p: [f64; 3]) -> [f64; 4] {
        let v = [
            p[0] - self.origin[0],
            p[1] - self.origin[1],
            p[2] - self.origin[2],
        ];
        let m = &self.matrix;
        std::array::from_fn(|r| m[r] * v[0] + m[r + 4] * v[1] + m[r + 8] * v[2] + m[r + 12])
    }

    /// Clip coordinates to pixels: -1..1 becomes 0..width, and y flips because pixel rows count down.
    fn pixel(&self, clip: [f64; 4]) -> (f64, f64) {
        (
            (clip[0] / clip[3] * 0.5 + 0.5) * self.size.0,
            (0.5 - clip[1] / clip[3] * 0.5) * self.size.1,
        )
    }

    /// A world point in pixels, None behind the eye.
    pub fn point(&self, p: &Point) -> Option<(f64, f64)> {
        let clip = self.clip([p[0], p[1], p[2]]);
        (clip[3] > 0.0).then(|| self.pixel(clip)) // `bool::then`: true gives Some(value), false gives None
    }

    /// World coordinates in pixels, None behind the eye.
    pub fn xyz(&self, p: [f64; 3]) -> Option<(f64, f64)> {
        let clip = self.clip(p);
        (clip[3] > 0.0).then(|| self.pixel(clip))
    }

    /// A box as a circle in pixels, centre and radius; an endless radius when it reaches the eye.
    pub fn circle(&self, b: &AABB) -> Option<(f64, f64, f64)> {
        let m = &self.matrix;
        let clip = self.clip([b.cx, b.cy, b.cz]);
        let radius = (b.hx * b.hx + b.hy * b.hy + b.hz * b.hz).sqrt();
        // the nearest depth the box can have: clip w of its closest point
        let near = clip[3] - (m[3] * m[3] + m[7] * m[7] + m[11] * m[11]).sqrt() * radius;

        if !near.is_finite() {
            return None;
        }

        if near <= 1e-9 {
            return Some((self.size.0 * 0.5, self.size.1 * 0.5, f64::INFINITY));
        }

        let (x, y) = self.pixel(clip);
        let vertical = (m[1] * m[1] + m[5] * m[5] + m[9] * m[9]).sqrt(); // clip units per world unit
        Some((x, y, radius * vertical * 0.5 * self.size.1 / near))
    }

    /// The pixel box of a chain of points as a circle; an endless radius when one is behind the eye.
    pub fn footprint(&self, points: &[Point]) -> Option<(f64, f64, f64)> {
        let (mut low, mut high) = ([f64::INFINITY; 2], [f64::NEG_INFINITY; 2]);

        for p in points {
            let Some((x, y)) = self.point(p) else {
                return Some((self.size.0 * 0.5, self.size.1 * 0.5, f64::INFINITY));
            };
            low = [low[0].min(x), low[1].min(y)];
            high = [high[0].max(x), high[1].max(y)];
        }

        (low[0] <= high[0]).then(|| {
            let (width, height) = (high[0] - low[0], high[1] - low[1]);
            (
                low[0] + width * 0.5,
                low[1] + height * 0.5,
                width.hypot(height) * 0.5,
            )
        })
    }
}

// Bins are a grid of equal cells over the screen; a query reads the few cells around the pointer instead of every object.
/// Ids sorted into screen cells by where their circles land: rows filled a slice at a time, or any id put in.
pub struct Bins {
    cell: f64,            // cell size, pixels
    columns: usize,       // cells across
    lines: usize,         // cells down
    cells: Vec<Vec<u32>>, // the rows of each cell
    large: Vec<u32>,      // rows too large to bin, offered on every query
    next: u32,            // the first row not binned yet
}

impl Bins {
    /// Empty cells over a `size` pixel screen.
    pub fn new(size: (f64, f64), cell: f64) -> Self {
        let columns = (size.0 / cell).ceil().clamp(1.0, 4096.0) as usize;
        let lines = (size.1 / cell).ceil().clamp(1.0, 4096.0) as usize;
        Self {
            cell,
            columns,
            lines,
            cells: vec![Vec::new(); columns * lines],
            large: Vec::new(),
            next: 0,
        }
    }

    /// Bin up to `budget` more rows below `end`, where the last call stopped; `circle` puts a row on screen.
    pub fn fill<F>(&mut self, end: u32, budget: u32, mut circle: F)
    where
        F: FnMut(u32) -> Option<(f64, f64, f64)>,
    {
        let stop = self.next.saturating_add(budget).min(end); // saturating: stops at u32::MAX instead of overflowing

        for row in self.next..stop {
            if let Some((x, y, radius)) = circle(row) {
                self.insert(row, (x, y), radius);
            }
        }

        self.next = self.next.max(stop);
    }

    /// Put `id` in every cell its circle touches; one too large for that is offered on every query.
    pub fn insert(&mut self, id: u32, at: (f64, f64), radius: f64) {
        if radius > self.cell * LARGE_CELLS {
            self.large.push(id);
            return;
        }

        let Some([left, top, right, bottom]) = self.span(at, radius) else {
            return;
        };

        for line in top..=bottom {
            for column in left..=right {
                self.cells[line * self.columns + column].push(id);
            }
        }
    }

    /// Rows whose circles may come within `reach` of `at`, sorted, each once.
    pub fn near(&self, at: (f64, f64), reach: f64, out: &mut Vec<u32>) {
        out.clear();
        out.extend_from_slice(&self.large);

        if let Some([left, top, right, bottom]) = self.span(at, reach) {
            for line in top..=bottom {
                for column in left..=right {
                    out.extend_from_slice(&self.cells[line * self.columns + column]);
                }
            }
        }

        out.sort_unstable();
        out.dedup(); // drops repeats that sit side by side, hence the sort
    }

    /// The cells a circle touches: left, top, right, bottom; None when it misses the screen.
    fn span(&self, at: (f64, f64), radius: f64) -> Option<[usize; 4]> {
        let (left, right) = ((at.0 - radius) / self.cell, (at.0 + radius) / self.cell);
        let (top, bottom) = ((at.1 - radius) / self.cell, (at.1 + radius) / self.cell);

        // off screen, or NaN: every comparison with NaN is false, so the negated test catches it too
        if !(right >= 0.0 && bottom >= 0.0 && left < self.columns as f64 && top < self.lines as f64)
        {
            return None;
        }

        let clamp = |value: f64, count: usize| (value.max(0.0) as usize).min(count - 1);
        Some([
            clamp(left, self.columns),
            clamp(top, self.lines),
            clamp(right, self.columns),
            clamp(bottom, self.lines),
        ])
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A point on z = 0.
    fn p(x: f64, y: f64) -> Point {
        Point::new(x, y, 0.0)
    }

    /// x and y are screen pixels already.
    fn flat(point: &Point) -> Option<(f64, f64)> {
        Some((point[0], point[1]))
    }

    /// An open polyline: two ends, inner vertices, one midpoint per span.
    #[test]
    fn an_open_polyline_offers_ends_vertices_and_midpoints() {
        let mut out = Vec::new();
        from_polyline(
            &[p(0.0, 0.0), p(10.0, 0.0), p(10.0, 10.0)],
            false,
            7,
            &mut out,
        );
        let count = |k: SnapKind| out.iter().filter(|s| s.kind == k).count();
        assert_eq!(count(SnapKind::End), 2);
        assert_eq!(count(SnapKind::Vertex), 1);
        assert_eq!(count(SnapKind::Mid), 2);
        assert!(out.iter().all(|s| s.owner == 7));
    }

    /// A closed loop has no ends.
    #[test]
    fn a_closed_loop_has_no_ends() {
        let mut out = Vec::new();
        from_polyline(
            &[p(0.0, 0.0), p(10.0, 0.0), p(10.0, 10.0)],
            true,
            0,
            &mut out,
        );
        assert_eq!(out.iter().filter(|s| s.kind == SnapKind::End).count(), 0);
        assert_eq!(out.iter().filter(|s| s.kind == SnapKind::Vertex).count(), 3);
        assert_eq!(out.iter().filter(|s| s.kind == SnapKind::Mid).count(), 3);
    }

    /// A farther end beats a nearer near-point.
    #[test]
    fn kind_wins_before_distance() {
        let candidates = vec![
            Snap {
                point: p(2.0, 0.0),
                kind: SnapKind::Near,
                owner: 0,
            },
            Snap {
                point: p(6.0, 0.0),
                kind: SnapKind::End,
                owner: 0,
            },
        ];
        let best = best(&candidates, DEFAULT, (0.0, 0.0), 12.0, flat).expect("a snap");
        assert_eq!(best.kind, SnapKind::End);
    }

    /// Within one kind, the nearest wins.
    #[test]
    fn distance_decides_within_a_kind() {
        let candidates = vec![
            Snap {
                point: p(9.0, 0.0),
                kind: SnapKind::End,
                owner: 1,
            },
            Snap {
                point: p(3.0, 0.0),
                kind: SnapKind::End,
                owner: 2,
            },
        ];
        assert_eq!(
            best(&candidates, DEFAULT, (0.0, 0.0), 12.0, flat)
                .unwrap()
                .owner,
            2
        );
    }

    /// Too far or not visible: no snap.
    #[test]
    fn out_of_reach_and_out_of_sight_do_not_snap() {
        let candidates = vec![Snap {
            point: p(40.0, 0.0),
            kind: SnapKind::End,
            owner: 0,
        }];
        assert!(
            best(&candidates, DEFAULT, (0.0, 0.0), 12.0, flat).is_none(),
            "too far"
        );
        let near = vec![Snap {
            point: p(1.0, 0.0),
            kind: SnapKind::End,
            owner: 0,
        }];
        assert!(
            best(&near, DEFAULT, (0.0, 0.0), 12.0, |_| None).is_none(),
            "not visible"
        );
    }

    /// The nearest point stays on the segment.
    #[test]
    fn nearest_on_a_segment_stays_on_the_segment() {
        let (a, b) = (p(0.0, 0.0), p(10.0, 0.0));
        let middle = nearest_on_segment(&a, &b, &p(4.0, 5.0), 0);
        assert!((middle.point[0] - 4.0).abs() < 1e-12 && middle.point[1].abs() < 1e-12);
        let past = nearest_on_segment(&a, &b, &p(50.0, 5.0), 0);
        assert!((past.point[0] - 10.0).abs() < 1e-12);
        let before = nearest_on_segment(&a, &b, &p(-50.0, 5.0), 0);
        assert!(before.point[0].abs() < 1e-12);
    }

    /// A mode switched off never snaps.
    #[test]
    fn a_mode_switched_off_is_skipped() {
        let candidates = vec![Snap {
            point: p(1.0, 0.0),
            kind: SnapKind::Vertex,
            owner: 0,
        }];
        assert!(best(&candidates, END, (0.0, 0.0), 12.0, flat).is_some());
        assert!(best(&candidates, NEAR | MID, (0.0, 0.0), 12.0, flat).is_none());
        assert_eq!(mode("near"), Some(NEAR));
        assert_eq!(mode("perp"), Some(PERP));
        assert_eq!(mode("sideways"), None);
    }

    /// The ray over a segment finds the point under it.
    #[test]
    fn nearest_to_a_ray_lands_under_the_cursor() {
        let (a, b) = (p(0.0, 0.0), p(10.0, 0.0));
        let down = Vector::new(0.0, 0.0, -1.0);
        let hit = nearest_to_ray(&a, &b, &Point::new(3.0, 2.0, 5.0), &down);
        assert!((hit[0] - 3.0).abs() < 1e-12 && hit[1].abs() < 1e-12);
        let past = nearest_to_ray(&a, &b, &Point::new(30.0, 2.0, 5.0), &down);
        assert!((past[0] - 10.0).abs() < 1e-12);
        let along = nearest_to_ray(
            &a,
            &b,
            &Point::new(-5.0, 0.0, 0.0),
            &Vector::new(1.0, 0.0, 0.0),
        );
        assert!(along[0].abs() < 1e-12, "a parallel ray takes the start");
    }

    /// The perpendicular foot exists only inside the segment.
    #[test]
    fn a_perpendicular_foot_stays_inside() {
        let (a, b) = (p(0.0, 0.0), p(10.0, 0.0));
        let foot = perpendicular(&a, &b, &p(4.0, 7.0)).expect("inside");
        assert!((foot[0] - 4.0).abs() < 1e-12 && foot[1].abs() < 1e-12);
        assert!(perpendicular(&a, &b, &p(12.0, 7.0)).is_none());
        assert!(perpendicular(&a, &a, &p(1.0, 1.0)).is_none());
    }

    /// A closed loop offers its centre; an open chain does not.
    #[test]
    fn a_closed_loop_offers_its_center() {
        let square = [
            p(0.0, 0.0),
            p(4.0, 0.0),
            p(4.0, 4.0),
            p(0.0, 4.0),
            p(0.0, 0.0),
        ];
        let mut out = Vec::new();
        from_loop(&square, 3, &mut out);
        assert_eq!(out.len(), 1);
        assert_eq!(out[0].kind, SnapKind::Center);
        assert!((out[0].point[0] - 2.0).abs() < 1e-12 && (out[0].point[1] - 2.0).abs() < 1e-12);
        from_loop(&square[..4], 3, &mut out);
        assert_eq!(out.len(), 1, "open chains have no centre");
    }

    /// Kind wins across lists, then distance; an empty list or a switched-off mode offers nothing.
    #[test]
    fn best_in_ranks_across_lists() {
        let snap = |x, kind, owner| Snap {
            point: p(x, 0.0),
            kind,
            owner,
        };
        let first = vec![snap(1.0, SnapKind::Near, 1), snap(8.0, SnapKind::Mid, 2)];
        let second = vec![snap(6.0, SnapKind::End, 3), snap(3.0, SnapKind::Mid, 4)];
        let best = |lists: &[&[Snap]], modes| {
            let joined = lists.iter().flat_map(|list| list.iter());
            best_in(joined, modes, (0.0, 0.0), 12.0, flat).map(|s| s.owner)
        };
        assert_eq!(
            best(&[&first[..], &second[..]], DEFAULT),
            Some(3),
            "an End beats a nearer Near"
        );
        assert_eq!(
            best(&[&first[..], &second[..]], MID),
            Some(4),
            "Mid only: the nearest Mid of both"
        );
        assert_eq!(best(&[&first[..], &[]], END), None, "no End anywhere");
        assert_eq!(best(&[], DEFAULT), None, "nothing to rank");
    }

    /// An identity view makes clip space the world: pixels follow from x and y.
    #[test]
    fn a_screen_puts_points_and_boxes_in_pixels() {
        let mut matrix = [0.0; 16];

        for i in [0, 5, 10, 15] {
            matrix[i] = 1.0;
        }

        let screen = Screen::new(matrix, [0.0; 3], (200.0, 100.0));
        assert_eq!(screen.point(&p(0.0, 0.0)), Some((100.0, 50.0)));
        assert_eq!(screen.point(&p(1.0, 1.0)), Some((200.0, 0.0)));
        let small = AABB {
            cx: 0.0,
            cy: 0.0,
            cz: 0.0,
            hx: 0.1,
            hy: 0.0,
            hz: 0.0,
        };
        let (x, y, radius) = screen.circle(&small).expect("on screen");
        assert_eq!((x, y), (100.0, 50.0));
        assert!((radius - 5.0).abs() < 1e-12, "a tenth of the half height");
        let (x, y, radius) = screen
            .footprint(&[p(0.0, 0.0), p(1.0, 1.0)])
            .expect("a wire");
        assert_eq!((x, y), (150.0, 25.0));
        assert!((radius - 100.0_f64.hypot(50.0) * 0.5).abs() < 1e-12);
        assert_eq!(screen.footprint(&[]), None);

        // w is the distance in front of the eye, down -z
        matrix[15] = 0.0;
        matrix[11] = -1.0;
        let eye = Screen::new(matrix, [0.0; 3], (200.0, 100.0));
        let around = AABB {
            cz: -0.5,
            hx: 1.0,
            ..small
        };
        assert_eq!(
            eye.circle(&around).map(|c| c.2),
            Some(f64::INFINITY),
            "a box around the eye is everywhere"
        );
        assert_eq!(
            eye.point(&Point::new(0.0, 0.0, 1.0)),
            None,
            "behind the eye"
        );
        let behind = eye.footprint(&[Point::new(0.0, 0.0, -1.0), Point::new(0.0, 0.0, 1.0)]);
        assert_eq!(
            behind.map(|c| c.2),
            Some(f64::INFINITY),
            "a wire reaching behind the eye"
        );
    }

    /// Rows land in the cells their circles cover; a huge one is always offered, one off screen never.
    #[test]
    fn bins_offer_the_rows_near_a_point() {
        let circles = [
            (15.0, 15.0, 2.0),
            (150.0, 80.0, 3.0),
            (100.0, 50.0, 500.0),
            (-50.0, 20.0, 5.0),
        ];
        let mut bins = Bins::new((200.0, 100.0), 10.0);
        let mut out = Vec::new();
        bins.fill(4, 2, |row| Some(circles[row as usize]));
        bins.near((150.0, 80.0), 4.0, &mut out);
        assert_eq!(out, [1]);
        // the next slice goes on where the first stopped
        bins.fill(4, 2, |row| Some(circles[row as usize]));
        bins.near((15.0, 15.0), 4.0, &mut out);
        assert_eq!(out, [0, 2]);
        bins.near((190.0, 10.0), 4.0, &mut out);
        assert_eq!(out, [2]);
        bins.near((f64::NAN, 10.0), 4.0, &mut out);
        assert_eq!(out, [2]);
        // any id can go in by hand, a point included
        bins.insert(9, (190.0, 10.0), 0.0);
        bins.near((188.0, 12.0), 4.0, &mut out);
        assert_eq!(out, [2, 9]);
    }

    /// A placed line offers its moved ends and middle, and itself as a wire.
    #[test]
    fn a_placed_line_offers_ends_middle_and_a_wire() {
        let line = Geometry::Line(session_rust::Line::new(0.0, 0.0, 0.0, 10.0, 0.0, 0.0).into());
        let (mut out, mut wires) = (Vec::new(), Vec::new());
        of_geometry(
            &line,
            &Xform::translation(0.0, 5.0, 0.0),
            9,
            0,
            &mut out,
            &mut wires,
        );
        let found: Vec<_> = out
            .iter()
            .map(|s| (s.kind, s.point[0], s.point[1], s.owner))
            .collect();
        assert_eq!(
            found,
            [
                (SnapKind::End, 0.0, 5.0, 9),
                (SnapKind::End, 10.0, 5.0, 9),
                (SnapKind::Mid, 5.0, 5.0, 9)
            ]
        );
        assert_eq!(wires.len(), 1);
        assert_eq!(control_count(&line), 0, "no mesh or surface controls");
    }
}

use crate::engine::gpu::patch::Span;
use crate::engine::gpu::segments::SegRows;
use crate::engine::gpu::{CylinderSegment, Upload};
use session_rust::AABB;
use session_rust::{Geometry, NurbsSurface, RenderVertex};
use std::collections::HashMap;

pub use crate::engine::gpu::arena::Sample; // `pub use` re-exports it: callers name it from this module

// Each surface vertex keeps its (u, v) parameter, so after a control point moves the surface is evaluated again there.
/// Enough of a surface upload to re-evaluate it after a control moves.
pub struct SurfacePreview {
    samples: Vec<Sample>,              // uv of every vertex
    vertices: Vec<RenderVertex>,       // vertices as uploaded
    controls: Vec<Vec<f64>>,           // control points at capture, per surface
    pipes: Vec<CylinderSegment>,       // edge pipes as uploaded
    pipe_vertices: Vec<[usize; 2]>,    // vertex index at each pipe end
    pipe_normals: Vec<[usize; 2]>,     // vertex whose normal each pipe side uses
    chains: Vec<std::ops::Range<u32>>, // joined pipe runs
}

impl SurfacePreview {
    /// Remember the upload of one surface or BRep.
    pub(crate) fn capture(
        up: &Upload,
        span: Span,
        local: crate::engine::gpu::patch::Counts,
        geometry: &Geometry,
    ) -> Option<Self> {
        if span.count.verts == 0
            || span.count.ribbons != 0
            || span.count.spheres != 0
            || span.count.dots != 0
        {
            return None; // not a surface upload
        }

        let first = local.verts as usize; // first vertex in the upload
        let end = first + span.count.verts as usize;
        let samples: Vec<_> = up
            .arena
            .surface_samples
            .iter()
            .filter(|sample| (first..end).contains(&(sample.index as usize)))
            .copied()
            .collect();

        if samples.len() != span.count.verts as usize {
            return None; // a vertex without uv
        }

        // vertices at each position
        let mut positions = HashMap::<[u32; 3], Vec<usize>>::new(); // `::<..>` names the key and value types

        for (i, vertex) in up.arena.verts[first..end].iter().enumerate() {
            positions
                .entry(vertex.position.map(f32::to_bits))
                .or_default()
                .push(i);
        }

        let start_pipe = local.pipes as usize;
        let end_pipe = start_pipe + span.count.pipes as usize;
        let pipes = up.seg.pipes[start_pipe..end_pipe].to_vec();
        // pipe ends by vertex index, not by position
        let boundary: HashMap<_, _> = up.arena.surface_boundaries.iter().copied().collect();
        let pipe_vertices = (start_pipe..end_pipe)
            .map(|pipe| {
                let ends = boundary.get(&(pipe as u32))?;
                Some([ends[0] as usize - first, ends[1] as usize - first])
            })
            .collect::<Option<Vec<_>>>()?;
        // a vertex on each side of the pipe, for its normals
        let pipe_normals = pipes
            .iter()
            .map(|p| {
                let candidates = positions.get(&p.p0.map(f32::to_bits))?;
                let first = *candidates.first()?;
                let other = candidates
                    .iter()
                    .copied()
                    .find(|&i| samples[i].surface != samples[first].surface)
                    .unwrap_or(first);
                Some([first, other])
            })
            .collect::<Option<Vec<_>>>()?;
        let chains = up
            .seg
            .pipe_chains
            .iter()
            .filter(|r| r.start >= local.pipes && r.end <= local.pipes + span.count.pipes)
            .map(|r| r.start - local.pipes..r.end - local.pipes)
            .collect();
        Some(Self {
            samples,
            vertices: up.arena.verts[first..end].to_vec(),
            controls: surfaces(geometry)?.iter().map(|s| s.m_cv.clone()).collect(),
            pipes,
            pipe_vertices,
            pipe_normals,
            chains,
        })
    }

    /// Re-evaluate the vertices and pipes for the edited geometry.
    pub fn evaluate(&self, geometry: &Geometry) -> Option<(Vec<RenderVertex>, SegRows, AABB)> {
        let surfaces = surfaces(geometry)?;
        // surfaces whose controls moved
        let changed: Vec<_> = surfaces
            .iter()
            .enumerate()
            .map(|(i, s)| self.controls.get(i) != Some(&s.m_cv))
            .collect();
        let mut bounds = AABB::empty();
        let mut vertices = Vec::with_capacity(self.samples.len());

        for (sample, baseline) in self.samples.iter().zip(&self.vertices) {
            let surface = surfaces.get(sample.surface as usize)?;

            // unchanged surface: keep the vertex
            if !changed[sample.surface as usize] {
                bounds.union_with_point(
                    baseline.position[0] as f64,
                    baseline.position[1] as f64,
                    baseline.position[2] as f64,
                );
                vertices.push(*baseline);
                continue;
            }

            let point = surface.point_at(sample.uv[0], sample.uv[1])?;
            let normal = surface.normal_at(sample.uv[0], sample.uv[1]);
            let position = point.to_f32();

            if position.iter().any(|p| !p.is_finite()) {
                return None;
            }

            bounds.union_with_point(position[0] as f64, position[1] as f64, position[2] as f64);
            vertices.push(RenderVertex {
                position,
                normal: [
                    normal[0] as f32 * sample.sign, // -1 on a reversed face
                    normal[1] as f32 * sample.sign,
                    normal[2] as f32 * sample.sign,
                ],
                color: baseline.color,
            });
        }

        let mut segments = SegRows {
            pipe_chains: self.chains.clone(),
            ..Default::default()
        };

        for ((pipe, ends), normals) in self
            .pipes
            .iter()
            .zip(&self.pipe_vertices)
            .zip(&self.pipe_normals)
        {
            let mut pipe = *pipe;
            pipe.p0 = vertices[ends[0]].position;
            pipe.p1 = vertices[ends[1]].position;
            let a = vertices[normals[0]].normal.map(f64::from);
            let b = vertices[normals[1]].normal.map(f64::from);
            if pipe.facing != super::walk::encode::FACING_UNKNOWN {
                pipe.facing = super::walk::encode::pack_facing(Some(&a), Some(&b));
            }
            segments.pipes.push(pipe);
        }

        Some((vertices, segments, bounds))
    }

    /// Memory held by the preview.
    pub fn allocated_bytes(&self) -> usize {
        self.samples.capacity() * std::mem::size_of::<Sample>()
            + self.vertices.capacity() * std::mem::size_of::<RenderVertex>()
            + self.controls.capacity() * std::mem::size_of::<Vec<f64>>()
            + self
                .controls
                .iter()
                .map(|v| v.capacity() * 8)
                .sum::<usize>()
            + self.pipes.capacity() * std::mem::size_of::<CylinderSegment>()
            + (self.pipe_vertices.capacity() + self.pipe_normals.capacity())
                * std::mem::size_of::<[usize; 2]>()
            + self.chains.capacity() * std::mem::size_of::<std::ops::Range<u32>>()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::app::deform::{self, Target};
    use crate::app::walk::{Walk, WalkCx, walk_geometry};
    use crate::engine::gpu::patch::Counts;
    use session_rust::{BRep, Xform};
    use std::rc::Rc;

    /// Vertices at one point keep their own uv when pulled apart.
    #[test]
    fn coincident_boundary_samples_keep_their_own_uv_after_edit() {
        let mut surface = BRep::create_box(40.0, 30.0, 25.0).m_surfaces[0].clone();
        // collapse one edge to a point, then open it
        let pole = surface.get_cv(0, 0).unwrap();
        surface.set_cv(0, 1, &pole);
        let source = Geometry::NurbsSurface(Rc::new(surface.clone()));
        let mut upload = Upload::default();
        walk_geometry(
            &mut Walk::of(&mut upload),
            &WalkCx {
                vert_base: 0,
                cloud_px: 0.0,
                row: 0,
                attributes: false,
            },
            &source,
        );
        let span = Span {
            start: Counts::default(),
            count: Counts::of(&upload),
        };
        let preview = SurfacePreview::capture(&upload, span, Counts::default(), &source).unwrap();
        surface.set_cv(
            0,
            1,
            &session_rust::Point::new(pole[0], pole[1], pole[2] + 12.0),
        );
        let (_, pipes, _) = preview
            .evaluate(&Geometry::NurbsSurface(Rc::new(surface)))
            .unwrap();
        let first_boundary = &upload.seg.pipe_chains[0];
        assert!(
            pipes.pipes[first_boundary.start as usize..first_boundary.end as usize]
                .iter()
                .all(|p| p.p0 != p.p1),
            "each formerly coincident endpoint must follow its own parameter"
        );
        for pair in
            pipes.pipes[first_boundary.start as usize..first_boundary.end as usize].windows(2)
        {
            assert_eq!(pair[0].p1, pair[1].p0);
        }
    }

    /// A surface preview keeps its four edges joined.
    #[test]
    fn standalone_surface_preview_keeps_connectivity_and_only_four_boundary_ids() {
        let box_ = BRep::create_box(40.0, 30.0, 25.0);
        let source = Geometry::NurbsSurface(Rc::new(box_.m_surfaces[0].clone()));
        let mut upload = Upload::default();
        walk_geometry(
            &mut Walk::of(&mut upload),
            &WalkCx {
                vert_base: 0,
                cloud_px: 0.0,
                row: 0,
                attributes: false,
            },
            &source,
        );
        let span = Span {
            start: Counts::default(),
            count: Counts::of(&upload),
        };
        let preview = SurfacePreview::capture(&upload, span, Counts::default(), &source)
            .expect("every grid vertex retains its UV");
        assert!(upload.seg.pipe_ids.iter().all(|id| *id < 4));
        assert_eq!(upload.seg.pipe_chains.len(), 4);
        for edge in 0..4 {
            let changed = deform::transform(
                &source,
                Target::Edge(edge),
                &Xform::translation(0.0, 0.0, 7.0),
            )
            .unwrap();
            let (vertices, pipes, _) = preview.evaluate(&changed).unwrap();
            assert_eq!(vertices.len(), upload.arena.verts.len());
            assert_eq!(pipes.pipes.len(), upload.seg.pipes.len());
            assert!(
                vertices
                    .iter()
                    .zip(&upload.arena.verts)
                    .any(|(a, b)| a.position != b.position)
            );
            for pipe in pipes.pipes {
                assert_eq!(pipe.facing, super::super::walk::encode::FACING_UNKNOWN);
                assert!(vertices.iter().any(|v| v.position == pipe.p0));
                assert!(vertices.iter().any(|v| v.position == pipe.p1));
            }
        }
    }

    /// A box preview moves with a face and restores on cancel.
    #[test]
    fn joined_shell_preview_moves_source_samples_and_cancel_restores_them() {
        let source = Geometry::BRep(Rc::new(BRep::create_box(10.0, 10.0, 10.0)));
        let mut upload = Upload::default();
        let cx = WalkCx {
            vert_base: 0,
            cloud_px: 0.0,
            row: 3,
            attributes: false,
        };
        walk_geometry(&mut Walk::of(&mut upload), &cx, &source);
        let span = Span {
            start: Counts::default(),
            count: Counts::of(&upload),
        };
        let preview = SurfacePreview::capture(&upload, span, Counts::default(), &source)
            .expect("joined box has parameter provenance");
        let (before, _, _) = preview.evaluate(&source).unwrap();
        assert_eq!(before.len(), upload.arena.verts.len());

        for (a, b) in before.iter().zip(&upload.arena.verts) {
            assert_eq!(
                a.position, b.position,
                "initial sample is the drawn source position"
            );
        }

        let changed =
            deform::transform(&source, Target::Face(0), &Xform::translation(0.0, 0.0, 2.0))
                .unwrap();
        let Geometry::BRep(brep) = &changed else {
            unreachable!()
        };
        assert!(brep.is_solid(), "source shell remains joined");
        let (after, pipes, _) = preview.evaluate(&changed).unwrap();
        assert!(
            before
                .iter()
                .zip(&after)
                .any(|(a, b)| a.position != b.position)
        );
        assert!(
            before
                .iter()
                .zip(&after)
                .any(|(a, b)| a.position == b.position)
        );

        for pipe in pipes.pipes {
            assert!(after.iter().any(|v| v.position == pipe.p0));
            assert!(after.iter().any(|v| v.position == pipe.p1));
        }

        let (cancelled, _, _) = preview.evaluate(&source).unwrap();

        for (a, b) in before.iter().zip(&cancelled) {
            assert_eq!(a.position, b.position);
        }
    }
}

// A helper may follow the tests: order inside a Rust file does not matter.
/// The surfaces inside a geometry.
fn surfaces(geometry: &Geometry) -> Option<&[NurbsSurface]> {
    match geometry {
        Geometry::BRep(b) => Some(&b.m_surfaces),
        Geometry::NurbsSurface(s) => Some(std::slice::from_ref(s)),
        Geometry::Element(e) => match e.geometry() {
            session_rust::element::ElementGeometry::BRep(b) => Some(&b.m_surfaces),
            _ => None,
        },
        _ => None,
    }
}

use super::tests::view;

#[cfg(not(target_arch = "wasm32"))]
mod gpu {
    use super::view;
    use crate::app::clipping::{Mode, clip_plane, plane_from};
    use crate::app::scene::{FileDoc, Scene};
    use crate::engine::gpu::clip::ClipPlane;
    use crate::engine::gpu::{FrameInput, Gpu, Instance};
    use session_rust::{Color, Mesh, Point, Session, Xform};
    use std::rc::Rc;

    /// Canvas side, px.
    const SIZE: usize = 256;

    /// Face colors as the canvas stores them.
    const GREY: [u8; 3] = [188, 188, 188];
    const RED: [u8; 3] = [255, 0, 0];
    const BLUE: [u8; 3] = [0, 0, 255];
    const YELLOW: [u8; 3] = [255, 255, 0];

    /// A box from `lo` to `hi` in one color, faces outward; `top` false leaves its top open.
    fn block(lo: [f64; 3], hi: [f64; 3], color: Color, top: bool) -> Mesh {
        // corners as Mesh::create_box orders them: bottom then top, counterclockwise
        let corners = (0..8)
            .map(|i: usize| {
                let x = if i % 4 == 1 || i % 4 == 2 {
                    hi[0]
                } else {
                    lo[0]
                };
                let y = if i % 4 >= 2 { hi[1] } else { lo[1] };
                let z = if i >= 4 { hi[2] } else { lo[2] };
                Point::new(x, y, z)
            })
            .collect();
        let mut faces = vec![
            vec![0, 3, 2, 1],
            vec![0, 1, 5, 4],
            vec![2, 3, 7, 6],
            vec![0, 4, 7, 3],
            vec![1, 2, 6, 5],
        ];

        if top {
            faces.push(vec![4, 5, 6, 7]);
        }

        let mut mesh = Mesh::from_vertices_and_faces(corners, faces);
        mesh.set_objectcolor(color);
        mesh
    }

    /// The meshes as one document on a headless GPU, flat faces, no edges; None without an adapter.
    fn solids(meshes: Vec<Mesh>) -> Option<(Gpu, Scene)> {
        crate::app::clipping::verify_solids();
        let mut gpu = pollster::block_on(Gpu::new_headless(SIZE as u32, SIZE as u32)).ok()?;
        gpu.pass_mut::<super::super::Clip>().fill = 0; // existing hatch regressions explicitly choose Hatch
        gpu.view.show_grid = false;
        gpu.view.show_mesh_edges = false;
        gpu.view.show_points = false;
        gpu.view.lit = false;
        let mut session = Session::new("solids");

        for mesh in meshes {
            session.add_mesh(mesh, None);
        }

        let mut scene = Scene::new();
        scene.add_file(FileDoc {
            name: "solids".into(),
            session: Rc::new(session),
            place: Xform::identity(),
            point_px: 0.0,
            display_only: false,
        });
        scene.upload_to(&mut gpu);
        Some((gpu, scene))
    }

    /// Cut with `planes` and find the solids they cross, as a frame of the viewer does.
    fn cut(gpu: &mut Gpu, scene: &Scene, planes: &[ClipPlane]) {
        gpu.set_clip_planes(planes);
        gpu.find_solids(|row| scene.solid_faces(row));
    }

    /// The world XY plane through height `z`, everything above cut away.
    fn cut_above(z: f64) -> ClipPlane {
        let plane = plane_from(Mode::Xy, &[[0.0, 0.0, z]], 200.0).unwrap();
        clip_plane(&plane, &Xform::identity()).unwrap()
    }

    /// The frame seen from `eye` toward `target`, and a scene point's pixel in it.
    fn frame(
        gpu: &mut Gpu,
        eye: [f64; 3],
        target: [f64; 3],
        perspective: bool,
    ) -> (FrameInput, impl Fn([f64; 3]) -> (usize, usize) + use<>) {
        let d: f64 = (0..3)
            .map(|i| (target[i] - eye[i]).powi(2))
            .sum::<f64>()
            .sqrt();
        let rebase = gpu.rebase_anchor(&Point::new(target[0], target[1], target[2]), d, 0.0);
        let anchor = [rebase.anchor[0], rebase.anchor[1], rebase.anchor[2]];
        let view_proj = view(eye, target, anchor, perspective);
        let map = view_proj.clone();
        let pixel = move |p: [f64; 3]| {
            let q = map.transform_point(&Point::new(
                p[0] - anchor[0],
                p[1] - anchor[1],
                p[2] - anchor[2],
            ));
            (
                ((q[0] * 0.5 + 0.5) * SIZE as f64) as usize,
                ((0.5 - q[1] * 0.5) * SIZE as f64) as usize,
            )
        };
        let input = FrameInput {
            view_proj,
            clear: wgpu::Color {
                r: 0.2,
                g: 0.2,
                b: 0.2,
                a: 1.0,
            },
            now_ms: 0.0,
        };
        (input, pixel)
    }

    /// Shares of hatch ink, cap paper and `color` among the pixels within `r` px of `at`.
    fn patch(rgba: &[u8], at: (usize, usize), r: usize, color: [u8; 3]) -> [f64; 3] {
        let mut counts = [0.0; 3];
        let mut total = 0.0_f64;

        for y in at.1.saturating_sub(r)..(at.1 + r + 1).min(SIZE) {
            for x in at.0.saturating_sub(r)..(at.0 + r + 1).min(SIZE) {
                let p = &rgba[(y * SIZE + x) * 4..][..3];
                let luma = p.iter().map(|c| u32::from(*c)).sum::<u32>() / 3;
                let grey = p.iter().max().unwrap() - p.iter().min().unwrap() < 30;
                total += 1.0;
                // sRGB: a line pixel of 0.75 coverage reads 137
                counts[0] += f64::from(u8::from(grey && luma < 170));
                counts[1] += f64::from(u8::from(p.iter().all(|c| *c > 225)));
                counts[2] += f64::from(u8::from(
                    (0..3).all(|k| (i32::from(p[k]) - i32::from(color[k])).abs() < 30),
                ));
            }
        }

        counts.map(|count| count / total.max(1.0))
    }

    /// True for black lines on white paper.
    fn hatched(shares: [f64; 3]) -> bool {
        shares[0] > 0.04 && shares[0] < 0.6 && shares[1] > 0.3
    }

    /// Every sample count and projection, with the frame drawn from `eye` toward `target`.
    fn each_view(
        gpu: &mut Gpu,
        eye: [f64; 3],
        target: [f64; 3],
        projections: &[bool],
        check: impl Fn(&[u8], &dyn Fn([f64; 3]) -> (usize, usize), &str),
    ) {
        for samples in [1, 4] {
            gpu.view.msaa_forced = Some(samples);
            gpu.resize(SIZE as u32, SIZE as u32);

            for &perspective in projections {
                let (input, pixel) = frame(gpu, eye, target, perspective);
                let rgba = gpu.render_offscreen(&input);
                let label = format!("{samples}x, perspective {perspective}");
                check(&rgba, &pixel, &label);
            }
        }
    }

    #[test]
    #[ignore = "requires a native GPU adapter"]
    fn sections_default_to_light_grey_with_black_boundaries() {
        let (mut gpu, scene) = solids(vec![block([-50.0; 3], [50.0; 3], Color::blue(), true)])
            .expect("native GPU");
        gpu.pass_mut::<super::super::Clip>().fill = super::super::Clip::new(gpu.target()).fill;
        assert_eq!(gpu.pass::<super::super::Clip>().fill, 1);
        cut(&mut gpu, &scene, &[cut_above(0.0)]);
        for samples in [1, 4] {
            gpu.view.msaa_forced = Some(samples);
            gpu.resize(SIZE as u32, SIZE as u32);
            for dpr in [1.0, 2.0] {
                gpu.logical_size = [SIZE as f64 / dpr; 2];
                for perspective in [false, true] {
                    let (input, pixel) =
                        frame(&mut gpu, [0.0, 0.0, 250.0], [0.0; 3], perspective);
                    let rgba = gpu.render_offscreen(&input);
                    let center = pixel([0.0; 3]);
                    for y in center.1 - 8..=center.1 + 8 {
                        for x in center.0 - 8..=center.0 + 8 {
                            let rgb = &rgba[(y * SIZE + x) * 4..][..3];
                            assert!(
                                rgb.iter().all(|v| (202..=204).contains(v)),
                                "solid light grey, without hatch: {rgb:?}"
                            );
                        }
                    }
                    for edge in [
                        [-50.0, 0.0, 0.0],
                        [50.0, 0.0, 0.0],
                        [0.0, -50.0, 0.0],
                        [0.0, 50.0, 0.0],
                    ] {
                        let at = pixel(edge);
                        let black = (at.1 - 4..=at.1 + 4)
                            .flat_map(|y| {
                                (at.0 - 4..=at.0 + 4).map(move |x| (y * SIZE + x) * 4)
                            })
                            .filter(|at| rgba[*at..*at + 3].iter().all(|v| *v < 16))
                            .count();
                        assert!(
                            black >= 5,
                            "black cut edge: {edge:?}, {samples}x, DPR {dpr}, perspective {perspective}"
                        );
                    }
                    let ids = gpu.render_ids_offscreen(&input);
                    assert_eq!(
                        ids[center.1 * SIZE + center.0][0],
                        1,
                        "the cap still picks its solid"
                    );
                }
            }
        }
    }

    #[test]
    #[ignore = "requires a native GPU adapter"]
    /// A cut cube seen from the cut side: hatch on the section, the kept top face stays plain,
    /// and the removed half shows the section behind it.
    fn a_cut_cube_caps_its_section_and_nothing_else() {
        let Some((mut gpu, scene)) =
            solids(vec![block([0.0; 3], [100.0; 3], Color::grey(), true)])
        else {
            return;
        };
        assert_ne!(gpu.objects.row(0).unwrap().flags & Instance::FLAG_CLOSED, 0);
