        cut(
            &mut gpu,
            &scene,
            &[clip_plane(&plane.unwrap(), &Xform::identity()).unwrap()],
        );
        each_view(
            &mut gpu,
            [-200.0, 50.0, 300.0],
            [50.0, 50.0, 50.0],
            &[true, false],
            |rgba, pixel, label| {
                let cap = patch(rgba, pixel([50.0, 50.0, 50.0]), 8, GREY);
                assert!(hatched(cap), "{label}: the section is hatched: {cap:?}");
                let top = patch(rgba, pixel([75.0, 50.0, 100.0]), 4, GREY);
                assert!(
                    top[2] > 0.95,
