        ];
        // the top, +x and bottom faces, each seen from the side its plane cuts away
        let cases = [
            (
                plane_from(Mode::Xy, &[[0.0, 0.0, hi[2]]], 300.0),
                [mid[0], mid[1], hi[2]],
                [mid[0] - 150.0, mid[1] - 200.0, hi[2] + 250.0],
            ),
            (
                plane_from(Mode::Yz, &[[hi[0], 0.0, 0.0]], 300.0),
                [hi[0], mid[1], mid[2]],
