use crate::State;
use crate::app::scene::Hydrated;

/// What waits for released documents to come back.
pub(crate) enum Resume {
    Controls(u32), // F10 on this row
    Rewalk,        // walk the lanes again: a compaction or a features toggle
}

impl State {
    /// Fetch the released documents edits asked for.
    pub(crate) fn fetch_wanted(&mut self) {
        for (doc, url, token) in self.scene.take_wanted() {
            #[cfg(target_arch = "wasm32")]
            crate::app::loader::spawn_hydrate(doc, url, token);
            #[cfg(not(target_arch = "wasm32"))]
            let _ = (doc, url, token);
        }
    }

    /// Run `resume` once the documents it needs are back.
    pub(crate) fn resume_after(&mut self, resume: Resume) {
        self.features.resume.push(resume);
        self.fetch_wanted();
    }

    /// Why `rows` cannot be edited now: a streamed shell never, a released document once it is back.
    pub(crate) fn locked_reason(&mut self, rows: &[u32]) -> Option<String> {
        let mut reason = None;

        for &row in rows {
            if let Some(doc) = self.scene.released_doc(row) {
                reason = self.scene.editable(doc).err();
            } else if self.scene.display_only(row) {
                return Some(crate::app::scene::READ_ONLY.into());
            }
        }

        if reason.is_some() {
            self.fetch_wanted();
        }

        reason
    }

    /// A released document's objects came back, or could not.
    pub fn hydrated(&mut self, back: Hydrated) {
        // a fetch for a replaced scene or an older release is dropped quietly
        if !self.scene.awaits(back.doc, back.token) {
            return;
        }

        let name = self.scene.docs[back.doc].name.clone();
        let result = back
            .session
            .and_then(|session| self.scene.hydrate(back.doc, back.token, session));

        match result {
            Ok(()) => self.status(&format!("'{name}' is editable ({:.0} ms)", back.ms)),
            Err(error) => {
                self.scene.fetch_failed(back.doc, back.token);
                self.features.resume.clear();
                self.status(&format!("Cannot edit '{name}': {error}"));
                return;
            }
        }

        let waiting = std::mem::take(&mut self.features.resume);

        for resume in waiting {
            self.run_resume(resume);
        }

        self.touch();
    }

    /// Idle work between edits: one kernel purge step, frames kept coming until the cycle ends.
    pub(crate) fn purge_idle(&mut self) {
        let gesture = self.features.dragging.is_some() || self.features.control_drag.is_some();

        if !gesture && self.scene.purge_step() {
            self.needs_frame = true;
        }
    }

    /// Run one waiting edit when its documents are back, else keep it.
    fn run_resume(&mut self, resume: Resume) {
        match resume {
            Resume::Controls(row) if self.scene.released_doc(row).is_none() => {
                if self.scene.selected == Some(row) {
                    self.enable_controls();
                }
            }
            Resume::Rewalk if !self.scene.has_released() => {
                self.scene.rewalk_editable(&mut self.gpu);
                self.reselect_face();
                self.place_gizmo(None);
                self.update_label();
            }
            waiting => self.features.resume.push(waiting),
        }
    }
}

impl State {
    /// F10 on a released document: fetch it and show the controls once it is back; true while it comes.
    pub(super) fn controls_after_hydrate(&mut self, parent: u32) -> bool {
        let Some(doc) = self.scene.released_doc(parent) else {
            return false;
        };
        self.scene.want(doc);
        self.status(&format!(
            "Loading '{}' for its control points",
            self.scene.docs[doc].name
        ));
        self.resume_after(Resume::Controls(parent));
        true
    }

    /// Snapping asked for a released document: fetch it.
    pub(super) fn fetch_if_wanting(&mut self) {
        if self.scene.wanting() {
            self.fetch_wanted();
        }
    }
}

use super::State;
use crate::app::gizmo::{Handle, typed_value};

// The number box is the text field a clicked handle opens: type 250 on Move X to move the selection 250 mm.
/// The number box of a clicked gumball handle, as the panel draws it.
pub struct NumberPrompt {
    pub handle: Handle,     // the handle clicked
    pub title: String,      // e.g. Move X
    pub unit: &'static str, // mm, deg or factor
    pub hint: &'static str, // the value that changes nothing
    pub at: [f32; 2],       // the handle on screen, CSS pixels
}

impl State {
    /// True while a number box waits for its value.
    pub fn number_box_open(&self) -> bool {
        self.features
            .gizmo
            .as_ref()
            .is_some_and(|gizmo| gizmo.typing.is_some())
    }

    /// The open number box, pinned to its handle wherever the view puts it.
    pub fn number_prompt(&self) -> Option<NumberPrompt> {
        let gizmo = self.features.gizmo.as_ref()?;
        let handle = gizmo.typing?;
        let point = gizmo.handle_point(handle, self.world_per_px());
        let (x, y) = self.project([point[0], point[1], point[2]])?;
        let scale = self.pixel_scale(); // device pixels per CSS pixel
        let (_, _, unit) = handle.labels();
        Some(NumberPrompt {
            handle,
            title: handle.title(),
            unit,
            hint: if unit == "factor" { "1" } else { "0" },
            at: [(x / scale) as f32, (y / scale) as f32],
        })
    }

    /// Close the number box; true when one was open.
    pub fn close_number_box(&mut self) -> bool {
        let Some(gizmo) = self
            .features
            .gizmo
            .as_mut()
            .filter(|gizmo| gizmo.typing.is_some())
        else {
            return false;
        };
        gizmo.typing = None;
        self.touch();
        true
    }

    /// Enter in the number box: the value becomes one undo step; `Ok(None)` when nothing changed.
    pub fn type_number(&mut self, text: &str) -> Result<Option<String>, String> {
        let Some(gizmo) = self.features.gizmo.as_ref() else {
            return Ok(None);
        };
        let Some(handle) = gizmo.typing else {
            return Ok(None);
        };
        // `?` hands a bad number back as Err, which keeps the box open; Ok(None) means nothing to change
        let Some(value) = typed_value(handle, text)? else {
            self.close_number_box();
            return Ok(None);
        };
        let delta = gizmo.typed(handle, value);
        let label = match handle {
            Handle::Translate(_) => "move",
            Handle::Rotate(_) => "rotate",
            Handle::Scale(_) | Handle::ScaleUniform => "scale",
        };
        self.close_number_box();

        if let Err(error) = self.apply(delta, label) {
            self.status(&error);
            return Ok(None);
        }

        let (_, _, unit) = handle.labels();
        Ok(Some(format!("{} {value} {unit}", handle.title())))
    }
}

impl State {
    /// A tap that opened a number box raises the phone keyboard.
    pub(crate) fn number_box_tapped(&self, tap: bool) {
        if tap && self.number_box_open() {
        }
    }
}

const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const path = require('node:path');
const { chromium } = require('playwright');
const browserUi = require('../docs/extensions/browser.cjs');
const root = path.resolve(__dirname, '..');

async function state(page) {
  return page.evaluate(() => JSON.parse(document.querySelector('canvas')?.getAttribute('data-viewer-inspection') || 'null'));
}
async function wait(page, predicate, argument) {
  await page.waitForFunction(({ source, argument }) => {
    const raw = document.querySelector('canvas')?.getAttribute('data-viewer-inspection');
    return raw && Function('s', 'a', `return (${source})(s,a)`)(JSON.parse(raw), argument);
  }, { source: predicate.toString(), argument });
}
async function key(page, value) {
  const before = (await state(page)).submitted_at_ms;
  await page.keyboard.press(value);
  await wait(page, (s, a) => s.submitted_at_ms > a && !s.pick_busy, before);
  await page.waitForTimeout(150);
}
async function command(page, text) {
  await browserUi.command(page, text);
}

async function action(page, prefix, label) {
  await browserUi.button(page, prefix + '/', label);
}

async function selectCreated(page) {
  await key(page, 'l');
  await action(page, 'select', 'Select Created');
  await key(page, 'l');
  await page.locator('canvas').focus();
  await wait(page, s => s.selected !== null);
}
function project(s, p) {
  const v = p.map((n,i) => n - s.origin[i]);
  const c = [0,1,2,3].map(r => s.mvp[r]*v[0]+s.mvp[4+r]*v[1]+s.mvp[8+r]*v[2]+s.mvp[12+r]);
  return [(c[0]/c[3]*.5+.5)*s.logical_canvas[0],(.5-c[1]/c[3]*.5)*s.logical_canvas[1]];
}
async function drag(page, from, to, cancel = false) {
  await page.mouse.move(...from);
  await page.waitForTimeout(60);
  await page.mouse.down();
  await page.mouse.move(...to, { steps: 8 });
  if (cancel) await key(page, 'Escape');
  await page.mouse.up();
  await page.waitForTimeout(150);
}
async function round(browser, config) {
  const context = await browser.newContext({ viewport: config.viewport, deviceScaleFactor: config.dpr || 1 });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => errors.push(String(e)));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  try {
    await page.route('**/view_local.yaml', r => r.fulfill({ contentType:'application/yaml', body:'name: Editing lessons\nitems:\n  - file: extension-nested.pb\n' }));
    await page.route('**/extension-nested.pb', r => r.fulfill({ path:path.join(root,'docs/extensions/nested.pb') }));
    await page.route('**/favicon.ico', r => r.fulfill({status:204}));
    await page.goto(new URL('?data=off&inspect=1', process.env.VIEWER_URL || 'http://localhost:8791/').href);
    await wait(page, s => s.objects === 3);
    await page.locator('canvas').focus();
    await key(page, '5');
    if (config.perspective) await key(page, 'Space');
    if (!(await browserUi.ui(page)).layers_open) await key(page, 'l');
