// Panel = one piece of the interface over the canvas, e.g. the number box; each lives in its own file.
use crate::State;
use std::cell::Cell;
use theme::{BUNDLED, fonts, visuals};
use winit::window::Window;
mod overlay; // register:overlay
mod pointer; // register:pointer
mod theme; // register:theme

/// Declare each panel's module and list it in PANELS, so a panel is one file plus one line.
macro_rules! panels {
    // `$(,)?` allows a comma after the last name
    ($($name:ident),* $(,)?) => {
        $(pub(crate) mod $name;)*

        // every panel file has a unit struct `Hooks`, a struct with no fields that exists only to implement Panel
        /// The panels in drawing order; the number box first, so its Escape never reaches the command line.
        const PANELS: &[&dyn Panel] = &[$(&$name::Hooks),*];
    };
}

panels! {
    number_box,   // register:number_box
}

// As with Lane in 04a, every hook but `show` has a default body, so a panel writes only the hooks it uses.
/// One panel. Its state lives in its own file; these hooks are all the frame needs from it.
trait Panel {
    /// Copy what it shows from the viewer, before the frame.
    fn fill(&self, _state: &mut State) {}

    /// Draw into the root area; a click or a line to run goes to `out`.
    fn show(&self, root: &mut egui::Ui, controls: &mut Option<Vec<Control>>, out: &mut Output);

    /// Apply what it took this frame, once egui is done; true when something changed.
    fn apply(&self, _state: &mut State) -> bool {
        false
    }

    /// True while it takes the keys.
    fn keys_taken(&self) -> bool {
        false
    }

    /// True while Escape is its own, so the command line leaves it alone.
    fn holds_escape(&self) -> bool {
        false
    }

    /// Its open text field for the phone keyboard: the egui id, after `edit` ran on the text.
    // `&mut dyn FnMut(&mut String)` = any closure that may change the text; lesson 23's phone keyboard writes through it
    #[cfg(target_arch = "wasm32")]
    fn field(&self, _edit: &mut dyn FnMut(&mut String)) -> Option<&'static str> {
        None
    }

    /// Whether `point` is on its text field, which raises the keyboard, and on a floating area that keeps the pointer.
    fn hit(&self, _point: egui::Pos2) -> (bool, bool) {
        (false, false)
    }

    /// Its part of the state browser tests read.
    fn snapshot(&self, _json: &mut serde_json::Map<String, serde_json::Value>) {}

    /// True while it is open and Escape closes it.
    fn closes_on_escape(&self) -> bool {
        false
    }

    /// A press at `pointer` over the canvas: focus its field when the press is on it.
    fn press(&self, _context: &egui::Context, _pointer: egui::Pos2) {}
}

thread_local! { static MENU_OPEN: Cell<bool> = const { Cell::new(false) }; } // an egui popup, e.g. a layer or colour menu, is open

/// True while a popup such as a layer or colour menu is open.
fn menu_open() -> bool {
    MENU_OPEN.get()
}

/// True while a panel takes the keys: the command line, a layer rename, the number box or an open menu.
pub fn keys_taken() -> bool {
    menu_open() || PANELS.iter().any(|panel| panel.keys_taken())
}

/// True while another panel owns Escape, e.g. a layer rename.
fn escape_held() -> bool {
    PANELS.iter().any(|panel| panel.holds_escape())
}

/// Whether `point` is on a text field, which raises the keyboard, and on a floating area that keeps the pointer.
pub(crate) fn hit(point: egui::Pos2) -> (bool, bool) {
    // `fold` carries one pair through the panels: a field or a popup of any panel under the point sets its half
    PANELS.iter().fold((false, false), |(field, popup), panel| {
        let (on_field, on_popup) = panel.hit(point);
        (field || on_field, popup || on_popup)
    })
}

/// One clickable control and where it was drawn, for browser tests.
#[derive(serde::Serialize)]
pub struct Control {
    key: String,    // what it does
    label: String,  // text shown
    rect: [f32; 4], // left, top, right, bottom
}

/// What the panels hand back from one frame, applied once egui is done.
#[derive(Default)]
struct Output {
    action: Option<String>,  // a panel click, for `State::panel_action`
    command: Option<String>, // a line to run
}

/// The egui interface over the canvas.
pub struct Ui {
    context: egui::Context,                  // egui state
    input: egui_winit::State,                // winit events into egui
    controls: Option<Vec<Control>>,          // controls drawn this frame, when inspecting
    scene_rect: egui::Rect,                  // canvas area not covered by panels
    pointer: egui::Pos2,                     // last pointer position
    ui_drag: bool,                           // a drag started on a panel
    over_panel: bool,                        // the pointer was last over a panel or popup
    touches: std::collections::HashSet<u64>, // fingers on panels
}

impl Ui {
    /// Draw the panels with the whole fonts, main font first.
    pub fn use_fonts(&mut self, faces: [&'static [u8]; 3]) {
        self.context.set_fonts(fonts(faces));
    }

    /// Set up egui with the light theme.
    pub fn new(window: &Window, _logical_width: f64) -> Self {
        // Context = egui's whole memory: focus, open popups, fonts and style; a clone is a second handle to the same one
        let context = egui::Context::default();
        context.set_fonts(fonts(BUNDLED));
        // egui may lay a frame out twice to settle sizes; a second pass would type every letter twice
        context.options_mut(|options| options.max_passes = 1.try_into().unwrap());
        context.set_theme(egui::Theme::Light);
        context.set_visuals(visuals());
        let input = egui_winit::State::new(
            context.clone(),
            egui::ViewportId::ROOT,
            window,
            Some(window.scale_factor() as f32),
            window.theme(),
            // the largest texture side egui may create, in pixels
            Some(4096),
        );
        Self {
            context,
            input,
            // native tests always record the controls; the browser only with ?inspect=1
            #[cfg(not(target_arch = "wasm32"))]
            controls: Some(Vec::new()),
            #[cfg(target_arch = "wasm32")]
            controls: (crate::app::route::query("inspect").as_deref() == Some("1")).then(Vec::new),
            scene_rect: egui::Rect::EVERYTHING, // the whole canvas until the first frame measures the panels
            pointer: egui::Pos2::ZERO,
            ui_drag: false,
            over_panel: false,
            touches: std::collections::HashSet::new(),
        }
    }

    /// Lay out and draw the panels; true when the frame must be redrawn.
    pub fn frame(&mut self, state: &mut State) -> bool {
        // RawInput = everything since the last frame: pointer moves, clicks, keys and typed text
        let mut input = self.input.take_egui_input(&state.window);
        // layout in CSS pixels
        let logical = state.logical_size();
        input.screen_rect = Some(egui::Rect::from_min_size(
            egui::Pos2::ZERO,
            egui::vec2(logical[0] as f32, logical[1] as f32),
        ));

        if let Some(controls) = self.controls.as_mut() {
            controls.clear();
        }

        let mut out = Output::default();

        for panel in PANELS {
            panel.fill(state);
        }

        // a dragged object's snap, else the shape being drawn
        let mut drawing = state.drag_overlay();
        // in one egui run, keys reach the field focused before that run's clicks;
        // so every switch between clicks and keys starts a new run, and a tap then a typed 5 lands in the tapped field
        let mut batches = Vec::new();
        let mut events = Vec::new();
        let mut keyboard = None;
        for event in std::mem::take(&mut input.events) {
            let kind = match &event {
                egui::Event::PointerButton { .. } => Some(false),
                egui::Event::Key { .. } | egui::Event::Text(_) | egui::Event::Paste(_) => {
                    Some(true)
                }
                _ => None,
            };
            if kind.is_some() && keyboard.is_some() && kind != keyboard {
                let mut batch = input.clone();
                batch.events = std::mem::take(&mut events);
                batches.push(batch);
            }
            if kind.is_some() {
                keyboard = kind;
            }
            events.push(event);
        }
        input.events = events;
        batches.push(input);
        // the closure describes every panel; each run calls it again and egui lays out what it describes
        let mut draw = |root: &mut egui::Ui| {
            if let Some(controls) = self.controls.as_mut() {
                controls.clear();
            }
            for panel in PANELS {
                panel.show(root, &mut self.controls, &mut out);
            }
            // what the panels leave free is the scene; the pointer routing uses it
            self.scene_rect = root.available_rect_before_wrap();
            let painter = root.painter().with_clip_rect(self.scene_rect);
            let scale = state.pixel_scale() as f32;

            if let Some(drawing) = &drawing {
                overlay::drawing(&painter, drawing, scale);
            }

        };
        let mut batches = batches.into_iter();
        // `unwrap` cannot fail: the last push above leaves at least one batch
        let mut output = self.context.run_ui(batches.next().unwrap(), &mut draw);
        for batch in batches {
            output.append(self.context.run_ui(batch, &mut draw));
        }
        MENU_OPEN.set(egui::Popup::is_any_open(&self.context));
        // what egui asks of the page: the cursor shape, a copy to the clipboard
        self.input
            .handle_platform_output(&state.window, std::mem::take(&mut output.platform_output));
        let mut changed = false;

        for panel in PANELS {
            changed |= panel.apply(state);
        }

        let Output { action, command } = out;
        changed |= action.is_some() || command.is_some();

        if let Some(key) = action {
        }

        if let Some(text) = command {
        }

        self.publish();
        let repaint = changed || self.context.has_requested_repaint();
        // a 1600-pixel canvas 800 CSS pixels wide gives 2.0
        output.pixels_per_point = state.gpu.config.width as f32 / logical[0].max(1.0) as f32;

        if let Some(ui) = state.gpu.ui.as_mut() {
            ui.prepare(
                &state.gpu.ctx,
                &self.context,
                output,
                [state.gpu.config.width, state.gpu.config.height],
            );
        }

        repaint
    }

    /// Write the panel state onto the canvas for browser tests.
    fn publish(&self) {
        // `&& let` adds a pattern to the condition: the block runs only when both hold
        if self.controls.is_some()
            && let Some(canvas) = web_sys::window()
                .and_then(|window| window.document())
                .and_then(|document| document.get_element_by_id("canvas"))
        {
            let mut snapshot = serde_json::Map::new();
            snapshot.insert("framework".into(), "egui 0.34.3".into());
            snapshot.insert("scene_rect".into(), corners(Some(self.scene_rect)));
            snapshot.insert("controls".into(), serde_json::json!(self.controls));

            for panel in PANELS {
                panel.snapshot(&mut snapshot);
            }

            let snapshot = serde_json::Value::Object(snapshot).to_string();
            let _ = canvas.set_attribute("data-viewer-ui", &snapshot);
        }

        if let Some(status) = web_sys::window()
            .and_then(|w| w.document())
            .and_then(|d| d.get_element_by_id("viewer-status"))
        {
            // the page's loading note gives way to the panels
            let _ = status.set_attribute("hidden", "");
        }
    }
}

/// Remember one control's rectangle, when inspecting.
fn record(controls: &mut Option<Vec<Control>>, key: &str, label: &str, response: &egui::Response) {
    let Some(controls) = controls.as_mut() else {
        return;
    };
    let r = response.rect;
    controls.push(Control {
        key: key.to_string(),
        label: label.to_string(),
        rect: [r.min.x, r.min.y, r.max.x, r.max.y],
    });
}

/// A rectangle as `[left, top, right, bottom]` for browser tests, null when there is none.
fn corners(rect: Option<egui::Rect>) -> serde_json::Value {
    serde_json::json!(rect.map(|r| [r.min.x, r.min.y, r.max.x, r.max.y]))
}

// The number box: type an exact distance or angle for the gumball handle the pointer is on.
use super::{Control, Output, record};
use crate::State;
use crate::app::gizmo::Handle;
use crate::state::number_box::NumberPrompt;
use std::cell::RefCell;

/// What the gumball number box shows and took this frame.
#[derive(Default)]
pub(crate) struct NumberBox {
    number_prompt: Option<NumberPrompt>, // the box, when open
    number_handle: Option<Handle>,       // the handle the box was opened for
    number: String,                      // text typed into the box
    number_error: String,                // why the typed value was refused
    number_rect: Option<egui::Rect>,     // where the box is, for taps
    typed: Option<String>,               // a value Enter took this frame
    closed: bool,                        // closed without a value this frame
}

// egui redraws the box from scratch every frame, so what it must remember lives here, outside egui
thread_local! { static STATE: RefCell<NumberBox> = RefCell::default(); } // kept between frames

/// The number box, registered in PANELS.
pub(super) struct Hooks;

impl super::Panel for Hooks {
    fn fill(&self, state: &mut State) {
        // the viewer's state from lesson 21 says whether a box is open and for which handle
        let prompt = state.number_prompt();

        // a box whose handle went behind the eye closes, so no unseen field keeps the keys
        if prompt.is_none() {
            state.close_number_box();
        }

        // `with_borrow_mut` lends the value inside the thread-local for as long as the closure runs
        STATE.with_borrow_mut(|model| model.number_prompt = prompt);
    }

    fn show(&self, root: &mut egui::Ui, controls: &mut Option<Vec<Control>>, _out: &mut Output) {
        STATE.with_borrow_mut(|model| draw(root, model, controls));
    }

    fn apply(&self, state: &mut State) -> bool {
        let (typed, closed) =
            STATE.with_borrow_mut(|model| (model.typed.take(), std::mem::take(&mut model.closed)));

        if closed {
            state.close_number_box();
        }

        // Enter: one undo step, or the reason under the field
        if let Some(text) = &typed {
            match state.type_number(text) {
                Ok(Some(done)) => {
                    crate::app::feedback::status(&done);
                }
                Ok(None) => {}
                Err(error) => STATE.with_borrow_mut(|model| model.number_error = error),
            }
        }

        typed.is_some() || closed
    }

    fn keys_taken(&self) -> bool {
        STATE.with_borrow(|model| model.number_prompt.is_some())
    }

    #[cfg(target_arch = "wasm32")]
    fn field(&self, edit: &mut dyn FnMut(&mut String)) -> Option<&'static str> {
        STATE.with_borrow_mut(|model| {
            model.number_prompt.is_some().then(|| {
                edit(&mut model.number);
                "number-input"
            })
        })
    }

    fn hit(&self, point: egui::Pos2) -> (bool, bool) {
        let inside =
            STATE.with_borrow(|model| model.number_rect.is_some_and(|r| r.contains(point)));
        (inside, inside)
    }

    fn snapshot(&self, json: &mut serde_json::Map<String, serde_json::Value>) {
        STATE.with_borrow(|model| {
            json.insert("number".into(), model.number.clone().into());
            json.insert("number_error".into(), model.number_error.clone().into());
            json.insert("number_rect".into(), super::corners(model.number_rect));
        });
    }
}

/// The gumball number box beside its handle; Enter keeps the text in `typed`, Escape sets `closed`.
fn draw(
    root: &mut egui::Ui,                 // the panel area
    model: &mut NumberBox,               // the panel state
    controls: &mut Option<Vec<Control>>, // placed controls to draw
) {
    let Some(prompt) = model.number_prompt.as_ref() else {
        model.number_handle = None;
        model.number_rect = None;
        return;
    };
    // an Id names a widget across frames: focus, and later the phone keyboard, find the field by it
    let id = egui::Id::new("number-input");
    let opened = model.number_handle != Some(prompt.handle);

    // a new box starts empty, with the keys
    if opened {
        model.number_handle = Some(prompt.handle);
        model.number.clear();
        model.number_error.clear();
        root.memory_mut(|memory| memory.request_focus(id));
    }

    let focused = root.memory(|memory| memory.focused());

    // Escape, or another field taking the keys, closes it
    // `consume_key` removes the key from the input, so no other widget sees the same Escape
    if root.input_mut(|i| i.consume_key(egui::Modifiers::NONE, egui::Key::Escape))
        || focused.is_some_and(|other| other != id)
    {
        model.closed = true;
        return;
    }

    // a click in the scene dropped the focus: the box keeps the keys while it is open
    if focused.is_none() {
        root.memory_mut(|memory| memory.request_focus(id));
    }

    let enter = root.input_mut(|i| i.consume_key(egui::Modifiers::NONE, egui::Key::Enter));
    // Area = a floating layer at any position; Foreground puts it above every panel
    let area = egui::Area::new(egui::Id::new("number-box"))
        .order(egui::Order::Foreground)
        // the box's lower left corner sits 12 points right of and above the handle
        .pivot(egui::Align2::LEFT_BOTTOM)
        .fixed_pos(egui::pos2(prompt.at[0] + 12.0, prompt.at[1] - 12.0))
        .show(root.ctx(), |ui| {
            egui::Frame::new()
                .fill(egui::Color32::WHITE)
                .stroke(egui::Stroke::new(1.0_f32, egui::Color32::from_gray(215)))
                .inner_margin(5)
                .show(ui, |ui| {
                    ui.style_mut().override_font_id = Some(egui::FontId::proportional(14.0));
                    ui.horizontal(|ui| {
                        ui.label(&prompt.title);
                        let edit = ui.add_sized(
                            [72.0, 22.0],
                            egui::TextEdit::singleline(&mut model.number)
                                .id(id)
                                .hint_text(prompt.hint)
                                .char_limit(64), // a pasted page stops at 64 characters
                        );
                        record(controls, "number/input", &prompt.title, &edit);
                        ui.label(prompt.unit);
                    });

                    if !model.number_error.is_empty() {
                        ui.colored_label(egui::Color32::from_rgb(170, 30, 30), &model.number_error);
                    }
                });
        });
    model.number_rect = Some(area.response.rect);

    if enter {
        model.typed = Some(model.number.clone());
    }
}

// Painter = egui's pen for loose lines, boxes and text, clipped here to the scene area.
/// The shape being drawn: its points joined, a square and the prompt at the last; in device pixels.
pub(super) fn drawing(painter: &egui::Painter, drawing: &(Vec<(f64, f64)>, String), scale: f32) {
    let points: Vec<egui::Pos2> = drawing
        .0
        .iter()
        // device pixels to egui points: at scale 2.0, pixel 400 is point 200
        .map(|p| egui::pos2(p.0 as f32 / scale, p.1 as f32 / scale))
        .collect();

    // `windows(2)` yields each neighbouring pair: 4 points give 3 segments
    for pair in points.windows(2) {
        painter.line_segment(
            [pair[0], pair[1]],
            egui::Stroke::new(1.5_f32, egui::Color32::from_rgb(30, 110, 170)),
        );
    }

    if let Some(p) = points.last() {
        painter.rect_stroke(
            egui::Rect::from_center_size(*p, egui::vec2(8.0, 8.0)),
            0.0,
            egui::Stroke::new(1.5_f32, egui::Color32::from_rgb(30, 110, 170)),
            egui::StrokeKind::Middle,
        );
        painter.text(
            *p + egui::vec2(10.0, -12.0),
            egui::Align2::LEFT_BOTTOM,
            &drawing.1,
            egui::FontId::proportional(14.0),
            egui::Color32::from_rgb(20, 80, 130),
        );
    }
}

// A child module sees its parent's private items, so this file reads Ui's fields as if it were mod.rs.
use super::{PANELS, Ui, hit, keys_taken};
use winit::window::Window;

// Routing = deciding who gets each event: a press on a panel stays in egui, a press on the scene reaches the viewer.
impl Ui {
    /// Offer one event to the panels; (consumed, needs repaint).
    pub fn event(&mut self, window: &Window, event: &winit::event::WindowEvent) -> (bool, bool) {
        // egui always sees the event; `consumed` then says whether the viewer should not
        let response = self.input.on_window_event(window, event);
        let escape = matches!(event, winit::event::WindowEvent::KeyboardInput { event, .. }
            if event.logical_key == winit::keyboard::Key::Named(winit::keyboard::NamedKey::Escape))
            && PANELS.iter().any(|panel| panel.closes_on_escape());
        // a `use` inside a function names these types for this function only
        use winit::event::{ElementState, TouchPhase, WindowEvent};
        // winit reports device pixels, egui works in points: at ratio 2.0, x = 400 is point 200
        let ratio = window.scale_factor() as f32;
        let mut consumed = response.consumed;
        let mut scene_rect = self.scene_rect;
        scene_rect.max.y -= 5.0; // the lowest 5 points of the scene count as panel: the edge of what is docked below
        // the closure below borrows this clone, leaving `self` free to change inside the match
        let context = self.context.clone();
        // the completion list, the number box, a context menu or a colour menu
        let in_popup = |point| {
            hit(point).1
                || context
                    .layer_id_at(point)
                    .is_some_and(|layer| layer.order != egui::Order::Background)
        };

        match event {
            // the current pointer decides, not last frame's hover: a fast move may cross a panel edge between frames
            WindowEvent::CursorMoved { position, .. } => {
                self.pointer = egui::pos2(position.x as f32 / ratio, position.y as f32 / ratio);
                self.over_panel = in_popup(self.pointer) || !scene_rect.contains(self.pointer);
                consumed = self.ui_drag || self.over_panel;
            }
            WindowEvent::MouseInput { state, button, .. } => {
                if *state == ElementState::Pressed {
                    self.ui_drag = in_popup(self.pointer) || !scene_rect.contains(self.pointer);
                    self.over_panel = self.ui_drag;
                    self.press();
                }

                consumed = self.ui_drag;

                // a left drag from the scene let go over a panel is dropped, not applied
                if *state == ElementState::Released {
                    consumed |= *button == winit::event::MouseButton::Left && self.over_panel;
                    self.ui_drag = false;
                }
            }
            WindowEvent::MouseWheel { .. } => {
                consumed = in_popup(self.pointer) || !scene_rect.contains(self.pointer)
            }
            // the first finger decides for the whole gesture: a pinch that starts on the scene stays on the scene
            WindowEvent::Touch(touch) => {
                self.pointer = egui::pos2(
                    touch.location.x as f32 / ratio,
                    touch.location.y as f32 / ratio,
                );

                if touch.phase == TouchPhase::Started {
                    if self.touches.is_empty() {
                        self.ui_drag = in_popup(self.pointer) || !scene_rect.contains(self.pointer);
                        self.press();
                    }

                    self.touches.insert(touch.id);
                }

                consumed = self.ui_drag;

                if matches!(touch.phase, TouchPhase::Ended | TouchPhase::Cancelled) {
                    self.touches.remove(&touch.id);

                    if self.touches.is_empty() {
                        self.ui_drag = false;
                    }
                }
            }
            WindowEvent::Focused(false) => {
                self.ui_drag = false;
                self.touches.clear();
            }
            _ => {}
        }

        // an open menu or number box keeps the keys too, so Escape only closes it
        if matches!(event, WindowEvent::KeyboardInput { .. }) && keys_taken() {
            consumed = true;
        }
        (consumed || escape, response.repaint || escape)
    }

    /// A press: the panel whose field it lands on opens it.
    fn press(&mut self) {
        for panel in PANELS {
            panel.press(&self.context, self.pointer);
        }
    }
}

/// The subset label fonts inside the binary; the panels use them until the whole fonts are downloaded.
pub(super) const BUNDLED: [&[u8]; 3] = [
    crate::engine::text::FONT_BYTES,
    crate::engine::text::FALLBACK_BYTES,
    crate::engine::text::SYMBOL_BYTES,
];

/// The panel fonts: the label fonts, Noto Sans first, then its symbol fallbacks.
pub(super) fn fonts(faces: [&'static [u8]; 3]) -> egui::FontDefinitions {
    let mut fonts = egui::FontDefinitions::empty();
    let names = ["Noto Sans", "Noto Sans Symbols 2", "Noto Sans Symbols"];

    for (name, bytes) in names.into_iter().zip(faces) {
        // `from_static` borrows the bytes already in the binary instead of copying them
        let data = std::sync::Arc::new(egui::FontData::from_static(bytes));
        fonts.font_data.insert(name.to_owned(), data);

        // a family is a fallback list: a glyph missing from Noto Sans, e.g. ⌘, is looked up in the next font
        for family in [egui::FontFamily::Proportional, egui::FontFamily::Monospace] {
            fonts
                .families
                .entry(family)
                .or_default()
                .push(name.to_owned());
        }
    }

    fonts
}

/// The white theme: black text, white fields, light grey panels, no borders.
pub(super) fn visuals() -> egui::Visuals {
    let mut visuals = egui::Visuals::light();
    visuals.override_text_color = Some(egui::Color32::BLACK);
    visuals.window_fill = egui::Color32::WHITE;
    visuals.panel_fill = egui::Color32::from_gray(245);
    visuals.window_stroke = egui::Stroke::NONE;
    visuals.extreme_bg_color = egui::Color32::WHITE; // the inside of text fields
    visuals.selection.bg_fill = egui::Color32::from_rgb(200, 222, 245);
    visuals.selection.stroke = egui::Stroke::new(1.0_f32, egui::Color32::BLACK);
    visuals.text_cursor.stroke = egui::Stroke::new(1.5_f32, egui::Color32::BLACK);
    visuals.text_cursor.blink = false; // a blink would ask for a new frame twice a second; frames are drawn on demand
    visuals.indent_has_left_vline = false;

    // the five states a widget can be in, from plain label to open menu, share one flat look
    for widget in [
        &mut visuals.widgets.noninteractive,
        &mut visuals.widgets.inactive,
        &mut visuals.widgets.hovered,
        &mut visuals.widgets.active,
        &mut visuals.widgets.open,
    ] {
        widget.bg_stroke = egui::Stroke::NONE;
        widget.bg_fill = egui::Color32::from_gray(245);
        widget.weak_bg_fill = egui::Color32::WHITE;
        widget.fg_stroke.color = egui::Color32::BLACK;
    }

    visuals
}

