#[test]
fn bare_transform_verbs_start_picking() {
    for (line, tool) in [
        ("move", "Moving"),
        ("rotate", "Rotating"),
        ("scale", "Scaling { mode: 3 }"),
        ("copy", "Copying"),
        ("Orient 3 Points", "Orienting"),
