            [[0.0, -600.0, 0.0], [0.0, 0.0, 0.0]]
        ));
        let zero = [Answer::Point(p(0.0, 0.0, 0.0)), Answer::Number(-1.0)];
        assert!(build(&SHAPE, &plane(XY.0, XY.1), &zero, "Brep").is_err());
    }
}

