            p(40., 0., 0.),
            p(40., 30., 10.),
            p(0., 30., 0.),
        ];
        assert!(!planar(&bent, &loop_normal(&bent).unwrap()));
        assert!(loop_normal(&[p(0., 0., 0.), p(1., 0., 0.), p(2., 0., 0.)]).is_none());
