mod tests {
    use super::*;
    use crate::app::command::tool::shape::tests::{XZ, build, corners, p, plane};

    /// Nine controls, closed, every sample at the radius in the plane.
    #[test]
    fn the_circle_lies_in_the_plane() {
        let center = p(1.0, 2.0, 3.0);
        let answers = [
            Answer::Point(center.clone()),
            Answer::Point(p(11.0, 2.0, 3.0)),
        ];
        let made = build(&SHAPE, &plane(XZ.0, XZ.1), &answers, "").unwrap();
        let Geometry::NurbsCurve(curve) = &made else {
            panic!()
        };
        assert_eq!(curve.cv_count(), 9);
        assert!(curve.is_closed());

        for q in corners(&made) {
            assert!((q.distance(&center, None) - 10.0).abs() < 1e-9);
            assert!((q[1] - 2.0).abs() < 1e-9);
        }
    }
}

use crate::app::command::tool::shape::{self, Answer, Ask, CURVE, Frame, Part, Shape, positive};
use crate::app::command::{Action, Spec};
use session_rust::{Geometry, Point, Primitives};
use std::rc::Rc;

pub const SPEC: Spec = Spec::new(
    &["Nurbs Curve Ellipse"],
    "Nurbs Curve Ellipse: center, end of the first axis or its radius, second radius · Example: Nurbs Curve Ellipse 0,0,0 20 10",
    parse,
);

pub static SHAPE: Shape = Shape {
    name: "Nurbs Curve Ellipse",
    options: CURVE,
    upfront: false,
    ask,
    read,
    outline,
    build,
};

/// Start the questions, answered by any typed words.
fn parse(_verb: &str, rest: &[&str]) -> Result<Box<dyn Action>, String> {
    shape::start(&SHAPE, rest)
}

/// Center, the first axis end, then the second radius.
fn ask(answers: &[Answer], _part: &Part, _option: &str) -> Option<Ask> {
    match answers.len() {
        0 => Some(Ask::point("Center")),
        1 => Some(Ask::size("First axis end or radius")),
        2 => Some(Ask::size("Second radius")),
        _ => None,
    }
}

/// A click turns the first axis toward it; the second radius is a click's distance from that axis.
fn read(frame: &Frame, answers: &[Answer], _option: &str) -> Result<Part, String> {
    let mut part = Part::new(frame.clone());

    if let Some(first) = answers.get(1) {
        if let Answer::Point(end) = first {
            let [u, v, _] = frame.local(end);
            part.frame = frame.turned(u, v);
        }

        part.sizes
            .push(positive(frame.size(first), "The first radius")?);
    }

    if let Some(second) = answers.get(2) {
        let radius = match second {
            Answer::Number(value) => *value,
            Answer::Point(p) => part.frame.local(p)[1].abs(),
        };
        part.sizes.push(positive(radius, "The second radius")?);
    }

    Ok(part)
}

/// The first axis, then the ellipse.
fn outline(part: &Part) -> Vec<Vec<Point>> {
    let frame = &part.frame;

    match part.sizes[..] {
        [first] => vec![vec![frame.at(-first, 0.0, 0.0), frame.at(first, 0.0, 0.0)]],
        [first, second] => vec![frame.oval(first, second, 0.0)],
        _ => Vec::new(),
    }
}

/// The kernel ellipse, its first radius along the first axis.
fn build(part: &Part, _option: &str) -> Result<Geometry, String> {
    let [first, second] = part.sizes[..] else {
        return Err("Nurbs Curve Ellipse needs two radii".into());
    };
    let mut curve = Primitives::ellipse(0.0, 0.0, 0.0, first, second);
    curve.transform(&part.frame.to_xform());
    curve.name = "ellipse".into();
    Ok(Geometry::NurbsCurve(Rc::new(curve)))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::app::command::tool::shape::tests::{XY, build, corners, p, plane};

    /// It starts at the first axis end, and every sample fits (u/a)² + (v/b)² = 1.
    #[test]
    fn the_ellipse_follows_its_axes() {
        let top = plane(XY.0, XY.1);
        let answers = [
            Answer::Point(p(0.0, 0.0, 0.0)),
            Answer::Point(p(0.0, 20.0, 0.0)),
            Answer::Number(10.0),
        ];
        let made = build(&SHAPE, &top, &answers, "").unwrap();
        let Geometry::NurbsCurve(curve) = &made else {
            panic!()
        };
        assert_eq!(curve.cv_count(), 9);
        assert!(
            curve
                .point_at(curve.domain().0)
                .distance(&p(0.0, 20.0, 0.0), None)
                < 1e-9
        );

        for q in corners(&made) {
            assert!(((q[1] / 20.0).powi(2) + (q[0] / 10.0).powi(2) - 1.0).abs() < 1e-9);
        }
    }
}

use crate::app::command::tool::shape::{self, Answer, Ask, CURVE, Frame, Part, Shape, positive};
use crate::app::command::{Action, Spec};
use session_rust::{Geometry, Point, Primitives};
use std::rc::Rc;

pub const SPEC: Spec = Spec::new(
    &["Nurbs Curve Parabola"],
    "Nurbs Curve Parabola: start, end or length, apex or height · Example: Nurbs Curve Parabola 0,0,0 100 40",
    parse,
);

pub static SHAPE: Shape = Shape {
    name: "Nurbs Curve Parabola",
    options: CURVE,
    upfront: false,
    ask,
    read,
    outline,
    build,
};

const SAMPLES: usize = 32; // preview segments

/// Start the questions, answered by any typed words.
fn parse(_verb: &str, rest: &[&str]) -> Result<Box<dyn Action>, String> {
    shape::start(&SHAPE, rest)
}

/// Start, end, then the apex.
fn ask(answers: &[Answer], _part: &Part, _option: &str) -> Option<Ask> {
    match answers.len() {
        0 => Some(Ask::point("Start")),
        1 => Some(Ask::size("End or length")),
        2 => Some(Ask::size("Apex or height")),
        _ => None,
    }
}

/// The frame runs from start to end; the apex is where the curve passes half way, off the chord.
fn read(frame: &Frame, answers: &[Answer], _option: &str) -> Result<Part, String> {
    let mut part = Part::new(frame.clone());
    let Some(end) = answers.get(1) else {
        return Ok(part);
    };

    if let Answer::Point(end) = end {
        let [u, v, _] = frame.local(end);
        part.frame = frame.turned(u, v);
    }

    let length = positive(frame.size(end), "The length")?; // a click lands on the plane
    part.sizes.push(length);

    if let Some(apex) = answers.get(2) {
        let [u, v, w] = match apex {
            Answer::Number(height) => [length * 0.5, *height, 0.0], // to the left of start → end
            Answer::Point(p) => part.frame.local(p),
        };

        if v.hypot(w) <= 1e-9 * length {
            return Err("The apex must lie off the line from start to end".into());
        }

        part.sizes.extend([u, w, v]); // the height last: the cursor readout shows it
    }

    Ok(part)
}

/// Start, apex and end in the world.
fn points(part: &Part) -> Option<[Point; 3]> {
    let [length, u, w, v] = part.sizes[..] else {
        return None;
    };
    let frame = &part.frame;
    Some([
        frame.at(0.0, 0.0, 0.0),
        frame.at(u, v, w),
        frame.at(length, 0.0, 0.0),
    ])
}

/// The chord, then the parabola.
fn outline(part: &Part) -> Vec<Vec<Point>> {
    let Some([start, apex, end]) = points(part) else {
        return part.sizes.first().map_or_else(Vec::new, |length| {
            vec![vec![
                part.frame.at(0.0, 0.0, 0.0),
                part.frame.at(*length, 0.0, 0.0),
            ]]
        });
    };
    // the Bezier control that makes the curve pass the apex half way
    let control = [0, 1, 2].map(|i| 2.0 * apex[i] - 0.5 * (start[i] + end[i]));
    let curve = (0..=SAMPLES)
        .map(|i| {
            let t = i as f64 / SAMPLES as f64;
            let (a, b, c) = ((1.0 - t) * (1.0 - t), 2.0 * t * (1.0 - t), t * t);
            Point::new(
                a * start[0] + b * control[0] + c * end[0],
                a * start[1] + b * control[1] + c * end[1],
                a * start[2] + b * control[2] + c * end[2],
            )
        })
        .collect();
    vec![curve]
}

/// The kernel parabola through start, apex and end.
fn build(part: &Part, _option: &str) -> Result<Geometry, String> {
    let [start, apex, end] =
        points(part).ok_or("Nurbs Curve Parabola needs a start, an end and an apex")?;
    let mut curve = Primitives::parabola(&start, &apex, &end);
    curve.name = "parabola".into();
    Ok(Geometry::NurbsCurve(Rc::new(curve)))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::app::command::tool::shape::tests::{XY, build, p, plane};

    /// It passes start, apex half way and end; an apex on the chord is refused.
    #[test]
    fn the_parabola_passes_its_three_points() {
        let top = plane(XY.0, XY.1);
        let answers = [
            Answer::Point(p(0.0, 0.0, 0.0)),
            Answer::Number(1000.0),
            Answer::Number(400.0),
        ];
        let Geometry::NurbsCurve(curve) = build(&SHAPE, &top, &answers, "").unwrap() else {
            panic!()
        };
        let (a, b) = curve.domain();
        assert_eq!(curve.cv_count(), 3);
        assert!(curve.point_at(a).distance(&p(0.0, 0.0, 0.0), None) < 1e-9);
        assert!(
            curve
                .point_at(0.5 * (a + b))
                .distance(&p(500.0, 400.0, 0.0), None)
                < 1e-9
        );
        assert!(curve.point_at(b).distance(&p(1000.0, 0.0, 0.0), None) < 1e-9);
        let flat = [
            Answer::Point(p(0.0, 0.0, 0.0)),
            Answer::Point(p(10.0, 0.0, 0.0)),
            Answer::Point(p(5.0, 0.0, 0.0)),
        ];
        assert!(build(&SHAPE, &top, &flat, "").is_err());
    }
}

use crate::app::command::tool::gather::{self, Input, Made, Recipe, Step};
use crate::app::command::tool::surfacing::checked;
use crate::app::command::{Action, Spec};
use session_rust::{NurbsSurface, Point};

pub const SPEC: Spec = Spec {
    aliases: &["nurbssurface_4_points"],
    ..Spec::new(
        &["Nurbs Surface 4 Points"],
        "Nurbs Surface 4 Points: four corners in order · Example: Nurbs Surface 4 Points 0,0,0 10,0,0 10,10,3 0,10,0",
        parse,
    )
};

pub static RECIPE: Recipe = Recipe {
    name: "Nurbs Surface 4 Points",
    chips: &[("Cancel", "Escape")],
    steps: &[
        Step::Point("corner 1 of 4"),
        Step::Point("corner 2 of 4"),
        Step::Point("corner 3 of 4"),
        Step::Point("corner 4 of 4"),
    ],
    axis: super::loft::no_axis,
    build,
};

/// Corners typed with the command answer at once.
fn parse(_verb: &str, rest: &[&str]) -> Result<Box<dyn Action>, String> {
    if !rest.is_empty() && rest.len() != 4 {
        return Err("Nurbs Surface 4 Points takes 4 corner points".into());
    }

    gather::start(&RECIPE, rest)
}

/// The bilinear patch a, b, c, d: u runs a to b, v runs a to d.
pub fn patch(corners: &[Point; 4]) -> Result<NurbsSurface, String> {
    let [a, b, c, d] = corners;
    let area = (c - a).cross(&(d - b)).magnitude();
    let size = [b, c, d]
        .iter()
        .map(|p| p.distance(a, None))
        .fold(1.0, f64::max);

    if area <= 1e-12 * size * size {
        return Err("The 4 corners enclose no area".into());
    }

    let points = [a.clone(), d.clone(), b.clone(), c.clone()];
    NurbsSurface::create(false, false, 1, 1, 2, 2, &points)
}

/// The patch through the four answered corners.
fn build(input: &Input) -> Result<Made, String> {
    let corners: Vec<Point> = (0..4).filter_map(|index| input.point(index)).collect();
    let corners: [Point; 4] = corners
        .try_into()
        .map_err(|_| "Nurbs Surface 4 Points takes 4 corner points".to_string())?;
    Ok(Made {
        geometries: vec![checked(patch(&corners)?, "surface")?],
        message: "Created a NURBS surface from 4 corners".into(),
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::app::command::tool::surfacing::tests::p;

    /// The corners come back and the middle is their mean.
    #[test]
    fn the_corners_are_reproduced() {
        let corners = [
            p(0., 0., 0.),
            p(100., 0., 0.),
            p(100., 100., 50.),
            p(0., 100., 0.),
        ];
        let surface = patch(&corners).unwrap();
        let (u, v) = (surface.domain(0).unwrap(), surface.domain(1).unwrap());
        let at = |s: f64, t: f64| {
            surface
                .point_at(u.0 + s * (u.1 - u.0), v.0 + t * (v.1 - v.0))
                .unwrap()
        };
        assert!(at(0., 0.).distance(&corners[0], None) < 1e-9);
        assert!(at(1., 0.).distance(&corners[1], None) < 1e-9);
        assert!(at(1., 1.).distance(&corners[2], None) < 1e-9);
        assert!(at(0., 1.).distance(&corners[3], None) < 1e-9);
        assert!(at(0.5, 0.5).distance(&p(50., 50., 12.5), None) < 1e-9);
        let flat = [p(0., 0., 0.), p(1., 0., 0.), p(2., 0., 0.), p(3., 0., 0.)];
        assert!(patch(&flat).is_err());
    }
}

use crate::app::command::tool::gather::{self, Input, Made, Recipe, Step};
