        assert_eq!(accept("m").0, "Move");
        assert_eq!(parsed("length"), Ok("Length".into()));
        assert_eq!(parsed("VOLUME"), Ok("Volume".into()));
        assert!(parsed("Area 2").is_err());
    }
}

