/// Frames drawn by a headless GPU; every test here needs a native adapter.
#[cfg(not(target_arch = "wasm32"))]
mod gpu {
    use super::*;
    use crate::camera::Camera;
    use crate::engine::gpu::FrameInput;
    use session_rust::{BRep, Color, PointCloud, Vector};

    /// Colors and ids of one frame.
    struct Shot {
        color: Vec<u8>,     // RGBA pixels
        ids: Vec<[u32; 2]>, // object and sub id per pixel
    }

    /// Draw one frame and its id frame.
    fn shot(gpu: &mut Gpu, camera: &Camera) -> Shot {
        let anchor = gpu
            .rebase_anchor(&camera.origin(), camera.distance_world(), 0.0)
            .anchor;
        let input = FrameInput {
            view_proj: camera.view_proj_anchored(4.0 / 3.0, &anchor),
            clear: wgpu::Color::WHITE,
            now_ms: 0.0,
        };
        Shot {
            color: gpu.render_offscreen(&input),
            ids: gpu.render_ids_offscreen(&input),
        }
    }

    /// The ids of a frame as identities; a drawn id must be a live row.
    fn named(scene: &Scene, ids: &[[u32; 2]]) -> Vec<Option<(usize, Rc<str>)>> {
        ids.iter()
            .map(|&[object, _]| {
                (object != 0).then(|| {
                    scene
                        .identity_of(object - 1)
                        .unwrap_or_else(|| panic!("row {} is drawn but dead", object - 1))
                })
            })
            .collect()
    }

    /// A mesh, a BRep, a polyline, a point, a curve, a cloud and two overlapping elements.
    fn solids() -> Session {
        let mut session = Session::new("solids");
        let at = |session: &mut Session, node: Rc<RefCell<TreeNode>>, x: f64, y: f64| {
            let guid = node.borrow().name.clone();
            session.set_xform(&guid, Xform::translation(x, y, 0.0));
        };
        let mesh = session
            .add_mesh(Mesh::create_box(10.0, 10.0, 10.0), None)
            .unwrap();
        at(&mut session, mesh, 0.0, 0.0);
        let brep = session
            .add_brep(BRep::create_box(10.0, 10.0, 10.0), None)
            .unwrap();
        at(&mut session, brep, 20.0, 0.0);
        session.add_polyline(
            Polyline::new(vec![
                p(35.0, -5.0, 0.0),
                p(45.0, 5.0, 0.0),
                p(50.0, -5.0, 0.0),
            ]),
            None,
        );
        let mut point = p(60.0, 0.0, 0.0);
        point.width = 12.0;
        session.add_point(point, None);
        let curve = session.add_nurbscurve(arc(), None).unwrap();
        at(&mut session, curve, 0.0, 20.0);
        let points: Vec<Point> = (0..400)
            .map(|i| p((i % 20) as f64, -20.0 - (i / 20) as f64, 0.0))
            .collect();
        let normals = vec![Vector::new(0.0, 0.0, 1.0); points.len()];
        let colors = vec![Color::red(); points.len()];
        session.add_pointcloud(PointCloud::new(points, normals, colors), None);

        for (x, y) in [(40.0, 30.0), (45.0, 33.0)] {
            let mut element = Element::new("glass");
            element.set_geometry(Mesh::create_box(10.0, 10.0, 10.0));
            let node = session.add_element(element, None);
            at(&mut session, node, x, y);
        }

        session
    }

    /// A headless GPU with the scene loaded and a camera fitted to it.
    fn loaded(session: &Rc<Session>) -> (Gpu, Scene, Camera) {
        let mut gpu = pollster::block_on(Gpu::new_headless(400, 300)).expect("a native adapter");
        gpu.view.show_grid = false;
        gpu.view.opacity = 0.7;
        let mut scene = Scene::new();
        scene.add_file(FileDoc {
            name: "solids".into(),
            session: Rc::clone(session),
            place: Xform::identity(),
            point_px: 0.0,
            display_only: false,
        });
        scene.upload_to(&mut gpu);
        let mut camera = Camera::new();
        camera.fit(&gpu.bounds, 4.0 / 3.0);
        (gpu, scene, camera)
    }

    /// Sync and flush.
    fn commit(scene: &mut Scene, gpu: &mut Gpu) {
        scene.sync();
        scene.upload_to(gpu);
    }

    /// A deleted object leaves no pixel and no id: the frame equals a fresh load without it.
    #[test]
    #[ignore = "requires a native GPU adapter"]
    fn kill_leaves_no_pixels_and_no_ids() {
        let (mut gpu, mut scene, camera) = loaded(&Rc::new(solids()));
        let kinds: [fn(&Geometry) -> bool; 5] = [
            |g| matches!(g, Geometry::Mesh(_)),
            |g| matches!(g, Geometry::BRep(_)),
            |g| matches!(g, Geometry::Polyline(_)),
            |g| matches!(g, Geometry::Point(_)),
            |g| matches!(g, Geometry::PointCloud(_)),
        ];

        for kind in kinds {
            let row = find(&scene, kind).unwrap();
            assert!(scene.delete_row(row));
            commit(&mut scene, &mut gpu);
            let (mut fresh_gpu, fresh, _) = loaded(&scene.docs[0].session);

            for samples in [1, 4] {
                for gpu in [&mut gpu, &mut fresh_gpu] {
                    gpu.view.msaa_forced = Some(samples);
                    gpu.resize(400, 300);
                }

                let after = shot(&mut gpu, &camera);
                let want = shot(&mut fresh_gpu, &camera);
                let differ = after
                    .color
                    .chunks_exact(4)
                    .zip(want.color.chunks_exact(4))
                    .filter(|(a, b)| a != b)
                    .count();
                assert_eq!(differ, 0, "{samples}x: pixels differ from a fresh load");
                assert_eq!(named(&scene, &after.ids), named(&fresh, &want.ids));
            }
        }
    }

    /// Delete, create, a count-changing trim and a cancelled drag, undone: the same pixels and ids.
    #[test]
    #[ignore = "requires a native GPU adapter"]
    fn edit_then_undo_is_pixel_and_id_identical() {
        let (mut gpu, mut scene, camera) = loaded(&Rc::new(solids()));

        for samples in [1, 4] {
            gpu.view.msaa_forced = Some(samples);
            gpu.resize(400, 300);
            let before = shot(&mut gpu, &camera);
            let same = |gpu: &mut Gpu, label: &str| {
                let now = shot(gpu, &camera);
                assert!(now.color == before.color, "{samples}x {label}: pixels");
                assert!(now.ids == before.ids, "{samples}x {label}: ids");
            };

            let element = find(&scene, |g| matches!(g, Geometry::Element(_))).unwrap();
            assert!(scene.delete_row(element));
            commit(&mut scene, &mut gpu);
            assert!(scene.undo());
            commit(&mut scene, &mut gpu);
            same(&mut gpu, "delete, undo");

            scene.model(&point::SPEC, &[[5.0, 5.0, 5.0]]).unwrap();
            commit(&mut scene, &mut gpu);
            assert!(scene.undo());
            commit(&mut scene, &mut gpu);
            same(&mut gpu, "create, undo");

            let curve = find(&scene, |g| matches!(g, Geometry::NurbsCurve(_))).unwrap();
            scene.selected = Some(curve);
            scene.edit_interval(Interval::Extend(-0.5, 1.5)).unwrap();
            commit(&mut scene, &mut gpu);
            assert!(scene.undo());
            commit(&mut scene, &mut gpu);
            same(&mut gpu, "trim, undo");

            let source = scene.geometry(curve).unwrap().clone();
            let Geometry::NurbsCurve(original) = &source else {
                panic!()
            };
            let mut grown = (**original).clone();
            let (lo, hi) = grown.domain();
            assert!(grown.extend(lo, hi + (hi - lo)));
            scene.redraw(curve, &Geometry::NurbsCurve(Rc::new(grown)), true);
            scene.upload_to(&mut gpu);
            scene.redraw(curve, &source, false);
            scene.upload_to(&mut gpu);
            same(&mut gpu, "drag, cancel");
        }
    }

    /// Arrowheads follow set, move, copy and undo: each frame equals a fresh load of the document.
    #[test]
    #[ignore = "requires a native GPU adapter"]
    fn arrowheads_follow_edits() {
        use session_rust::Arrowhead;

        let mut session = Session::new("heads");
        // not flat, so the document loads as models, not as a drawing sheet
        session.add_polyline(
            Polyline::new(vec![
                p(0.0, 0.0, 0.0),
                p(20.0, 10.0, 5.0),
                p(40.0, 0.0, 10.0),
            ]),
            None,
        );
        session.add_nurbscurve(arc(), None);
        let (mut gpu, mut scene, camera) = loaded(&Rc::new(session));
        let before = shot(&mut gpu, &camera);
        let fresh = |scene: &Scene, gpu: &mut Gpu, label: &str| {
            let (mut fresh_gpu, _, _) = loaded(&scene.docs[0].session);
            let want = shot(&mut fresh_gpu, &camera);
            assert!(
                shot(gpu, &camera).color == want.color,
                "{label}: pixels differ from a fresh load"
            );
        };
        let rows: Vec<u32> = (0..scene.object_count() as u32).collect();
        let edits = rows
            .iter()
            .map(|&row| {
                let geometry = match scene.geometry(row).unwrap() {
                    Geometry::Polyline(pl) => {
                        let mut pl = (**pl).clone();
                        pl.arrowhead = Arrowhead::BOTH;
                        Geometry::Polyline(Rc::new(pl))
                    }
                    Geometry::NurbsCurve(c) => {
                        let mut c = (**c).clone();
                        c.arrowhead = Arrowhead::END;
                        Geometry::NurbsCurve(Rc::new(c))
                    }
                    _ => panic!("a curve"),
                };
                (row, geometry)
            })
            .collect();
        scene.replace_rows(edits, "arrowhead").unwrap();
        commit(&mut scene, &mut gpu);
        assert!(
            shot(&mut gpu, &camera).color != before.color,
            "the heads draw"
        );
        fresh(&scene, &mut gpu, "heads");

        scene
            .transform_rows(&rows, &Xform::translation(5.0, 5.0, 0.0), "move")
            .unwrap();
        commit(&mut scene, &mut gpu);
        fresh(&scene, &mut gpu, "move");

        scene
            .copy_rows(&rows, &Xform::translation(0.0, -30.0, 0.0))
            .unwrap();
        commit(&mut scene, &mut gpu);
        fresh(&scene, &mut gpu, "copy");

        // selected, every head turns yellow; hidden, nothing is drawn
        let dark = |rgba: &[u8]| {
            rgba.chunks_exact(4)
                .filter(|c| c[0] < 128 && c[1] < 128)
                .count()
        };
        let all: Vec<u32> = (0..64)
            .filter(|&row| scene.identity_of(row).is_some())
            .collect();
        assert_eq!(all.len(), 4, "two curves and their copies");
        assert!(dark(&shot(&mut gpu, &camera).color) > 100);

        for &row in &all {
            gpu.set_selected(row, true);
        }

        assert_eq!(
            dark(&shot(&mut gpu, &camera).color),
            0,
            "no black head while selected"
        );

        for &row in &all {
            gpu.set_selected(row, false);
            gpu.set_hidden(row, true);
        }

        assert_eq!(
            dark(&shot(&mut gpu, &camera).color),
            0,
            "hidden heads draw nothing"
        );

        for &row in &all {
            gpu.set_hidden(row, false);
        }

        // a clipping plane with every curve on its cut side leaves no head behind
        use crate::app::clipping::{Mode, clip_plane, plane_from};
        let plane = plane_from(
            Mode::Normal,
            &[[-1000.0, 0.0, 0.0], [-999.0, 0.0, 0.0]],
            2000.0,
        )
        .unwrap();
        gpu.set_clip_planes(&[clip_plane(&plane, &Xform::identity()).unwrap()]);
        assert_eq!(
            dark(&shot(&mut gpu, &camera).color),
            0,
            "clipped heads draw nothing"
        );
        gpu.set_clip_planes(&[]);

        for _ in 0..3 {
            assert!(scene.undo());
            commit(&mut scene, &mut gpu);
        }

        let back = shot(&mut gpu, &camera);
        assert!(back.color == before.color, "undo takes the heads off");
        assert!(back.ids == before.ids, "undo restores the ids");
    }

    /// A compaction draws what a fresh load draws, ids mapped by identity, and shrinks the lanes.
    #[test]
    #[ignore = "requires a native GPU adapter"]
    fn compaction_is_exact_and_shrinks() {
        let (mut gpu, mut scene, camera) = loaded(&Rc::new(solids()));
        let mut dice = Dice(9);

        for _ in 0..60 {
            edit(&mut scene, &mut dice);
            commit(&mut scene, &mut gpu);
        }

        assert!(scene.dead.bytes() > 0);
        scene.rewalk_editable(&mut gpu);
        let (mut fresh_gpu, fresh, _) = loaded(&scene.docs[0].session);
        let mut extra = Vec::new();

        for file in &scene.docs[1..] {
            extra.push(FileDoc {
                name: file.name.clone(),
                session: Rc::clone(&file.session),
                place: file.place.clone(),
                point_px: file.point_px,
                display_only: false,
            });
        }

        let mut fresh = fresh;
        fresh.created_doc = scene.created_doc;

        for doc in extra {
            fresh.add_file(doc);
            fresh.upload_to(&mut fresh_gpu);
        }

        for samples in [1, 4] {
            for gpu in [&mut gpu, &mut fresh_gpu] {
                gpu.view.msaa_forced = Some(samples);
                gpu.resize(400, 300);
            }

            let after = shot(&mut gpu, &camera);
            let want = shot(&mut fresh_gpu, &camera);
            assert!(after.color == want.color, "{samples}x: pixels");
            assert_eq!(named(&scene, &after.ids), named(&fresh, &want.ids));
            let subs = |shot: &Shot| shot.ids.iter().map(|id| id[1]).collect::<Vec<_>>();
            assert_eq!(
                subs(&after),
                subs(&want),
                "{samples}x: lane rows as a fresh load"
            );
        }

        let lanes = |gpu: &Gpu| {
            gpu.arena.allocated_bytes()
                + gpu.segments.allocated_bytes()
                + gpu.glyphs.allocated_bytes()
        };
        assert_eq!(
            lanes(&gpu),
            lanes(&fresh_gpu),
            "lanes as small as a fresh load"
        );
    }

    /// Time the phases of one edit in a scene the size of `view_lines`: kernel, sync, flush.
    #[test]
    #[ignore = "requires a native GPU adapter"]
    fn bench_edit_phases() {
        let mut gpu = pollster::block_on(Gpu::new_headless(400, 300)).expect("a native adapter");
        let mut scene = Scene::new();

        for doc in 0..9 {
            let mut session = Session::new(&format!("sheet {doc}"));

            for i in 0..80_000 {
                let x = (i % 400) as f64;
                let y = (i / 400) as f64 + doc as f64 * 300.0;
                session.add_line(Line::new(x, y, 0.0, x + 0.5, y + 0.5, 0.0), None);
            }

            scene.add_file(file(&format!("sheet {doc}"), session, Xform::identity()));
            scene.upload_to(&mut gpu);
        }

        let ms = |start: std::time::Instant| start.elapsed().as_secs_f64() * 1e3;
        let mut phases = Vec::new();

        for round in 0..5 {
            let t = std::time::Instant::now();
            let (doc, guid) = scene
                .model(&point::SPEC, &[[round as f64, 0.0, 0.0]])
                .unwrap();
            let kernel = ms(t);
            let t = std::time::Instant::now();
            scene.sync();
            let sync = ms(t);
            let t = std::time::Instant::now();
            scene.upload_to(&mut gpu);
            let flush = ms(t);
            let row = scene.row_of(doc, &guid).unwrap();
            let t = std::time::Instant::now();
            scene.delete_row(row);
            scene.sync();
            scene.upload_to(&mut gpu);
            let delete = ms(t);
            let t = std::time::Instant::now();
            scene.undo();
            scene.sync();
            scene.upload_to(&mut gpu);
            let undo = ms(t);
            phases.push(format!(
                "create {kernel:.2}+{sync:.2}+{flush:.2} ms, delete {delete:.2} ms, undo {undo:.2} ms"
            ));
        }

        eprintln!("{} objects:\n{}", scene.object_count(), phases.join("\n"));
    }

    /// Streamed sheet segments and cloud points survive edits and both compactions.
    #[test]
    #[ignore = "requires a native GPU adapter"]
    fn streamed_rows_survive_edits_and_compaction() {
        let (mut gpu, mut scene, camera) = loaded(&Rc::new(solids()));
        shells(&mut scene);
        scene.upload_to(&mut gpu);
        let sheet = scene.sheets[0].row;
        let cloud = scene.streamed[0].row;
        let points = |gpu: &Gpu| {
            let found = gpu
                .cloud
                .clouds
                .iter()
                .find(|c| c.instance == cloud)
                .unwrap();
            (found.resident, found.chunks.len())
        };
        let before = points(&gpu);
        let entity = |gpu: &Gpu| {
            (0..gpu.segments.ribbon_count())
                .filter_map(|row| {
                    gpu.segments
                        .row_of(row)
                        .map(|hit| (hit, gpu.segments.source_id(row)))
                })
                .collect::<Vec<_>>()
        };
        let entities = entity(&gpu);
        assert_eq!(entities.len(), 2);

        // a document cloud dies and comes back from its tomb, nothing uploaded; purged, its points are dead
        let row = find(&scene, |g| matches!(g, Geometry::PointCloud(_))).unwrap();
        let resident = gpu.cloud.point_count;

        for _ in 0..3 {
            assert!(scene.delete_row(row));
            commit(&mut scene, &mut gpu);
            assert!(scene.undo());
            commit(&mut scene, &mut gpu);
        }

        assert_eq!(
            gpu.cloud.point_count, resident,
            "an undo draws the buried cloud again"
        );
        let doc = scene.identity_of(row).unwrap().0;
        assert!(scene.delete_row(row));
        Rc::make_mut(&mut scene.docs[doc].session).purge();
        commit(&mut scene, &mut gpu);
        assert!(scene.dead_points > 0);

        let mut dice = Dice(21);

        for _ in 0..40 {
            edit(&mut scene, &mut dice);
            commit(&mut scene, &mut gpu);
        }

        scene.compact_clouds(&mut gpu);
        scene.rewalk_editable(&mut gpu);
        assert_eq!(points(&gpu), before, "the streamed cloud keeps its points");
        assert_eq!(gpu.cloud.point_count, gpu.cloud.resident());
        assert_eq!(entity(&gpu), entities, "sheet segments keep their entities");
        assert_eq!(
            scene.identity_of(sheet).map(|id| id.1.to_string()),
            Some("sheet:plan.pb".into())
        );
        let now = shot(&mut gpu, &camera);
        assert!(named(&scene, &now.ids).iter().flatten().count() > 0);
    }
}

// Split: cut a curve, or one face of a surface or solid, with cutter curves; the kernel does the geometry.
use super::scene::{Scene, sync};
use session_rust::simple_split;
use session_rust::{BRep, Geometry, NurbsCurve, TreeNode};
use std::cell::RefCell;
use std::rc::Rc;

/// True for a geometry that can cut: a line, polyline or curve.
pub fn is_cutter(geometry: &Geometry) -> bool {
    matches!(
        geometry,
        Geometry::Line(_) | Geometry::Polyline(_) | Geometry::NurbsCurve(_)
    )
}

/// The face to split: None for a curve, the selected face for a BRep.
pub fn face_index(geometry: &Geometry, selected: Option<usize>) -> Result<Option<usize>, String> {
    match geometry {
        Geometry::Line(_)
        | Geometry::Polyline(_)
        | Geometry::NurbsCurve(_)
        | Geometry::NurbsSurface(_) => Ok(None),
        Geometry::BRep(brep) => brep_face(brep, selected).map(Some),
        Geometry::Element(element) => match element.geometry() {
            session_rust::element::ElementGeometry::BRep(brep) => {
                brep_face(brep, selected).map(Some)
            }
            _ => Err("Split accepts curves and NURBS/BRep faces".into()),
        },
        _ => Err("Split accepts lines, polylines, NURBS curves and surface faces".into()),
    }
}

/// The selected face, or the only one.
fn brep_face(brep: &BRep, selected: Option<usize>) -> Result<usize, String> {
    selected
        .or((brep.face_count() == 1).then_some(0))
        .filter(|face| *face < brep.face_count())
        .ok_or_else(|| {
            "Ctrl+Shift-select one BRep face before Split; the solid stays joined".into()
        })
}

/// A cutter as a NURBS curve.
fn curve(geometry: &Geometry) -> Result<NurbsCurve, String> {
    // a line or polyline is a NURBS curve of degree 1, so one kernel routine cuts with all three
    match geometry {
        Geometry::Line(line) => Ok(NurbsCurve::create(
            false,
            1,
            &[line.point_at(0.), line.point_at(1.)],
        )),
        Geometry::Polyline(polyline) => Ok(NurbsCurve::create(false, 1, &polyline.get_points())),
        Geometry::NurbsCurve(curve) => Ok((**curve).clone()),
        _ => Err("Choose a line, polyline or NURBS curve as cutter".into()),
    }
}

impl Scene {
    /// Split `target` by the cutters; returns how many pieces.
    pub fn split_rows(
        &mut self,
        target: u32,
        face: Option<usize>,
        cutters: &[u32],
    ) -> Result<usize, String> {
        if cutters.is_empty() || cutters.len() > 64 {
            return Err("Choose 1–64 cutter curves".into());
        }

        if !self.selectable(target) {
            return Err("Unlock the target before splitting".into());
        }

        let (doc, guid) = self.identity_of(target).ok_or("Target no longer exists")?;
        let file = self.docs.get(doc).ok_or("Target has no source document")?;

        if file.display_only {
            return Err("Target is display only".into());
        }

        let back = self
            .placement_of(target)
            .ok_or("Target has no placement")?
            .inverse()
            .ok_or("Target placement is singular")?; // world into the target's frame
        let mut tools = Vec::new(); // cutters in the target's frame

        for &row in cutters {
            if row == target || !self.selectable(row) {
                return Err("Choose an unlocked cutter distinct from the target".into());
            }

            let mut cutter = curve(self.geometry(row).ok_or("Cutter no longer exists")?)?;
            let place = self.placement_of(row).ok_or("Cutter has no placement")?;

            if place.inverse().is_none() {
                return Err("Cannot transform the cutter into target coordinates".into());
            }

            // cutter frame to world, then world to target frame, as one matrix
            cutter.transform(&(&back * &place));
            tools.push(cutter);
        }

        let source = self
            .geometry(target)
            .ok_or("Source geometry is unavailable")?;
        let face = face_index(source, face)?;
        let tolerance = 1e-6; // closer than a millionth of a unit counts as touching
        // the new geometries and how many regions the cut made
        let (mut pieces, regions) = match source {
            Geometry::Line(line) => {
                let pieces: Vec<_> = simple_split::split_line_by_curves(line, &tools, tolerance)?
                    .into_iter()
                    .map(|p| Geometry::Line(Rc::new(p)))
                    .collect();
                let count = pieces.len();
                (pieces, count)
            }
            Geometry::Polyline(line) => {
                let pieces: Vec<_> =
                    simple_split::split_polyline_by_curves(line, &tools, tolerance)?
                        .into_iter()
                        .map(|p| Geometry::Polyline(Rc::new(p)))
                        .collect();
                let count = pieces.len();
                (pieces, count)
            }
            Geometry::NurbsCurve(curve) => {
                let pieces: Vec<_> = simple_split::split_curve_by_curves(curve, &tools, tolerance)?
                    .into_iter()
                    .map(|p| Geometry::NurbsCurve(Rc::new(p)))
                    .collect();
                let count = pieces.len();
                (pieces, count)
            }
            Geometry::NurbsSurface(surface) => {
                let mut brep = simple_split::split_surface_by_curves(surface, &tools, tolerance)?;
                brep.name = surface.name.clone();
                let count = brep.face_count();
                (vec![Geometry::BRep(Rc::new(brep))], count)
            }
            Geometry::BRep(brep) => {
                let next = simple_split::split_brep_face_by_curves(
                    brep,
                    face.ok_or("Select a face")?,
                    &tools,
                    tolerance,
                )?;
                let count = next.face_count() - brep.face_count() + 1;
                (vec![Geometry::BRep(Rc::new(next))], count)
            }
            Geometry::Element(element) => {
                let session_rust::element::ElementGeometry::BRep(brep) = element.geometry() else {
                    return Err("Element has no BRep".into());
                };
                let next = simple_split::split_brep_face_by_curves(
                    brep,
                    face.ok_or("Select a face")?,
                    &tools,
                    tolerance,
                )?;
                let count = next.face_count() - brep.face_count() + 1;
                let mut result = (**element).clone();
                result.set_brep_geometry(next);
                (vec![Geometry::Element(Rc::new(result))], count)
            }
            _ => return Err("Unsupported split target".into()),
        };

        if regions < 2 {
            return Ok(1); // nothing was cut
        }

        // the pieces inherit the parent, placement and colours
        let parent = self
            .node_of(target)
            .and_then(|(node, in_tree)| in_tree.then(|| node.borrow().parent()).flatten());
        let place = file.session.xform(&guid);
        let color = self.colors.get(&(doc, Rc::clone(&guid))).copied();
        let edge_color = self.edge_colors.get(&(doc, Rc::clone(&guid))).copied();

        // name the pieces `x (part 1)`, `x (part 2)`...
        if pieces.len() > 1 {
            let name = source.name();

            for (index, piece) in pieces.iter_mut().enumerate() {
                let name = format!("{name} (part {})", index + 1);

                match piece {
                    Geometry::Line(p) => Rc::make_mut(p).name = name,
                    Geometry::Polyline(p) => Rc::make_mut(p).name = name,
                    Geometry::NurbsCurve(p) => Rc::make_mut(p).name = name,
                    _ => unreachable!("only curves create sibling objects"),
                }
            }
        }

        // the first piece replaces the target, the rest are added beside it
        let first = pieces.remove(0);
        let session = Rc::make_mut(&mut self.docs[doc].session);
        // a copied session has its own nodes
        let parent = parent.and_then(|node| {
            let name = node.borrow().name.clone();

            if session
                .tree
                .root()
                .is_some_and(|root| Rc::ptr_eq(&root, &top(&node)))
            {
                Some(node)
            } else {
                session.tree.get_node_by_name(&name)
            }
        });
        let mut made = Vec::new();
        session.begin("split");
        let replaced = session.replace(&guid, first);
        debug_assert!(replaced); // checked in debug builds only; a release build drops the test

        for piece in pieces {
            let node = match piece {
                Geometry::Line(piece) => session.add_line((*piece).clone(), parent.as_ref()),
                Geometry::Polyline(piece) => session
                    .add_polyline((*piece).clone(), parent.as_ref())
                    .expect("valid split polyline"),
                Geometry::NurbsCurve(piece) => session
                    .add_nurbscurve((*piece).clone(), parent.as_ref())
                    .expect("valid split curve"),
                _ => unreachable!("only curves create sibling objects"),
            };
            let id = node.borrow().name.clone();
            session.set_xform(&id, place.clone());
            made.push(node);

            if let Some(color) = color {
                self.colors.insert((doc, Rc::from(id.as_str())), color);
            }

            if let Some(color) = edge_color {
                self.edge_colors.insert((doc, Rc::from(id.as_str())), color);
            }
        }

        let notes = sync::commit(session);
        self.noted(doc, notes);

        for node in &made {
            self.hint(doc, node);
        }

        self.edited(&[doc]);
        Ok(regions)
    }
}

/// The top of the tree a node hangs in.
fn top(node: &Rc<RefCell<TreeNode>>) -> Rc<RefCell<TreeNode>> {
    let mut top = Rc::clone(node);

    loop {
        let parent = top.borrow().parent();

        match parent {
            Some(parent) => top = parent,
            None => return top,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::app::scene::FileDoc;
    use session_rust::Xform;
    use session_rust::{Line, Point, Session};

    /// Add one placed document.
    fn add(scene: &mut Scene, session: Rc<Session>, name: &str, place: Xform) {
        scene.add_file(FileDoc {
            name: name.into(),
            session,
            place,
            point_px: 0.,
            display_only: false,
        });
    }

    /// A split keeps the group, placement and other placements; undo reverses it.
    #[test]
    fn split_preserves_tree_placement_and_other_shared_documents_and_undo() {
        let mut session = Session::new("shared");
        let group = session.add_group("parts");
        session.set_xform(&group.borrow().name, Xform::translation(10., 0., 0.));
        let target = session.add_line(
            Line::from_points(&Point::new(-2., 0., 0.), &Point::new(2., 0., 0.)),
            Some(&group),
        );
        let id = target.borrow().name.clone();
        let shared = Rc::new(session);
        let mut scene = Scene::new();
        add(
            &mut scene,
            Rc::clone(&shared),
            "first",
            Xform::translation(100., 0., 0.),
        );
        add(
            &mut scene,
            Rc::clone(&shared),
            "second",
            Xform::translation(200., 0., 0.),
        );
        let mut cutters = Session::new("cutters");
        cutters.add_line(
            Line::from_points(&Point::new(110., -2., 0.), &Point::new(110., 2., 0.)),
            None,
        );
        add(&mut scene, Rc::new(cutters), "cutters", Xform::identity());
        scene
            .colors
            .insert(scene.identity_of(0).unwrap(), [60, 170, 100]);
        assert_eq!(scene.split_rows(0, None, &[2]).unwrap(), 2);
        let first = &scene.docs[0].session;
        assert_eq!(first.objects.lines.len(), 2);
        assert_eq!(scene.docs[1].session.objects.lines.len(), 1);
        assert_eq!(shared.objects.lines.len(), 1);
        let parent = first.tree.get_node_by_name("parts").unwrap();
        assert_eq!(parent.borrow().children().len(), 2);
        assert_eq!(
            shared
                .tree
                .get_node_by_name("parts")
                .unwrap()
                .borrow()
                .children()
                .len(),
            1
        );
        assert!(first.lookup.contains_key(&id));
        let Geometry::Line(line) = &first.lookup[&id] else {
            panic!()
        };
        assert!(line.point_at(1.).distance(&Point::new(0., 0., 0.), None) < 1e-6);
        assert_eq!(scene.colors.len(), 2);
        assert!(scene.undo());
