pub const SPEC: Spec = Spec {
    options: &["Opacity 1", "Opacity 0.7", "Opacity 0.4", "Opacity 0"],
    wait_for_option: true,
    ..Spec::new(
        &["Opacity"],
        "Opacity 0..1: how solid the faces are · 0 is x-ray, 1 solid · Example: Opacity 0.5",
        parse,
    )
