//! Render one headless frame of the given scenes and print the ink count.

use session_viewer::selftest::{SceneFile, render_scene};

/// A logger that prints every record to stderr.
struct StderrLog;

impl log::Log for StderrLog {
    /// Every level is on.
    fn enabled(&self, _: &log::Metadata) -> bool {
        true
    }

    /// Print one record.
    fn log(&self, r: &log::Record) {
        eprintln!("[{}] {}", r.level(), r.args());
    }

    /// Nothing is buffered.
    fn flush(&self) {}
}

/// Parse `<out.ppm> <scenes>...` and the VIEWER_W / VIEWER_H size, then render.
fn main() {
    let _ = log::set_logger(&StderrLog);
    log::set_max_level(log::LevelFilter::Info);
    let args: Vec<String> = std::env::args().skip(1).collect();
    let out = args.first().cloned().unwrap_or_else(|| "out.ppm".into());
    let files = SceneFile::from_args(&args[1.min(args.len())..]);
    let w = std::env::var("VIEWER_W")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(900);
    let h = std::env::var("VIEWER_H")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(700);
    print!("{}", render_scene(&files, w, h, &out));
}

//! Native harness: render a scene to a file without a browser.
//! A harness is a small program that drives the viewer from a terminal: load files, draw off screen, write an image.

use crate::app::manifest::Manifest;
use crate::app::scene::{FileDoc, Scene};
use crate::camera::FOVY_DEG;
use crate::camera::{Camera, View};
use crate::engine::gpu::{FrameInput, Gpu, Pick};
use crate::engine::performance::now_ms;
use crate::engine::text::{TextLabel, TextPlacement};
use session_rust::{Session, Xform};
use std::rc::Rc;

/// Background color.
const CLEAR: wgpu::Color = wgpu::Color {
    r: 0.9,
    g: 0.9,
    b: 0.9,
    a: 1.0,
};

/// One file to load.
pub struct SceneFile {
    pub path: String,       // the .pb file
    pub place: Xform,       // where it goes in the scene
    pub point_px: f32,      // point size, 0 for the default
    pub display_only: bool, // drop the source after upload
}

impl SceneFile {
    /// Files from the command line: manifests or single .pb files.
    pub fn from_args(args: &[String]) -> Vec<SceneFile> {
        let mut out = Vec::new();
        for p in args {
            // a plain .pb at the origin
            if !(p.ends_with(".json") || p.ends_with(".yaml") || p.ends_with(".yml")) {
                out.push(SceneFile {
                    path: p.clone(),
                    place: Xform::identity(),
                    point_px: 0.0,
                    display_only: false,
                });
                continue;
            }
            // panic! stops the program with a message: fine for a tool run by hand, never inside the viewer
            let bytes =
                std::fs::read(p).unwrap_or_else(|e| panic!("cannot read manifest {p}: {e}"));
            let man = Manifest::parse(&bytes)
                .unwrap_or_else(|e| panic!("cannot parse manifest {p}: {e}"));
            let root = assets_root(p, &man);
            // every file the manifest lists, placed as it says
            for (i, item) in man.items.iter().enumerate() {
                let path = root.join(&item.file).to_string_lossy().into_owned();
                out.push(SceneFile {
                    path,
                    place: man.place(i, [3000.0, 3000.0]), // unplaced items fill a grid of 3000 x 3000 mm cells
                    point_px: item.point_size as f32,
                    display_only: item.display_only,
                });
            }
        }
        out
    }
}

/// The directory the manifest's files are in: its own, or its parent.
fn assets_root(manifest: &str, man: &Manifest) -> std::path::PathBuf {
    let here = std::path::Path::new(manifest)
        .parent()
        .unwrap_or(std::path::Path::new("."))
        .to_path_buf();
    let first = man
        .items
        .first()
        .map(|i| i.file.clone())
        .unwrap_or_default();
    if here.join(&first).exists() {
        here
    } else {
        here.join("..")
    }
}

/// The camera, set from VIEWER_* environment variables.
// An environment variable is set on the command line in front of the program: `VIEWER_VIEW=top cargo run ...`.
fn camera_from_env(gpu: &Gpu, aspect: f64) -> Camera {
    let mut camera = Camera::new();
    camera.fit(&gpu.bounds, aspect);
    // VIEWER_ORBIT=dx,dy in mouse pixels
    if let Ok(o) = std::env::var("VIEWER_ORBIT") {
        // `.ok()` turns a parse error into None, and filter_map skips it: "10,x" gives just 10
        let mut it = o.split(',').filter_map(|v| v.trim().parse::<f32>().ok());
        camera.orbit(it.next().unwrap_or(0.0), it.next().unwrap_or(0.0));
    }
    // VIEWER_ORTHO=1 for orthographic
    if std::env::var("VIEWER_ORTHO").is_ok() {
        camera.toggle_projection();
    }
    // VIEWER_VIEW=top|bottom|front|right|iso
    if let Ok(v) = std::env::var("VIEWER_VIEW") {
        camera.set_view(match v.as_str() {
            "top" => View::Top,
            "bottom" => View::Bottom,
            "front" => View::Front,
            "right" => View::Right,
            _ => View::Iso,
        });
    }
    // VIEWER_ZOOM=N wheel steps, negative zooms out
    if let Ok(z) = std::env::var("VIEWER_ZOOM") {
        let n: i32 = z.trim().parse().unwrap_or(0);
        for _ in 0..n.abs() {
            camera.zoom(if n > 0 { 1.0 } else { -1.0 });
        }
    }
    // VIEWER_DISTANCE_SCALE=k multiplies the distance
    if let Ok(value) = std::env::var("VIEWER_DISTANCE_SCALE") {
        let scale: f64 = value
            .parse()
            .expect("VIEWER_DISTANCE_SCALE must be a number");
        assert!(
            scale.is_finite() && scale > 0.0,
            "VIEWER_DISTANCE_SCALE must be positive and finite"
        );
        camera.distance *= scale;
        camera.update_position();
    }
    report_camera(&camera);
    camera
}

/// Log the camera in scene units.
fn report_camera(camera: &Camera) {
    let units = camera.unit.to_meters();
    let eye = camera.position.map(|v| v / units); // meters to scene units
    let target = camera.target.map(|v| v / units);
    // from_fn builds a 3-element array by calling the closure with i = 0, 1, 2
    let forward = std::array::from_fn::<_, 3, _>(|i| {
        (camera.target[i] - camera.position[i]) / camera.distance
    });
    // half the view height, orthographic only
    let ortho_h = if camera.perspective {
        0.0
    } else {
        camera.distance_world() * (FOVY_DEG * 0.5).to_radians().tan()
    };
    log::info!(
        "camera: eye ({:.6}, {:.6}, {:.6}) mm, target ({:.6}, {:.6}, {:.6}) mm, distance {:.6} mm",
        eye[0],
        eye[1],
        eye[2],
        target[0],
        target[1],
        target[2],
        camera.distance_world()
    );
    // the same camera in the form census_plates reads back, so both tools draw from one eye
    log::info!(
        "census camera: CENSUS_EYE={:.12},{:.12},{:.12} CENSUS_FWD={:.12},{:.12},{:.12} CENSUS_UP={:.12},{:.12},{:.12} CENSUS_ORTHO_H={:.9}",
        camera.position[0],
        camera.position[1],
        camera.position[2],
        forward[0],
        forward[1],
        forward[2],
        camera.up[0],
        camera.up[1],
        camera.up[2],
        ortho_h
    );
}

/// Load every file into the scene, then upload once.
fn load_files(scene: &mut Scene, gpu: &mut Gpu, files: &[SceneFile]) {
    for f in files {
        let t0 = std::time::Instant::now();
        let bytes =
            std::fs::read(&f.path).unwrap_or_else(|e| panic!("cannot read {}: {e}", f.path));
        let session =
            Session::pb_loads(&bytes).unwrap_or_else(|e| panic!("cannot parse {}: {e:?}", f.path));
        let t1 = t0.elapsed();
        let name = f.path.rsplit('/').next().unwrap_or(&f.path).to_string();
        scene.add_file(FileDoc {
            name: name.clone(),
            session: Rc::new(session),
            place: f.place.clone(),
            point_px: f.point_px,
            display_only: f.display_only,
        });
        println!(
            "  {name}: {:.1} MB | decode {t1:?} | walk {:?}",
            bytes.len() as f64 / 1.048576e6,
            t0.elapsed() - t1 // walk time = everything since t0 minus the decode
        );
    }
    scene.upload_to(gpu);
}

/// The matrix and clear color for one frame.
fn frame_input(gpu: &mut Gpu, camera: &Camera, aspect: f64) -> FrameInput {
    let now = now_ms();
    let rebase = gpu.rebase_anchor(&camera.origin(), camera.distance_world(), now);
    FrameInput {
        view_proj: camera.view_proj_anchored(aspect, &rebase.anchor),
        clear: CLEAR,
        now_ms: now,
    }
}

/// Drag frame times by tier, and how long the first slow frames took to reach each tier.
fn report_drag(ms: &[f64], tiers: &[u8]) {
    let percentile = |values: &mut Vec<f64>, p: f64| {
        values.sort_by(f64::total_cmp); // f64 has no sort() because NaN has no order; total_cmp gives every value a place
        values
            .get(((values.len() as f64 - 1.0) * p).round() as usize)
            .copied()
            .unwrap_or(0.0)
    };
    let mut all = ms.to_vec();
    println!(
        "drag: p50 {:.1} ms, p95 {:.1} ms",
        percentile(&mut all, 0.5),
        percentile(&mut all, 0.95)
    );
    // the first frame timed the pause before the drag
    let first_slow = ms.iter().skip(1).position(|t| *t > 33.0).map(|i| i + 1); // 33 ms per frame = 30 fps

    for tier in 1..=crate::engine::performance::TOP_TIER {
        let Some(entered) = tiers.iter().position(|t| *t >= tier) else {
            continue;
        };
        let since = first_slow.map_or(0.0, |start| ms[start..entered].iter().sum::<f64>());
        let mut at: Vec<f64> = ms
            .iter()
            .zip(tiers)
            .filter(|(_, t)| **t == tier)
            .map(|(v, _)| *v)
            .collect();
        println!(
            "drag: tier {tier} from frame {entered}, {since:.0} ms after the first slow frame; p50 {:.1} ms there",
            percentile(&mut at, 0.5)
        );
    }
}

/// Forty labels fixed on screen; with `mixed`, forty nameplates and forty anchors in the scene too.
fn bench_labels(gpu: &Gpu, mixed: bool) -> Vec<TextLabel> {
    let b = &gpu.bounds;
    let label = |id: u32, placement| TextLabel {
        id,
        object: None,
        text: format!("Label {id} of the bench"),
        font_size: 14.0,
        line_height: 20.0,
        color: [0, 0, 0, 255],
        placement,
        clip: None,
    };
    let mut labels = Vec::new();

    for i in 0..40u32 {
        let (left, top) = (20.0 + (i % 4) as f32 * 180.0, 20.0 + (i / 4) as f32 * 24.0);
        labels.push(label(i + 1, TextPlacement::Screen { left, top }));

        if mixed {
            // spread over the scene box
            let t = f64::from(i) / 40.0;
            let world = [
                b.cx + b.hx * (t * 2.0 - 1.0),
                b.cy + b.hy * (1.0 - t * 2.0),
                b.cz,
            ];
            let padding = [6.0, 3.0];
            labels.push(label(
                i + 101,
                TextPlacement::Nameplate {
                    world,
                    padding,
                    rounded: true,
                },
            ));
            labels.push(label(
                i + 201,
                TextPlacement::Anchor {
                    world,
                    offset: [0.0, 12.0],
                },
            ));
        }
    }

    labels
}

/// Up to six clipping planes through the middle of `bounds`, each cutting a different side.
fn middle_planes(
    bounds: &session_rust::AABB,
    count: usize,
) -> Vec<crate::engine::gpu::clip::ClipPlane> {
    use crate::app::clipping::{Mode, clip_plane, plane_from};
    let c = [bounds.cx, bounds.cy, bounds.cz];
    let h = [bounds.hx, bounds.hy, bounds.hz];
    // (axis, sign): the side cut away, a fifth of the way out from the middle
    let sides = [
        (2, 1.0),
        (0, 1.0),
        (1, 1.0),
        (2, -1.0),
        (0, -1.0),
        (1, -1.0),
    ];
    let mut planes = Vec::new();

    for &(axis, sign) in sides.iter().take(count.min(6)) {
        let mut origin = c;
        origin[axis] += sign * h[axis] * 0.2;
        let mut normal = origin;
        normal[axis] += sign;
        // Mode::Normal reads two points: the origin, then a point one unit along the normal
        let plane = plane_from(Mode::Normal, &[origin, normal], h[0].max(h[1]).max(h[2]))
            .expect("a plane through the scene");
        planes.extend(clip_plane(&plane, &Xform::identity()));
    }

    planes
}

/// Write RGBA pixels as a PPM image.
// PPM is the simplest image file: a text header `P6 width height 255`, then 3 bytes per pixel.
// pub(crate): visible to every module of this crate (lifecycle.rs uses it), hidden from other crates.
pub(crate) fn write_ppm(path: &str, rgba: &[u8], w: u32, h: u32) -> std::io::Result<()> {
    use std::io::Write;
    let mut f = std::io::BufWriter::new(std::fs::File::create(path)?); // collects small writes into large ones
    write!(f, "P6\n{w} {h}\n255\n")?;
    for px in rgba.chunks_exact(4) {
        f.write_all(&px[..3])?; // alpha is dropped
    }
    f.flush()
}

/// Load, frame, draw one frame and write it to `out`.
pub fn render_scene(files: &[SceneFile], w: u32, h: u32, out: &str) -> String {
    // Headless = no window: the frame is drawn into a texture. There is no browser event loop
    // to drive async code natively, so block_on waits for the GPU setup right here.
    let mut gpu = pollster::block_on(Gpu::new_headless(w, h)).expect("headless gpu");
    let mut scene = Scene::new();
    // VIEWER_CLIP=n cuts with n clipping planes through the scene's middle; solids get checked first
    let planes: usize = std::env::var("VIEWER_CLIP")
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(0);

    if planes > 0 {
        crate::app::clipping::verify_solids();
    }

    load_files(&mut scene, &mut gpu, files);
    gpu.set_clip_planes(&middle_planes(&gpu.bounds, planes));
    gpu.find_solids(|row| scene.solid_faces(row));
    // VIEWER_SELECT=name highlights one object
    if let Ok(name) = std::env::var("VIEWER_SELECT") {
        let row = (0..scene.row_count() as u32)
            .find(|row| scene.object_name(*row) == name)
            .unwrap_or_else(|| panic!("VIEWER_SELECT object not found: {name}"));
        scene.selected = Some(row);
        gpu.set_selected(row, true);
    }
    let aspect = w as f64 / h as f64;
    let mut camera = camera_from_env(&gpu, aspect);
    // VIEWER_AO=1 turns ambient occlusion on
    gpu.view.ssao = std::env::var_os("VIEWER_AO").is_some();
    // VIEWER_LABELS=screen|mixed adds labels fixed on screen, or also anchored in the scene
    if let Ok(kind) = std::env::var("VIEWER_LABELS") {
        let labels = bench_labels(&gpu, kind == "mixed");
        gpu.text.set_labels(labels).expect("bench labels");
    }

    // VIEWER_FRAMES=N times N frames first
    if let Some(n) = std::env::var("VIEWER_FRAMES")
        .ok()
        .and_then(|v| v.parse::<usize>().ok())
    {
        // VIEWER_FRAMES_ORBIT=dx orbits by dx mouse pixels before each timed frame
        let step: f32 = std::env::var("VIEWER_FRAMES_ORBIT")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(0.0);
        let mut ms: Vec<f64> = Vec::new();
        // VIEWER_GPU_TIMING=1 also times every pass on the GPU
        gpu.timer = crate::engine::gpu::timing::PassTimer::new(&gpu.ctx);
        let mut text_ms = 0.0;
        let prepared = gpu.text.stats.preparations;
        // VIEWER_INTERACT=1 draws the orbit as a drag, through the drag quality tiers
        let drag = std::env::var_os("VIEWER_INTERACT").is_some();
        let mut tiers = Vec::new();
        gpu.performance.interacting = drag;

        for _ in 0..n.max(1) {
            camera.orbit(step, 0.0);
            let input = frame_input(&mut gpu, &camera, aspect);
            let before = gpu.text.stats.preparations;
            let t = std::time::Instant::now();
            let _ = gpu.render_offscreen(&input); // `let _ =` drops the pixels: only the time counts here
            ms.push(t.elapsed().as_secs_f64() * 1000.0);
            tiers.push(gpu.performance.drag_tier());

            if drag {
                gpu.performance.frame(0, 0, now_ms(), false);
            }

            if gpu.text.stats.preparations > before {
                text_ms += gpu.text.stats.preparation_ms;
            }
        }

        gpu.performance.interacting = false;

        if drag {
            report_drag(&ms, &tiers);
        }

        camera.orbit(-step * n.max(1) as f32, 0.0); // back to the start, so the saved image is the untimed view
        ms.sort_by(|a, b| a.partial_cmp(b).unwrap());
        println!(
            "frames: n={} median {:.1} ms ({:.0} fps) min {:.1} max {:.1}",
            ms.len(),
            ms[ms.len() / 2],
            1000.0 / ms[ms.len() / 2],
            ms[0],
            ms[ms.len() - 1]
        );

        // take() moves the timer out and leaves None, so later frames are not timed
        if let Some(timer) = gpu.timer.take() {
            let spans: Vec<String> = timer
                .medians()
                .iter()
                .map(|(label, ms)| format!("{label} {ms:.3}"))
                .collect();
            println!("gpu ms, median per pass: {}", spans.join(", "));
            let (buffers, textures) = gpu.allocated_bytes();
            let tiles = gpu.arena.tiles.allocated_bytes().0;
            println!("gpu bytes: buffers {buffers}, textures {textures}, tile tables {tiles}");
            let count = gpu.text.stats.preparations - prepared;
            println!(
                "text: {count} preparations, {:.4} ms each, {:.4} ms per frame",
                text_ms / count.max(1) as f64,
                text_ms / n.max(1) as f64
            );
        }
    }

    let input = frame_input(&mut gpu, &camera, aspect);
    let rgba = gpu.render_offscreen(&input);
    write_ppm(out, &rgba, w, h).expect("write ppm");
    // VIEWER_IDS=path writes the id frame
    if let Ok(path) = std::env::var("VIEWER_IDS") {
        write_ids(&mut gpu, &scene, &input, &path);
    }

    // VIEWER_PICK=x,y reports what is under that pixel
    if let Ok(v) = std::env::var("VIEWER_PICK") {
        let mut it = v.split(',').filter_map(|t| t.trim().parse::<u32>().ok());
        if let (Some(px), Some(py)) = (it.next(), it.next()) {
            report_pick(&mut gpu, &scene, &input, (px, py));
        }
    }

    // pixels darker than the background: it is 0.9 x 255 = 230, ink is below 200 in some channel
    let ink = rgba
        .chunks_exact(4)
        .filter(|p| p[0] < 200 || p[1] < 200 || p[2] < 200)
        .count();
    format!(
        "wrote {out}  {w}x{h}  non-background pixels: {ink} ({:.1}%)\n",
        100.0 * ink as f64 / (w * h) as f64
    )
}

/// Write the id frame and a guid-to-row map beside it.
fn write_ids(gpu: &mut Gpu, scene: &Scene, input: &FrameInput, path: &str) {
    use std::io::Write;
    let ids = gpu.render_ids_offscreen(input);
    let mut file = std::io::BufWriter::new(std::fs::File::create(path).expect("create ID frame"));
    // File layout: the 4-byte tag HLI2, width, height, then two u32 per pixel, all little-endian.
    file.write_all(b"HLI2").expect("write ID format");
    file.write_all(&gpu.config.width.to_le_bytes())
        .expect("write ID width");
    file.write_all(&gpu.config.height.to_le_bytes())
        .expect("write ID height");
    for id in ids {
        file.write_all(&id[0].to_le_bytes())
            .expect("write object ID");
        file.write_all(&id[1].to_le_bytes())
            .expect("write segment ID");
    }
    file.flush().expect("flush ID frame");
    // which guid is which row
    let mut mapping = std::collections::BTreeMap::new();
    for row in 0..gpu.objects.len() {
        if let Some(hit) = scene.resolve(Pick { row, sub: 0 }, gpu) {
            let range = scene.ribbon_range(row).unwrap_or(0..0);
            mapping.insert(hit.guid, serde_json::json!({ "object_id": row + 1, "ribbon_start": range.start, "ribbon_count": range.len() }));
        }
    }
    let map = std::fs::File::create(format!("{path}.json")).expect("create ID mapping");
    serde_json::to_writer_pretty(map, &mapping).expect("write ID mapping");
    println!(
        "wrote IDs {path}: {}x{}, {} object GUIDs; opaque picking core, alpha >= 0.5",
        gpu.config.width,
        gpu.config.height,
        mapping.len()
    );
}

/// Pick one pixel and print what it hit.
fn report_pick(gpu: &mut Gpu, scene: &Scene, input: &FrameInput, at: (u32, u32)) {
    gpu.pick.request(at.0, at.1);
    let _ = gpu.render_offscreen(input);
    // the GPU copies the picked id back later; Wait blocks until that copy is done
    let _ = gpu.ctx.device.poll(wgpu::PollType::Wait {
        submission_index: None,
        timeout: None,
    });
    let pick: Option<Pick> = gpu.pick.poll().flatten();
    match pick.and_then(|p| scene.resolve(p, gpu)) {
        Some(hit) => match hit.point {
            Some(pt) => println!(
                "pick: ({},{}) doc='{}' row={} point={} id={} pos=({:.0}, {:.0}, {:.0})",
                at.0,
                at.1,
                hit.doc,
                hit.row,
                pt.local,
                pt.id,
                pt.position[0],
                pt.position[1],
                pt.position[2]
            ),
            None => println!(
                "pick: ({},{}) doc='{}' guid={} row={}",
                at.0, at.1, hit.doc, hit.guid, hit.row
            ),
        },
        None => println!("pick: ({},{}) nothing", at.0, at.1),
    }
}

/// Upload and picking checks on one device.
// A module declared inside selftest.rs lives in the folder of the same name: src/selftest/lifecycle.rs.
pub mod lifecycle;

/// Check that every BRep edge keeps its id after upload.
pub fn check_cad_edges(paths: &[String]) {
    let mut gpu = pollster::block_on(Gpu::new_headless(64, 64)).unwrap();
    let mut scene = Scene::new();
    for path in paths {
        check_cad_edge_file(&mut scene, &mut gpu, path);
    }
}

/// Check one BRep file's edge ids.
fn check_cad_edge_file(scene: &mut Scene, gpu: &mut Gpu, path: &str) {
    scene.clear(gpu);
    let bytes = std::fs::read(path).unwrap();
    let session = Session::pb_loads(&bytes).unwrap();
    scene.add_file(FileDoc {
        name: path.into(),
        session: Rc::new(session),
        place: Xform::identity(),
        point_px: 0.0,
        display_only: false,
    });
    scene.upload_to(gpu);
    let Some(session_rust::Geometry::BRep(brep)) = scene.geometry(0) else {
        panic!("expected BRep fixture");
    };
    // the edges the file has
    let mut expected = std::collections::BTreeSet::new();
    for (edge, source) in brep.m_edges.iter().enumerate() {
        if !source.degenerated {
            expected.insert(edge as u32);
        }
    }
    // the edges the GPU segments resolve to
    let mut actual = std::collections::BTreeSet::new();
    let mut segment = 0u32;
    // segment ids count up from 0 until one no longer resolves; the top bit marks an edge segment
    while let Some(edge) = scene.edge_at(Pick {
        row: 0,
        sub: 0x8000_0000 | segment,
    }) {
        assert!(expected.contains(&edge), "invented CAD edge {edge}");
        assert_eq!(
            scene.edge_at(Pick {
                row: 1,
                sub: 0x8000_0000 | segment
            }),
            None
        );
        actual.insert(edge);
        segment += 1;
    }
    assert_eq!(actual, expected, "missing source edge in {path}");
    println!(
        "{path}: {segment} segments retain {} source edge IDs",
        actual.len()
    );
}

//! Check that resize, a second walk, edits undone and reload draw the same pixels and ids.

use crate::{
    app::scene::{FileDoc, Scene, SheetInit, StreamedInit},
    app::stream::{CloudFields, CloudLod, SheetFields},
    app::walk::{cloud::StreamRows, sheet::SheetRows},
    camera::{Camera, View},
    engine::gpu::{FrameInput, Gpu, Pick},
};
use session_rust::{Color, Line, Point, Session, Xform};
use std::{collections::HashSet, path::Path, rc::Rc};

type Source = (String, Rc<Session>, Xform); // a type alias names the tuple once: name, session, placement

/// One rendered frame: the picture and the id picture.
#[derive(PartialEq, Eq)]
struct Frame {
    color: Vec<u8>,     // RGBA pixels
    ids: Vec<[u32; 2]>, // object and segment id per pixel
}

/// Load the sources, uploading after each one or once at the end.
fn load(scene: &mut Scene, gpu: &mut Gpu, sources: &[Source], incremental: bool) {
    for (name, session, place) in sources {
        scene.add_file(FileDoc {
            name: name.clone(),
            session: Rc::clone(session),
            place: place.clone(),
            point_px: 0.0,
            display_only: false,
        });
        if incremental {
            scene.upload_to(gpu);
        }
    }
    if !incremental {
        scene.upload_to(gpu);
    }
}

/// Draw one frame and check every id in it resolves.
fn render(gpu: &mut Gpu, scene: &Scene, camera: &Camera) -> Frame {
    let anchor = gpu
        .rebase_anchor(&camera.origin(), camera.distance_world(), 0.0)
        .anchor;
    let input = FrameInput {
        view_proj: camera.view_proj_anchored(4.0 / 3.0, &anchor),
        clear: wgpu::Color {
            r: 0.9,
            g: 0.9,
            b: 0.9,
            a: 1.0,
        },
        now_ms: 0.0,
    };
    let color = gpu.render_offscreen(&input);
    let ids = gpu.render_ids_offscreen(&input);
    assert!(
        ids.iter().any(|id| id[0] != 0),
        "scene must produce pickable geometry"
    );
    // every distinct id drawn
    for [object, sub] in ids
        .iter()
        .copied()
        .filter(|id| id[0] != 0)
        .collect::<HashSet<_>>()
    {
        let row = object - 1; // ids are row + 1, 0 is background
        let decoded = sub.saturating_sub(1);
        let hit = scene
            .resolve(Pick { row, sub: decoded }, gpu)
            .expect("rendered object ID resolves");
        assert_eq!(hit.row, row);
        // `&& let` (a let chain) tests the edge bit and unpacks the range in one condition
        if sub & 0x8000_0000 != 0
            && let Some(range) = scene.ribbon_range(row)
        {
            assert!(
                range.contains(&((sub & 0x7fff_ffff) - 1)),
                "ribbon ID must stay inside its retained object range"
            );
        }
    }
    Frame { color, ids }
}

/// Assert two frames are pixel-identical.
fn same(label: &str, reference: &Frame, current: &Frame) {
    assert_eq!(
        (reference.color.len(), reference.ids.len()),
        (current.color.len(), current.ids.len()),
        "{label}: frame dimensions"
    );
    let color = reference
        .color
        .chunks_exact(4)
        .zip(current.color.chunks_exact(4))
        .filter(|(a, b)| a != b)
        .count();
    let ids = reference
        .ids
        .iter()
        .zip(&current.ids)
        .filter(|(a, b)| a != b)
        .count();
    assert_eq!(
        (color, ids),
        (0, 0),
        "{label}: spatial pixel/ID differences"
    );
    println!("{label}: identical full color and picking frames");
}

/// Write a frame as a PPM image; `super` is the parent module, selftest.rs.
fn write_frame(path: &Path, frame: &Frame) {
    super::write_ppm(path.to_str().unwrap(), &frame.color, 800, 600).unwrap();
}

/// Render at MSAA 1 and 4, after a resize and back; all must repeat exactly.
fn states(gpu: &mut Gpu, scene: &Scene, camera: &Camera) -> Vec<Frame> {
    let mut frames = Vec::new();
    // each sample count draws the same twice
    for msaa in [1, 4] {
        gpu.view.msaa_forced = Some(msaa);
        gpu.resize(800, 600);
        frames.push(render(gpu, scene, camera));
        same(
            &format!("MSAA{msaa} repeat"),
            &frames[frames.len() - 1],
            &render(gpu, scene, camera),
        );
    }
    gpu.view.msaa_forced = Some(1);
    gpu.resize(800, 600);
    same("MSAA1→4→1", &frames[0], &render(gpu, scene, camera));
    gpu.resize(960, 720);
    let _ = render(gpu, scene, camera);
    gpu.resize(800, 600);
    same("resize→restore", &frames[0], &render(gpu, scene, camera));
    frames
}

/// Load, walk again, edit and undo, and reload one scene; every state must draw the same.
fn check(gpu: &mut Gpu, sources: &[Source], name: &str, out: &Path) {
    let mut scene = Scene::new();
    load(&mut scene, gpu, sources, false);
    if name == "lines" {
        assert_eq!(gpu.arena.face_count(), 0); // a lines-only scene has no faces
    }
    // perspective iso and orthographic top
    for (view_name, view) in [("iso", View::Iso), ("top", View::Top)] {
        let mut camera = Camera::new();
        camera.fit(&gpu.bounds, 4.0 / 3.0);
        if view_name == "top" {
            camera.set_view(view);
        }
        println!(
            "{name} {view_name}: eye {:?}, target {:?}, perspective {}",
            camera.position, camera.target, camera.perspective
        );
        let baseline = states(gpu, &scene, &camera);
        for (i, frame) in baseline.iter().enumerate() {
            write_frame(&out.join(format!("{name}_{view_name}_{i}.ppm")), frame);
        }
        // rows walked again draw the same
        scene.rewalk_editable(gpu);
        let rebuilt = states(gpu, &scene, &camera);
        for (i, (a, b)) in baseline.iter().zip(&rebuilt).enumerate() {
            same(&format!("rewalk state{i}"), a, b);
        }
        // an edit and its undo draw the same
        edit_and_undo(&mut scene, gpu);
        let undone = states(gpu, &scene, &camera);
        for (i, (a, b)) in baseline.iter().zip(&undone).enumerate() {
            same(&format!("edit and undo state{i}"), a, b);
        }
        // reloaded one file at a time draws the same
        scene.clear(gpu);
        load(&mut scene, gpu, sources, true);
        let incremental = states(gpu, &scene, &camera);
        for (i, (a, b)) in baseline.iter().zip(&incremental).enumerate() {
            same(&format!("incremental after release state{i}"), a, b);
        }
    }
    scene.clear(gpu);
}

/// Delete the first object and draw a point, then undo both.
fn edit_and_undo(scene: &mut Scene, gpu: &mut Gpu) {
    let row = (0..scene.row_count() as u32)
        .find(|&row| scene.geometry(row).is_some())
        .expect("an object");
    let (doc, guid) = scene.identity_of(row).expect("a live row");
    assert!(scene.delete_row(row));
    scene.sync();
    scene.upload_to(gpu);
    scene
        .model(&crate::app::command::verbs::point::SPEC, &[[0.0, 0.0, 0.0]])
        .expect("a point");
    scene.sync();
    scene.upload_to(gpu);

    // undo goes back across documents: the point, then the deleted object
    for _ in 0..2 {
        assert!(scene.undo());
        scene.sync();
        scene.upload_to(gpu);
    }

    assert!(
        scene.row_of(doc, &guid).is_some(),
        "the deleted object is back"
    );
}

/// Lines beside a streamed sheet and a streamed cloud: edits undone draw as before.
fn check_streamed(gpu: &mut Gpu) {
    let mut scene = Scene::new();
    load(&mut scene, gpu, &lines(), false);
    scene.add_sheet(
        SheetInit {
            name: "sheet".into(),
            url: "sheet.pb".into(),
            meta_url: None,
            place: Xform::translation(0.0, 400.0, 0.0),
            rows: SheetRows {
                positions: vec![
                    -300.0, 0.0, 0.0, 300.0, 0.0, 0.0, 300.0, 0.0, 0.0, 300.0, 90.0, 0.0,
                ],
                colors: Vec::new(),
                widths: vec![2.0, 2.0],
                ids: vec![11, 12],
            },
            fields: SheetFields {
                count: 2,
                ..Default::default()
            },
            resident: 2,
        },
        gpu,
    );
    let positions: Vec<f32> = (0..200)
        .flat_map(|i| [(i % 20) as f32 * 10.0, -400.0 - (i / 20) as f32 * 10.0, 0.0])
        .collect();
    scene.add_streamed_cloud(
        StreamedInit {
            name: "cloud".into(),
            url: "cloud.pb".into(),
            place: Xform::identity(),
            rows: StreamRows {
                positions,
                colors: vec![0xff00_00ff; 200],
                normals: Vec::new(),
            },
            lod: CloudLod::default(),
            fields: CloudFields {
                end: 0,
                coords_at: 0,
                coords_len: 0,
                colors_at: 0,
                colors_len: 0,
                normals_at: 0,
                normals_len: 0,
                count: 200,
                ids_at: 0,
                ids_len: 0,
                revision: None,
            },
            resident: 200,
            point_px: 4.0,
            col_at: 0,
            ceiling: 200,
        },
        gpu,
    );
    let mut camera = Camera::new();
    camera.fit(&gpu.bounds, 4.0 / 3.0);
    let baseline = states(gpu, &scene, &camera);
    edit_and_undo(&mut scene, gpu);
    let undone = states(gpu, &scene, &camera);
    for (i, (a, b)) in baseline.iter().zip(&undone).enumerate() {
        same(&format!("streamed edit and undo state{i}"), a, b);
    }
    scene.clear(gpu);
}

/// Two small documents of lines and points.
fn lines() -> Vec<Source> {
    (0..2)
        .map(|i| {
            let name = format!("lines{i}");
            let mut session = Session::new(&name);
            for y in [-200.0, 0.0, 200.0] {
                let mut line = Line::new(-300.0, y, 0.0, 300.0, y + 70.0, 0.0);
                line.linecolor = Color::blue();
                line.width = -1.0;
                session.add_line(line, None);
                let mut point = Point::new(-300.0, y, 0.0);
                point.pointcolor = Color::red();
                point.width = 5.0;
                session.add_point(point, None);
            }
            (
                name,
                Rc::new(session),
                Xform::translation(i as f64 * 800.0, 0.0, i as f64 * 100.0),
            )
        })
        .collect()
}

/// Run the checks and write the frames to the output directory.
pub fn run() {
    let mut args = std::env::args().skip(1);
    let out = args.next().expect("output directory");
    let out = Path::new(&out);
    std::fs::create_dir_all(out).unwrap();
    let mut gpu = pollster::block_on(Gpu::new_headless(800, 600)).expect("headless GPU");
    gpu.view.show_grid = false;
    check(&mut gpu, &lines(), "lines", out);
    check_streamed(&mut gpu);
    let files: Vec<_> = args
        .enumerate()
        .map(|(i, path)| {
            let session = Session::pb_loads(&std::fs::read(&path).unwrap()).unwrap();
            (
                path,
                Rc::new(session),
                Xform::translation(i as f64 * 6000.0, 0.0, 0.0),
            )
        })
        .collect();
    if !files.is_empty() {
        check(&mut gpu, &files, "meshes", out);
    }
    println!(
        "lifecycle OK: no-face rendering, runtime MSAA toggles, resize, rewalk, edit and undo, streamed sources, release, incremental uploads and picking"
    );
}

